INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('IKcoding-jp/Roast-Plus/issue-creator', 'community', 'IKcoding-jp', 'Roast-Plus', 'IKcoding-jp/Roast-Plus', 'issue-creator', 0, 0, 30, '2026-03-08T01:57:15.409Z', '2026-03-08T02:07:01.165Z', '69f811979f3020fc1642bc5441fa8fc07bafe32f7305edc5f93dd21dea832f3d', '{"id":"IKcoding-jp/Roast-Plus/issue-creator","name":"issue-creator","description":{"en":"The issue-creator skill facilitates the creation of well-structured issues through a systematic workflow, benefiting developers and project managers. It automates brainstorming, code investigation, and working document generation.","zh":"Issue Creator是AIエージェント的一种技能，用于创建issue和工作文档","ja":"Issue CreatorはAIエージェントのスキルで、IssueとWorking Documentsを生成する","ko":"Issue Creator는 AI Agent의 기술로 issue와 작업 문서를 생성합니다","es":"Issue Creator es una herramienta de AI Agent que automatiza el proceso de creación de incidencias, mejorando la eficiencia y la colaboración en equipo.","fr":"Issue Creator est un outil d''agent IA qui automatise le processus de création de problèmes, améliorant l''efficacité et la collaboration d''équipe.","de":"Issue Creator ist ein AI-Tool, das den Prozess der Erstellung von Problemen automatisiert, um die Effizienz und die Teamzusammenarbeit zu verbessern.","pt":"O Issue Creator é uma ferramenta de código que ajuda a criar issues de forma eficiente, utilizando brainstorming e criação de documentos de trabalho","ru":"ИИ Агент Issue Creator - это инструмент для автоматизации создания задач, использующий брейншторминг и генерацию документов","ar":"Issue Creator هو أداة ذكاء اصطناعي لإنشاء قضايا بطريقة فعالة، باستخدام العصف الذهني وإنشاء مستندات العمل"},"seo":{"title":{"en":"issue-creator: AI-Powered Issue Creation Setup Guide | AI...","zh":"Issue Creator_SETUP GUIDE","ja":"Issue Creator ベストプラクティス","ko":"Issue Creator 구현 가이드","es":"Guía de configuración de Issue Creator para desarrolladores","fr":"Guide d''installation de Issue Creator pour les développeurs","de":"Einrichtungsleitfaden für Issue Creator-Entwickler","pt":"Guia de Configuração do Issue Creator para Desenvolvedores","ru":"Настройка ИИ Агента Issue Creator: Руководство для Разраб...","ar":"دليل إعداد Issue Creator لأدوات الذكاء الاصطناعي للطورين"},"description":{"en":"Unlock efficient issue creation with issue-creator. Learn how to set up and utilize this AI agent skill for streamlined workflow and accurate issue reporting.","zh":"AIエージェントIssue Creator使用指南，了解工作流程和技术细节","ja":"AIエージェントIssue Creatorの設定方法とワークフローについて","ko":"AI Agent Issue Creator 구현 방법 및 기술 세부 정보","es":"Aprende a configurar Issue Creator para agilizar el proceso de creación de incidencias y mejorar la colaboración en equipo con esta herramienta de AI Agent","fr":"Découvrez comment configurer Issue Creator pour accélérer le processus de création de problèmes et améliorer la collaboration d''équipe avec cet outil d''agent IA","de":"Erfahren Sie, wie Sie Issue Creator einrichten, um den Prozess der Erstellung von Problemen zu beschleunigen und die Teamzusammenarbeit mit diesem AI-Tool zu...","pt":"Aprenda a configurar o Issue Creator, uma ferramenta de código para criar issues de forma eficiente, e melhore sua produtividade como desenvolvedor","ru":"Узнайте, как настроить ИИ Агент Issue Creator для автоматизации создания задач и повысить свою производительность как разработчика","ar":"تعلم كيفية إعداد Issue Creator لأدوات الذكاء الاصطناعي لإنشاء قضايا بطريقة فعالة و تحسين إنتاجيتك كطور"},"definition":{"en":"issue-creator is a specialized AI agent skill designed to systematically create and manage issues through a phased workflow, including brainstorming, code analysis, and documentation.","zh":"Issue Creator是一种AIエージェント技能，用于创建issue和工作文档","ja":"Issue Creatorは、IssueとWorking Documentsを生成するAIエージェントのスキル","ko":"Issue Creator는 issue와 작업 문서를 생성하는 AI Agent 기술","es":"Issue Creator es una herramienta de AI que ayuda a los desarrolladores a crear incidencias de manera eficiente","fr":"Issue Creator est un outil d''IA qui aide les développeurs à créer des problèmes de manière efficace","de":"Issue Creator ist ein AI-Tool, das Entwicklern hilft, Probleme effizient zu erstellen","pt":"O que é Issue Creator? É uma ferramenta de código que cria issues de forma eficiente","ru":"Что такое ИИ Агент Issue Creator? Это инструмент для автоматизации создания задач","ar":"ما هو Issue Creator؟ هو أداة ذكاء اصطناعي لإنشاء قضايا بطريقة فعالة"},"features":{"en":["Initiates brainstorming sessions using the superpowers:brainstorming skill","Conducts code investigations based on project scope and requirements","Generates working documents in accordance with project scale and complexity","Creates well-structured issues following a systematic 6-phase workflow","Integrates with existing workflows to enhance issue tracking and management"],"zh":["支持ブレインストーミング功能","根据规模进行代码调査","生成Working Documents","支持超级权限的brainstorming技能","具有工作流程的六个阶段"],"ja":["ブレインストーミング機能をサポート","規模に応じてコード調査","Working Documentsを生成","スーパーパワーのbrainstormingスキルをサポート","6つのフェーズを持つワークフロー"],"ko":["브레인스토밍 기능 지원","규모에 따라 코드 조사","작업 문서 생성","슈퍼 파워의 브레인스토밍 기술 지원","6개의 단계를 가진 워크플로"],"es":["Automatización del proceso de creación de incidencias","Integración con superpowers:brainstorming para una mejor comprensión de los requisitos","Generación de documentos de trabajo según sea necesario","No requiere codificación para la creación de incidencias","Soporte para distintas fases del proceso de creación de incidencias","Colaboración en equipo mejorada"],"fr":["Automatisation du processus de création de problèmes","Intégration avec superpowers:brainstorming pour une meilleure compréhension des exigences","Génération de documents de travail selon les besoins","Pas de codage requis pour la création de problèmes","Prise en charge de différentes phases du processus de création de problèmes","Collaboration d''équipe améliorée"],"de":["Automatisierung des Prozesses der Erstellung von Problemen","Integration mit superpowers:brainstorming für ein besseres Verständnis der Anforderungen","Erstellung von Arbeitsdokumenten nach Bedarf","Keine Codierung erforderlich für die Erstellung von Problemen","Unterstützung für verschiedene Phasen des Prozesses der Erstellung von Problemen","Verbesserte Teamzusammenarbeit"],"pt":["Utiliza brainstorming para entender os requisitos do usuário","Cria issues de forma eficiente com base nos resultados do brainstorming","Gera documentos de trabalho automaticamente","Integração com a skill de brainstorming para uma experiência mais completa","Não executa alterações de código, apenas cria issues e documentos","Utiliza a ferramenta de código para criar issues de forma automática"],"ru":["Использует брейншторминг для понимания требований пользователя","Создает задачи эффективно на основе результатов брейншторминга","Генерирует документы автоматически","Интегрируется с навыком брейншторминга для более полного опыта","Не выполняет изменения кода, только создает задачи и документы","Использует инструмент кода для создания задач автоматически"],"ar":["يستخدم العصف الذهني لفهم متطلبات المستخدم","ينشئ قضايا بطريقة فعالة بناءً على نتائج العصف الذهني","يولد مستندات العمل تلقائيًا","يتكامل مع مهارة العصف الذهني لتجربة أكثر كمالًا","لا ي実ن تعديلات على الكود، فقط ينشئ قضايا ومستندات","يستخدم أداة الكود لإنشاء قضايا تلقائيًا"]},"keywords":{"en":["how to use issue-creator","issue-creator setup guide","issue-creator alternative","issue-creator vs competing tools","what is issue-creator","issue-creator install","issue-creator workflow optimization","ai-powered issue creation","automated issue tracking"],"zh":["AIエージェント","Issue Creator","ブレインストーミング","代码调査","Working Documents","超级权限","AI工具","工作流程"],"ja":["AIエージェント","Issue Creator","ブレインストーミング","コード調査","Working Documents","スーパーパワー","AIツール","ワークフロー"],"ko":["AI 에이전트","Issue Creator","브레인스토밍","코드 조사","작업 문서","슈퍼 파워","AI 도구","워크플로"],"es":["Issue Creator","herramienta de AI","creación de incidencias","colaboración en equipo","automatización de procesos","desarrollo de software","AI Agent","superpowers:brainstorming","integración de herramientas"],"fr":["Issue Creator","outil d''IA","création de problèmes","collaboration d''équipe","automatisation de processus","développement de logiciels","agent IA","superpowers:brainstorming","intégration d''outils"],"de":["Issue Creator","AI-Tool","Erstellung von Problemen","Teamzusammenarbeit","Automatisierung von Prozessen","Software-Entwicklung","AI-Agent","superpowers:brainstorming","Integration von Tools"],"pt":["Issue Creator","ferramenta de código","brainstorming","criação de issues","documentos de trabalho","desenvolvedores","produtividade","ferramentas de desenvolvimento","automatização de tarefas","melhoria de processo"],"ru":["ИИ Агент Issue Creator","инструмент кода","брейншторминг","создание задач","документы","разработчики","производительность","инструменты разработки","автоматизация задач","улучшение процесса"],"ar":["Issue Creator","أداة الكود","العصف الذهني","إنشاء قضايا","مستندات العمل","الطورين","الإنتاجية","أدوات التطوير","تأتمة المهام","تحسين العملية"]}},"owner":"IKcoding-jp","repo":"Roast-Plus","repoPath":"IKcoding-jp/Roast-Plus","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.409Z","topics":[],"category":"community","skillMd":{"name":"issue-creator","description":"GitHub Issue作成スキル。ブレインストーミング→コードベース調査→影響範囲特定→gh issue create→Working Documents生成まで一気通貫。タスク規模に応じて調査深度とWorking生成を自動調整。使用タイミング: (1)「〜のIssueを作って」 (2)「〜を実装したい」 (3)「〜のバグを報告」 (4)「〜をリファクタしたい」 (5)「Issue作成」 (6)「〜の機能を追加したい」 (7)「〜を改善したい」","bodyPreview":"# Issue Creator\n\n## ワークフロー\n\n```\n0. ブレインストーミング → 1. 作業内容理解+規模判定 → 2. コード調査(規模に応じて) → 3. Issue内容整理 → 4. ユーザー確認 → 5. Issue作成 → 6. Working Documents生成(規模に応じて)\n```\n\n⚠️ **このスキルではコード修正を行わない。調査とIssue作成とWorking生成のみ。**\n\n---\n\n## Phase 0: ブレインストーミング（必須）\n\n**必ず `superpowers:brainstorming` スキルを Skill ツールで明示的に呼び出すこと。**\n\n⚠️ **`using-superpowers`による自動発動には依存しない。** 本スキル内でbrainstormingを明示的に呼び出すため、using-superpowersの「1%ルール」による二重発動は不要。issue-creator実行中はbrainstormingの自動発動を抑制する。\n\nユーザーの意図・要件・設計を深掘りし、曖昧な要件を明確化してからPhase 1に進む","body":"# Issue Creator\n\n## ワークフロー\n\n```\n0. ブレインストーミング → 1. 作業内容理解+規模判定 → 2. コード調査(規模に応じて) → 3. Issue内容整理 → 4. ユーザー確認 → 5. Issue作成 → 6. Working Documents生成(規模に応じて)\n```\n\n⚠️ **このスキルではコード修正を行わない。調査とIssue作成とWorking生成のみ。**\n\n---\n\n## Phase 0: ブレインストーミング（必須）\n\n**必ず `superpowers:brainstorming` スキルを Skill ツールで明示的に呼び出すこと。**\n\n⚠️ **`using-superpowers`による自動発動には依存しない。** 本スキル内でbrainstormingを明示的に呼び出すため、using-superpowersの「1%ルール」による二重発動は不要。issue-creator実行中はbrainstormingの自動発動を抑制する。\n\nユーザーの意図・要件・設計を深掘りし、曖昧な要件を明確化してからPhase 1に進む。\n\n### Phase 1 への引き継ぎ\n\nブレインストーミング完了後、以下を確定した状態で Phase 1 に進む:\n- **何を実現したいか**（ユーザーの意図）\n- **スコープ**（含む/含まない機能）\n- **制約・前提条件**（技術的制約、既存機能との関係）\n\nこの確定内容が Issue 本文・Working Documents の基盤となる。\n\n---\n\n## Phase 1: 作業内容理解 + 規模判定\n\n### タイプ判定\n\nIssueタイプを判定: `bug` / `feat` / `refactor` / `docs` / `style` / `perf` / `chore` / `test`\n不明点はユーザーに質問。\n\n### 規模判定\n\nタスクの規模を3段階で判定:\n\n| 規模 | 基準 | 例 |\n|------|------|-----|\n| **小** | 1-2ファイル変更、単純な修正 | typo修正、設定変更、1関数の修正 |\n| **中** | 3-5ファイル変更、機能の追加・修正 | コンポーネント追加、既存機能の改善 |\n| **大** | 6ファイル以上、新機能、複雑なリファクタ | 新ページ作成、アーキテクチャ変更 |\n\n⚠️ **規模判定に迷ったら「中」として扱う。**\n\n---\n\n## Phase 2: コード調査（規模に応じて調整）\n\n### 大規模タスク → 詳細調査\n\n- `find_symbol` / `search_for_pattern` で関連コード特定\n- `get_symbols_overview` で構造把握\n- `find_referencing_symbols` で影響範囲確認\n\n⚠️ **この調査結果はWorking Documents生成に流用されるため、しっかり行う。**\n\n### 中規模タスク → 標準調査\n\n- `search_for_pattern` で関連コード特定\n- `get_symbols_overview` で変更対象ファイルの構造把握\n\n### 小規模タスク → 軽微調査 or 省略\n\n- 対象ファイルが明確な場合は調査省略可\n- 不明な場合のみ `search_for_pattern` で軽く確認\n\n---\n\n## Phase 3: Issue本文作成\n\n```markdown\n## 概要\n[何をするか - 1-2文]\n\n## 理由/背景\n[なぜ必要か]\n\n## 対象箇所\n- `path/to/file.ts:行番号` - 関数/コンポーネント名\n\n## 作業内容\n- [ ] タスク1\n- [ ] タスク2\n\n## 影響範囲\n- 関連コンポーネント・依存関係\n```\n\n⚠️ **小規模タスクでは「対象箇所」「影響範囲」は省略可。**\n\n---\n\n## Phase 4: ユーザー確認 🔹確認ポイント\n\nIssue本文を提示し、以下を確認:\n- 内容が正しいか\n- 規模判定が妥当か\n- Working Documents生成の有無（AIの判断を提示）\n\n---\n\n## Phase 5: Issue作成\n\n```bash\n# ⚠️ 一時ファイルはリポジトリルートに相対パスで作成（Windows互換）\n# /tmp/ はWindowsで正しく解決されないため使用禁止\ncat > .tmp-issue-body.md <<''EOF''\n[Issue本文]\nEOF\n\ngh issue create --title \"[type]: タイトル\" --body-file .tmp-issue-body.md --label \"ラベル\"\nrm -f .tmp-issue-body.md\n```\n\n**ラベル対応**: bug→`bug`, feat→`enhancement`, refactor→`refactor`, docs→`documentation`, style→`design`, perf→`performance`, chore→`chore`, test→`testing`\n\n---\n\n## Phase 6: Working Documents生成（AIが規模に応じて判断）\n\n⚠️ **`superpowers:writing-plans` は使用しない。** Working Documents（`docs/working/`）がissue-creatorの計画出力先であり、writing-plansの `docs/plans/` とは役割が異なる。issue-creator実行中はwriting-plansの自動発動を抑制する。\n\n### 生成判断基準\n\n| 規模 | Working生成 | 理由 |\n|------|:----------:|------|\n| **大** | ✅ 必ず生成 | コンテキスト保持が必須 |\n| **中** | ✅ 生成推奨 | /fix-issueでの作業効率化 |\n| **小** | △ AIが判断 | 内容に応じて生成/スキップ |\n\n### 小規模タスクでの判断基準\n\n以下に該当する場合は**スキップ可**:\n- 軽微なドキュメント修正（typo、リンク修正等）\n- 単純な依存関係更新（`npm update`のみ）\n- 緊急のホットフィックス（即座に修正が必要）\n- 1ファイルの軽微な修正\n\n以下に該当する場合は**生成する**:\n- バグ修正（原因調査の記録が重要）\n- テスト追加（テスト計画が必要）\n- 複数セッションにまたがる可能性がある作業\n\n### タスクタイプ別の生成内容\n\n| タイプ | requirement.md | tasklist.md | design.md | testing.md |\n|--------|:-------------:|:-----------:|:---------:|:----------:|\n| bug    | ✅ | ✅ | ✅ | ✅ |\n| feat   | ✅ | ✅ | ✅ | ✅ |\n| refactor | ✅ | ✅ | ✅ | △ 必要に応じて |\n| test   | △ 軽量 | ✅ | △ 軽量 | ✅ |\n| docs   | △ 軽量 | ✅ | - | - |\n| style  | △ 軽量 | ✅ | △ 軽量 | - |\n| chore  | - | ✅ | - | - |\n\n### ディレクトリ構成\n\n```\ndocs/working/{YYYYMMDD}_{Issue番号}_{タイトル}/\n├── requirement.md  # 要件定義\n├── tasklist.md     # タスクリスト（必須）\n├── design.md       # 設計書\n└── testing.md      # テスト計画\n```\n\n### 生成ロジック\n\n**Phase 0 のブレインストーミング結果** + **Phase 2 のコード調査結果**を流用して以下を生成:\n\n1. **requirement.md**: ブレインストーミングで確定した要件を構造化\n2. **tasklist.md**: 作業内容をフェーズ別タスクに分解\n3. **design.md**: 変更対象ファイル、実装方針、影響範囲\n4. **testing.md**: テストケース、カバレッジ目標\n\nテンプレートは **[working-templates.md](references/working-templates.md)** を参照。\n\n---\n\n## Phase 7: 完了\n\n```\n✅ Issue #124 を作成しました\n✅ Working Documents を生成しました（or スキップしました）\n   └── docs/working/20260206_124_タイトル/\n\n次のステップ:\n  /fix-issue 124\n```\n\n---\n\n## 詳細パターン\n\n実際のIssue作成例は以下を参照:\n\n- **[issue-examples.md](references/issue-examples.md)** - バグ報告、機能追加、リファクタリング等の具体例\n"},"lastSynced":"2026-03-08T02:07:01.165Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring structured issue creation and workflow automation in software development projects.","zh":"适用于需要结构化问题创建和工作流自动化的软件开发项目的开发代理。","ja":"ソフトウェア開発プロジェクトで構造化された問題作成とワークフローの自動化が必要な開発エージェントに適しています。","ko":"구조화된 문제 생성 및 워크플로 자동화를 필요로 하는 소프트웨어 개발 프로젝트를 위한 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo que requieren la creación de problemas estructurados y automatización de flujo de trabajo en proyectos de desarrollo de software.","fr":"Idéal pour les agents de développement nécessitant la création de problèmes structurés et l''automatisation du workflow dans les projets de développement de logiciels.","de":"Ideal für Entwicklungssagenten, die eine strukturierte Problemerstellung und Workflow-Automatisierung in Software-Entwicklungsprojekten benötigen.","pt":"Ideal para Agentes de Desenvolvimento que requerem criação de problemas estruturados e automação de fluxo de trabalho em projetos de desenvolvimento de software.","ru":"Идеально для агентов разработки, требующих структурированного создания проблем и автоматизации рабочего процесса в проектах разработки программного обеспечения.","ar":"مثالي للوكلاء التطوير الذين يتطلبون إنشاء مشاكل منظم وآلي في مشاريع تطوير البرمجيات."},"recommendation":{"en":"Empowers agents to systematically create well-structured issues through automated brainstorming, code investigation, and working document generation, utilizing skills like superpowers:brainstorming for comprehensive project understanding.","zh":"赋予代理通过自动化头脑风暴、代码调查和工作文档生成等技能，系统地创建结构化的问题，利用像superpowers:brainstorming这样的技能来实现对项目的全面理解。","ja":"エージェントに、自動化されたブレインストーミング、コード調査、作業文書の生成など、スーパーパワーズ：ブレインストーミングのようなスキルを利用して、体系的に構造化された問題を作成することができるようにします。","ko":"에이전트에게 자동화된 ブレインストーミング、코드 조사 및 작업 문서 생성 등의 스킬을 사용하여 체계적으로 구조화된 문제를 생성할 수 있도록 하며, superpowers:brainstorming과 같은 스킬을 사용하여 프로젝트에 대한 종합적인 이해를 구현할 수 있습니다.","es":"Habilita a los agentes a crear sistemáticamente problemas bien estructurados a través de una lluvia de ideas automatizada, investigación de código y generación de documentos de trabajo, utilizando habilidades como superpowers:brainstorming para una comprensión integral del proyecto.","fr":"Permet aux agents de créer systématiquement des problèmes bien structurés grâce à une réflexion automatique, une investigation de code et une génération de documents de travail, en utilisant des compétences comme superpowers:brainstorming pour une compréhension globale du projet.","de":"Ermächtigt die Agenten, systematisch gut strukturierte Probleme durch automatisierte Ideenfindung, Codeuntersuchung und Generierung von Arbeitsdokumenten zu erstellen, unter Nutzung von Fähigkeiten wie superpowers:brainstorming für ein umfassendes Projektverständnis.","pt":"Habilita os agentes a criar systematicamente problemas bem estruturados por meio de brainstorming automatizado, investigação de código e geração de documentos de trabalho, utilizando habilidades como superpowers:brainstorming para uma compreensão abrangente do projeto.","ru":"Наделяет агентов возможностью систематически создавать хорошо структурированные проблемы посредством автоматизированного мозгового штурма, расследования кода и генерации рабочих документов, используя навыки, такие как superpowers:brainstorming для всестороннего понимания проекта.","ar":"يجعل الوكلاء قادرون على إنشاء مشاكل منظم ومتكاملة من خلال دمج الأفكار الآلي وتحقيق الفحص والتحليل للكود وتوليد وثائق العمل، باستخدام مهارات مثل superpowers:brainstorming لفهم شامل للمشروع."},"useCases":{"en":["Automating issue creation for project managers","Generating working documents based on issue scope","Streamlining code investigation for developers"],"zh":["为项目经理自动创建问题","根据问题范围生成工作文档","为开发人员简化代码调查"],"ja":["プロジェクトマネージャー向けの問題自動作成","問題範囲に基づく作業文書の生成","開発者向けのコード調査の簡素化"],"ko":["프로젝트 매니저를 위한 문제 자동 생성","문제 범위에 따라 작업 문서 생성","개발자를 위한 코드 조사 단순화"],"es":["Automatización de la creación de problemas para los administradores de proyectos","Generación de documentos de trabajo en función del alcance del problema","Optimización de la investigación de código para los desarrolladores"],"fr":["Automatisation de la création de problèmes pour les gestionnaires de projet","Génération de documents de travail en fonction de la portée du problème","Optimisation de l''investigation de code pour les développeurs"],"de":["Automatisierung der Problemerstellung für Projektmanager","Generierung von Arbeitsdokumenten basierend auf dem Problembereich","Optimierung der Codeuntersuchung für Entwickler"],"pt":["Automatizar a criação de problemas para gerentes de projeto","Gerar documentos de trabalho com base no escopo do problema","Otimizar a investigação de código para desenvolvedores"],"ru":["Автоматизировать создание проблем для менеджеров проекта","Генерировать рабочие документы на основе объема проблемы","Оптимизировать расследование кода для разработчиков"],"ar":["تأتمتة إنشاء المشاكل لمديري المشاريع","توليد وثائق العمل بناءً على نطاق المشكلة","جعل تحقيق الفحص والتحليل للكود أكثر كفاءة للمطورين"]},"limitations":{"en":["Does not perform code modifications, only investigation and issue creation","Requires explicit invocation of superpowers:brainstorming skill"],"zh":["不执行代码修改，只能进行代码调查和问题创建","需要显式调用superpowers:brainstorming技能"],"ja":["コードの修正は実行せず、コード調査と問題作成のみ","スーパーパワーズ：ブレインストーミングスキルの明示的な呼び出しが必要"],"ko":["코드 수정을 수행하지 않으며, 코드 조사 및 문제 생성만 수행","superpowers:brainstorming 스킬의 명시적 호출이 필요"],"es":["No realiza modificaciones de código, solo investigación y creación de problemas","Requiere la invocación explícita de la habilidad superpowers:brainstorming"],"fr":["Ne réalise pas de modifications de code, mais seulement une investigation et une création de problèmes","Nécessite l''invocation explicite de la compétence superpowers:brainstorming"],"de":["Führt keine Codeänderungen durch, sondern nur Untersuchung und Problemerstellung","Benötigt die explizite Aufrufung der Fähigkeit superpowers:brainstorming"],"pt":["Não realiza modificações de código, apenas investigação e criação de problemas","Requer invocação explícita da habilidade superpowers:brainstorming"],"ru":["Не выполняет модификацию кода, только расследование и создание проблем","Требует явного вызова навыка superpowers:brainstorming"],"ar":["لا تقوم بتعديل الكود، بل فقط التحقيق وإنشاء المشاكل","تتطلب استدعاء صريح لمهارة superpowers:brainstorming"]},"version":4},"contentHash":"69f811979f3020fc1642bc5441fa8fc07bafe32f7305edc5f93dd21dea832f3d","qualityScore":30}');
