INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('IKcoding-jp/Roast-Plus/issue-creator', 'issue-creator', 'IKcoding-jp', 'Roast-Plus', 'community', 'issue-creator IKcoding-jp Roast-Plus community The issue-creator skill facilitates the creation of well-structured issues through a systematic workflow, benefiting developers and project managers. It automates brainstorming, code investigation, and working document generation. Issue Creator是AIエージェント的一种技能，用于创建issue和工作文档 Issue CreatorはAIエージェントのスキルで、IssueとWorking Documentsを生成する Issue Creator는 AI Agent의 기술로 issue와 작업 문서를 생성합니다 Issue Creator es una herramienta de AI Agent que automatiza el proceso de creación de incidencias, mejorando la eficiencia y la colaboración en equipo. Issue Creator est un outil d''agent IA qui automatise le processus de création de problèmes, améliorant l''efficacité et la collaboration d''équipe. Issue Creator ist ein AI-Tool, das den Prozess der Erstellung von Problemen automatisiert, um die Effizienz und die Teamzusammenarbeit zu verbessern. O Issue Creator é uma ferramenta de código que ajuda a criar issues de forma eficiente, utilizando brainstorming e criação de documentos de trabalho ИИ Агент Issue Creator - это инструмент для автоматизации создания задач, использующий брейншторминг и генерацию документов Issue Creator هو أداة ذكاء اصطناعي لإنشاء قضايا بطريقة فعالة، باستخدام العصف الذهني وإنشاء مستندات العمل how to use issue-creator issue-creator setup guide issue-creator alternative issue-creator vs competing tools what is issue-creator issue-creator install issue-creator workflow optimization ai-powered issue creation automated issue tracking AIエージェント Issue Creator ブレインストーミング 代码调査 Working Documents 超级权限 AI工具 工作流程 Initiates brainstorming sessions using the superpowers:brainstorming skill Conducts code investigations based on project scope and requirements Generates working documents in accordance with project scale and complexity Creates well-structured issues following a systematic 6-phase workflow Integrates with existing workflows to enhance issue tracking and management issue-creator is a specialized AI agent skill designed to systematically create and manage issues through a phased workflow, including brainstorming, code analysis, and documentation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ludicroushq/STARTer/orpc', 'community', 'ludicroushq', 'STARTer', 'ludicroushq/STARTer', 'orpc', 0, 0, 30, '2026-03-08T01:57:15.416Z', '2026-03-08T02:07:15.450Z', 'b240c7c2fce5de87538e5b9acc49038c65c312d4a58dd18cdacf628ca678671f', '{"id":"ludicroushq/STARTer/orpc","name":"orpc","description":{"en":"The orpc skill provides a robust RPC implementation for AI agents, supporting features like error logging and cached session management. It benefits developers building scalable and efficient applications.","zh":"ORPC 是一个 RPC 版本的服务端开发框架，提供了中间件和路由配置等功能。","ja":"ORPC は RPC バージョンのサーバーサイド開発フレームワークで、ミドルウェアとルーティング設定などの機能を提供します。","ko":"ORPC는 RPC 버전의 서버 사이드 개발 프레임워크로, 미들웨어 및 라우팅 구성 등의 기능을 제공합니다.","es":"orpc es una herramienta de RPC que permite una comunicación eficiente entre servidores y clientes. Aprende a configurar orpc y mejorar tus habilidades de desarrollo","fr":"orpc est un outil de RPC qui permet une communication efficace entre les serveurs et les clients. Découvrez comment configurer orpc et améliorer vos compétences de développement","de":"orpc ist ein RPC-Tool, das eine effiziente Kommunikation zwischen Servern und Clients ermöglicht. Erfahren Sie, wie Sie orpc konfigurieren und Ihre Entwicklungsfähigkeiten verbessern","pt":"O ORPC é uma ferramenta poderosa para desenvolvedores. Aprenda a configurá-lo e a aproveitar suas funcionalidades.","ru":"ORPC - это мощный инструмент для разработчиков ИИ Агентов. Узнайте, как настроить его и использовать его возможности.","ar":"ORPC هو أداة قوية لمنشئي أدوات الذكاء الاصطناعي. تعلم كيفية إعدادها وتحقيق إمكاناتها."},"seo":{"title":{"en":"orpc: RPC Setup Guide for AI Agents","zh":"ORPC Setup Guide: RPC 版本和中间件配置","ja":"ORPC の設定方法: RPC バージョンとミドルウェア","ko":"ORPC 설정 가이드: RPC 버전 및 미들웨어 구성","es":"Guía de configuración de orpc: Implementación de RPC","fr":"Guide d''installation d''orpc: Mise en œuvre de RPC","de":"orpc-Setup-Leitfaden: RPC-Implementierung","pt":"Guia de Configuração do ORPC: Melhores Práticas para Dese...","ru":"Настройка ORPC: Руководство по лучшим практикам для разра...","ar":"دليل إعداد ORPC: أفضل الممارسات لمنشئي أدوات الذكاء الاصط..."},"description":{"en":"Discover how to implement orpc for efficient RPC handling. Learn to set up orpc with our expert guide and unlock its full potential.","zh":"了解 ORPC 的 RPC 版本和中间件配置，实现高效的服务端开发，AIエージェント","ja":"ORPC の RPC バージョンとミドルウェアを設定して、効率的なサーバーサイド開発を実現する、AIエージェント","ko":"ORPC의 RPC 버전 및 미들웨어 구성으로 효율적인 서버 사이드 개발을 구현하고, AI 도구","es":"Aprende a configurar orpc con nuestra guía paso a paso. Descubre cómo implementar RPC y mejorar tus habilidades de desarrollo","fr":"Découvrez comment configurer orpc avec notre guide étape par étape. Améliorez vos compétences de développement avec la mise en œuvre de RPC","de":"Erfahren Sie, wie Sie orpc mit unserem Schritt-für-Schritt-Leitfaden konfigurieren. Verbessern Sie Ihre Entwicklungsfähigkeiten mit der Implementierung von RPC","pt":"Aprenda a configurar o ORPC com nosso guia passo a passo. Descubra as melhores práticas para desenvolvedores e melhore sua experiência com o RPC do ORPC.","ru":"Узнайте, как настроить ORPC с нашей пошаговой инструкцией. Откройте для себя лучшие практики для разработчиков ИИ Агентов и улучшите свой опыт с RPC ORPC.","ar":"تعلم كيفية إعداد ORPC باستخدام دليلنا خطوة بخطوة. اكتشف أفضل الممارسات لمنشئي أدوات الذكاء الاصطناعي وتحسين تجربتك مع RPC ORPC."},"definition":{"en":"orpc is a lightweight RPC framework used for building efficient and scalable applications, utilizing the RPC version of ORPC.","zh":"ORPC 是一个基于 RPC 的服务端开发框架，提供了高效的中间件和路由配置。","ja":"ORPC は RPC に基づいたサーバーサイド開発フレームワークで、効率的なミドルウェアとルーティング設定を提供します。","ko":"ORPC는 RPC 기반의 서버 사이드 개발 프레임워크로, 효율적인 미들웨어 및 라우팅 구성 기능을 제공합니다.","es":"orpc es un protocolo de comunicación de procedimiento remoto que permite la interacción entre servidores y clientes","fr":"orpc est un protocole de communication de procédure à distance qui permet l''interaction entre les serveurs et les clients","de":"orpc ist ein Remote-Procedure-Call-Protokoll, das die Interaktion zwischen Servern und Clients ermöglicht","pt":"O que é ORPC? É uma ferramenta de RPC que permite aos desenvolvedores criar aplicações escaláveis e eficientes.","ru":"Что такое ORPC? Это инструмент RPC, который позволяет разработчикам создавать масштабируемые и эффективные приложения.","ar":"ما هو ORPC؟ هو أداة RPC التي تمكن منشئي أدوات الذكاء الاصطناعي من إنشاء تطبيقات قابلة للتوسع والكفاءة."},"features":{"en":["Implements ORPC RPC handler with error logging in src/server/handler.ts","Supports ORPC middleware including baseOs, withUserOs, and withoutUserOs in src/server/index.ts","Defines ORPC route definitions in src/server/routes/index.ts","Provides an isomorphic ORPC client for server and client use in src/server/client/index.ts","Utilizes a cached session getter in src/server/utils/get-session.ts"],"zh":["支持 RPC 版本的服务端开发","提供中间件配置（baseOs、withUserOs、withoutUserOs）","支持路由配置和管理","提供 Isomorphic 客户端（服务器/客户端）","支持缓存 Session 获取"],"ja":["RPC バージョンのサーバーサイド開発をサポート","ミドルウェア設定（baseOs、withUserOs、withoutUserOs）を提供","ルーティング設定と管理をサポート","Isomorphic クライアント（サーバー/クライアント）を提供","キャッシュ セッション取得をサポート"],"ko":["RPC 버전의 서버 사이드 개발을 지원","미들웨어 구성（baseOs、withUserOs、withoutUserOs）을 제공","라우팅 구성 및 관리를 지원","Isomorphic 클라이언트（서버/클라이언트）를 제공","캐시 세션 가져오기를 지원"],"es":["Implementación de RPC para una comunicación eficiente","Soporte para middleware y routas personalizadas","Cliente isomórfico para una mayor flexibilidad","Gestión de sesiones con caché para mejorar el rendimiento","Soporte para errores y registro de errores para una depuración más sencilla"],"fr":["Mise en œuvre de RPC pour une communication efficace","Support pour les middleware et les routes personnalisées","Client isomorphe pour une plus grande flexibilité","Gestion des sessions avec cache pour améliorer les performances","Support pour les erreurs et le journal des erreurs pour une débogage plus simple"],"de":["Implementierung von RPC für eine effiziente Kommunikation","Unterstützung für Middleware und benutzerdefinierte Routen","Isomorpher Client für eine größere Flexibilität","Sitzungsverwaltung mit Cache für eine verbesserte Leistung","Unterstützung für Fehler und Fehlerprotokoll für eine einfachere Fehlersuche"],"pt":["Suporte a RPC do ORPC","Manipulação de erros com logging","Definição de rotas com src/server/routes/index.ts","Cliente isomórfico do ORPC","Obtenção de sessão em cache com src/server/utils/get-session.ts"],"ru":["Поддержка RPC ORPC","Обработка ошибок с логированием","Определение маршрутов с src/server/routes/index.ts","Изоморфный клиент ORPC","Получение кэшированной сессии с src/server/utils/get-session.ts"],"ar":["دعم RPC ORPC","تعامل الأخطاء مع تسجيل","تعريف المسارات مع src/server/routes/index.ts","عميل متشابه ORPC","الحصول على جلسة مخزنة مؤقتا مع src/server/utils/get-session.ts"]},"keywords":{"en":["how to use orpc","orpc setup guide","orpc alternative","orpc vs grpc","orpc install","what is orpc","orpc documentation","orpc rpc example"],"zh":["ORPC","RPC","服务端开发","中间件配置","路由配置","Isomorphic 客户端","AIエージェント","服务器开发框架"],"ja":["ORPC","RPC","サーバーサイド開発","ミドルウェア設定","ルーティング設定","Isomorphic クライアント","AIエージェント","サーバー開発フレームワーク"],"ko":["ORPC","RPC","서버 사이드 개발","미들웨어 구성","라우팅 구성","Isomorphic 클라이언트","AI 도구","서버 개발 프레임워크"],"es":["orpc","RPC","desarrollo de software","comunicación de procedimiento remoto","middleware","rutas personalizadas","cliente isomórfico","gestión de sesiones","caché","errores y registro de errores"],"fr":["orpc","RPC","développement de logiciels","communication de procédure à distance","middleware","routes personnalisées","client isomorphe","gestion des sessions","cache","erreurs et journal des erreurs"],"de":["orpc","RPC","Software-Entwicklung","Remote-Procedure-Call","Middleware","benutzerdefinierte Routen","isomorpher Client","Sitzungsverwaltung","Cache","Fehler und Fehlerprotokoll"],"pt":["ORPC","RPC","desenvolvimento de aplicações","escalabilidade","eficiência","erros","logging","rotas","cliente isomórfico","sessão em cache"],"ru":["ORPC","RPC","разработка приложений","масштабируемость","эффективность","ошибки","логирование","маршруты","изоморфный клиент","кэшированная сессия"],"ar":["ORPC","RPC","تطوير التطبيقات","القدرة على التوسع","الكفاءة","الأخطاء","تسجيل","المسارات","عميل متشابه","جلسة مخزنة مؤقتا"]}},"owner":"ludicroushq","repo":"STARTer","repoPath":"ludicroushq/STARTer","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.416Z","topics":[],"category":"community","skillMd":{"name":"orpc","description":"ORPC RPC framework for server routes, middleware, and client setup. Activate when creating API endpoints, server routes, or working with the RPC layer.","bodyPreview":"# ORPC\n\nWe use the RPC version of ORPC. https://orpc.dev/docs/getting-started\n\n## Files\n\n- `src/server/handler.ts` - ORPC RPC handler with error logging\n- `src/server/index.ts` - ORPC middleware (`baseOs`, `withUserOs`, `withoutUserOs`)\n- `src/server/routes/index.ts` - ORPC route definitions (currently empty)\n- `src/server/client/index.ts` - Isomorphic ORPC client (server/client)\n- `src/server/utils/get-session.ts` - Cached session getter\n\n## Routing\n\nAll routes be properly organized in `src/ser","body":"# ORPC\n\nWe use the RPC version of ORPC. https://orpc.dev/docs/getting-started\n\n## Files\n\n- `src/server/handler.ts` - ORPC RPC handler with error logging\n- `src/server/index.ts` - ORPC middleware (`baseOs`, `withUserOs`, `withoutUserOs`)\n- `src/server/routes/index.ts` - ORPC route definitions (currently empty)\n- `src/server/client/index.ts` - Isomorphic ORPC client (server/client)\n- `src/server/utils/get-session.ts` - Cached session getter\n\n## Routing\n\nAll routes be properly organized in `src/server/routes`. The file path should always match the RPC path. Every RPC function should be a folder containing an `index.ts`. Every sub-folder should also contain an `index.ts` which reexports the scoped routes.\n\n```ts\n// src/server/routes/posts/list/index.ts\nexport const list = withUserOs.handler();\n\n// src/server/routes/posts/index.ts\nimport { list } from \"./list\";\n\nexport const postsRoutes = {\n  list,\n};\n\n// src/server/routes/index.ts\nimport { postsRoutes } from \"./posts\";\n\nexport const routes = {\n  posts: postsRoutes,\n};\n```\n\n## Functions\n\nALWAYS use one of the `os` variables defined in `src/server/index.ts` depending on the data you need. If there is recurring logic consider update the existing os to deduplicate that work or create a new one. For example if you have a concept of organizations, consider making an `export const withOrganizationOs = withUserOs.use(withOrganizationMiddleware);`\n"},"lastSynced":"2026-03-08T02:07:15.450Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents requiring robust and scalable RPC implementation with features like error logging and cached session management.","zh":"适用于需要强大且可扩展的RPC实现的AI代理，具有错误日志记录和缓存会话管理等功能。","ja":"ロバストでスケーラブルなRPC実装とエラーロギングやキャッシュセッション管理などの機能を必要とするAIエージェントに適しています。","ko":"강력하고 확장 가능한 RPC 구현 및 오류 로깅 및 캐시 세션 관리와 같은 기능이 필요한 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA que requieren una implementación de RPC robusta y escalable con características como registro de errores y administración de sesiones en caché.","fr":"Idéal pour les agents IA nécessitant une mise en œuvre de RPC robuste et évolutive avec des fonctionnalités comme la journalisation des erreurs et la gestion de sessions mises en cache.","de":"Ideal für KI-Agents, die eine robuste und skalierbare RPC-Implementierung mit Funktionen wie Fehlerprotokollierung und zwischengespeicherte Sitzungsverwaltung erfordern.","pt":"Ideal para Agentes de IA que exigem uma implementação robusta e escalável de RPC com recursos como registro de erros e gerenciamento de sessões em cache.","ru":"Идеально для агентов ИИ, требующих прочной и масштабируемой реализации RPC с функциями, такими как ведение журнала ошибок и кеширование управления сессиями.","ar":"مثالي لعمليات الوكيل الذكي التي تتطلب تنفيذ RPC متين ومرن مع ميزات مثل تسجيل الأخطاء وإدارة الجلسات المخزنة مؤقتا."},"recommendation":{"en":"Empowers agents to leverage the ORPC RPC version for efficient application development, utilizing features like error logging and cached session management through the isomorphic ORPC client, while supporting protocols defined in https://orpc.dev/docs/getting-started.","zh":"赋予代理使用ORPC RPC版本进行高效应用开发的能力，利用ORPC同构客户端的错误日志记录和缓存会话管理等功能，同时支持https://orpc.dev/docs/getting-started中定义的协议。","ja":"ORPC RPCバージョンを使用して効率的なアプリケーション開発を行うためのエージェントの能力を付与し、エラーロギングやキャッシュセッション管理などの機能をORPCの同型クライアントを通じて利用し、https://orpc.dev/docs/getting-startedで定義されたプロトコルをサポートします。","ko":"에이전트가 ORPC RPC 버전을 사용하여 효율적인 애플리케이션 개발을 진행할 수 있는 능력을 부여하며, ORPC 동형 클라이언트를 통해 오류 로깅 및 캐시 세션 관리와 같은 기능을 활용하며, https://orpc.dev/docs/getting-started에서 정의된 프로토콜을 지원합니다.","es":"Habilita a los agentes a aprovechar la versión de RPC de ORPC para un desarrollo de aplicaciones eficiente, utilizando características como el registro de errores y la administración de sesiones en caché a través del cliente isomorfo de ORPC, al mismo tiempo que admite protocolos definidos en https://orpc.dev/docs/getting-started.","fr":"Permet aux agents d''exploiter la version RPC d''ORPC pour un développement d''applications efficace, en utilisant des fonctionnalités comme la journalisation des erreurs et la gestion de sessions mises en cache via le client isomorphique d''ORPC, tout en prenant en charge les protocoles définis dans https://orpc.dev/docs/getting-started.","de":"Ermöglicht es den Agents, die ORPC-RPC-Version für eine effiziente Anwendungsentwicklung zu nutzen, indem sie Funktionen wie Fehlerprotokollierung und zwischengespeicherte Sitzungsverwaltung über den isomorphen ORPC-Client verwenden, während sie Protokolle unterstützt, die in https://orpc.dev/docs/getting-started definiert sind.","pt":"Habilita os agentes a aproveitar a versão ORPC RPC para desenvolvimento de aplicativos eficientes, utilizando recursos como registro de erros e gerenciamento de sessões em cache por meio do cliente isomórfico ORPC, ao mesmo tempo em que suporta protocolos definidos em https://orpc.dev/docs/getting-started.","ru":"Наделяет агентов возможностью использовать версию ORPC RPC для эффективного разработки приложений, используя функции, такие как ведение журнала ошибок и кеширование управления сессиями через изоморфный клиент ORPC, при этом поддерживая протоколы, определенные в https://orpc.dev/docs/getting-started.","ar":"يمنح الوكيل القدرة على الاستفادة من إصدار ORPC RPC من أجل تطوير التطبيقات بفعالية، باستخدام ميزات مثل تسجيل الأخطاء وإدارة الجلسات المخزنة مؤقتا من خلال عميل ORPC المتشابه، مع دعم البروتوكولات المحددة في https://orpc.dev/docs/getting-started."},"useCases":{"en":["Implementing error logging for RPC handlers","Managing cached sessions for efficient application scaling","Defining routes for organized application architecture"],"zh":["为RPC处理程序实现错误日志记录","管理缓存会话以实现高效的应用程序扩展","定义路由以实现有组织的应用程序架构"],"ja":["RPCハンドラーのエラーロギングを実装する","効率的なアプリケーションスケーリングのためのキャッシュセッションを管理する","整理されたアプリケーションアーキテクチャのためのルーティングを定義する"],"ko":["RPC 핸들러의 오류 로깅을 구현한다","효율적인 애플리케이션 확장성을 위한 캐시 세션을 관리한다","조직화된 애플리케이션 아키텍처를 위한 라우팅을 정의한다"],"es":["Implementar el registro de errores para controladores de RPC","Administrar sesiones en caché para una escalabilidad de aplicaciones eficiente","Definir rutas para una arquitectura de aplicaciones organizada"],"fr":["Mettre en œuvre la journalisation des erreurs pour les gestionnaires de RPC","Gérer les sessions mises en cache pour une mise à l''échelle des applications efficace","Définir des routes pour une architecture d''applications organisée"],"de":["Implementierung der Fehlerprotokollierung für RPC-Handler","Verwaltung von zwischengespeicherten Sitzungen für eine effiziente Anwendungsskalierung","Definieren von Routen für eine organisierte Anwendungsarchitektur"],"pt":["Implementar o registro de erros para manipuladores RPC","Gerenciar sessões em cache para escalabilidade de aplicativos eficiente","Definir rotas para arquitetura de aplicativos organizada"],"ru":["Реализовать ведение журнала ошибок для обработчиков RPC","Управлять кешированием сессий для эффективной масштабируемости приложений","Определить маршруты для организованной архитектуры приложений"],"ar":["تنفيذ تسجيل الأخطاء لمعالجات RPC","إدارة الجلسات المخزنة مؤقتا من أجل تحسين فعالية توسيع نطاق التطبيقات","تحديد مسارات لتخطيط تطبيقات منظم"]},"limitations":{"en":["Requires ORPC RPC version implementation","Needs proper routing organization in src/server/routes/index.ts"],"zh":["需要ORPC RPC版本的实现","需要在src/server/routes/index.ts中正确组织路由"],"ja":["ORPC RPCバージョンの実装が必要","src/server/routes/index.tsで適切なルーティングの組織化が必要"],"ko":["ORPC RPC 버전의 구현이 필요하다","src/server/routes/index.ts에서 올바른 라우팅 조직화가 필요하다"],"es":["Requiere implementación de la versión de RPC de ORPC","Necesita una organización de enrutamiento adecuada en src/server/routes/index.ts"],"fr":["Nécessite une mise en œuvre de la version RPC d''ORPC","Besoin d''une organisation de routage appropriée dans src/server/routes/index.ts"],"de":["Benötigt die Implementierung der ORPC-RPC-Version","Benötigt eine ordnungsgemäße Routing-Organisation in src/server/routes/index.ts"],"pt":["Exige implementação da versão ORPC RPC","Necessita de organização de roteamento adequada em src/server/routes/index.ts"],"ru":["Требует реализации версии ORPC RPC","Требует правильной организации маршрутизации в src/server/routes/index.ts"],"ar":["يتطلب تنفيذ إصدار ORPC RPC","يحتاج إلى تنظيم المسارات بشكل صحيح في src/server/routes/index.ts"]},"version":4},"contentHash":"b240c7c2fce5de87538e5b9acc49038c65c312d4a58dd18cdacf628ca678671f","qualityScore":30}');
