INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('arsac/qb-sync/grpc-protobuf', 'grpc-protobuf', 'arsac', 'qb-sync', 'community', 'grpc-protobuf arsac qb-sync community The grpc-protobuf skill enables developers to work with gRPC and Protocol Buffers, defining services and generating proto files for efficient communication. It benefits developers building scalable APIs. gRPC-Protobuf是一种高性能的RPC框架，使用Proto文件定义服务接口 gRPC-Protobufは高性能のRPCフレームワークで、Protoファイルを使用してサービスインターフェースを定義します gRPC-Protobuf는 높은 성능의 RPC 프레임워크로, Proto 파일을 사용하여 서비스 인터페이스를 정의합니다 gRPC y Protocol Buffers permiten la creación de servicios de alto rendimiento y escalables. Aprenda a configurar y utilizar estas tecnologías. gRPC et Protocol Buffers permettent de créer des services haute performance et évolutifs. Découvrez comment les configurer et les utiliser. gRPC und Protocol Buffers ermöglichen die Erstellung von High-Performance- und skalierbaren Diensten. Erfahren Sie, wie Sie diese Technologien konfigurieren und verwenden. O gRPC-protobuf é uma tecnologia que permite a criação de serviços de rede eficientes. Ele utiliza arquivos proto para definir a estrutura dos dados e serviços RPC. gRPC-protobuf - это технология, позволяющая создавать эффективные сетевые службы. Он использует файлы proto для определения структуры данных и служб RPC для ИИ Агентов. gRPC-protobuf هو تقنية تمكن من إنشاء خدمات الشبكة الكفءة. يستخدم ملفات بروتو لتعريف هيكل البيانات وخدمات RPC للأدوات الذكية. how to use grpc-protobuf grpc-protobuf tutorial what is grpc-protobuf grpc-protobuf vs REST grpc-protobuf install grpc-protobuf setup guide gRPC and Protocol Buffers example grpc-protobuf alternative grpc-protobuf best practices gRPC-Protobuf Proto文件结构 服务定义 Protocol Buffers RPC框架 AIエージェント gRPC开发 Protobuf教程 RPC性能优化 Defines services using Protocol Buffers syntax Generates proto files with options like java_package and java_multiple_files Supports import of external proto files like google/protobuf/timestamp.proto Enables creation of unary RPCs like CreateEnvironment and GetEnvironment Uses proto3 syntax for defining message structures Imports empty.proto for handling empty messages grpc-protobuf is a skill that combines gRPC and Protocol Buffers for building efficient, scalable APIs and microservices.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dyh1807/riscv-axi-sim/verify-simulator', 'community', 'dyh1807', 'riscv-axi-sim', 'dyh1807/riscv-axi-sim', 'verify-simulator', 0, 0, 30, '2026-03-08T01:57:15.422Z', '2026-03-08T02:07:23.349Z', '9bf65eaf64ceab9c348ec5468a026c29baf5bb0d224fd5356d0078219db11c44', '{"id":"dyh1807/riscv-axi-sim/verify-simulator","name":"verify-simulator","description":{"en":"The verify-simulator skill is designed for developers to test and validate RV32 simulations, including Linux kernel startup and baremetal benchmarking. It benefits embedded system developers and AI agent testers.","zh":"verify-simulator是一个单周期rv32模拟器，支持AXI接口，用于验证Linux内核启动和Baremetal基准测试","ja":"verify-simulatorはシングルサイクルrv32シミュレーターで、AXIインターフェースをサポートし、Linuxカーネル起動とBaremetalベンチマークテストの検証に使用される","ko":"verify-simulator는 단일 사이클 rv32 시뮬레이터로 AXI 인터페이스를 지원하며 Linux 커널 시작 및 Baremetal 벤치마크 테스트의 검증에 사용됩니다","es":"Verify-simulator es una herramienta de prueba para Linux y baremetal que utiliza AXI. Soporta pruebas de Linux Kernel y baremetal","fr":"Verify-simulator est un outil de test pour Linux et baremetal qui utilise AXI. Il prend en charge les tests de noyau Linux et baremetal","de":"Verify-simulator ist ein Testtool für Linux und Baremetal, das AXI verwendet. Es unterstützt Linux-Kernel- und Baremetal-Tests","pt":"O verify-simulator é uma ferramenta de simulação de rv32 com interface AXI para testes de Linux e baremetal.","ru":"Verify-simulator - это инструмент симуляции rv32 с интерфейсом AXI для тестирования Linux и baremetal.","ar":"verify-simulator هو أداة محاكاة rv32 مع واجهة AXI لاختبار لينكس وبرامج البارميتال"},"seo":{"title":{"en":"verify-simulator: RV32 Simulation Setup Guide | AI Agent ...","zh":"verify-simulator_setup_guide","ja":"verify-simulatorベストプラクティス","ko":"verify-simulator 설정 가이드","es":"Guía de configuración de verify-simulator para pruebas de...","fr":"Guide de configuration de verify-simulator pour les tests...","de":"Einrichtungsleitfaden für verify-simulator zur Durchführu...","pt":"Guia de Configuração do verify-simulator para Testes de S...","ru":"ИИ Агенты: Руководство по настройке verify-simulator для ...","ar":"دليل إعداد verify-simulator لأدوات الذكاء الاصطناعي للتحق..."},"description":{"en":"Discover how to validate Linux kernel startup and run CoreMark & Dhrystone benchmarks with verify-simulator - get started now and optimize your RV32 simulati...","zh":"了解verify-simulator的验证测试方法，包括Linux内核启动测试和Baremetal基准测试","ja":"verify-simulatorの検証テスト方法を学ぶ：Linuxカーネル起動テストとBaremetalベンチマークテスト","ko":"verify-simulator의 검증 테스트 방법에 대해 알아보세요: Linux 커널 시작 테스트 및 Baremetal 벤치마크 테스트","es":"Aprende a configurar y utilizar verify-simulator para pruebas de Linux y baremetal, incluyendo CoreMark y Dhrystone","fr":"Découvrez comment configurer et utiliser verify-simulator pour les tests Linux et baremetal, y compris CoreMark et Dhrystone","de":"Erfahren Sie, wie Sie verify-simulator für Linux- und Baremetal-Tests einrichten und verwenden, einschließlich CoreMark und Dhrystone","pt":"Aprenda a configurar o verify-simulator para testes de simulação de Linux e baremetal, incluindo CoreMark e Dhrystone","ru":"Изучите настройку verify-simulator для тестирования симуляции Linux и baremetal, включая CoreMark и Dhrystone","ar":"تعلم كيفية تكوين verify-simulator لاختبار محاكاة لينكس وبرامج البارميتال بما في ذلك.CoreMark و Dhrystone"},"definition":{"en":"verify-simulator is a single cycle RV32 simulator with AXI interface, used for verifying and testing Linux kernel startup and baremetal applications.","zh":"verify-simulator是一种用于验证Linux内核启动和Baremetal基准测试的单周期rv32模拟器","ja":"verify-simulatorは、Linuxカーネル起動とBaremetalベンチマークテストの検証に使用されるシングルサイクルrv32シミュレーターです","ko":"verify-simulator는 Linux 커널 시작 및 Baremetal 벤치마크 테스트의 검증에 사용되는 단일 사이클 rv32 시뮬레이터입니다","es":"Verify-simulator es un simulador de un solo ciclo rv32 con interfaz AXI para pruebas de Linux y baremetal","fr":"Verify-simulator est un simulateur de cycle unique rv32 avec interface AXI pour les tests Linux et baremetal","de":"Verify-simulator ist ein Simulator für einen einzigen Zyklus rv32 mit AXI-Schnittstelle für Linux- und Baremetal-Tests","pt":"O verify-simulator é uma ferramenta de simulação de rv32 que executa testes de Linux e baremetal.","ru":"Verify-simulator - это инструмент симуляции rv32, выполняющий тесты Linux и baremetal.","ar":"verify-simulator هو أداة محاكاة rv32 التي تقوم باختبار لينكس وبرامج البارميتال"},"features":{"en":["Supports Linux kernel startup testing with MMU and virtual-to-physical address translation","Runs CoreMark and Dhrystone benchmarks for baremetal applications","Utilizes timeout command for quick regression testing and stability validation","Executes baremetal/linux.bin and other binary files for simulation","Allows for verification of CPU core logic and AXI interface functionality"],"zh":["支持Linux内核启动测试","支持Baremetal基准测试（CoreMark和Dhrystone）","单周期rv32模拟器","AXI接口支持","超时验证功能"],"ja":["Linuxカーネル起動テストのサポート","Baremetalベンチマークテスト（CoreMarkとDhrystone）のサポート","シングルサイクルrv32シミュレーター","AXIインターフェースのサポート","タイムアウト検証機能"],"ko":["Linux 커널 시작 테스트 지원","Baremetal 벤치마크 테스트（CoreMark 및 Dhrystone）지원","단일 사이클 rv32 시뮬레이터","AXI 인터페이스 지원","타임아웃 검증 기능"],"es":["Soporte para pruebas de Linux Kernel","Pruebas de baremetal con CoreMark y Dhrystone","Interfaz AXI para simulación de hardware","Compatibilidad con timeout para pruebas de larga duración","Soporte para pruebas de arranque de Linux"],"fr":["Prise en charge des tests de noyau Linux","Tests baremetal avec CoreMark et Dhrystone","Interface AXI pour la simulation de matériel","Compatibilité avec timeout pour les tests de longue durée","Prise en charge des tests d''amorçage de Linux"],"de":["Unterstützung für Linux-Kernel-Tests","Baremetal-Tests mit CoreMark und Dhrystone","AXI-Schnittstelle für Hardware-Simulation","Kompatibilität mit Timeout für Langzeit-Tests","Unterstützung für Linux-Boot-Tests"],"pt":["Suporte a testes de Linux com MMU e endereçamento virtual","Testes de baremetal com CoreMark e Dhrystone","Interface AXI para simulação de rv32","Comando de timeout para testes de longa duração","Suporte a testes de simulação de Linux kernel"],"ru":["Поддержка тестирования Linux с MMU и виртуальной адресацией","Тесты baremetal с CoreMark и Dhrystone","Интерфейс AXI для симуляции rv32","Команда timeout для тестов длительного выполнения","Поддержка тестирования симуляции ядра Linux"],"ar":["دعم اختبار لينكس مع MMU وتحويل العناوين الافتراضي","اختبارات برامج البارميتال مع.CoreMark و Dhrystone","واجهة AXI لمحاكاة rv32","أمر timeout لاختبارات مدة طويلة","دعم اختبار محاكاة نواة لينكس"]},"keywords":{"en":["how to use verify-simulator","verify-simulator setup guide","RV32 simulation tools","Linux kernel startup testing","CoreMark and Dhrystone benchmarks","AXI interface verification","verify-simulator alternative","verify-simulator vs other simulators","verify-simulator install and configuration"],"zh":["verify-simulator","Linux内核启动测试","Baremetal基准测试","rv32模拟器","AXI接口","AIエージェント","单周期模拟器"],"ja":["verify-simulator","Linuxカーネル起動テスト","Baremetalベンチマークテスト","rv32シミュレーター","AXIインターフェース","AIエージェント","シングルサイクルシミュレーター"],"ko":["verify-simulator","Linux 커널 시작 테스트","Baremetal 벤치마크 테스트","rv32 시뮬레이터","AXI 인터페이스","AI 에이전트","단일 사이클 시뮬레이터"],"es":["verify-simulator","pruebas de Linux","pruebas de baremetal","CoreMark","Dhrystone","interfaz AXI","simulación de hardware","herramientas de prueba","desarrollo de software"],"fr":["verify-simulator","tests Linux","tests baremetal","CoreMark","Dhrystone","interface AXI","simulation de matériel","outils de test","développement de logiciels"],"de":["verify-simulator","Linux-Tests","Baremetal-Tests","CoreMark","Dhrystone","AXI-Schnittstelle","Hardware-Simulation","Testtools","Software-Entwicklung"],"pt":["verify-simulator","simulação de rv32","testes de Linux","baremetal","CoreMark","Dhrystone","interface AXI","timeout","simulação de núcleo de Linux"],"ru":["verify-simulator","симуляция rv32","тестирование Linux","baremetal","CoreMark","Dhrystone","интерфейс AXI","timeout","симуляция ядра Linux"],"ar":["verify-simulator","محاكاة rv32","اختبار لينكس","برامج البارميتال","CoreMark","Dhrystone","واجهة AXI","timeout","محاكاة نواة لينكس"]}},"owner":"dyh1807","repo":"riscv-axi-sim","repoPath":"dyh1807/riscv-axi-sim","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.422Z","topics":[],"category":"community","skillMd":{"name":"verify-simulator","description":"Simulator validation and test runs for Linux boot, CoreMark, and Dhrystone in this project; use when verifying simulator correctness or running quick regression commands.","bodyPreview":"# 模拟器验证技能 / Simulator Verification Skills\n\n本文档记录了项目编译后的常用验证测试方法。\n\n## 1. Linux Kernel 启动测试\n**用途**: 验证模拟器对 Linux 内核启动的支持，涉及复杂的虚实地址转换 (MMU) 和长时间运行。\n\n*   **基本命令**:\n    ```bash\n    ./a.out baremetal/linux.bin\n    ```\n*   **超时验证**:\n    由于 Linux 启动耗时较长，可以使用 `timeout` 命令（如设置 60 秒）来验证模拟器能否在指定时间内稳定运行，用于快速回归测试。\n    ```bash\n    timeout 60s ./a.out baremetal/linux.bin\n    ```\n\n## 2. Baremetal 基准测试 (CoreMark & Dhrystone)\n**用途**: 验证 CoreMark 和 Dhrystone 基准测试正确性。相比 Linux，这些是较小的裸机程序，不涉及复杂的地址转换，适合快速验证 CPU 核心逻辑。","body":"# 模拟器验证技能 / Simulator Verification Skills\n\n本文档记录了项目编译后的常用验证测试方法。\n\n## 1. Linux Kernel 启动测试\n**用途**: 验证模拟器对 Linux 内核启动的支持，涉及复杂的虚实地址转换 (MMU) 和长时间运行。\n\n*   **基本命令**:\n    ```bash\n    ./a.out baremetal/linux.bin\n    ```\n*   **超时验证**:\n    由于 Linux 启动耗时较长，可以使用 `timeout` 命令（如设置 60 秒）来验证模拟器能否在指定时间内稳定运行，用于快速回归测试。\n    ```bash\n    timeout 60s ./a.out baremetal/linux.bin\n    ```\n\n## 2. Baremetal 基准测试 (CoreMark & Dhrystone)\n**用途**: 验证 CoreMark 和 Dhrystone 基准测试正确性。相比 Linux，这些是较小的裸机程序，不涉及复杂的地址转换，适合快速验证 CPU 核心逻辑。\n\n*   **Dhrystone 测试**:\n    ```bash\n    ./a.out baremetal/new_dhrystone/dhrystone.bin\n    ```\n*   **CoreMark 测试**:\n    ```bash\n    ./a.out baremetal/new_coremark/coremark.bin\n    ```\n"},"lastSynced":"2026-03-08T02:07:23.349Z","agentAnalysis":{"suitability":{"en":"Ideal for Embedded System Agents and AI testers requiring RV32 simulation validation and Linux kernel startup testing.","zh":"适用于需要RV32模拟验证和Linux内核启动测试的嵌入式系统代理和AI测试人员。","ja":"RV32シミュレーションの検証とLinuxカーネル起動テストを必要とする組み込みシステムエージェントとAIテスターに最適です。","ko":"RV32 시뮬레이션 검증 및 Linux 커널 시작 테스트가 필요한 임베디드 시스템 에이전트 및 AI 테스터에 적합합니다.","es":"Ideal para agentes de sistemas embebidos y testers de IA que requieren validación de simulación RV32 y prueba de inicio del núcleo de Linux.","fr":"Idéal pour les agents de systèmes intégrés et les testeurs d''IA nécessitant une validation de simulation RV32 et un test de démarrage du noyau Linux.","de":"Ideal für Embedded-System-Agents und AI-Tester, die eine RV32-Simulationsvalidierung und einen Linux-Kernel-Starttest benötigen.","pt":"Ideal para agentes de sistemas incorporados e testadores de IA que exigem validação de simulação RV32 e teste de inicialização do kernel do Linux.","ru":"Идеально подходит для агентов встроенных систем и тестировщиков ИИ, требующих проверки симуляции RV32 и тестирования запуска ядра Linux.","ar":"مثالي للوكلاء أنظمة مدمجة ومتخصصي اختبار الذكاء الاصطناعي الذين يتطلبون التحقق من صحة محاكاة RV32 واختبار تشغيل نواة لينكس."},"recommendation":{"en":"Empowers agents to validate RV32 simulations, including Linux kernel startup and baremetal benchmarking using CoreMark and Dhrystone tests, ensuring reliable and efficient embedded system development with MMU and long-running process support.","zh":"赋予代理验证RV32模拟的能力，包括Linux内核启动和使用CoreMark和Dhrystone测试的裸机基准测试，确保可靠且高效的嵌入式系统开发，支持MMU和长时间运行的进程。","ja":"エージェントがRV32シミュレーションを検証できるようにし、CoreMarkとDhrystoneテストを使用したバレメタルベンチマーキングおよびLinuxカーネル起動を含み、MMUと長時間実行プロセスのサポートを備えた信頼性が高く効率的な組み込みシステム開発を可能にします。","ko":"에이전트가 RV32 시뮬레이션을 검증할 수 있도록 하여 CoreMark 및 Dhrystone 테스트를 사용한 베어메탈 벤치마킹 및 Linux 커널 시작을 포함하고 MMU 및 장기 실행 프로세스 지원을 통해 신뢰할 수 있고 효율적인 임베디드 시스템 개발을 가능하게 합니다.","es":"Habilita a los agentes a validar simulaciones RV32, incluyendo el inicio del núcleo de Linux y el benchmarking de baremetal con las pruebas CoreMark y Dhrystone, garantizando un desarrollo de sistemas embebidos confiable y eficiente con soporte de MMU y procesos de larga duración.","fr":"Permet aux agents de valider les simulations RV32, y compris le démarrage du noyau Linux et le benchmarking de baremetal à l''aide des tests CoreMark et Dhrystone, garantissant un développement de systèmes intégrés fiable et efficace avec une prise en charge de MMU et de processus longs.","de":"Ermächtigt die Agenten, RV32-Simulationen zu validieren, einschließlich des Linux-Kernel-Starts und des Baremetal-Benchmarkings mit den CoreMark- und Dhrystone-Tests, um eine zuverlässige und effiziente Entwicklung von Embedded-Systemen mit MMU- und Langzeitprozessunterstützung zu gewährleisten.","pt":"Habilita os agentes a validar simulações RV32, incluindo inicialização do kernel do Linux e benchmarking baremetal usando testes CoreMark e Dhrystone, garantindo desenvolvimento de sistemas incorporados confiável e eficiente com suporte a MMU e processos de longa execução.","ru":"Наделяет агентов возможностью проверить симуляции RV32, включая запуск ядра Linux и тестирование производительности baremetal с помощью тестов CoreMark и Dhrystone, обеспечивая надежную и эффективную разработку встроенных систем с поддержкой MMU и長-running процессов.","ar":"تمكين الوكلاء من التحقق من محاكاة RV32، بما في ذلك تشغيل نواة لينكس واختبار معايير الأداء لبرامج التشغيل الأساسية باستخدام اختبارات CoreMark و Dhrystone، مما يضمن تطويرا موثوقاً وفعّالاً لأنظمة مدمجة مع دعم MMU والعمليات التي تعمل لمدة طويلة."},"useCases":{"en":["Validating Linux kernel startup on RV32 simulations","Performing baremetal benchmarking with CoreMark and Dhrystone tests","Automating regression testing for RV32 simulations with timeout validation"],"zh":["在RV32模拟中验证Linux内核启动","使用CoreMark和Dhrystone测试进行裸机基准测试","使用超时验证自动化RV32模拟的回归测试"],"ja":["RV32シミュレーションでのLinuxカーネル起動の検証","CoreMarkとDhrystoneテストを使用したバレメタルベンチマーキング","タイムアウト検証を使用したRV32シミュレーションのリグレッションテストの自動化"],"ko":["RV32 시뮬레이션에서 Linux 커널 시작 검증","CoreMark 및 Dhrystone 테스트를 사용한 베어메탈 벤치마킹","타임아웃 검증을 사용한 RV32 시뮬레이션의 회귀 테스트 자동화"],"es":["Validar el inicio del núcleo de Linux en simulaciones RV32","Realizar benchmarking de baremetal con las pruebas CoreMark y Dhrystone","Automatizar las pruebas de regresión para simulaciones RV32 con validación de tiempo de espera"],"fr":["Valider le démarrage du noyau Linux sur des simulations RV32","Effectuer un benchmarking de baremetal avec les tests CoreMark et Dhrystone","Automatiser les tests de régression pour les simulations RV32 avec une validation de la commande de délai d''attente"],"de":["Überprüfen des Linux-Kernel-Starts in RV32-Simulationen","Durchführen von Baremetal-Benchmarking mit den CoreMark- und Dhrystone-Tests","Automatisieren von Regressions tests für RV32-Simulationen mit Timeout-Validierung"],"pt":["Validar a inicialização do kernel do Linux em simulações RV32","Realizar benchmarking baremetal com testes CoreMark e Dhrystone","Automatizar testes de regressão para simulações RV32 com validação de tempo de espera"],"ru":["Проверить запуск ядра Linux в симуляциях RV32","Провести тестирование производительности baremetal с помощью тестов CoreMark и Dhrystone","Автоматизировать тестирование регрессии для симуляций RV32 с проверкой времени ожидания"],"ar":["التحقق من تشغيل نواة لينكس في محاكاة RV32","إجراء اختبار معايير الأداء لبرامج التشغيل الأساسية باستخدام اختبارات CoreMark و Dhrystone","تأتمتة اختبارات الانحدار لمحاكاة RV32 مع التحقق من وقت الانتظار"]},"limitations":{"en":["Requires compiled project binaries","Limited to RV32 simulations and Linux kernel startup testing","Dependent on timeout command for regression testing"],"zh":["需要编译后的项目二进制文件","仅限RV32模拟和Linux内核启动测试","依赖于超时命令进行回归测试"],"ja":["コンパイル済みのプロジェクトバイナリが必要","RV32シミュレーションとLinuxカーネル起動テストに限定","リグレッションテストにはタイムアウトコマンドに依存"],"ko":["컴파일된 프로젝트 바이너리가 필요함","RV32 시뮬레이션 및 Linux 커널 시작 테스트로 제한됨","회귀 테스트는 타임아웃 명령에 의존"],"es":["Requiere binarios de proyecto compilados","Limitado a simulaciones RV32 y pruebas de inicio del núcleo de Linux","Dependiente del comando de tiempo de espera para pruebas de regresión"],"fr":["Nécessite des binaires de projet compilés","Limité aux simulations RV32 et aux tests de démarrage du noyau Linux","Dépend de la commande de délai d''attente pour les tests de régression"],"de":["Benötigt kompilierte Projektbinärdateien","Begrenzt auf RV32-Simulationen und Linux-Kernel-Starttests","Abhängig vom Timeout-Befehl für Regressions tests"],"pt":["Exige binários de projetos compilados","Limitado a simulações RV32 e teste de inicialização do kernel do Linux","Dependente do comando de tempo de espera para testes de regressão"],"ru":["Требует скомпилированных бинарных проектов","Ограничен симуляциями RV32 и тестированием запуска ядра Linux","Зависит от команды времени ожидания для тестирования регрессии"],"ar":["يتطلب ثنائيات مشروع مترجمة","محدود بمحاكاة RV32 واختبار تشغيل نواة لينكس","يعتمد على أمر وقت الانتظار لاختبارات الانحدار"]},"version":4},"contentHash":"9bf65eaf64ceab9c348ec5468a026c29baf5bb0d224fd5356d0078219db11c44","qualityScore":30}');
