INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dyh1807/riscv-axi-sim/verify-simulator', 'verify-simulator', 'dyh1807', 'riscv-axi-sim', 'community', 'verify-simulator dyh1807 riscv-axi-sim community The verify-simulator skill is designed for developers to test and validate RV32 simulations, including Linux kernel startup and baremetal benchmarking. It benefits embedded system developers and AI agent testers. verify-simulator是一个单周期rv32模拟器，支持AXI接口，用于验证Linux内核启动和Baremetal基准测试 verify-simulatorはシングルサイクルrv32シミュレーターで、AXIインターフェースをサポートし、Linuxカーネル起動とBaremetalベンチマークテストの検証に使用される verify-simulator는 단일 사이클 rv32 시뮬레이터로 AXI 인터페이스를 지원하며 Linux 커널 시작 및 Baremetal 벤치마크 테스트의 검증에 사용됩니다 Verify-simulator es una herramienta de prueba para Linux y baremetal que utiliza AXI. Soporta pruebas de Linux Kernel y baremetal Verify-simulator est un outil de test pour Linux et baremetal qui utilise AXI. Il prend en charge les tests de noyau Linux et baremetal Verify-simulator ist ein Testtool für Linux und Baremetal, das AXI verwendet. Es unterstützt Linux-Kernel- und Baremetal-Tests O verify-simulator é uma ferramenta de simulação de rv32 com interface AXI para testes de Linux e baremetal. Verify-simulator - это инструмент симуляции rv32 с интерфейсом AXI для тестирования Linux и baremetal. verify-simulator هو أداة محاكاة rv32 مع واجهة AXI لاختبار لينكس وبرامج البارميتال how to use verify-simulator verify-simulator setup guide RV32 simulation tools Linux kernel startup testing CoreMark and Dhrystone benchmarks AXI interface verification verify-simulator alternative verify-simulator vs other simulators verify-simulator install and configuration verify-simulator Linux内核启动测试 Baremetal基准测试 rv32模拟器 AXI接口 AIエージェント 单周期模拟器 Supports Linux kernel startup testing with MMU and virtual-to-physical address translation Runs CoreMark and Dhrystone benchmarks for baremetal applications Utilizes timeout command for quick regression testing and stability validation Executes baremetal/linux.bin and other binary files for simulation Allows for verification of CPU core logic and AXI interface functionality verify-simulator is a single cycle RV32 simulator with AXI interface, used for verifying and testing Linux kernel startup and baremetal applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('banteg/crimson/crimson-release', 'community', 'banteg', 'crimson', 'banteg/crimson', 'crimson-release', 0, 0, 30, '2026-03-08T01:57:15.430Z', '2026-03-08T02:07:31.930Z', '4975b5ba3d57d80a57b0694c855b87b7025bfcabf1f4726f532a85cddf31262e', '{"id":"banteg/crimson/crimson-release","name":"crimson-release","description":{"en":"crimson-release is a faithful rewrite of Crimsonland 1.9.93 from 2003, benefiting developers who need a clean release commit and tag. It provides a workflow for producing a release commit and tag.","zh":"Crimson Release是一个版本控制工具，用于管理Git仓库和版本号。它提供了自动化脚本和工作流来简化版本管理过程","ja":"Crimson Releaseは、Gitリポジトリとバージョン番号を管理するためのバージョン管理ツールです。自動化スクリプトとワークフローを提供してバージョン管理プロセスを簡素化します","ko":"Crimson Release는 Git 저장소 및 버전 번호를 관리하기 위한 버전 관리 도구입니다. 자동화 스크립트 및 워크플로우를 제공하여 버전 관리 프로세스를 간소화합니다","es":"crimson-release es una réplica fiel de crimsonland 1.9.93, que permite a los desarrolladores crear una versión limpia del repositorio mediante una lista de verificación","fr":"crimson-release est une réécriture fidèle de crimsonland 1.9.93, qui permet aux développeurs de créer une version propre du référentiel à l''aide d''une liste de vérification","de":"crimson-release ist eine treue Neuimplementierung von crimsonland 1.9.93, die es Entwicklern ermöglicht, eine saubere Version des Repositories mithilfe einer Prüfliste zu erstellen","pt":"O Crimson Release é uma reescrita fiel do Crimsonland 1.9.93, oferecendo funcionalidades avançadas de desenvolvimento de AI. Aprenda a configurá-lo com nosso guia","ru":"Crimson Release - это версия Crimsonland 1.9.93, предлагающая расширенные возможности для ИИ Агентов. Узнайте, как его настроить","ar":"Crimson Release هو إعادة كتابة متوافقة مع Crimsonland 1.9.93، يقدم ميزات متقدمة لبرمجة AI. تعرف على كيفية إعداده"},"seo":{"title":{"en":"crimson-release: Faithful Rewrite Setup Guide | AI Agent ...","zh":"Crimson Release Setup Guide - AIエージェント版本控制","ja":"Crimson Release Setup Guide - AIエージェントのためのバージョン管理","ko":"Crimson Release Setup Guide - AI 툴 버전 관리","es":"Guía de configuración de crimson-release para desarrollad...","fr":"Guide de mise en place de crimson-release pour les dévelo...","de":"Einrichtungsleitfaden für crimson-release für Entwickler","pt":"Guia de Configuração do Crimson Release: Ferramentas de D...","ru":"Настройка Crimson Release: Лучшие Практики для ИИ Агентов","ar":"دليل إعداد Crimson Release: أدوات متقدمة لبرمجة AI"},"description":{"en":"Get started with crimson-release, a 2003 Crimsonland 1.9.93 rewrite. Learn how to produce a clean release commit and tag with our step-by-step guide.","zh":"了解Crimson Release的技术细节，包括版本控制、Git工作流和自动化脚本","ja":"Crimson Releaseの技術的詳細を学び、バージョン管理、Gitワークフロー、自動化スクリプトをマスターする","ko":"Crimson Release의 기술적 세부 사항을 확인하고 버전 관리, Git 워크플로 및 자동화 스크립트를 자동화하십시오","es":"Aprende a configurar y utilizar crimson-release, una réplica fiel de crimsonland 1.9.93, con nuestra guía paso a paso para desarrolladores","fr":"Découvrez comment configurer et utiliser crimson-release, une réécriture fidèle de crimsonland 1.9.93, avec notre guide étape par étape pour les développeurs","de":"Erfahren Sie, wie Sie crimson-release, eine treue Neuimplementierung von crimsonland 1.9.93, konfigurieren und verwenden können, mit unserer Schritt-für-Schr...","pt":"Aprenda a configurar o Crimson Release, uma reescrita fiel do Crimsonland 1.9.93, e descubra suas funcionalidades avançadas de desenvolvimento de AI","ru":"Узнайте, как настроить Crimson Release, версию Crimsonland 1.9.93, и откройте для себя его расширенные возможности для ИИ Агентов","ar":"تعرف على كيفية إعداد Crimson Release، إعادة كتابة متوافقة مع Crimsonland 1.9.93، واكتشف ميزاته المتقدمة لبرمجة AI"},"definition":{"en":"crimson-release is a faithful rewrite of Crimsonland 1.9.93 from 2003, providing a clean release commit and tag workflow.","zh":"Crimson Release是一种AIエージェント工具，用于管理Git版本控制和自动化脚本","ja":"Crimson Releaseは、Gitのバージョン管理と自動化スクリプトを管理するためのAIエージェントツールです","ko":"Crimson Release는 Git 버전 관리 및 자동화 스크립트를 관리하기 위한 AI 툴입니다","es":"crimson-release es una herramienta de línea de comandos que automatiza el proceso de creación de una versión de lanzamiento para un repositorio de código","fr":"crimson-release est un outil en ligne de commande qui automatise le processus de création d''une version de publication pour un référentiel de code","de":"crimson-release ist ein Kommandozeilen-Tool, das den Prozess der Erstellung einer Release-Version für ein Code-Repository automatisiert","pt":"O Crimson Release é uma ferramenta de desenvolvimento de AI que reescreve o Crimsonland 1.9.93","ru":"Crimson Release - это инструмент для ИИ Агентов, представляющий собой версию Crimsonland 1.9.93","ar":"Crimson Release هو أداة برمجة AI التي تعيد كتابة Crimsonland 1.9.93"},"features":{"en":["Ensures a clean working tree using `git status --porcelain`","Runs checks using `just check`","Bumps version using `uv version --bump minor`","Supports dev-only bump using `uv version`","Produces a clean release commit and tag"],"zh":["自动化版本控制","Git工作流管理","版本号管理","自动化脚本执行","支持just check和uv version命令"],"ja":["自動化されたバージョン管理","Gitワークフローの管理","バージョン番号の管理","自動化スクリプトの実行","just checkとuv versionコマンドのサポート"],"ko":["자동 버전 관리","Git 워크플로우 관리","버전 번호 관리","자동화 스크립트 실행","just check 및 uv version 명령어 지원"],"es":["Compatibilidad con Git para garantizar la integridad del repositorio","Ejecución de comandos como `just check` y `uv version` para la verificación y actualización de la versión","Soporte para la creación de etiquetas y confirmación antes de la publicación","Integración con la línea de comandos para una configuración y ejecución flexibles"],"fr":["Compatibilité avec Git pour assurer l''intégrité du référentiel","Exécution de commandes telles que `just check` et `uv version` pour la vérification et la mise à jour de la version","Prise en charge de la création d''étiquettes et de la confirmation avant la publication","Intégration avec la ligne de commande pour une configuration et une exécution flexibles"],"de":["Kompatibilität mit Git, um die Integrität des Repositories sicherzustellen","Ausführung von Befehlen wie `just check` und `uv version` für die Überprüfung und Aktualisierung der Version","Unterstützung für die Erstellung von Tags und Bestätigung vor der Veröffentlichung","Integration mit der Kommandozeile für eine flexible Konfiguration und Ausführung"],"pt":["Suporte à execução de comandos Git","Verificação de integridade do repositório com `git status --porcelain`","Compatibilidade com `just check` para testes","Incremento de versão com `uv version --bump minor`","Controle de fluxo de trabalho com `git commit`, `git tag` e `git push`"],"ru":["Поддержка выполнения команд Git","Проверка целостности репозитория с `git status --porcelain`","Совместимость с `just check` для тестирования","Инкремент версии с `uv version --bump minor`","Контроль рабочего процесса с `git commit`, `git tag` и `git push`"],"ar":["دعم تنفيذ أوامر Git","فحص سلامة المستودع مع `git status --porcelain`","توافق مع `just check` للاختبارات","زيادة الإصدار مع `uv version --bump minor`","مراقبة تدفق العمل مع `git commit` و `git tag` و `git push`"]},"keywords":{"en":["how to use crimson-release","crimson-release setup guide","crimson-release alternative","crimson-release vs Crimsonland","crimson-release install","what is crimson-release","crimson-release workflow","crimson-release git workflow"],"zh":["Crimson Release","AIエージェント","版本控制","Git","自动化脚本","版本管理","just check","uv version"],"ja":["Crimson Release","AIエージェント","バージョン管理","Git","自動化スクリプト","バージョン番号","just check","uv version"],"ko":["Crimson Release","AI 툴","버전 관리","Git","자동화 스크립트","버전 번호","just check","uv version"],"es":["crimson-release","herramientas de línea de comandos","automatización de lanzamientos","Git","just check","uv version","etiquetas de versión","desarrollo de software"],"fr":["crimson-release","outils en ligne de commande","automatisation des publications","Git","just check","uv version","étiquettes de version","développement de logiciels"],"de":["crimson-release","Kommandozeilen-Tools","Automatisierung von Releases","Git","just check","uv version","Versionstags","Software-Entwicklung"],"pt":["Crimson Release","desenvolvimento de AI","ferramentas de desenvolvimento","Git","UV","Just","repositório","controle de versão","fluxo de trabalho"],"ru":["Crimson Release","ИИ Агенты","инструменты разработки","Git","UV","Just","репозиторий","контроль версий","рабочий процесс"],"ar":["Crimson Release","برمجة AI","أدوات برمجة","Git","UV","Just","مستودع","مراقبة الإصدار","تدفق العمل"]}},"owner":"banteg","repo":"crimson","repoPath":"banteg/crimson","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.430Z","topics":[],"category":"community","skillMd":{"name":"crimson-release","description":"Run the Crimson release checklist (just check, uv version bump, uv lock), then create a conventional-commit release commit, tag it, and push. Default bump is minor (use dev bump when needed).","bodyPreview":"# Crimson Release\n\n## Goal\n\nProduce a clean release commit + tag for this repo by running the checklist below in order.\n\n## Workflow\n\n### Pre-flight\n\n- Ensure the working tree is clean: `git status --porcelain` prints nothing.\n- Ensure the branch is correct (usually `master`).\n- Ask for confirmation before any of: `git commit`, `git tag`, `git push`.\n\n### 0) Checks\n\nRun: `just check`\n\n### 1) Bump version (default: minor)\n\nRun: `uv version --bump minor`\n\nIf you need a dev-only bump instead (e.g.,","body":"# Crimson Release\n\n## Goal\n\nProduce a clean release commit + tag for this repo by running the checklist below in order.\n\n## Workflow\n\n### Pre-flight\n\n- Ensure the working tree is clean: `git status --porcelain` prints nothing.\n- Ensure the branch is correct (usually `master`).\n- Ask for confirmation before any of: `git commit`, `git tag`, `git push`.\n\n### 0) Checks\n\nRun: `just check`\n\n### 1) Bump version (default: minor)\n\nRun: `uv version --bump minor`\n\nIf you need a dev-only bump instead (e.g., `0.1.0.dev29 -> 0.1.0.dev30`), run: `uv version --bump dev`\n\nCapture the resulting version string (use `uv version` if needed).\n\n### 2) Refresh lockfile\n\nRun: `uv lock`\n\n### 3) Commit\n\n- Verify the diff is expected: `git diff --stat`.\n- Stage: `git add -A`.\n- Commit using conventional commits (example): `git commit -m \"chore(release): bump version to <version>\"`.\n\n### 4) Tag\n\n- Prefer an annotated tag.\n- Derive the tag from the version (common pattern): `v<version>`.\n- If tag format is unclear, ask before creating it.\n\nExample:\n\n```bash\ngit tag -a \"v<version>\" -m \"v<version>\"\n```\n\n### 5) Push\n\n- Push branch and tag.\n- Prefer: `git push --follow-tags`.\n- If the remote/tag needs to be explicit, push both separately.\n\n## Sanity checks\n\n- Ensure only expected files changed (typically `pyproject.toml` and `uv.lock`).\n- Stop and ask if new failures appear or unexpected files change.\n"},"lastSynced":"2026-03-08T02:07:31.930Z","agentAnalysis":{"suitability":{"en":"Ideal for Git-based AI Agents needing automated release management and version control.","zh":"适用于需要自动化发布管理和版本控制的基于 Git 的 AI Agent。","ja":"Git ベースの AI エージェントが自動化されたリリース管理とバージョン管理を必要とする場合に適しています。","ko":"자동화된 릴리스 관리 및 버전 관리가 필요한 Git 기반 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA basados en Git que necesitan administración de versiones y control de versiones automatizados.","fr":"Idéal pour les agents IA basés sur Git qui nécessitent une gestion de version et un contrôle de version automatisés.","de":"Ideal für Git-basierte KI-Agents, die eine automatisierte Versionsverwaltung und -kontrolle benötigen.","pt":"Ideal para Agentes de IA baseados em Git que necessitam de gerenciamento de lançamento automatizado e controle de versão.","ru":"Идеально для агентов ИИ на основе Git, которым требуется автоматизированное управление выпусками и контроль версий.","ar":"مثالية لعميل الذكاء الاصطناعي المستند إلى Git الذين يحتاجون إلى إدارة الإصدار الآلية ومراقبة الإصدار."},"recommendation":{"en":"Empowers agents to produce clean release commits and tags using Git workflows, incorporating tools like `just check` and `uv version` for streamlined development and version bumping, including minor and dev-only bumps.","zh":"赋予代理生成干净的发布提交和标签，使用 Git 工作流，并结合 `just check` 和 `uv version` 等工具，用于简化开发和版本更新，包括次要和开发者仅更新。","ja":"エージェントにクリーンなリリースコミットとタグを生成させることで、Git ワークフローを使用し、`just check` や `uv version` などのツールを組み込んで開発とバージョン更新を簡素化します。マイナーアップデートや開発者専用のアップデートも含みます。","ko":"에이전트가 깨끗한 릴리스 커밋과 태그를 생성하도록 허용하여 Git 워크플로우를 사용하고 `just check` 및 `uv version`와 같은 도구를 통합하여 개발 및 버전 업데이트를 간소화합니다. 마이너 업데이트와 개발자 전용 업데이트도 포함됩니다.","es":"Habilita a los agentes a producir confirmaciones y etiquetas de lanzamiento limpias utilizando flujos de trabajo de Git, incorporando herramientas como `just check` y `uv version` para un desarrollo y aumento de versión optimizados, incluyendo aumentos menores y solo para desarrollo.","fr":"Permet aux agents de produire des validations et des balises de version propres en utilisant les flux de travail Git, en intégrant des outils tels que `just check` et `uv version` pour un développement et une mise à jour de version rationalisés, y compris les mises à jour mineures et de développement uniquement.","de":"Ermächtigt die Agents, saubere Release-Commits und -Tags mit Git-Workflows zu erstellen, indem Tools wie `just check` und `uv version` für eine optimierte Entwicklung und Versionsverwaltung verwendet werden, einschließlich minorer und nur für die Entwicklung bestimmter Versionssprünge.","pt":"Habilita os agentes a produzir commits e tags de lançamento limpos usando fluxos de trabalho do Git, incorporando ferramentas como `just check` e `uv version` para desenvolvimento e incremento de versão simplificados, incluindo incrementos menores e apenas para desenvolvedores.","ru":"Наделяет агентов возможностью производить чистые коммиты и теги выпусков с помощью рабочих процессов Git, включая инструменты như `just check` и `uv version` для упрощенного развития и увеличения версии, включая незначительные и только для разработчиков.","ar":"تمكين الوكيل من إنتاج التزامات إصدار نظيفة و علامات باستخدام تدفقات العمل Git، ودمج أدوات مثل `just check` و `uv version` لتطوير وزيادة الإصدار المبسّطة، بما في ذلك زيادات صغيرة وเฉพาะ للمطورين فقط."},"useCases":{"en":["Automating release commit generation","Bumping version numbers for new releases","Validating repository status before pushing changes"],"zh":["自动化发布提交生成","为新发布更新版本号","在推送更改之前验证仓库状态"],"ja":["リリースコミットの自動生成","新しいリリースのバージョン番号の更新","変更をプッシュする前にリポジトリの状態を検証する"],"ko":["릴리스 커밋 자동 생성","새 릴리스를 위한 버전 번호 업데이트","변경 사항을 푸시하기 전에 리포지토리 상태 확인"],"es":["Generación automática de commits de lanzamiento","Actualización de números de versión para nuevos lanzamientos","Validación del estado del repositorio antes de realizar cambios"],"fr":["Génération automatique de validations de version","Mise à jour des numéros de version pour les nouveaux lancements","Validation de l''état du référentiel avant d''apporter des modifications"],"de":["Automatisierte Generierung von Release-Commits","Aktualisierung von Versionsnummern für neue Releases","Überprüfung des Repository-Status vor dem Einchecken von Änderungen"],"pt":["Geração automática de commit de lançamento","Aumento de números de versão para novos lançamentos","Validação do status do repositório antes de enviar alterações"],"ru":["Автоматическая генерация коммитов выпуска","Увеличение номеров версий для новых выпусков","Проверка статуса репозитория перед отправкой изменений"],"ar":["التوليد الآلي للالتزام بالنسخة","زيادة أرقام الإصدار للنشرات الجديدة","التحقق من حالة المستودع قبل إرسال التغييرات"]},"limitations":{"en":["Requires Git repository access","Needs `just` and `uv` tools installed","Limited to Git-based version control"],"zh":["需要 Git 仓库访问","需要安装 `just` 和 `uv` 工具","仅限 Git 基础的版本控制"],"ja":["Git リポジトリへのアクセスが必要","`just` と `uv` ツールのインストールが必要","Git ベースのバージョン管理のみ"],"ko":["Git 리포지토리 액세스가 필요","`just` 및 `uv` 도구 설치 필요","Git 기반 버전 관리만 제한"],"es":["Requiere acceso al repositorio de Git","Necesita las herramientas `just` y `uv` instaladas","Limitado al control de versiones basado en Git"],"fr":["Nécessite un accès au référentiel Git","Nécessite les outils `just` et `uv` installés","Limité au contrôle de version basé sur Git"],"de":["Benötigt Zugriff auf das Git-Repository","Benötigt die Tools `just` und `uv` installiert","Begrenzt auf Git-basiertes Versionskontrollsystem"],"pt":["Requer acesso ao repositório Git","Necessita das ferramentas `just` e `uv` instaladas","Limitado ao controle de versão baseado em Git"],"ru":["Требует доступа к репозиторию Git","Требует установленных инструментов `just` и `uv`","Ограничен контроль версий на основе Git"],"ar":["يتطلب الوصول إلى مستودع Git","يحتاج إلى تثبيت أدوات `just` و `uv`","محدود بالمراقبة الإصدار المستندة إلى Git"]},"version":4},"contentHash":"4975b5ba3d57d80a57b0694c855b87b7025bfcabf1f4726f532a85cddf31262e","qualityScore":30}');
