INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('banteg/crimson/crimson-release', 'crimson-release', 'banteg', 'crimson', 'community', 'crimson-release banteg crimson community crimson-release is a faithful rewrite of Crimsonland 1.9.93 from 2003, benefiting developers who need a clean release commit and tag. It provides a workflow for producing a release commit and tag. Crimson Release是一个版本控制工具，用于管理Git仓库和版本号。它提供了自动化脚本和工作流来简化版本管理过程 Crimson Releaseは、Gitリポジトリとバージョン番号を管理するためのバージョン管理ツールです。自動化スクリプトとワークフローを提供してバージョン管理プロセスを簡素化します Crimson Release는 Git 저장소 및 버전 번호를 관리하기 위한 버전 관리 도구입니다. 자동화 스크립트 및 워크플로우를 제공하여 버전 관리 프로세스를 간소화합니다 crimson-release es una réplica fiel de crimsonland 1.9.93, que permite a los desarrolladores crear una versión limpia del repositorio mediante una lista de verificación crimson-release est une réécriture fidèle de crimsonland 1.9.93, qui permet aux développeurs de créer une version propre du référentiel à l''aide d''une liste de vérification crimson-release ist eine treue Neuimplementierung von crimsonland 1.9.93, die es Entwicklern ermöglicht, eine saubere Version des Repositories mithilfe einer Prüfliste zu erstellen O Crimson Release é uma reescrita fiel do Crimsonland 1.9.93, oferecendo funcionalidades avançadas de desenvolvimento de AI. Aprenda a configurá-lo com nosso guia Crimson Release - это версия Crimsonland 1.9.93, предлагающая расширенные возможности для ИИ Агентов. Узнайте, как его настроить Crimson Release هو إعادة كتابة متوافقة مع Crimsonland 1.9.93، يقدم ميزات متقدمة لبرمجة AI. تعرف على كيفية إعداده how to use crimson-release crimson-release setup guide crimson-release alternative crimson-release vs Crimsonland crimson-release install what is crimson-release crimson-release workflow crimson-release git workflow Crimson Release AIエージェント 版本控制 Git 自动化脚本 版本管理 just check uv version Ensures a clean working tree using `git status --porcelain` Runs checks using `just check` Bumps version using `uv version --bump minor` Supports dev-only bump using `uv version` Produces a clean release commit and tag crimson-release is a faithful rewrite of Crimsonland 1.9.93 from 2003, providing a clean release commit and tag workflow.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('j5ik2o/cqrs-es-spec-kit-js/event-storming', 'community', 'j5ik2o', 'cqrs-es-spec-kit-js', 'j5ik2o/cqrs-es-spec-kit-js', 'event-storming', 0, 0, 30, '2026-03-08T01:57:15.431Z', '2026-03-08T02:07:32.294Z', '5ebfde992d9fb2fe80be7dcd58cdeb8900ea8ee9b1979d97e691f38392b6eafe', '{"id":"j5ik2o/cqrs-es-spec-kit-js/event-storming","name":"event-storming","description":{"en":"Event storming is a technique for domain modeling that helps developers identify and organize important events. It benefits developers by providing a clear understanding of domain behavior.","zh":"Event Storming 是一种用于梳理事件和命令的技术，通过确立事件名和动词的使用，帮助开发者整理业务逻辑","ja":"イベントストーミングは、イベントとコマンドを整理する技術で、イベント名と動詞の使用を確立することで、開発者がビジネスロジックを整理するのに役立ちます","ko":"이벤트 스토밍은 이벤트와 명령어를 정리하는 기술로, 이벤트 이름과 동사의 사용을 확립하여 개발자가 비즈니스 로직을 정리하는 데 도움이 됩니다","es":"Event Storming es una técnica para organizar eventos y comandos en el desarrollo de software. Ayuda a identificar y nombrar eventos de manera efectiva.","fr":"L''Event Storming est une technique pour organiser les événements et les commandes dans le développement de logiciels. Elle aide à identifier et à nommer les événements de manière efficace.","de":"Event Storming ist eine Technik zur Organisation von Ereignissen und Befehlen in der Softwareentwicklung. Sie hilft bei der Identifizierung und Benennung von Ereignissen auf effektive Weise.","pt":"O Event Storming é uma técnica de modelagem de domínio que ajuda a identificar e organizar eventos importantes no desenvolvimento de software.","ru":"Event Storming - это техника моделирования домена, которая помогает выявить и организовать важные события в разработке программного обеспечения.","ar":"event-storming هو تقنية نمذجة miền تساعد على تحديد وتنظيم الأحداث المهمة في تطوير البرمجيات."},"seo":{"title":{"en":"Event Storming: Best Practices Setup Guide | AI Agent Skill","zh":"Event Storming 设置指南 - AIエージェント","ja":"イベントストーミング セットアップ ガイド - AIエージェント","ko":"이벤트 스토밍 설정 가이드 - AI 에이전트","es":"Guía de configuración de Event Storming para desarrolladores","fr":"Guide de mise en place de l''Event Storming pour les dével...","de":"Einrichtungsleitfaden für Event Storming für Entwickler","pt":"Guia de Configuração do Event Storming: Melhores Práticas","ru":"Настройка ИИ Агента Event Storming: Руководство","ar":"دليل إعداد.event-storming: أفضل الممارسات"},"description":{"en":"Unlock efficient domain modeling with event-storming. Discover how to apply critical rules and simplify event/command management. Get started now!","zh":"了解 Event Storming 的技术细节和最佳实践，包括事件命名、命令与事件的对应、动词的使用等","ja":"イベントストーミングの技術的詳細とベストプラクティスを学ぶ、イベント命名、コマンドとイベントの対応、動詞の使用など","ko":"이벤트 스토밍의 기술적 세부 사항과最佳实践을 학습하세요. 이벤트 명명, 명령어 및 이벤트의 대응, 동사의 사용 등","es":"Aprende a implementar Event Storming en tu proyecto con nuestra guía detallada para desarrolladores. Mejora la organización de eventos y comandos.","fr":"Découvrez comment mettre en place l''Event Storming dans votre projet avec notre guide détaillé pour les développeurs. Améliorez l''organisation des événements...","de":"Erfahren Sie, wie Sie Event Storming in Ihrem Projekt implementieren können, mit unserer detaillierten Anleitung für Entwickler. Verbessern Sie die Organisat...","pt":"Aprenda a configurar o Event Storming com nossas melhores práticas e melhore a sua experiência de desenvolvimento com ferramentas de IA","ru":"Узнайте, как настроить ИИ Агента Event Storming с нашим руководством и улучшите свой опыт разработки с инструментами ИИ","ar":"تعلم كيفية إعداد.event-storming بأفضل الممارسات لدينا وتحسين تجربة التطوير الخاصة بك مع أدوات الـ AI"},"definition":{"en":"Event-storming is a domain modeling technique that involves identifying and organizing important events in a domain, using a set of rules to ensure consistency and clarity.","zh":"Event Storming 是一种 Domain-Driven Design 技术，用于梳理事件和命令","ja":"イベントストーミングは、Domain-Driven Design 技術の一つで、イベントとコマンドを整理するために使用されます","ko":"이벤트 스토밍은 도메인 주도 설계 기술 중 하나로, 이벤트와 명령어를 정리하는 데 사용됩니다","es":"Event Storming es una técnica de desarrollo de software que se centra en la identificación y organización de eventos importantes.","fr":"L''Event Storming est une technique de développement de logiciels qui se concentre sur l''identification et l''organisation d''événements importants.","de":"Event Storming ist eine Software-Entwicklungstechnik, die sich auf die Identifizierung und Organisation wichtiger Ereignisse konzentriert.","pt":"Event Storming é uma técnica de modelagem de domínio que se concentra em eventos importantes.","ru":"Event Storming - это техника моделирования домена, которая фокусируется на важных событиях.","ar":"event-storming هو تقنية نمذجة miền تركز على الأحداث المهمة."},"features":{"en":["Identifies important domain events using verb-based naming conventions","Ensures one-to-one correspondence between commands and events","Supports event/command management using a standardized naming scheme","Enables clear expression of relationships using ''R(, )'' notation","Facilitates organization of events, commands, and aggregates using a structured approach"],"zh":["事件命名和动词的使用","命令与事件的对应","动词的使用和区分","关系的表达和整理","事件和命令的梳理"],"ja":["イベント命名と動詞の使用","コマンドとイベントの対応","動詞の使用と区別","関係の表現と整理","イベントとコマンドの整理"],"ko":["이벤트 명명과 동사의 사용","명령어와 이벤트의 대응","동사의 사용과 구분","관계의 표현과 정리","이벤트와 명령어의 정리"],"es":["Identificación de eventos importantes con verbos en forma pasada","Organización de eventos y comandos con la regla de 1 comando por evento","Uso de la notación ''R(, )'' para expresar relaciones","Correspondencia entre nombres de comandos y eventos","Evitación de la confusión entre eventos con verbos diferentes"],"fr":["Identification d''événements importants avec des verbes à la forme passée","Organisation d''événements et de commandes avec la règle de 1 commande par événement","Utilisation de la notation ''R(, )'' pour exprimer des relations","Correspondance entre les noms de commandes et les événements","Évitement de la confusion entre les événements avec des verbes différents"],"de":["Identifizierung wichtiger Ereignisse mit Verben in der Vergangenheitsform","Organisation von Ereignissen und Befehlen mit der Regel von 1 Befehl pro Ereignis","Verwendung der Notation ''R(, )'' zur Ausdruck von Beziehungen","Übereinstimmung zwischen Befehlsnamen und Ereignissen","Vermeidung von Verwechslungen zwischen Ereignissen mit unterschiedlichen Verben"],"pt":["Identificação de eventos importantes no domínio","Organização de eventos em uma estrutura lógica","Uso de verbos no passado para nomear eventos","Distinção clara entre comandos e eventos","Uso de relacionamentos para conectar eventos"],"ru":["Выявление важных событий в домене","Организация событий в логической структуре","Использование глаголов в прошедшем времени для названия событий","Чёткое различие между командами и событиями","Использование отношений для соединения событий"],"ar":["تحديد الأحداث المهمة في المجال","تنظيم الأحداث في هيكل منطقي","استخدام الأفعال الماضية لتسمية الأحداث","تمييز واضح بين الأوامر والأحداث","استخدام العلاقات لربط الأحداث"]},"keywords":{"en":["how to use event-storming","event-storming setup guide","event-storming vs domain-driven design","event-storming alternative approaches","event-storming install and configuration","what is event-storming in software development"],"zh":["Event Storming","Domain-Driven Design","事件命名","命令与事件","动词的使用","关系的表达","AIエージェント","イベントストーミング"],"ja":["イベントストーミング","Domain-Driven Design","イベント命名","コマンドとイベント","動詞の使用","関係の表現","AIエージェント","イベントストーミング"],"ko":["이벤트 스토밍","도메인 주도 설계","이벤트 명명","명령어와 이벤트","동사의 사용","관계의 표현","AI 에이전트","이벤트 스토밍"],"es":["Event Storming","desarrollo de software","organización de eventos","comandos","verbos en forma pasada","regla de 1 comando por evento","notación R(, )","herramientas de desarrollo","técnica de desarrollo"],"fr":["Event Storming","développement de logiciels","organisation d''événements","commandes","verbes à la forme passée","règle de 1 commande par événement","notation R(, )","outils de développement","technique de développement"],"de":["Event Storming","Software-Entwicklung","Ereignisorganisation","Befehle","Verben in der Vergangenheitsform","Regel von 1 Befehl pro Ereignis","Notation R(, )","Entwicklungstools","Entwicklungstechnik"],"pt":["event storming","modelagem de domínio","desenvolvimento de software","ferramentas de IA","melhores práticas","guias de configuração","tecnologia de desenvolvimento"],"ru":["event storming","моделирование домена","разработка программного обеспечения","инструменты ИИ","лучшие практики","руководства по настройке","технология разработки"],"ar":["event-storming","نمذجة المجال","تطوير البرمجيات","أدوات الـ AI","أفضل الممارسات","دلائل الإعداد","تكنولوجيا التطوير"]}},"owner":"j5ik2o","repo":"cqrs-es-spec-kit-js","repoPath":"j5ik2o/cqrs-es-spec-kit-js","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.431Z","topics":[],"category":"community","skillMd":{"name":"event-storming","description":"Event Stormingでイベント（動詞の過去形）を中心に、コマンド・集約・リードモデルを抽出/命名/レビューする作業に使う","bodyPreview":"# Event Storming\n\n## 使う場面\n- 要件や仕様にイベントの説明が不足している\n- イベント名の命名やイベント/リソースの区別に迷う\n- Event Storming成果物（イベント/コマンド/集約/リードモデル）を整理・追記したい\n\n## ルール（要点）\n- イベントはドメインの重要な出来事で、動詞の過去形で表現する\n- イベントはビジネスの重要な振る舞いを表すため、イベント中心に整理する\n- 原則として **1コマンドに対して1イベント** とし、1コマンドで複数イベントを生成しない\n- コマンド名の動詞とイベント名の動詞は対応させる（例: `AddCartItem` → `CartItemAdded`）\n- 動詞が異なる場合は別イベントとみなし、混同しない（例: `AppendCartItem` に `CartItemAdded` を割り当てない）\n- 関係の表現は「R(, )」で整理する\n\n詳細は `references/event-storming-notes.md` を参照する。\n\n## 手順（簡潔）\n1. 重要な出来事を列挙し、イベント名を過去形で確定す","body":"# Event Storming\n\n## 使う場面\n- 要件や仕様にイベントの説明が不足している\n- イベント名の命名やイベント/リソースの区別に迷う\n- Event Storming成果物（イベント/コマンド/集約/リードモデル）を整理・追記したい\n\n## ルール（要点）\n- イベントはドメインの重要な出来事で、動詞の過去形で表現する\n- イベントはビジネスの重要な振る舞いを表すため、イベント中心に整理する\n- 原則として **1コマンドに対して1イベント** とし、1コマンドで複数イベントを生成しない\n- コマンド名の動詞とイベント名の動詞は対応させる（例: `AddCartItem` → `CartItemAdded`）\n- 動詞が異なる場合は別イベントとみなし、混同しない（例: `AppendCartItem` に `CartItemAdded` を割り当てない）\n- 関係の表現は「R(, )」で整理する\n\n詳細は `references/event-storming-notes.md` を参照する。\n\n## 手順（簡潔）\n1. 重要な出来事を列挙し、イベント名を過去形で確定する\n2. 各イベントに対応するコマンドを逆算して決める\n3. イベントを受け取る集約を決め、境界を調整する\n4. クエリで必要なリードモデルを定義する\n5. R(Event, Resource) / R(Event, Event) / R(Resource, Resource) を整理する\n6. イベント/リソースの区別が曖昧なら判定ルールを適用する\n\n## 出力テンプレート\n```\n## Event Storming の前提モデル\n\n### イベント\n- ...\n\n### コマンド\n- ...\n\n### 集約\n- ...\n\n### リードモデル\n- ...\n```\n"},"lastSynced":"2026-03-08T02:07:32.294Z","agentAnalysis":{"suitability":{"en":"Perfect for Domain Modeling Agents needing advanced event organization and domain behavior understanding.","zh":"非常适合需要高级事件组织和领域行为理解的领域建模代理。","ja":"ドメインモデリングエージェントが高度なイベント組織とドメインの動作理解を必要とする場合に最適です。","ko":"고급 이벤트 조직 및 도메인 동작 이해가 필요한 도메인 모델링 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Modelado de Dominio que necesitan una organización de eventos avanzada y comprensión del comportamiento del dominio.","fr":"Parfait pour les Agents de Modélisation de Domaine ayant besoin d''une organisation d''événements avancée et de compréhension du comportement de domaine.","de":"Perfekt für Domain-Modeling-Agents, die eine erweiterte Ereignisorganisation und ein Verständnis des Domain-Verhaltens benötigen.","pt":"Perfeito para Agentes de Modelagem de Domínio que precisam de organização de eventos avançada e compreensão do comportamento de domínio.","ru":"Идеально подходит для агентов моделирования домена, которым необходима продвинутая организация событий и понимание поведения домена.","ar":"مثالي لعميل نمذجة المجال الذي يحتاج إلى تنظيم حدث متقدم و فهم سلوك المجال."},"recommendation":{"en":"Empowers agents to identify and organize important events using domain modeling techniques, providing a clear understanding of domain behavior through event storming, and utilizing principles like ''1コマンドに対して1イベント'' and verb correspondence for command and event naming.","zh":"赋予代理识别和组织重要事件的能力，使用领域建模技术，通过事件风暴提供对领域行为的清晰理解，并利用诸如''1コマンドに対して1イベント''和动词对应等原则进行命令和事件命名。","ja":"ドメインモデリング技術を使用して、重要なイベントを識別し、組織化するエージェントをEmpowerし、イベントストーミングを通じてドメインの動作に対する明確な理解を提供し、''1コマンドに対して1イベント''や動詞対応などの原則を使用してコマンドとイベントの命名を行う。","ko":"도메인 모델링 기술을 사용하여 중요한 이벤트를 식별하고 조직화하는 에이전트를 강화하여 이벤트 스토밍을 통해 도메인의 동작에 대한 명확한 이해를 제공하며, ''1コマンドに対して1イベント''와 동사 대응 등의 원칙을 사용하여 명령과 이벤트의 이름을 지정합니다.","es":"Habilita a los agentes para identificar y organizar eventos importantes utilizando técnicas de modelado de dominio, proporcionando una comprensión clara del comportamiento del dominio a través de la tormenta de eventos, y utilizando principios como ''1 comando para 1 evento'' y la correspondencia de verbos para la nomenclatura de comandos y eventos.","fr":"Permet aux agents d''identifier et d''organiser des événements importants en utilisant des techniques de modélisation de domaine, fournissant une compréhension claire du comportement de domaine à travers la tempête d''événements, et en utilisant des principes comme ''1 commande pour 1 événement'' et la correspondance de verbes pour la nomination de commandes et d''événements.","de":"Ermächtigt Agents, wichtige Ereignisse mithilfe von Domain-Modeling-Techniken zu identifizieren und zu organisieren, und bietet so ein klares Verständnis des Domain-Verhaltens durch Event-Storming und die Anwendung von Prinzipien wie ''1 Befehl für 1 Ereignis'' und Verb-Korrespondenz für die Benennung von Befehlen und Ereignissen.","pt":"Habilite os agentes a identificar e organizar eventos importantes usando técnicas de modelagem de domínio, fornecendo uma compreensão clara do comportamento do domínio por meio de tempestade de eventos, e utilizando princípios como ''1コマンドに対して1イベント'' e correspondência de verbo para nomeação de comando e evento.","ru":"Наделяет агентов возможностью выявлять и организовывать важные события с помощью техник моделирования домена, обеспечивая четкое понимание поведения домена посредством шторма событий, и используя принципы, такие как ''1コマンドに対して1イベント'' и соответствие глагола для именования команд и событий.","ar":"تمكين العميل من تحديد وتنظيم الأحداث المهمة باستخدام تقنيات نمذجة المجال، وتوفير فهم واضح لسلوك المجال من خلال عاصفة الأحداث، واستخدام مبادئ مثل ''1コマンドに対して1イベント'' ومراسلة الفعل لتسمية الأمر والحدث."},"useCases":{"en":["Automating event identification for complex domains","Generating domain behavior models using event storming techniques","Organizing event/command relationships for clearer domain understanding"],"zh":["复杂领域的事件识别自动化","使用事件风暴技术生成领域行为模型","组织事件/命令关系以获得更清晰的领域理解"],"ja":["複雑なドメインのイベント識別の自動化","イベントストーミング技術を使用したドメインの動作モデルの生成","イベント/コマンド関係の組織化によるドメインの理解の明確化"],"ko":["복잡한 도메인의 이벤트 식별 자동화","이벤트 스토밍 기술을 사용한 도메인 동작 모델 생성","이벤트/명령 관계의 조직화에 의한 도메인 이해의 명확화"],"es":["Automatización de la identificación de eventos para dominios complejos","Generación de modelos de comportamiento de dominio utilizando técnicas de tormenta de eventos","Organización de relaciones entre eventos/comandos para una comprensión más clara del dominio"],"fr":["Automation de l''identification d''événements pour des domaines complexes","Génération de modèles de comportement de domaine en utilisant des techniques de tempête d''événements","Organisation des relations entre événements/commandes pour une compréhension plus claire du domaine"],"de":["Automatisierung der Ereignisidentifizierung für komplexe Domains","Erzeugung von Domain-Verhaltensmodellen unter Verwendung von Event-Storming-Techniken","Organisation von Ereignis/Befehls-Beziehungen für ein klareres Domain-Verständnis"],"pt":["Automatizar a identificação de eventos para domínios complexos","Gerar modelos de comportamento de domínio usando técnicas de tempestade de eventos","Organizar relacionamentos entre eventos/comandos para uma compreensão de domínio mais clara"],"ru":["Автоматизировать выявление событий для сложных доменов","Генерировать модели поведения домена с помощью техник шторма событий","Организовывать отношения между событиями/командами для более четкого понимания домена"],"ar":["آليّة تحديد الأحداث للمجالات المعقّدة","توليد نماذج سلوك المجال باستخدام تقنيات عاصفة الأحداث","تنظيم علاقات الأحداث والأوامر من أجل فهم أوضح للمجال"]},"limitations":{"en":["Requires domain knowledge for effective event identification","Limited to event-based domain modeling"],"zh":["需要领域知识才能有效地识别事件","仅限于基于事件的领域建模"],"ja":["イベントの有効な識別にはドメイン知識が必要","イベントベースのドメインモデリングのみに限定される"],"ko":["이벤트를 효과적으로 식별하기 위해 도메인 지식이 필요함","이벤트 기반 도메인 모델링에만 제한됨"],"es":["Requiere conocimiento del dominio para una identificación efectiva de eventos","Limitado al modelado de dominio basado en eventos"],"fr":["Nécessite des connaissances de domaine pour une identification efficace d''événements","Limité au modélisation de domaine basé sur les événements"],"de":["Benötigt Domain-Kenntnisse für eine effektive Ereignisidentifizierung","Begrenzt auf ereignisbasiertes Domain-Modellieren"],"pt":["Exige conhecimento de domínio para identificação eficaz de eventos","Limitado à modelagem de domínio baseada em eventos"],"ru":["Требует знаний домена для эффективного выявления событий","Ограничен моделированием домена на основе событий"],"ar":["يتطلب معرفة المجال لتحديد الأحداث الفعال","محدود بنمذجة المجال القائمة على الأحداث"]},"version":4},"contentHash":"5ebfde992d9fb2fe80be7dcd58cdeb8900ea8ee9b1979d97e691f38392b6eafe","qualityScore":30}');
