INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('j5ik2o/cqrs-es-spec-kit-js/event-storming', 'event-storming', 'j5ik2o', 'cqrs-es-spec-kit-js', 'community', 'event-storming j5ik2o cqrs-es-spec-kit-js community Event storming is a technique for domain modeling that helps developers identify and organize important events. It benefits developers by providing a clear understanding of domain behavior. Event Storming 是一种用于梳理事件和命令的技术，通过确立事件名和动词的使用，帮助开发者整理业务逻辑 イベントストーミングは、イベントとコマンドを整理する技術で、イベント名と動詞の使用を確立することで、開発者がビジネスロジックを整理するのに役立ちます 이벤트 스토밍은 이벤트와 명령어를 정리하는 기술로, 이벤트 이름과 동사의 사용을 확립하여 개발자가 비즈니스 로직을 정리하는 데 도움이 됩니다 Event Storming es una técnica para organizar eventos y comandos en el desarrollo de software. Ayuda a identificar y nombrar eventos de manera efectiva. L''Event Storming est une technique pour organiser les événements et les commandes dans le développement de logiciels. Elle aide à identifier et à nommer les événements de manière efficace. Event Storming ist eine Technik zur Organisation von Ereignissen und Befehlen in der Softwareentwicklung. Sie hilft bei der Identifizierung und Benennung von Ereignissen auf effektive Weise. O Event Storming é uma técnica de modelagem de domínio que ajuda a identificar e organizar eventos importantes no desenvolvimento de software. Event Storming - это техника моделирования домена, которая помогает выявить и организовать важные события в разработке программного обеспечения. event-storming هو تقنية نمذجة miền تساعد على تحديد وتنظيم الأحداث المهمة في تطوير البرمجيات. how to use event-storming event-storming setup guide event-storming vs domain-driven design event-storming alternative approaches event-storming install and configuration what is event-storming in software development Event Storming Domain-Driven Design 事件命名 命令与事件 动词的使用 关系的表达 AIエージェント イベントストーミング Identifies important domain events using verb-based naming conventions Ensures one-to-one correspondence between commands and events Supports event/command management using a standardized naming scheme Enables clear expression of relationships using ''R(, )'' notation Facilitates organization of events, commands, and aggregates using a structured approach Event-storming is a domain modeling technique that involves identifying and organizing important events in a domain, using a set of rules to ensure consistency and clarity.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('wannysim/mumak-www/ci-preflight', 'community', 'wannysim', 'mumak-www', 'wannysim/mumak-www', 'ci-preflight', 0, 0, 30, '2026-03-08T01:57:15.472Z', '2026-03-08T02:09:37.889Z', 'ac2a15503e7271965d51898d6b7656a2522442beb1bdd9c89dc756a9d488c06d', '{"id":"wannysim/mumak-www/ci-preflight","name":"ci-preflight","description":{"en":"ci-preflight is a skill that enables local CI validation, allowing developers to run checks before committing or creating a PR. It benefits developers by catching errors early","zh":"CI Preflight 是一个代码变更前验证工具，帮助开发人员确保代码质量","ja":"CI Preflight は、コード変更前に検証を行うツールで、コード品質を確保するのに役立ちます","ko":"CI Preflight 는 코드 변경 전 검증을 수행하여 코드 품질을 향상시키는 도구입니다","es":"ci-preflight es una herramienta que valida el código antes de commit o PR, incluyendo verificación de tipos y lint","fr":"ci-preflight est un outil qui valide le code avant commit ou PR, y compris la vérification de types et lint","de":"ci-preflight ist ein Tool, das den Code vor Commit oder PR validiert, einschließlich Typüberprüfung und Lint","pt":"O CI Preflight é uma ferramenta que executa verificações de código antes do commit, garantindo a qualidade do código","ru":"CI Preflight - это инструмент, который выполняет проверки кода до коммита, гарантируя качество кода","ar":"CI Preflight هو أداة تقوم بتنفيذ عمليات التحقق من الشفرة قبل الالتزام، مما يضمن جودة الشفرة"},"seo":{"title":{"en":"ci-preflight: Local CI Validation Setup Guide | AI Agent ...","zh":"CI Preflight Setup Guide: 代码变更前验证","ja":"CI Preflight ベストプラクティス: コード変更前検証","ko":"CI Preflight 설정 가이드: 코드 변경 전 검증","es":"Guía de configuración de ci-preflight para validación de ...","fr":"Guide de mise en place de ci-preflight pour la validation...","de":"Einrichtungsleitfaden für ci-preflight zur Codevalidierung","pt":"Guia de Configuração do CI Preflight para Desenvolvedores","ru":"Настройка CI Preflight: Лучшие Практики для Разработчиков","ar":"إعداد CI Preflight: دليل المستخدم للاستفادة القصوى من أدو..."},"description":{"en":"Run CI validation locally before commit/PR with ci-preflight. Learn how to set up and use this skill to streamline your development workflow","zh":"了解 CI Preflight 的工作原理，并学习如何在代码变更前进行验证，以确保代码质量","ja":"CI Preflight の機能と、コード変更前に検証を行う方法を学びましょう","ko":"CI Preflight 를 통해 코드 변경 전 검증을 수행하고 코드 품질을 향상시키는 방법에 대해 알아보세요","es":"Aprende a configurar ci-preflight para validar tu código antes de commit o PR, incluyendo verificación de tipos, lint y formato","fr":"Découvrez comment configurer ci-preflight pour valider votre code avant commit ou PR, y compris la vérification de types, lint et format","de":"Erfahren Sie, wie Sie ci-preflight einrichten, um Ihren Code vor Commit oder PR zu validieren, einschließlich Typüberprüfung, Lint und Format","pt":"Aprenda a configurar o CI Preflight para melhorar a eficiência do seu pipeline de desenvolvimento com verificações de tipo, lint e testes","ru":"Узнайте, как настроить CI Preflight для повышения эффективности вашего конвейера разработки с помощью проверок типов, lint и тестов","ar":"تعرف على كيفية تعيين CI Preflight لتحسين كفاءة خط أنابيب التطوير الخاص بك مع عمليات التحقق من النوع والتنسيق والاختبار"},"definition":{"en":"ci-preflight is a local CI validation tool that runs checks on code changes before commit/PR, including type checking, linting, format checking, and testing","zh":"CI Preflight 是一个代码变更前验证工具，用于检查代码的类型、格式和测试","ja":"CI Preflight は、コードのタイプ、フォーマット、テストを検証するコード変更前検証ツールです","ko":"CI Preflight 는 코드의 타입, 포맷, 테스트를 검증하는 코드 변경 전 검증 도구입니다","es":"ci-preflight es una herramienta de validación de código que se ejecuta antes de commit o PR","fr":"ci-preflight est un outil de validation de code qui s''exécute avant commit ou PR","de":"ci-preflight ist ein Code-Validierungstool, das vor Commit oder PR ausgeführt wird","pt":"CI Preflight é uma ferramenta de verificação de código que executa verificações de tipo, lint e testes antes do commit","ru":"CI Preflight - это инструмент проверки кода, который выполняет проверки типов, lint и тесты до коммита","ar":"CI Preflight هو أداة للتحقق من الشفرة التي تقوم بتنفيذ عمليات التحقق من النوع والتنسيق والاختبار قبل الالتزام"},"features":{"en":["Executes type checking using pnpm turbo run check-types","Runs linting with pnpm turbo run lint","Performs format checking using pnpm turbo run format:check","Supports testing with pnpm turbo run test","Uses git diff to identify changed files and apps"],"zh":["支持 Type Check 验证","支持 Lint 验证","支持 Format Check 验证","支持 Test 验证","使用 pnpm turbo 运行验证","支持多个应用程序验证"],"ja":["Type Check 検証をサポート","Lint 検証をサポート","Format Check 検証をサポート","Test 検証をサポート","pnpm turbo を使用して検証を実行","複数のアプリケーション検証をサポート"],"ko":["타입 체크 검증 지원","린트 검증 지원","포맷 체크 검증 지원","테스트 검증 지원","pnpm turbo를 사용하여 검증 실행","다중 애플리케이션 검증 지원"],"es":["Verificación de tipos con pnpm turbo run check-types","Lint con pnpm turbo run lint","Verificación de formato con pnpm turbo run format:check","Ejecución de pruebas con pnpm turbo run test","Integración con Git para verificar cambios en el código","Soporte para múltiples aplicaciones y paquetes"],"fr":["Vérification de types avec pnpm turbo run check-types","Lint avec pnpm turbo run lint","Vérification de format avec pnpm turbo run format:check","Exécution de tests avec pnpm turbo run test","Intégration avec Git pour vérifier les modifications du code","Prise en charge de plusieurs applications et packages"],"de":["Typüberprüfung mit pnpm turbo run check-types","Lint mit pnpm turbo run lint","Formatüberprüfung mit pnpm turbo run format:check","Testausführung mit pnpm turbo run test","Integration mit Git zur Überprüfung von Codeänderungen","Unterstützung für mehrere Anwendungen und Pakete"],"pt":["Verificação de tipo com pnpm turbo run check-types","Verificação de lint com pnpm turbo run lint","Verificação de formatação com pnpm turbo run format:check","Execução de testes com pnpm turbo run test"],"ru":["Проверка типов с помощью pnpm turbo run check-types","Проверка lint с помощью pnpm turbo run lint","Проверка форматирования с помощью pnpm turbo run format:check","Выполнение тестов с помощью pnpm turbo run test"],"ar":["التحقق من النوع باستخدام pnpm turbo run check-types","التحقق من التنسيق باستخدام pnpm turbo run lint","التحقق من التنسيق باستخدام pnpm turbo run format:check","تشغيل الاختبارات باستخدام pnpm turbo run test"]},"keywords":{"en":["how to use ci-preflight","ci-preflight setup guide","ci-preflight alternative","pnpm turbo run check-types","local CI validation","ci-preflight vs Jenkins","ci-preflight install","git diff ci-preflight"],"zh":["CI Preflight","代码变更前验证","代码质量","Type Check","Lint","Format Check","Test","pnpm turbo","AIエージェント"],"ja":["CI Preflight","コード変更前検証","コード品質","Type Check","Lint","Format Check","Test","pnpm turbo","AIエージェント"],"ko":["CI Preflight","코드 변경 전 검증","코드 품질","타입 체크","린트","포맷 체크","테스트","pnpm turbo","AI 에이전트"],"es":["ci-preflight","validación de código","verificación de tipos","lint","formato","pruebas","git","pnpm","turbo","check-types","lint","format:check","test"],"fr":["ci-preflight","validation de code","vérification de types","lint","format","tests","git","pnpm","turbo","check-types","lint","format:check","test"],"de":["ci-preflight","code-validierung","typüberprüfung","lint","format","tests","git","pnpm","turbo","check-types","lint","format:check","test"],"pt":["CI Preflight","verificação de código","pnpm turbo","check-types","lint","format:check","testes","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["CI Preflight","проверка кода","pnpm turbo","check-types","lint","format:check","тесты","разработка программного обеспечения","инструменты разработки"],"ar":["CI Preflight","التحقق من الشفرة","pnpm turbo","check-types","lint","format:check","اختبارات","تطوير البرمجيات","أدوات التطوير"]}},"owner":"wannysim","repo":"mumak-www","repoPath":"wannysim/mumak-www","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.472Z","topics":[],"category":"community","skillMd":{"name":"ci-preflight","description":"코드 작성 완료 후 CI 검증을 로컬에서 수행합니다. 코드 변경 완료 시, 커밋 요청 시, PR 생성 요청 시 자동으로 적용됩니다.","bodyPreview":"# CI Preflight 검증\n\n코드 변경 후 커밋/PR 전에 CI에서 실행되는 검증을 로컬에서 먼저 수행합니다.\n\n## 필수: 코드 변경 완료 시 검증\n\n코드 작성을 완료하면 **반드시** 아래 검증을 순서대로 실행합니다.\n\n### 1. 변경된 앱 확인\n\n```bash\n# 현재 브랜치에서 변경된 파일 확인\ngit diff --name-only origin/develop...HEAD\n\n# 변경된 앱 파악 (apps/ 또는 packages/ 하위)\n```\n\n### 2. 검증 실행 (순서 중요)\n\n```bash\n# 1) Type Check - 가장 먼저 (타입 오류가 다른 검증에 영향)\npnpm turbo run check-types --filter=<app>\n\n# 2) Lint\npnpm turbo run lint --filter=<app>\n\n# 3) Format Check\npnpm turbo run format:check --filter=<app>\n\n# 4) Test\npnpm tur","body":"# CI Preflight 검증\n\n코드 변경 후 커밋/PR 전에 CI에서 실행되는 검증을 로컬에서 먼저 수행합니다.\n\n## 필수: 코드 변경 완료 시 검증\n\n코드 작성을 완료하면 **반드시** 아래 검증을 순서대로 실행합니다.\n\n### 1. 변경된 앱 확인\n\n```bash\n# 현재 브랜치에서 변경된 파일 확인\ngit diff --name-only origin/develop...HEAD\n\n# 변경된 앱 파악 (apps/ 또는 packages/ 하위)\n```\n\n### 2. 검증 실행 (순서 중요)\n\n```bash\n# 1) Type Check - 가장 먼저 (타입 오류가 다른 검증에 영향)\npnpm turbo run check-types --filter=<app>\n\n# 2) Lint\npnpm turbo run lint --filter=<app>\n\n# 3) Format Check\npnpm turbo run format:check --filter=<app>\n\n# 4) Test\npnpm turbo run test:ci --filter=<app>\n\n# 5) Build (선택적 - PR 전 권장)\npnpm turbo run build --filter=<app>\n```\n\n### 3. 빠른 전체 검증\n\n변경된 부분만 한번에 검증:\n\n```bash\n# develop 브랜치 대비 변경된 부분 검증\n# 주의: zsh에서는 반드시 따옴표로 감싸야 함 (bracket이 glob으로 해석됨)\npnpm turbo run check-types lint format:check test:ci --filter=''[origin/develop...HEAD]''\n```\n\n## Turbo 필터 팁\n\n### 자주 사용하는 패턴\n\n```bash\n# 특정 앱만\n--filter=blog\n--filter=mumak-next\n\n# 변경된 부분만 (CI와 동일)\n# zsh에서는 따옴표 필수\n--filter=''[origin/develop...HEAD]''\n\n# 특정 앱 + 의존성\n--filter=...blog\n```\n\n### 캐시 관련\n\n```bash\n# 캐시 무시 (이상한 동작 시)\npnpm turbo run check-types --force\n\n# 전체 캐시 삭제\npnpm turbo:clean && pnpm install\n```\n\n## 자주 발생하는 오류와 해결\n\n### Type Check 실패\n\n| 오류 유형            | 원인             | 해결                                                |\n| -------------------- | ---------------- | --------------------------------------------------- |\n| `Cannot find module` | 빌드 순서 문제   | `pnpm turbo run build --filter=@mumak/ui` 먼저 실행 |\n| 타입 불일치          | 의존 패키지 변경 | 해당 패키지 `check-types` 먼저 확인                 |\n| `.d.ts` 없음         | 빌드 미실행      | 의존 패키지 빌드 후 재시도                          |\n\n### Lint 실패\n\n```bash\n# 자동 수정 가능한 것들\npnpm turbo run lint:fix --filter=<app>\n```\n\n### Format 실패\n\n```bash\n# 포맷 자동 적용\npnpm turbo run format --filter=<app>\n```\n\n## 검증 체크리스트\n\n코드 변경 완료 시 확인:\n\n- [ ] `check-types` 통과\n- [ ] `lint` 통과 (또는 `lint:fix` 실행)\n- [ ] `format:check` 통과 (또는 `format` 실행)\n- [ ] `test:ci` 통과\n- [ ] (PR 전) `build` 통과\n\n## 빠른 검증 스크립트\n\n전체 검증을 한번에 실행하려면:\n\n```bash\n./scripts/preflight.sh [app-name]\n```\n\n스크립트 없이 한줄로:\n\n```bash\npnpm turbo run check-types lint format:check test:ci --filter=''[origin/develop...HEAD]''\n```\n"},"lastSynced":"2026-03-08T02:09:37.889Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated CI validation and pre-commit checks.","zh":"适合需要自动化CI验证和预提交检查的开发代理。","ja":"開発エージェントが自動化されたCI検証とプレコミットチェックを必要とする場合に最適です。","ko":"자동화된 CI 검증 및 커밋 전 확인이 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan validación automática de CI y comprobaciones pre-commit.","fr":"Parfait pour les agents de développement ayant besoin d''une validation automatique de CI et de vérifications pré-commit.","de":"Perfekt für Entwicklungssagenten, die eine automatisierte CI-Validierung und Vor-Commit-Prüfungen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de validação de CI automatizada e verificações pré-envio.","ru":"Идеально для агентов разработки, которым требуется автоматическая проверка CI и предварительные проверки.","ar":"مثالي للوكلاء الناشئين الذين يحتاجون إلى التحقق التلقائي من CI والتحقق قبل الإرسال."},"recommendation":{"en":"Empowers agents to run comprehensive checks including Type Check, Lint, Format Check, and Test using pnpm turbo, ensuring error-free code commits and PRs, and provides early error detection using git diff and origin/develop comparisons.","zh":"赋予代理运行全面检查的能力，包括类型检查、Lint、格式检查和使用pnpm turbo的测试，确保代码提交和PR无错误，并提供使用git diff和origin/develop比较的早期错误检测。","ja":"エージェントが包括的なチェックを実行する能力を与え、Type Check、Lint、Format Check、pnpm turboを使用したテストなどを実行し、エラーのないコードのコミットとPRを保証し、git diffとorigin/developの比較を使用した早期エラーディテクションを提供します。","ko":"에이전트가 포괄적인 확인을 실행할 수 있는 능력을 부여하여, pnpm turbo를 사용한 유형 확인, 린트, 형식 확인 및 테스트 등을 수행하여 오류가 없는 코드 커밋 및 PR을 보장하고, git diff 및 origin/develop 비교를 사용한 초기 오류 감지를 제공합니다.","es":"Habilita a los agentes a ejecutar comprobaciones exhaustivas que incluyen Type Check, Lint, Format Check y Test utilizando pnpm turbo, garantizando la ausencia de errores en los commits de código y PR, y proporciona una detección temprana de errores mediante comparaciones de git diff y origin/develop.","fr":"Permet aux agents d''exécuter des vérifications complètes, notamment Type Check, Lint, Format Check et Test, en utilisant pnpm turbo, garantissant des commits de code et des PR sans erreurs, et fournit une détection précoce des erreurs à l''aide de comparaisons git diff et origin/develop.","de":"Ermächtigt die Agenten, umfassende Prüfungen durchzuführen, einschließlich Type Check, Lint, Format Check und Test, unter Verwendung von pnpm turbo, um fehlerfreie Code-Commits und PRs sicherzustellen und bietet eine frühzeitige Fehlererkennung unter Verwendung von git diff- und origin/develop-Vergleichen.","pt":"Habilita os agentes a executar verificações abrangentes, incluindo Type Check, Lint, Format Check e Teste usando pnpm turbo, garantindo a entrega de código sem erros e PRs, e fornece detecção antecipada de erros usando git diff e comparações origin/develop.","ru":"Наделяет агентов возможностью запускать комплексные проверки, включая Type Check, Lint, Format Check и тестирование с помощью pnpm turbo, обеспечивая безошибочную отправку кода и запросов на слияние, и предоставляет раннее обнаружение ошибок с помощью git diff и сравнений origin/develop.","ar":"يمنح الوكلاء القدرة على تشغيل التحقق الشامل، بما في ذلك التحقق من النوع و Lint و Format Check و الاختبار باستخدام pnpm turbo، مما يضمن تسليم رمز خالي من الأخطاء و PRs، ويوفر الكشف المبكر عن الأخطاء باستخدام git diff والمقارنات origin/develop."},"useCases":{"en":["Automating pre-commit validation","Running Type Check and Lint on modified apps","Debugging format and test issues before PR creation"],"zh":["自动化预提交验证","在修改的应用程序上运行类型检查和Lint","在PR创建之前调试格式和测试问题"],"ja":["プレコミットの検証の自動化","変更されたアプリケーションでType CheckとLintを実行","PR作成前にフォーマットとテストの問題をデバッグ"],"ko":["커밋 전 확인의 자동화","수정된 애플리케이션에서 유형 확인 및 린트 실행","PR 생성 전에 형식 및 테스트 문제 디버깅"],"es":["Automatización de la validación pre-commit","Ejecución de Type Check y Lint en aplicaciones modificadas","Depuración de problemas de formato y pruebas antes de la creación de PR"],"fr":["Automatisation de la validation pré-commit","Exécution de Type Check et Lint sur des applications modifiées","Débogage des problèmes de format et de tests avant la création de PR"],"de":["Automatisierung der Vor-Commit-Validierung","Ausführung von Type Check und Lint auf modifizierten Apps","Fehlerbehebung bei Format- und Testproblemen vor der Erstellung von PR"],"pt":["Automatizar a validação pré-envio","Executar Type Check e Lint em aplicativos modificados","Depurar problemas de formato e teste antes da criação de PR"],"ru":["Автоматизация предварительной проверки","Запуск Type Check и Lint для измененных приложений","Отладка проблем формата и тестирования до создания запроса на слияние"],"ar":["التحكم الآلي في التحقق قبل الإرسال","تشغيل التحقق من النوع و Lint على التطبيقات المعدلة","تصحيح أخطاء التنسيق والاختبار قبل إنشاء PR"]},"limitations":{"en":["Requires pnpm and turbo setup","Limited to local CI validation","Dependent on git for version control"],"zh":["需要pnpm和turbo设置","仅限本地CI验证","依赖于git进行版本控制"],"ja":["pnpmとturboの設定が必要","ローカルCI検証のみ","バージョン管理にgitに依存"],"ko":["pnpm 및 터보 설정이 필요","로컬 CI 확인만 가능","버전 관리에 깃에 의존"],"es":["Requiere configuración de pnpm y turbo","Limitado a la validación de CI local","Dependiente de git para el control de versiones"],"fr":["Nécessite une configuration de pnpm et turbo","Limité à la validation de CI locale","Dépendant de git pour le contrôle de version"],"de":["Erfordert pnpm- und Turbo-Setup","Begrenzt auf lokale CI-Validierung","Von git für die Versionskontrolle abhängig"],"pt":["Requer configuração do pnpm e turbo","Limitado à validação de CI local","Dependente do git para controle de versão"],"ru":["Требует настройки pnpm и turbo","Ограничен локальной проверкой CI","Зависит от git для контроля версий"],"ar":["يتطلب إعداد pnpm و turbo","محدود بالتحقق المحلي من CI","يعتمد على git لمراقبة الإصدارات"]},"version":4},"contentHash":"ac2a15503e7271965d51898d6b7656a2522442beb1bdd9c89dc756a9d488c06d","qualityScore":30}');
