INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wannysim/mumak-www/ci-preflight', 'ci-preflight', 'wannysim', 'mumak-www', 'community', 'ci-preflight wannysim mumak-www community ci-preflight is a skill that enables local CI validation, allowing developers to run checks before committing or creating a PR. It benefits developers by catching errors early CI Preflight 是一个代码变更前验证工具，帮助开发人员确保代码质量 CI Preflight は、コード変更前に検証を行うツールで、コード品質を確保するのに役立ちます CI Preflight 는 코드 변경 전 검증을 수행하여 코드 품질을 향상시키는 도구입니다 ci-preflight es una herramienta que valida el código antes de commit o PR, incluyendo verificación de tipos y lint ci-preflight est un outil qui valide le code avant commit ou PR, y compris la vérification de types et lint ci-preflight ist ein Tool, das den Code vor Commit oder PR validiert, einschließlich Typüberprüfung und Lint O CI Preflight é uma ferramenta que executa verificações de código antes do commit, garantindo a qualidade do código CI Preflight - это инструмент, который выполняет проверки кода до коммита, гарантируя качество кода CI Preflight هو أداة تقوم بتنفيذ عمليات التحقق من الشفرة قبل الالتزام، مما يضمن جودة الشفرة how to use ci-preflight ci-preflight setup guide ci-preflight alternative pnpm turbo run check-types local CI validation ci-preflight vs Jenkins ci-preflight install git diff ci-preflight CI Preflight 代码变更前验证 代码质量 Type Check Lint Format Check Test pnpm turbo AIエージェント Executes type checking using pnpm turbo run check-types Runs linting with pnpm turbo run lint Performs format checking using pnpm turbo run format:check Supports testing with pnpm turbo run test Uses git diff to identify changed files and apps ci-preflight is a local CI validation tool that runs checks on code changes before commit/PR, including type checking, linting, format checking, and testing');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('radiantlogicinc/fastworkflow/landing-the-plane', 'community', 'radiantlogicinc', 'fastworkflow', 'radiantlogicinc/fastworkflow', 'landing-the-plane', 0, 0, 30, '2026-03-08T01:57:15.442Z', '2026-03-08T02:09:38.658Z', '7143f2461cc6d01794627d0e8b0297db7de40aeb51c73633057d527b49355729', '{"id":"radiantlogicinc/fastworkflow/landing-the-plane","name":"landing-the-plane","description":{"en":"landing-the-plane is a framework for building large-scale, deterministic, interactive workflows with a fault-tolerant, conversational UX, benefiting developers and teams. It ensures session completion with mandatory workflow steps.","zh":"Landing the Plane 框架提供了构建大规模、确定性、交互式工作流的解决方案，具有容错的对话式 UX","ja":"Landing the Plane フレームワークは、大規模で決定的なインタラクティブワークフローを構築し、フォールトトレラントな会話型 UX を提供します","ko":"Landing the Plane 프레임워크는 대규모 결정적 상호작용 워크플ロー 구축 및 오류 허용 가능한 대화형 UX 제공","es":"landing-the-plane es un framework para construir flujos de trabajo interactivos y escalables con una experiencia de usuario conversacional y tolerante a fallos","fr":"landing-the-plane est un framework pour créer des flux de travail interactifs et évolutifs avec une expérience utilisateur conversationnelle et tolérante aux erreurs","de":"landing-the-plane ist ein Framework für die Erstellung interaktiver und skalierbarer Workflows mit einer konversationellen Benutzeroberfläche und Fehlertoleranz","pt":"O Landing the Plane é um framework para criar fluxos de trabalho determinísticos e interativos com UX conversacional e tolerante a falhas","ru":"ИИ Агент Landing the Plane представляет собой каркас для построения крупномасштабных детерминированных рабочих процессов с отказоустойчивой UX","ar":"هبوط الطائرة هو إطار عمل لإنشاء أنظمة عمل تفاعلية ومنخفضة الأخطاء مع واجهة مستخدم محادثية"},"seo":{"title":{"en":"landing-the-plane: Session Completion Setup Guide | AI Ag...","zh":"Landing the Plane 框架：大规模工作流设置指南","ja":"Landing the Plane フレームワーク：大規模ワークフロー設定ガイド - AIエージェント","ko":"Landing the Plane 프레임워크: 대규모 워크플ロー 설정 가이드","es":"Guía de configuración de landing-the-plane para flujos de...","fr":"Guide de mise en place de landing-the-plane pour les flux...","de":"Setup Guide für landing-the-plane für interaktive Workflows","pt":"Landing the Plane: Guia de Configuração para Workflows De...","ru":"ИИ Агент Landing the Plane: Руководство по Настройке","ar":"هبوط الطائرة: دليل إعداد لأنظمة العمل التفاعلية"},"description":{"en":"Streamline your workflow with landing-the-plane! Learn how to complete sessions with ease using git push, quality gates, and issue tracking. Get started now!","zh":"了解 Landing the Plane 框架如何帮助您构建大规模、确定性、交互式工作流，并提供容错的对话式 UX","ja":"Landing the Plane フレームワークを使用して、大規模で決定的なインタラクティブワークフローを構築し、フォールトトレラントな会話型 UX を実現する方法を学びます - AIエージェント","ko":"Landing the Plane 프레임워크를 사용하여 대규모 결정적 상호작용 워크플ロー 구축 및 오류 허용 가능한 대화형 UX 제공 방법","es":"Aprende a implementar landing-the-plane para crear flujos de trabajo escalables y tolerantes a fallos con una experiencia de usuario conversacional","fr":"Découvrez comment mettre en place landing-the-plane pour créer des flux de travail interactifs évolutifs et tolérants aux erreurs avec une expérience utilisa...","de":"Erfahren Sie, wie Sie landing-the-plane implementieren, um groß angelegte, fehlertolerante Workflows mit einer konversationellen Benutzeroberfläche zu erstellen","pt":"Aprenda a utilizar o framework Landing the Plane para criar fluxos de trabalho interativos e tolerantes a falhas com UX conversacional","ru":"Узнайте, как использовать ИИ Агент Landing the Plane для построения крупномасштабных детерминированных рабочих процессов с отказоустойчивой UX","ar":"تعرف على إطار عمل هبوط الطائرة لإنشاء أنظمة عمل تفاعلية مع واجهة مستخدم محادثية منخفضة الأخطاء"},"definition":{"en":"landing-the-plane is a framework for building large-scale, deterministic, interactive workflows with a focus on session completion and fault-tolerant conversational UX.","zh":"Landing the Plane 框架是一种用于构建大规模、确定性、交互式工作流的解决方案","ja":"Landing the Plane フレームワークは、大規模で決定的なインタラクティブワークフローを構築するためのフレームワークです","ko":"Landing the Plane 프레임워크는 대규모 결정적 상호작용 워크플ロー 구축을 위한 프레임워크","es":"landing-the-plane es un framework de código abierto para crear flujos de trabajo interactivos y escalables","fr":"landing-the-plane est un framework open source pour créer des flux de travail interactifs et évolutifs","de":"landing-the-plane ist ein Open-Source-Framework für die Erstellung interaktiver und skalierbarer Workflows","pt":"O que é Landing the Plane? É um framework para criar fluxos de trabalho interativos e determinísticos","ru":"Что такое ИИ Агент Landing the Plane? Это каркас для построения детерминированных рабочих процессов","ar":"ما هو هبوط الطائرة؟ إنه إطار عمل لإنشاء أنظمة عمل تفاعلية ومنخفضة الأخطاء"},"features":{"en":["Runs quality gates using tests, linters, and builds","Updates issue status with commands like `bd close <id>` and `bd update <id> --status ...`","Creates issues for remaining work via `bd create`","Pushes changes to remote using `git push`","Ensures mandatory workflow steps for session completion","Supports fault-tolerant conversational UX"],"zh":["支持大规模工作流构建","提供容错的对话式 UX","集成 Git_push 功能","支持质量门控（测试、linters、构建）","支持问题跟踪和状态更新","支持 CLI 命令（如 bd create、bd close、bd update）"],"ja":["大規模ワークフローの構築をサポート","フォールトトレラントな会話型 UX を提供","Git_push 機能の統合","品質ゲート（テスト、linters、ビルド）のサポート","問題追跡とステータス更新のサポート","CLI コマンド（bd create、bd close、bd update など）のサポート"],"ko":["대규모 워크플ロー 구축 지원","오류 허용 가능한 대화형 UX 제공","Git_push 기능 통합","품질 게이트(테스트, linters, 빌드) 지원","문제 추적 및 상태 업데이트 지원","CLI 명령어(bd create, bd close, bd update 등) 지원"],"es":["Implementación de flujos de trabajo deterministas","Experiencia de usuario conversacional","Tolerancia a fallos y recuperación automática","Integración con herramientas de calidad como tests y linters","Compatibilidad con git para control de versiones"],"fr":["Mise en place de flux de travail déterministes","Expérience utilisateur conversationnelle","Tolérance aux erreurs et récupération automatique","Intégration avec des outils de qualité tels que des tests et des linters","Compatibilité avec git pour le contrôle de version"],"de":["Implementierung deterministischer Workflows","Konversationelle Benutzeroberfläche","Fehlertoleranz und automatische Wiederherstellung","Integration mit Qualitätstools wie Tests und Lintern","Kompatibilität mit git für Versionskontrolle"],"pt":["Criação de issues para trabalho restante via CLI","Execução de portões de qualidade (testes, linters, builds)","Atualização de status de issues via `bd update`","Push para repositório remoto via `git push`","Integração com ferramentas de desenvolvimento como Git e CLI"],"ru":["Создание задач для оставшейся работы через CLI","Выполнение контрольных точек качества (тесты, линтеры, сборки)","Обновление статуса задач через `bd update`","Отправка в удаленный репозиторий через `git push`","Интеграция с инструментами разработки, такими как Git и CLI"],"ar":["إنشاء مشاكل للعمل المتبقي عبر واجهة سطر الأوامر","تشغيل بوابات الجودة (اختبارات، لينتر، بناء)","تحديث حالة المشاكل عبر `bd update`","دفع إلى مستودع عن بعد عبر `git push`","التكامل مع أدوات التطوير مثل جيت وواجهة سطر الأوامر"]},"keywords":{"en":["how to use landing-the-plane","what is landing-the-plane","landing-the-plane alternative","landing-the-plane vs git workflow","landing-the-plane install","landing-the-plane setup guide","deterministic interactive workflows","conversational UX tools","session completion best practices"],"zh":["Landing the Plane 框架","大规模工作流","确定性工作流","交互式工作流","容错 UX","Git_push","质量门控","问题跟踪","CLI 命令"],"ja":["Landing the Plane フレームワーク","大規模ワークフロー","決定的なワークフロー","インタラクティブワークフロー","フォールトトレラントな UX","Git_push","品質ゲート","問題追跡","CLI コマンド","AIエージェント"],"ko":["Landing the Plane 프레임워크","대규모 워크플ロー","결정적 워크플ロー","상호작용 워크플ロー","오류 허용 가능한 UX","Git_push","품질 게이트","문제 추적","CLI 명령어","AI 도구"],"es":["landing-the-plane","flujos de trabajo interactivos","experiencia de usuario conversacional","tolerancia a fallos","git","tests","linters","desarrollo de software","herramientas de desarrollo"],"fr":["landing-the-plane","flux de travail interactifs","expérience utilisateur conversationnelle","tolérance aux erreurs","git","tests","linters","développement de logiciels","outils de développement"],"de":["landing-the-plane","interaktive Workflows","konversationelle Benutzeroberfläche","Fehlertoleranz","git","Tests","Linter","Software-Entwicklung","Entwicklungstools"],"pt":["Landing the Plane","fluxos de trabalho determinísticos","UX conversacional","tolerante a falhas","Git","CLI","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["ИИ Агент Landing the Plane","детерминированные рабочие процессы","отказоустойчивая UX","Git","CLI","разработка программного обеспечения","инструменты разработки","ИИ Агенты"],"ar":["هبوط الطائرة","أنظمة عمل تفاعلية","واجهة مستخدم محادثية","منخفضة الأخطاء","جيت","واجهة سطر الأوامر","تطوير البرمجيات","أدوات التطوير","أدوات الذكاء الاصطناعي"]}},"owner":"radiantlogicinc","repo":"fastworkflow","repoPath":"radiantlogicinc/fastworkflow","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.442Z","topics":[],"category":"community","skillMd":{"name":"landing-the-plane","description":"Completes work sessions by running quality gates, syncing bd, pushing to remote, and handing off. Use when ending a work session, landing the plane, session completion, or when the user asks to wrap up or finish work.","bodyPreview":"# Landing the Plane (Session Completion)\n\nWhen ending a work session, complete ALL steps below. Work is NOT complete until `git push` succeeds.\n\n## Mandatory workflow\n\n1. **File issues for remaining work** – Create issues (e.g. via `bd create`) for anything that needs follow-up.\n2. **Run quality gates** (if code changed) – Tests, linters, builds.\n3. **Update issue status** – Close finished work, update in-progress items (`bd close <id>`, `bd update <id> --status ...`).\n4. **PUSH TO REMOTE** – Ma","body":"# Landing the Plane (Session Completion)\n\nWhen ending a work session, complete ALL steps below. Work is NOT complete until `git push` succeeds.\n\n## Mandatory workflow\n\n1. **File issues for remaining work** – Create issues (e.g. via `bd create`) for anything that needs follow-up.\n2. **Run quality gates** (if code changed) – Tests, linters, builds.\n3. **Update issue status** – Close finished work, update in-progress items (`bd close <id>`, `bd update <id> --status ...`).\n4. **PUSH TO REMOTE** – Mandatory:\n   ```bash\n   git pull --rebase\n   bd sync\n   git push\n   git status   # MUST show \"up to date with origin\"\n   ```\n5. **Clean up** – Clear stashes, prune remote branches.\n6. **Verify** – All changes committed AND pushed.\n7. **Hand off** – Provide context for next session.\n\n## Critical rules\n\n- Activate the local Python environment before running scripts/tests.\n- Work is NOT complete until `git push` succeeds.\n- NEVER stop before pushing – that leaves work stranded locally.\n- NEVER say \"ready to push when you are\" – you must push.\n- If push fails, resolve and retry until it succeeds.\n"},"lastSynced":"2026-03-08T02:09:38.658Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring structured workflow management and fault-tolerant conversational UX.","zh":"适用于需要结构化工作流管理和容错对话UX的开发代理。","ja":"構造化されたワークフロー管理とフォールトトレラントな対話UXを必要とする開発エージェントに適しています。","ko":"구조화된 워크플로우 관리와 고장 감내형 대화 UX가 필요한 개발 에이전트에게 적합합니다.","es":"Ideal para Agentes de Desarrollo que requieren una gestión de flujo de trabajo estructurada y una experiencia de usuario conversacional tolerante a fallos.","fr":"Idéal pour les Agents de Développement nécessitant une gestion de workflow structurée et une expérience utilisateur conversationnelle tolérante aux erreurs.","de":"Ideal für Entwicklungsmittel, die eine strukturierte Workflow-Verwaltung und eine fehlertolerante Konversationsbenutzeroberfläche erfordern.","pt":"Ideal para Agentes de Desenvolvimento que requerem gerenciamento de fluxo de trabalho estruturado e UX conversacional tolerante a falhas.","ru":"Идеально для агентов разработки, требующих структурированного управления рабочим процессом и устойчивого к ошибкам разговорного UX.","ar":"مثالي للوكلاء النموزجيين الذين يتطلبون إدارةflux العمل الهيكلي وتجربة المستخدم الحوارية الصامدة للأخطاء."},"recommendation":{"en":"Empowers agents to enforce mandatory workflow steps, ensuring session completion with successful git push, while utilizing quality gates like tests, linters, and builds, and managing issue status updates via commands like `bd create`, `bd close`, and `bd update`.","zh":"赋予代理人执行强制工作流步骤的能力，确保会话完成并成功推送git，同时利用诸如测试、linters和构建等质量门槛，并通过命令如`bd create`、`bd close`和`bd update`管理问题状态更新。","ja":"エージェントに強制的なワークフロー手順を実施する能力を与え、セッションの完了とgitプッシュの成功を保証し、テスト、リンター、ビルドなどの品質ゲートウェイを利用し、`bd create`、`bd close`、`bd update`などのコマンドで問題のステータス更新を管理します。","ko":"에이전트에게 강제적인 워크플로우 단계를 수행할 수 있는 능력을 부여하여 세션 완료와 git 푸시 성공을 보장하며 테스트, 린터, 빌드 등과 같은 품질 게이트웨이를 활용하고 `bd create`, `bd close`, `bd update` 등의 명령어로 문제 상태 업데이트를 관리합니다.","es":"Habilita a los agentes a aplicar pasos de flujo de trabajo obligatorios, asegurando la finalización de la sesión con un git push exitoso, mientras se utilizan puertas de calidad como pruebas, linters y compilaciones, y se gestionan actualizaciones de estado de problemas mediante comandos como `bd create`, `bd close` y `bd update`.","fr":"Permet aux agents d''appliquer des étapes de workflow obligatoires, assurant l''achèvement de la session avec un git push réussi, tout en utilisant des portes de qualité comme des tests, des linters et des builds, et en gérant les mises à jour de statut de problèmes via des commandes comme `bd create`, `bd close` et `bd update`.","de":"Ermöglicht es Agenten, verpflichtende Workflow-Schritte durchzusetzen, wodurch die Sitzung mit einem erfolgreichen git push abgeschlossen wird, während Qualitätsprüfungen wie Tests, Linter und Builds verwendet werden und Statusaktualisierungen von Problemen über Befehle wie `bd create`, `bd close` und `bd update` verwaltet werden.","pt":"Concede poderes aos agentes para impor etapas de fluxo de trabalho obrigatórias, garantindo a conclusão da sessão com push git bem-sucedido, utilizando portais de qualidade como testes, linters e compilações, e gerenciando atualizações de status de problemas via comandos como `bd create`, `bd close` e `bd update`.","ru":"Наделяет агентов полномочиями по обеспечению обязательных шагов рабочего процесса, гарантируя завершение сессии с успешным пушированием гита, используя ворота качества, такие как тесты, линтеры и сборки, и управляя обновлениями статуса проблем через команды, такие как `bd create`, `bd close` и `bd update`.","ar":"تمكين الوكلاء من فرض خطوات تدفق العمل الإلزامية، مما يضمن إكمال الجلسة بشبكة git ناجحة، مع استخدام بوابات الجودة مثل الاختبارات والمنقحين وعمليات البناء، وإدارة تحديثات حالة المشكلات عبر أوامر مثل `bd create` و `bd close` و `bd update`."},"useCases":{"en":["Automating workflow completion with git push","Generating issues for remaining work via `bd create`","Updating issue status with `bd close` and `bd update` commands","Running quality gates for code changes"],"zh":["使用git推送自动完成工作流","通过`bd create`生成剩余工作的问题","使用`bd close`和`bd update`命令更新问题状态","运行代码更改的质量门槛"],"ja":["gitプッシュを使用してワークフローを自動的に完了する","`bd create`を使用して残りの作業の問題を生成する","`bd close`と`bd update`コマンドを使用して問題のステータスを更新する","コード変更の品質ゲートウェイを実行する"],"ko":["git 푸시를 사용하여 워크플로우를 자동으로 완료하는 것","`bd create`를 사용하여 남은 작업의 문제를 생성하는 것","`bd close`와 `bd update` 명령어를 사용하여 문제 상태를 업데이트하는 것","코드 변경의 품질 게이트웨이를 실행하는 것"],"es":["Automatización de la finalización del flujo de trabajo con git push","Generación de problemas para el trabajo restante a través de `bd create`","Actualización del estado del problema con los comandos `bd close` y `bd update`","Ejecución de puertas de calidad para cambios de código"],"fr":["Automatisation de l''achèvement du workflow avec git push","Génération de problèmes pour le travail restant via `bd create`","Mise à jour du statut du problème avec les commandes `bd close` et `bd update`","Exécution de portes de qualité pour les modifications de code"],"de":["Automatisierung der Workflow-Abschluss mit git push","Erzeugung von Problemen für die verbleibende Arbeit über `bd create`","Aktualisierung des Problemmstatus mit den Befehlen `bd close` und `bd update`","Ausführung von Qualitätsprüfungen für Codeänderungen"],"pt":["Automatizar a conclusão do fluxo de trabalho com push git","Gerar problemas para o trabalho restante via `bd create`","Atualizar o status do problema com comandos `bd close` e `bd update`","Executar portais de qualidade para alterações de código"],"ru":["Автоматизация завершения рабочего процесса с помощью пуширования гита","Генерация проблем для оставшейся работы через `bd create`","Обновление статуса проблемы с помощью команд `bd close` и `bd update`","Запуск ворот качества для изменений кода"],"ar":["تأتمتة إكمال تدفق العمل بشبكة git","توليد مشاكل للأعمال المتبقية عبر `bd create`","تحديث حالة المشكلة بأوامر `bd close` و `bd update`","تشغيل بوابات الجودة لتغييرات الشفرة"]},"limitations":{"en":["Requires git setup","Mandatory steps must be completed in sequence","Dependent on external tools like `bd` for issue management"],"zh":["需要git设置","强制步骤必须按顺序完成","依赖外部工具如`bd`进行问题管理"],"ja":["gitの設定が必要","強制的な手順はシーケンスで完了する必要がある","問題管理のために外部ツール如`bd`に依存する"],"ko":["git 설정이 필요하다","강제적인 단계는 순서대로 완료되어야 한다","문제 관리를 위해 외부 도구인 `bd`에 의존한다"],"es":["Requiere configuración de git","Los pasos obligatorios deben completarse en secuencia","Depende de herramientas externas como `bd` para la gestión de problemas"],"fr":["Nécessite une configuration git","Les étapes obligatoires doivent être effectuées en séquence","Dépend de outils externes comme `bd` pour la gestion de problèmes"],"de":["Erfordert git-Einrichtung","Verpflichtende Schritte müssen in Folge abgeschlossen werden","Hängt von externen Tools wie `bd` für die Problemmverwaltung ab"],"pt":["Requer configuração git","Etapa obrigatória deve ser concluída em sequência","Depende de ferramentas externas como `bd` para gerenciamento de problemas"],"ru":["Требуется настройка гита","Обязательные шаги должны быть выполнены в последовательности","Зависит от внешних инструментов, таких как `bd`, для управления проблемами"],"ar":["يتطلب إعداد git","الخطوة الإلزامية يجب أن تكتمل بالتسلسل","يعتمد على أدوات خارجية مثل `bd` لإدارة المشاكل"]},"version":4},"contentHash":"7143f2461cc6d01794627d0e8b0297db7de40aeb51c73633057d527b49355729","qualityScore":30}');
