INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('radiantlogicinc/fastworkflow/landing-the-plane', 'landing-the-plane', 'radiantlogicinc', 'fastworkflow', 'community', 'landing-the-plane radiantlogicinc fastworkflow community landing-the-plane is a framework for building large-scale, deterministic, interactive workflows with a fault-tolerant, conversational UX, benefiting developers and teams. It ensures session completion with mandatory workflow steps. Landing the Plane 框架提供了构建大规模、确定性、交互式工作流的解决方案，具有容错的对话式 UX Landing the Plane フレームワークは、大規模で決定的なインタラクティブワークフローを構築し、フォールトトレラントな会話型 UX を提供します Landing the Plane 프레임워크는 대규모 결정적 상호작용 워크플ロー 구축 및 오류 허용 가능한 대화형 UX 제공 landing-the-plane es un framework para construir flujos de trabajo interactivos y escalables con una experiencia de usuario conversacional y tolerante a fallos landing-the-plane est un framework pour créer des flux de travail interactifs et évolutifs avec une expérience utilisateur conversationnelle et tolérante aux erreurs landing-the-plane ist ein Framework für die Erstellung interaktiver und skalierbarer Workflows mit einer konversationellen Benutzeroberfläche und Fehlertoleranz O Landing the Plane é um framework para criar fluxos de trabalho determinísticos e interativos com UX conversacional e tolerante a falhas ИИ Агент Landing the Plane представляет собой каркас для построения крупномасштабных детерминированных рабочих процессов с отказоустойчивой UX هبوط الطائرة هو إطار عمل لإنشاء أنظمة عمل تفاعلية ومنخفضة الأخطاء مع واجهة مستخدم محادثية how to use landing-the-plane what is landing-the-plane landing-the-plane alternative landing-the-plane vs git workflow landing-the-plane install landing-the-plane setup guide deterministic interactive workflows conversational UX tools session completion best practices Landing the Plane 框架 大规模工作流 确定性工作流 交互式工作流 容错 UX Git_push 质量门控 问题跟踪 CLI 命令 Runs quality gates using tests, linters, and builds Updates issue status with commands like `bd close <id>` and `bd update <id> --status ...` Creates issues for remaining work via `bd create` Pushes changes to remote using `git push` Ensures mandatory workflow steps for session completion Supports fault-tolerant conversational UX landing-the-plane is a framework for building large-scale, deterministic, interactive workflows with a focus on session completion and fault-tolerant conversational UX.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('asolerp/PManagement/rn-ci-check', 'community', 'asolerp', 'PManagement', 'asolerp/PManagement', 'rn-ci-check', 0, 0, 30, '2026-03-08T01:57:15.486Z', '2026-03-08T02:10:04.789Z', '9823573b8ada780cb297e6f41bce93ab1fa87aa05403d6f5eecdcbd7937d4058', '{"id":"asolerp/PManagement/rn-ci-check","name":"rn-ci-check","description":{"en":"The rn-ci-check skill automates quality assurance by executing a suite of checks, including lint, TypeScript, and tests, benefiting developers with streamlined workflows.","zh":"RN CI Check 是一个自动化代码质量检查工具，支持 Lint、TypeScript、测试和构建检查，帮助开发者提高代码质量","ja":"RN CI Check はコード品質チェックの自動化ツールで、Lint、TypeScript、テスト、ビルドチェックに対応し、開発者のコード品質を向上させます","ko":"RN CI Check는 코드 품질 체크를 자동화하는 도구로, Lint, TypeScript, 테스트, 빌드 체크를 지원하여 개발자의 코드 품질을 향상시킵니다","es":"rn-ci-check es una herramienta que ejecuta la suite completa de verificación de calidad para mejorar la calidad del código","fr":"rn-ci-check est un outil qui exécute la suite complète de vérification de qualité pour améliorer la qualité du code","de":"rn-ci-check ist ein Tool, das die vollständige Qualitätsprüfungssuite ausführt, um die Code-Qualität zu verbessern","pt":"O rn-ci-check é uma ferramenta que executa a suite completa de verificação de qualidade de código, incluindo lint, TypeScript, testes e build check","ru":"rn-ci-check - это инструмент, который выполняет полный чек линта и тестов для проверки качества вашего кода","ar":"rn-ci-check هو أداة تقوم bằngتنفيذ مجموعة كاملة من التحقق من جودة الرمز، بما في ذلك لينت و تايب سكريبت واختبارات و فحص البناء"},"seo":{"title":{"en":"rn-ci-check: Automated Quality Assurance Setup Guide | AI...","zh":"RN CI Check.setup 指南：自动化代码质量检查","ja":"RN CI Check セットアップガイド：コード品質チェックの自動化","ko":"RN CI Check 설정 가이드: 코드 품질 체크 자동화","es":"Guía de Configuración de rn-ci-check para Verificación de...","fr":"Guide d''Installation de rn-ci-check pour Vérification de ...","de":"Einrichtungsleitfaden für rn-ci-check zur Qualitätssicherung","pt":"Guia de Configuração rn-ci-check: Verificação de Qualidad...","ru":"Настройка rn-ci-check: Полный Чек Линта и Тестов","ar":"إعداد rn-ci-check: دليل التحقق من جودة الرمز"},"description":{"en":"Discover how to automate quality checks with rn-ci-check. Learn to integrate lint, TypeScript, and tests for a robust development workflow. Get started now!","zh":"RN CI Check 是一个自动化代码质量检查工具，支持 Lint、TypeScript、测试和构建检查","ja":"RN CI Check はコード品質チェックの自動化ツールで、Lint、TypeScript、テスト、ビルドチェックに対応","ko":"RN CI Check는 코드 품질 체크를 자동화하는 도구로, Lint, TypeScript, 테스트, 빌드 체크를 지원합니다","es":"Aprende a configurar rn-ci-check para ejecutar la suite completa de verificación de calidad y mejorar la calidad de tu código","fr":"Découvrez comment configurer rn-ci-check pour exécuter la suite complète de vérification de qualité et améliorer la qualité de votre code","de":"Erfahren Sie, wie Sie rn-ci-check konfigurieren, um die vollständige Qualitätsprüfungssuite auszuführen und die Code-Qualität zu verbessern","pt":"Aprenda a configurar o rn-ci-check para verificar a qualidade do seu código com lint, TypeScript, testes e build check","ru":"Узнайте, как настроить rn-ci-check для проверки качества вашего кода с помощью линта, TypeScript, тестов и проверки сборки","ar":"تعرف على كيفية إعداد rn-ci-check للتحقق من جودة رمزك باستخدام لينت و تايب سكريبت واختبارات و فحص البناء"},"definition":{"en":"rn-ci-check is a skill that automates the execution of a comprehensive quality verification suite, including lint, TypeScript, and tests, to ensure code quality and reliability.","zh":"RN CI Check 是一个自动化代码质量检查工具","ja":"RN CI Check はコード品質チェックの自動化ツールです","ko":"RN CI Check는 코드 품질 체크를 자동화하는 도구입니다","es":"rn-ci-check es una herramienta de verificación de calidad que ejecuta comandos como lint, TypeScript y tests","fr":"rn-ci-check est un outil de vérification de qualité qui exécute des commandes comme lint, TypeScript et tests","de":"rn-ci-check ist ein Qualitätsprüfungstool, das Befehle wie lint, TypeScript und Tests ausführt","pt":"rn-ci-check é uma ferramenta de verificação de qualidade de código que executa lint, TypeScript, testes e build check","ru":"rn-ci-check - это инструмент для проверки качества кода, который выполняет линт, TypeScript, тесты и проверку сборки","ar":"rn-ci-check هو أداة للتحقق من جودة الرمز التي تنفذ لينت و تايب سكريبت واختبارات و فحص البناء"},"features":{"en":["Executes npm run lint for code quality checks","Runs TypeScript checks using npx tsc --noEmit","Performs tests using npm test","Optional build check using npx expo prebuild --clean --no-install","Reports results in a formatted table with status and details"],"zh":["支持 Lint 检查","支持 TypeScript 检查","支持 测试和构建检查","自动化代码质量检查","支持格式化报告输出"],"ja":["Lint チェックに対応","TypeScript チェックに対応","テストとビルドチェックに対応","コード品質チェックの自動化","フォーマット化されたレポート出力に対応"],"ko":["Lint 체크 지원","TypeScript 체크 지원","테스트와 빌드 체크 지원","코드 품질 체크 자동화","서식화된 보고서 출력 지원"],"es":["Ejecución de lint para detectar errores comunes","Verificación de TypeScript para garantizar la compatibilidad","Ejecución de tests para asegurar la funcionalidad","Opción de comprobación de build para garantizar la compatibilidad","Informe de resultados con formato personalizado"],"fr":["Exécution de lint pour détecter les erreurs courantes","Vérification de TypeScript pour garantir la compatibilité","Exécution de tests pour assurer la fonctionnalité","Option de vérification de build pour garantir la compatibilité","Rapport de résultats avec format personnalisé"],"de":["Ausführung von lint zur Erkennung von häufigen Fehlern","Überprüfung von TypeScript zur Gewährleistung der Kompatibilität","Ausführung von Tests zur Sicherstellung der Funktionalität","Option zur Überprüfung von Build zur Gewährleistung der Kompatibilität","Bericht über die Ergebnisse mit personalisierten Format"],"pt":["Executa lint para verificar erros comuns","Verifica código TypeScript com npx tsc --noEmit","Executa testes com npm test","Verifica build com npx expo prebuild --clean --no-install","Relata resultados com formato personalizado"],"ru":["Выполняет линт для проверки общих ошибок","Проверяет код TypeScript с помощью npx tsc --noEmit","Выполняет тесты с помощью npm test","Проверяет сборку с помощью npx expo prebuild --clean --no-install","Отчеты результатов с индивидуальным форматом"],"ar":["تنفذ لينت للتحقق من الأخطاء الشائعة","تتحقق من رمز تايب سكريبت مع npx tsc --noEmit","تنفذ اختبارات مع npm test","تتحقق من البناء مع npx expo prebuild --clean --no-install","تقرير النتائج بفورمة مخصصة"]},"keywords":{"en":["how to use rn-ci-check","rn-ci-check setup guide","automated quality assurance","rn-ci-check alternative","rn-ci-check vs Jest","rn-ci-check install","what is rn-ci-check","rn-ci-check workflow integration","rn-ci-check best practices"],"zh":["RN CI Check","代码质量检查","自动化测试","Lint 检查","TypeScript 检查","AIエージェント","代码质量优化"],"ja":["RN CI Check","コード品質チェック","自動化テスト","Lint チェック","TypeScript チェック","AIエージェント","コード品質最適化"],"ko":["RN CI Check","코드 품질 체크","자동화 테스트","Lint 체크","TypeScript 체크","AI 에이전트","코드 품질 최적화"],"es":["rn-ci-check","verificación de calidad","herramientas de desarrollo","lint","TypeScript","tests","build","informes de resultados","desarrollo de software","calidad del código"],"fr":["rn-ci-check","vérification de qualité","outils de développement","lint","TypeScript","tests","build","rapports de résultats","développement de logiciels","qualité du code"],"de":["rn-ci-check","Qualitätsprüfung","Entwicklungstools","lint","TypeScript","Tests","Build","Ergebnisberichte","Software-Entwicklung","Code-Qualität"],"pt":["rn-ci-check","verificação de qualidade de código","lint","TypeScript","testes","build check","ferramenta de desenvolvimento","desenvolvimento de software"],"ru":["rn-ci-check","проверка качества кода","линт","TypeScript","тесты","проверка сборки","инструмент разработки","разработка программного обеспечения"],"ar":["rn-ci-check","التحقق من جودة الرمز","لينت","تايب سكريبت","اختبارات","فحص البناء","أداة التطوير","تطوير البرمجيات"]}},"owner":"asolerp","repo":"PManagement","repoPath":"asolerp/PManagement","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.486Z","topics":[],"category":"community","skillMd":{"name":"rn-ci-check","description":"Ejecuta checks de CI para React Native - lint, typecheck, tests. Usar cuando el usuario pida verificar calidad del código, antes de commit, o al preparar PR.","bodyPreview":"# RN CI Check\n\nEjecuta la suite completa de verificación de calidad.\n\n## Comandos\n\n```bash\n# 1. Lint\nnpm run lint\n\n# 2. TypeScript (si aplica)\nnpx tsc --noEmit\n\n# 3. Tests\nnpm test\n\n# 4. Build check (opcional, más lento)\nnpx expo prebuild --clean --no-install\n```\n\n## Workflow\n\n1. Ejecutar lint primero (más rápido, errores comunes)\n2. Si lint pasa, ejecutar tests\n3. Reportar resultados con formato:\n\n```\n## CI Check Results\n\n| Check | Status | Details |\n|-------|--------|---------|\n| Lint | ✅/❌ |","body":"# RN CI Check\n\nEjecuta la suite completa de verificación de calidad.\n\n## Comandos\n\n```bash\n# 1. Lint\nnpm run lint\n\n# 2. TypeScript (si aplica)\nnpx tsc --noEmit\n\n# 3. Tests\nnpm test\n\n# 4. Build check (opcional, más lento)\nnpx expo prebuild --clean --no-install\n```\n\n## Workflow\n\n1. Ejecutar lint primero (más rápido, errores comunes)\n2. Si lint pasa, ejecutar tests\n3. Reportar resultados con formato:\n\n```\n## CI Check Results\n\n| Check | Status | Details |\n|-------|--------|---------|\n| Lint | ✅/❌ | N warnings, M errors |\n| Tests | ✅/❌ | X passed, Y failed |\n| Build | ✅/❌ | Notes |\n```\n\n## Fix Automático\n\n```bash\n# Auto-fix lint errors\nnpm run lint -- --fix\n\n# Format con Prettier\nnpx prettier --write \"src/**/*.{js,jsx,ts,tsx}\"\n```\n\n## Errores Comunes\n\n- **Import order**: Ejecutar `eslint --fix`\n- **Unused vars**: Revisar si es intencional, prefixar con `_` si es necesario\n- **Missing deps en hooks**: Añadir al array o usar `// eslint-disable-next-line`\n"},"lastSynced":"2026-03-08T02:10:04.789Z","agentAnalysis":{"suitability":{"en":"Perfect for JavaScript Agents needing automated quality assurance and streamlined workflows with lint, TypeScript, and tests.","zh":"适用于需要自动化质量保证和使用 lint、TypeScript、测试的 JavaScript Agents 的工作流程。","ja":"JavaScript エージェントが自動化された品質保証と lint、TypeScript、テストのストリームライン化されたワークフローを必要とする場合に最適です。","ko":"자동화된 품질 보증 및 Lint, TypeScript, 테스트와 함께 워크플로우를 스트림 라인화해야 하는 JavaScript 에이전트에 적합합니다.","es":"Perfecto para agentes de JavaScript que necesitan aseguramiento de la calidad automatizado y flujos de trabajo optimizados con lint, TypeScript y pruebas.","fr":"Parfait pour les agents JavaScript ayant besoin d''une assurance qualité automatisée et de flux de travail rationalisés avec lint, TypeScript et tests.","de":"Perfekt für JavaScript-Agents, die ein automatisiertes Qualitätsmanagement und optimierte Workflows mit lint, TypeScript und Tests benötigen.","pt":"Perfeito para Agents JavaScript que necessitam de garantia de qualidade automatizada e fluxos de trabalho otimizados com lint, TypeScript e testes.","ru":"Идеально подходит для агентов JavaScript, которым требуется автоматизированная проверка качества и оптимизированные рабочие процессы с lint, TypeScript и тестами.","ar":"مثالي للوكلاء JavaScript الذين يحتاجون إلى ضمان جودة 자동 وعمليات工作 مجهزة مع lint و TypeScript واختبارات."},"recommendation":{"en":"Empowers agents to execute comprehensive quality checks using npm, TypeScript, and Expo, ensuring code integrity and reliability with commands like npm run lint, npx tsc, and npm test.","zh":"赋予代理执行全面质量检查的能力，使用 npm、TypeScript 和 Expo，确保代码完整性和可靠性，使用类似 npm run lint、npx tsc 和 npm test 的命令。","ja":"エージェントに、npm、TypeScript、Expo を使用して包括的な品質チェックを実行する能力を付与し、コードの完全性と信頼性を確保する、npm run lint、npx tsc、npm test などのコマンドを使用します。","ko":"npm, TypeScript, Expo를 사용하여 포괄적인 품질 검사를 실행할 수 있는 기능을 에이전트에게 부여하여 코드의完整性와 신뢰성을 보장하고 npm run lint, npx tsc, npm test와 같은 명령을 사용합니다.","es":"Habilita a los agentes a ejecutar controles de calidad exhaustivos utilizando npm, TypeScript y Expo, garantizando la integridad y confiabilidad del código con comandos como npm run lint, npx tsc y npm test.","fr":"Permet aux agents d''exécuter des contrôles de qualité complets en utilisant npm, TypeScript et Expo, assurant l''intégrité et la fiabilité du code avec des commandes comme npm run lint, npx tsc et npm test.","de":"Ermöglicht es Agents, umfassende Qualitätskontrollen mit npm, TypeScript und Expo durchzuführen, wodurch die Integrität und Zuverlässigkeit des Codes mit Befehlen wie npm run lint, npx tsc und npm test gewährleistet werden.","pt":"Habilita os agentes a executar verificações de qualidade abrangentes usando npm, TypeScript e Expo, garantindo a integridade e confiabilidade do código com comandos como npm run lint, npx tsc e npm test.","ru":"Наделяет агентов возможностью выполнять комплексные проверки качества с использованием npm, TypeScript и Expo, обеспечивая целостность и надежность кода с помощью команд như npm run lint, npx tsc и npm test.","ar":"يمنح الوكلاء القدرة على تنفيذ فحوصات جودة شاملة باستخدام npm و TypeScript و Expo، مما يضمن سلامة وصلاحية الكود مع أوامر مثل npm run lint و npx tsc و npm test."},"useCases":{"en":["Automating code linting for error detection","Executing TypeScript checks for type safety","Running tests for functional validation"],"zh":["自动化代码 linting 以进行错误检测","执行 TypeScript 检查以进行类型安全","运行测试以进行功能验证"],"ja":["コードの linting を自動化してエラーを検出する","TypeScript のチェックを実行してタイプの安全性を確保する","テストを実行して機能を検証する"],"ko":["에러 감지를 위한 코드 린팅 자동화","타입 안전을 위한 TypeScript 체크 실행","기능 검증을 위한 테스트 실행"],"es":["Automatización de la detección de errores de código con lint","Ejecución de controles de TypeScript para la seguridad de tipos","Ejecución de pruebas para la validación funcional"],"fr":["Automatisation de la détection d''erreurs de code avec lint","Exécution de contrôles de TypeScript pour la sécurité des types","Exécution de tests pour la validation fonctionnelle"],"de":["Automatisierung der Fehlererkennung von Code mit lint","Ausführung von TypeScript-Prüfungen für die Typsicherheit","Ausführung von Tests für die funktionale Validierung"],"pt":["Automatizar a verificação de código para detecção de erros","Executar verificações de TypeScript para segurança de tipo","Executar testes para validação funcional"],"ru":["Автоматизировать проверку кода для обнаружения ошибок","Выполнять проверки TypeScript для безопасности типа","Выполнять тесты для функциональной проверки"],"ar":["ت خودومة فحص الشفرة للكشف عن الأخطاء","تشغيل فحوصات TypeScript لأمان النوع","تشغيل الاختبارات للتأكيد الوظيفي"]},"limitations":{"en":["Requires Node.js environment","Dependent on npm and Expo installations","Optional build check can be slower"],"zh":["需要 Node.js 环境","依赖于 npm 和 Expo 安装","可选的构建检查可能会更慢"],"ja":["Node.js 環境が必要","npm と Expo のインストールに依存している","オプションのビルド チェックは遅くなる可能性がある"],"ko":["Node.js 환경이 필요합니다.","npm 및 Expo 설치에 의존합니다.","선택적 빌드 확인은 더 느릴 수 있습니다."],"es":["Requiere un entorno de Node.js","Dependiente de las instalaciones de npm y Expo","La comprobación de compilación opcional puede ser más lenta"],"fr":["Nécessite un environnement Node.js","Dépendante des installations de npm et Expo","La vérification de construction optionnelle peut être plus lente"],"de":["Benötigt eine Node.js-Umgebung","Abhängig von npm- und Expo-Installationen","Der optionale Build-Check kann langsamer sein"],"pt":["Requer ambiente Node.js","Dependente das instalações do npm e Expo","Verificação de compilação opcional pode ser mais lenta"],"ru":["Требуется среда Node.js","Зависит от установок npm и Expo","Необязательная проверка сборки может быть медленнее"],"ar":["يتطلب بيئة Node.js","يعتمد على تثبيت npm و Expo","يمكن أن تكون فحص البناء الإختياري أبطأ"]},"version":4},"contentHash":"9823573b8ada780cb297e6f41bce93ab1fa87aa05403d6f5eecdcbd7937d4058","qualityScore":30}');
