INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('asolerp/PManagement/rn-ci-check', 'rn-ci-check', 'asolerp', 'PManagement', 'community', 'rn-ci-check asolerp PManagement community The rn-ci-check skill automates quality assurance by executing a suite of checks, including lint, TypeScript, and tests, benefiting developers with streamlined workflows. RN CI Check 是一个自动化代码质量检查工具，支持 Lint、TypeScript、测试和构建检查，帮助开发者提高代码质量 RN CI Check はコード品質チェックの自動化ツールで、Lint、TypeScript、テスト、ビルドチェックに対応し、開発者のコード品質を向上させます RN CI Check는 코드 품질 체크를 자동화하는 도구로, Lint, TypeScript, 테스트, 빌드 체크를 지원하여 개발자의 코드 품질을 향상시킵니다 rn-ci-check es una herramienta que ejecuta la suite completa de verificación de calidad para mejorar la calidad del código rn-ci-check est un outil qui exécute la suite complète de vérification de qualité pour améliorer la qualité du code rn-ci-check ist ein Tool, das die vollständige Qualitätsprüfungssuite ausführt, um die Code-Qualität zu verbessern O rn-ci-check é uma ferramenta que executa a suite completa de verificação de qualidade de código, incluindo lint, TypeScript, testes e build check rn-ci-check - это инструмент, который выполняет полный чек линта и тестов для проверки качества вашего кода rn-ci-check هو أداة تقوم bằngتنفيذ مجموعة كاملة من التحقق من جودة الرمز، بما في ذلك لينت و تايب سكريبت واختبارات و فحص البناء how to use rn-ci-check rn-ci-check setup guide automated quality assurance rn-ci-check alternative rn-ci-check vs Jest rn-ci-check install what is rn-ci-check rn-ci-check workflow integration rn-ci-check best practices RN CI Check 代码质量检查 自动化测试 Lint 检查 TypeScript 检查 AIエージェント 代码质量优化 Executes npm run lint for code quality checks Runs TypeScript checks using npx tsc --noEmit Performs tests using npm test Optional build check using npx expo prebuild --clean --no-install Reports results in a formatted table with status and details rn-ci-check is a skill that automates the execution of a comprehensive quality verification suite, including lint, TypeScript, and tests, to ensure code quality and reliability.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MehdiMamas/ShareGo/add-message-type', 'community', 'MehdiMamas', 'ShareGo', 'MehdiMamas/ShareGo', 'add-message-type', 0, 0, 30, '2026-03-08T01:57:15.493Z', '2026-03-08T02:10:11.035Z', 'a4e2b01d7e805512a763570d66505819e70e590414186bedbb2d48bd306dfc7b', '{"id":"MehdiMamas/ShareGo/add-message-type","name":"add-message-type","description":{"en":"The add-message-type skill enables serverless, end-to-end encrypted file and secret sharing between devices on a local network. Developers can extend the ShareGo protocol by adding new message types.","zh":"添加新的消息类型到ShareGo协议中，实现无服务器端到端加密的文件和密钥分享","ja":"ShareGoプロトコルに新しいメッセージタイプを追加して、サーバーレスエンドツーエンド暗号化ファイルとキーシェアリングを実現します","ko":"ShareGo 프로토콜에 새로운 메시지 유형을 추가하여 서버리스 종단간 암호화 파일과 키 공유를 구현합니다","es":"Agregar un nuevo tipo de mensaje en ShareGo implica modificar el núcleo de la biblioteca y la documentación. Se utilizan mensajes JSON tipados sobre WebSocket.","fr":"Ajouter un nouveau type de message dans ShareGo nécessite des modifications dans le cœur de la bibliothèque et de la documentation. Des messages JSON typés sur WebSocket sont utilisés.","de":"Das Hinzufügen eines neuen Nachrichtentyps in ShareGo erfordert Änderungen im Kern der Bibliothek und der Dokumentation. Es werden typisierte JSON-Nachrichten über WebSocket verwendet.","pt":"O protocolo ShareGo utiliza mensagens JSON tipadas sobre WebSocket. Adicionar um novo tipo de mensagem requer alterações no core library e documentação.","ru":"Протокол ShareGo использует типизированные JSON-сообщения над WebSocket. Добавление нового типа сообщения требует изменений в основной библиотеке и документации.","ar":"يستخدم بروتوكول ShareGo رسائل JSON من النوع المحدد عبر WebSocket. يتطلب إضافة نوع رسالة جديد تغييرات في المكتبة الأساسية والتوثيق."},"seo":{"title":{"en":"add-message-type: WebSocket Protocol Extension Setup Guid...","zh":"添加消息类型设置指南 - 无服务器端到端加密文件分享","ja":"メッセージタイプ追加セットアップガイド - サーバーレスエンドツーエンド暗号化ファイル共有","ko":"메시지 유형 추가 설정 가이드 - 서버리스 종단간 암호화 파일 공유","es":"Guía de configuración para agregar un nuevo tipo de mensa...","fr":"Guide d''installation pour ajouter un nouveau type de mess...","de":"Einrichtungsleitfaden für das Hinzufügen eines neuen Nach...","pt":"Guia de Configuração do Tipo de Mensagem em ShareGo","ru":"Настройка нового типа сообщения в ShareGo: ИИ Агенты","ar":"إعداد نوع الرسالة في ShareGo: أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to add new message types to the ShareGo protocol using typed JSON messages over WebSocket. Learn the steps and benefits now!","zh":"了解如何添加新的消息类型到ShareGo协议中，实现服务器端到端加密的文件和密钥分享","ja":"ShareGoプロトコルに新しいメッセージタイプを追加する方法を学び、サーバーレスエンドツーエンド暗号化ファイルとキーシェアリングを実現する","ko":"ShareGo 프로토콜에 새로운 메시지 유형을 추가하여 서버리스 종단간 암호화 파일과 키 공유를 구현하는 방법을 알아보세요","es":"Aprende a agregar un nuevo tipo de mensaje en ShareGo utilizando WebSocket y JSON. Descubre los pasos y las tecnologías necesarias.","fr":"Découvrez comment ajouter un nouveau type de message dans ShareGo en utilisant WebSocket et JSON. Suivez les étapes et les technologies nécessaires.","de":"Erfahren Sie, wie Sie einen neuen Nachrichtentyp in ShareGo mithilfe von WebSocket und JSON hinzufügen. Entdecken Sie die Schritte und erforderlichen Technol...","pt":"Aprenda a adicionar um novo tipo de mensagem ao protocolo ShareGo, incluindo alterações no core library e documentação.","ru":"Изучите процесс добавления нового типа сообщения в протокол ShareGo, включая изменения в основной библиотеке и документации. ИИ Агенты","ar":"تعرف على كيفية إضافة نوع رسالة جديد إلى بروتوكول ShareGo، بما في ذلك التغييرات في المكتبة الأساسية والتوثيق. أدوات الذكاء الاصطناعي"},"definition":{"en":"add-message-type is a skill that allows developers to extend the ShareGo protocol by adding new message types using typed JSON messages over WebSocket.","zh":"添加消息类型是ShareGo协议中的一个过程，涉及修改核心库和文档以支持新的消息类型","ja":"メッセージタイプ追加は、ShareGoプロトコルの中核ライブラリとドキュメントを変更して新しいメッセージタイプをサポートするプロセスです","ko":"메시지 유형 추가는 ShareGo 프로토콜의 핵심 라이브러리와 문서를 수정하여 새로운 메시지 유형을 지원하는 프로세스입니다","es":"Un nuevo tipo de mensaje en ShareGo es una extensión del protocolo que utiliza mensajes JSON tipados sobre WebSocket para compartir archivos y secretos de manera segura.","fr":"Un nouveau type de message dans ShareGo est une extension du protocole qui utilise des messages JSON typés sur WebSocket pour partager des fichiers et des secrets de manière sécurisée.","de":"Ein neuer Nachrichtentyp in ShareGo ist eine Erweiterung des Protokolls, das typisierte JSON-Nachrichten über WebSocket zur sicheren Freigabe von Dateien und Geheimnissen verwendet.","pt":"O tipo de mensagem é um componente fundamental do protocolo ShareGo, permitindo a comunicação segura entre dispositivos.","ru":"Тип сообщения является фундаментальным компонентом протокола ShareGo, обеспечивающим безопасную связь между устройствами.","ar":"نوع الرسالة هو مكون أساسي في بروتوكول ShareGo، مما يسمح بالاتصال الآمن بين الأجهزة."},"features":{"en":["Adds new message types to the ShareGo protocol using WebSocket","Modifies the core library by updating the MessageType enum in types.ts","Defines new message interfaces, such as PingMessage, extending BaseMessage","Supports end-to-end encrypted file and secret sharing between devices on a local network","Uses typed JSON messages for secure and reliable communication","Requires updates to the core library and documentation"],"zh":["使用WebSocket进行typed JSON消息传递","修改核心库以支持新的消息类型","定义消息接口以扩展BaseMessage","添加新的消息类型到MessageType枚举中","支持服务器端到端加密的文件和密钥分享"],"ja":["WebSocketを使用したtyped JSONメッセージの伝達","新しいメッセージタイプをサポートするためのコアライブラリの変更","メッセージインターフェイスの定義によるBaseMessageの拡張","MessageType列挙型への新しいメッセージタイプの追加","サーバーレスエンドツーエンド暗号化ファイルとキーシェアリングのサポート"],"ko":["WebSocket을 사용한 typed JSON 메시지 전달","新的 메시지 유형을 지원하기 위한 핵심 라이브러리 변경","메시지 인터페이스의 정의에 의한 BaseMessage 확장","MessageType 열거형에 새로운 메시지 유형 추가","서버리스 종단간 암호화 파일과 키 공유 지원"],"es":["Utiliza mensajes JSON tipados sobre WebSocket","Modificaciones en el núcleo de la biblioteca y la documentación","Extensión del protocolo ShareGo","Compartir archivos y secretos de manera segura","Sin necesidad de cloud o relay","Utiliza Wi-Fi para la comunicación"],"fr":["Utilise des messages JSON typés sur WebSocket","Modifications dans le cœur de la bibliothèque et de la documentation","Extension du protocole ShareGo","Partage de fichiers et de secrets de manière sécurisée","Pas besoin de cloud ou de relay","Utilise Wi-Fi pour la communication"],"de":["Verwendet typisierte JSON-Nachrichten über WebSocket","Änderungen im Kern der Bibliothek und der Dokumentation","Erweiterung des ShareGo-Protokolls","Sichere Freigabe von Dateien und Geheimnissen","Keine Notwendigkeit von Cloud oder Relay","Verwendet Wi-Fi für die Kommunikation"],"pt":["Utiliza mensagens JSON tipadas sobre WebSocket","Requer alterações no core library e documentação","Permite a adição de novos tipos de mensagens","Compatível com o protocolo ShareGo","Utiliza enum para definir os tipos de mensagens","Define a interface da mensagem com TypeScript"],"ru":["Использует типизированные JSON-сообщения над WebSocket","Требует изменений в основной библиотеке и документации","Позволяет добавлять новые типы сообщений","Совместим с протоколом ShareGo","Использует перечисление для определения типов сообщений","Определяет интерфейс сообщения с помощью TypeScript"],"ar":["يستخدم رسائل JSON من النوع المحدد عبر WebSocket","يتطلب تغييرات في المكتبة الأساسية والتوثيق","يسمح بإضافة أنواع رسائل جديدة","متوافق مع بروتوكول ShareGo","يستخدم التعداد لتحديد أنواع الرسائل","يحدد واجهة الرسالة باستخدام TypeScript"]},"keywords":{"en":["how to add new message type to ShareGo protocol","what is add-message-type skill","add-message-type alternative","add-message-type vs WebSocket protocol","add-message-type setup guide","add-message-type installation","ShareGo protocol extension","typed JSON messages over WebSocket","end-to-end encrypted file sharing"],"zh":["添加消息类型","ShareGo协议","WebSocket","typed JSON","服务器端到端加密","文件分享","AIエージェント","服务器less"],"ja":["メッセージタイプ追加","ShareGoプロトコル","WebSocket","typed JSON","サーバーレスエンドツーエンド暗号化","ファイル共有","AIエージェント","サーバーレス"],"ko":["메시지 유형 추가","ShareGo 프로토콜","WebSocket","typed JSON","서버리스 종단간 암호화","파일 공유","AI 에이전트","서버리스"],"es":["agregar nuevo tipo de mensaje","ShareGo","WebSocket","JSON","protocolo de mensajería","compartir archivos","compartir secretos","seguridad","Wi-Fi","desarrollo de aplicaciones"],"fr":["ajouter nouveau type de message","ShareGo","WebSocket","JSON","protocole de messagerie","partager des fichiers","partager des secrets","sécurité","Wi-Fi","développement d''applications"],"de":["neuen Nachrichtentyp hinzufügen","ShareGo","WebSocket","JSON","Nachrichtenprotokoll","Dateien freigeben","Geheimnisse freigeben","Sicherheit","Wi-Fi","Anwendungsentwicklung"],"pt":["adicionar tipo de mensagem","protocolo ShareGo","mensagens JSON tipadas","WebSocket","core library","documentação","TypeScript","enum","interface de mensagem"],"ru":["добавить тип сообщения","протокол ShareGo","типизированные JSON-сообщения","WebSocket","основная библиотека","документация","TypeScript","перечисление","интерфейс сообщения","ИИ Агенты"],"ar":["إضافة نوع الرسالة","بروتوكول ShareGo","رسائل JSON من النوع المحدد","WebSocket","المكتبة الأساسية","التوثيق","TypeScript","التعداد","واجهة الرسالة","أدوات الذكاء الاصطناعي"]}},"owner":"MehdiMamas","repo":"ShareGo","repoPath":"MehdiMamas/ShareGo","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.493Z","topics":[],"category":"community","skillMd":{"name":"add-message-type","description":"Guide for adding a new protocol message type to ShareGo. Use when extending the wire protocol with a new message type.","bodyPreview":"# Adding a new message type\n\nthe ShareGo protocol uses typed JSON messages over WebSocket. adding a new message type requires changes in the core library and documentation.\n\n## Steps\n\n### 1. Add the type to the enum\n\nfile: `core/src/protocol/types.ts`\n\n```typescript\nexport enum MessageType {\n  // ... existing types\n  PING = \"PING\",  // your new type\n}\n```\n\n### 2. Define the message interface\n\nfile: `core/src/protocol/types.ts`\n\n```typescript\nexport interface PingMessage extends BaseMessage {\n  t","body":"# Adding a new message type\n\nthe ShareGo protocol uses typed JSON messages over WebSocket. adding a new message type requires changes in the core library and documentation.\n\n## Steps\n\n### 1. Add the type to the enum\n\nfile: `core/src/protocol/types.ts`\n\n```typescript\nexport enum MessageType {\n  // ... existing types\n  PING = \"PING\",  // your new type\n}\n```\n\n### 2. Define the message interface\n\nfile: `core/src/protocol/types.ts`\n\n```typescript\nexport interface PingMessage extends BaseMessage {\n  type: MessageType.PING;\n  timestamp: number;\n}\n```\n\n### 3. Add to the union\n\nfile: `core/src/protocol/types.ts`\n\n```typescript\nexport type ProtocolMessage =\n  | HelloMessage\n  | ChallengeMessage\n  // ... existing\n  | PingMessage;  // add here\n```\n\n### 4. Update serialization validation\n\nfile: `core/src/protocol/serialization.ts`\n\nadd a case for the new type in `deserializeMessage()` to validate required fields:\n\n```typescript\ncase MessageType.PING:\n  if (typeof parsed.timestamp !== \"number\") {\n    throw new Error(\"PING: missing timestamp\");\n  }\n  break;\n```\n\n### 5. Handle in session\n\nfile: `core/src/session/session.ts`\n\nadd a case in `handleIncoming()`:\n\n```typescript\ncase MessageType.PING:\n  this.handlePing(msg as PingMessage);\n  break;\n```\n\n### 6. Export if needed\n\nif the new message type needs to be used by app shells, export it from:\n- `core/src/protocol/index.ts`\n- `core/src/index.ts`\n\n### 7. Add tests\n\nfile: `core/src/protocol/serialization.test.ts`\n\n```typescript\nit(\"should roundtrip PING message\", () => {\n  const msg: PingMessage = {\n    ...createBaseFields(MessageType.PING, \"ABC123\", 1),\n    timestamp: Date.now(),\n  };\n  const bytes = serializeMessage(msg);\n  const parsed = deserializeMessage(bytes);\n  expect(parsed.type).toBe(MessageType.PING);\n});\n```\n\n### 8. Update documentation\n\n- `docs/PROTOCOL.md` — add the message spec, fields table, and example JSON\n- `docs/THREAT_MODEL.md` — add security implications if the message carries sensitive data\n- `.cursor/rules/sharego-protocol.mdc` — update if wire format changes\n\n## Security checklist\n\n- [ ] new message does NOT carry plaintext sensitive data (passwords, OTPs)\n- [ ] if it carries binary data, it uses AEAD encryption like DATA messages\n- [ ] sequence number is required and validated\n- [ ] protocol version is checked\n- [ ] session ID is validated\n- [ ] unknown/unexpected messages of this type are rejected, not ignored\n- [ ] no new fields leak key material or internal state\n\n## Checklist\n\n- [ ] enum value added to `MessageType`\n- [ ] interface defined extending `BaseMessage`\n- [ ] added to `ProtocolMessage` union\n- [ ] serialization validation added in `deserializeMessage()`\n- [ ] handler added in `session.ts` `handleIncoming()`\n- [ ] exported from barrel files (if needed by app shells)\n- [ ] roundtrip test added\n- [ ] `docs/PROTOCOL.md` updated with spec\n- [ ] `docs/THREAT_MODEL.md` updated if security-relevant\n"},"lastSynced":"2026-03-08T02:10:11.035Z","agentAnalysis":{"suitability":{"en":"Ideal for Advanced Protocol Agents needing to extend the ShareGo protocol with custom message types over WebSocket.","zh":"适用于需要使用自定义消息类型扩展ShareGo协议的高级协议代理，支持通过WebSocket进行通信。","ja":"ShareGoプロトコルをカスタムメッセージタイプで拡張する必要がある高度なプロトコルエージェントに適しています。WebSocketを介して通信します。","ko":"WebSocket을 통해 커스텀 메시지 유형으로 ShareGo 프로토콜을 확장해야 하는 고급 프로토콜 에이전트에 적합합니다.","es":"Ideal para Agentes de Protocolo Avanzados que necesitan extender el protocolo ShareGo con tipos de mensajes personalizados sobre WebSocket.","fr":"Idéal pour les agents de protocole avancés ayant besoin d''étendre le protocole ShareGo avec des types de messages personnalisés sur WebSocket.","de":"Ideal für erweiterte Protokollagenten, die das ShareGo-Protokoll mit benutzerdefinierten Nachrichtentypen über WebSocket erweitern müssen.","pt":"Ideal para Agentes de Protocolo Avançados que precisam estender o protocolo ShareGo com tipos de mensagens personalizados sobre WebSocket.","ru":"Идеально для Продвинутых Агентов Протокола, которым необходимо расширить протокол ShareGo с помощью пользовательских типов сообщений через WebSocket.","ar":"مثالي لعميل بروتوكول متقدم يحتاج إلى توسيع بروتوكول ShareGo مع أنواع رسائل مخصصة عبر WebSocket."},"recommendation":{"en":"Empowers agents to define new message interfaces, such as PingMessage, using typed JSON messages and enums like MessageType, enhancing end-to-end encrypted file and secret sharing capabilities.","zh":"赋予代理定义新的消息接口，例如PingMessage，使用带有MessageType等枚举的类型化JSON消息，增强端到端加密的文件和密钥共享能力。","ja":"エージェントがMessageTypeなどの列挙型を使用した型付きJSONメッセージで新しいメッセージインターフェイス（例：PingMessage）を定義できるようにし、エンドツーエンド暗号化されたファイルおよびシークレット共有機能を強化します。","ko":"에이전트가 MessageType 등의 열거형을 사용한 유형화된 JSON 메시지를 통해 새로운 메시지 인터페이스(예: PingMessage)를 정의할 수 있도록 하여, 종단 간 암호화된 파일 및 비밀 공유 기능을 강화합니다.","es":"Permite a los agentes definir nuevas interfaces de mensajes, como PingMessage, utilizando mensajes JSON con tipos y enums como MessageType, lo que mejora las capacidades de intercambio de archivos y secretos cifrados de extremo a extremo.","fr":"Permet aux agents de définir de nouvelles interfaces de messages, telles que PingMessage, en utilisant des messages JSON typés et des énumérations comme MessageType, améliorant ainsi les capacités de partage de fichiers et de secrets chiffrés de bout en bout.","de":"Ermöglicht es Agenten, neue Nachrichtenschnittstellen wie PingMessage zu definieren, indem sie typisierte JSON-Nachrichten und Enums wie MessageType verwenden, wodurch die Funktionen zum Austausch von Dateien und Geheimnissen mit End-to-End-Verschlüsselung verbessert werden.","pt":"Permite que os agentes definam novas interfaces de mensagens, como PingMessage, usando mensagens JSON tipadas e enums como MessageType, melhorando as capacidades de compartilhamento de arquivos e segredos criptografados de ponta a ponta.","ru":"Позволяет агентам определять новые интерфейсы сообщений, такие как PingMessage, используя типизированные сообщения JSON и перечисления, такие как MessageType, повышая возможности шифрования файлов и секретов от конца до конца.","ar":"يمكن للعميل تعريف واجهات رسائل جديدة، مثل PingMessage، باستخدام رسائل JSON من نوع معين وتراكيب مثل MessageType، وتحسين القدرات التي تمكن من مشاركة الملفات والأسرار المشفرة من النهاية إلى النهاية."},"useCases":{"en":["Extending the ShareGo protocol with custom message types","Implementing typed JSON messages over WebSocket","Adding new message types to the core library and documentation"],"zh":["使用自定义消息类型扩展ShareGo协议","通过WebSocket实现类型化JSON消息","向核心库和文档添加新的消息类型"],"ja":["ShareGoプロトコルをカスタムメッセージタイプで拡張する","WebSocket上で型付きJSONメッセージを実装する","コアライブラリとドキュメントに新しいメッセージタイプを追加する"],"ko":["커스텀 메시지 유형으로 ShareGo 프로토콜 확장","WebSocket에서 유형화된 JSON 메시지 구현","코어 라이브러리 및 문서에 새로운 메시지 유형 추가"],"es":["Extender el protocolo ShareGo con tipos de mensajes personalizados","Implementar mensajes JSON con tipos sobre WebSocket","Agregar nuevos tipos de mensajes a la biblioteca y documentación básica"],"fr":["Étendre le protocole ShareGo avec des types de messages personnalisés","Mettre en œuvre des messages JSON typés sur WebSocket","Ajouter de nouveaux types de messages à la bibliothèque et à la documentation de base"],"de":["Das ShareGo-Protokoll mit benutzerdefinierten Nachrichtentypen erweitern","Typisierte JSON-Nachrichten über WebSocket implementieren","Neue Nachrichtentypen zur Kernbibliothek und -dokumentation hinzufügen"],"pt":["Estender o protocolo ShareGo com tipos de mensagens personalizados","Implementar mensagens JSON tipadas sobre WebSocket","Adicionar novos tipos de mensagens à biblioteca central e documentação"],"ru":["Расширение протокола ShareGo с помощью пользовательских типов сообщений","Реализация типизированных сообщений JSON через WebSocket","Добавление новых типов сообщений в основную библиотеку и документацию"],"ar":["توسيع بروتوكول ShareGo مع أنواع رسائل مخصصة","تنفيذ رسائل JSON من نوع معين عبر WebSocket","إضافة أنواع رسائل جديدة إلى المكتبة الأساسية والتوثيق"]},"limitations":{"en":["Requires changes to the core library and documentation","Typed JSON messages over WebSocket only","ShareGo protocol extension limitations apply"],"zh":["需要对核心库和文档进行更改","仅支持WebSocket上的类型化JSON消息","ShareGo协议扩展限制适用"],"ja":["コアライブラリとドキュメントの変更が必要","WebSocket上での型付きJSONメッセージのみをサポート","ShareGoプロトコル拡張の制限が適用される"],"ko":["코어 라이브러리 및 문서의 변경이 필요","WebSocket에서 유형화된 JSON 메시지만 지원","ShareGo 프로토콜 확장 제한 사항이 적용"],"es":["Requiere cambios en la biblioteca y documentación básica","Mensajes JSON con tipos solo sobre WebSocket","Se aplican las limitaciones de extensión del protocolo ShareGo"],"fr":["Nécessite des modifications de la bibliothèque et de la documentation de base","Messages JSON typés uniquement sur WebSocket","Les limitations d''extension du protocole ShareGo s''appliquent"],"de":["Erfordert Änderungen an der Kernbibliothek und -dokumentation","Typisierte JSON-Nachrichten nur über WebSocket","Die Einschränkungen der ShareGo-Protokollerweiterung gelten"],"pt":["Requer alterações na biblioteca central e documentação","Mensagens JSON tipadas sobre WebSocket apenas","Limitações da extensão do protocolo ShareGo se aplicam"],"ru":["Требует изменений в основной библиотеке и документации","Типизированные сообщения JSON через WebSocket только","Ограничения расширения протокола ShareGo применяются"],"ar":["يتطلب تغييرات في المكتبة الأساسية والتوثيق","رسائل JSON من نوع معين عبر WebSocket فقط","قيود توسيع بروتوكول ShareGo تنطبق"]},"version":4},"contentHash":"a4e2b01d7e805512a763570d66505819e70e590414186bedbb2d48bd306dfc7b","qualityScore":30}');
