INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MehdiMamas/ShareGo/add-message-type', 'add-message-type', 'MehdiMamas', 'ShareGo', 'community', 'add-message-type MehdiMamas ShareGo community The add-message-type skill enables serverless, end-to-end encrypted file and secret sharing between devices on a local network. Developers can extend the ShareGo protocol by adding new message types. 添加新的消息类型到ShareGo协议中，实现无服务器端到端加密的文件和密钥分享 ShareGoプロトコルに新しいメッセージタイプを追加して、サーバーレスエンドツーエンド暗号化ファイルとキーシェアリングを実現します ShareGo 프로토콜에 새로운 메시지 유형을 추가하여 서버리스 종단간 암호화 파일과 키 공유를 구현합니다 Agregar un nuevo tipo de mensaje en ShareGo implica modificar el núcleo de la biblioteca y la documentación. Se utilizan mensajes JSON tipados sobre WebSocket. Ajouter un nouveau type de message dans ShareGo nécessite des modifications dans le cœur de la bibliothèque et de la documentation. Des messages JSON typés sur WebSocket sont utilisés. Das Hinzufügen eines neuen Nachrichtentyps in ShareGo erfordert Änderungen im Kern der Bibliothek und der Dokumentation. Es werden typisierte JSON-Nachrichten über WebSocket verwendet. O protocolo ShareGo utiliza mensagens JSON tipadas sobre WebSocket. Adicionar um novo tipo de mensagem requer alterações no core library e documentação. Протокол ShareGo использует типизированные JSON-сообщения над WebSocket. Добавление нового типа сообщения требует изменений в основной библиотеке и документации. يستخدم بروتوكول ShareGo رسائل JSON من النوع المحدد عبر WebSocket. يتطلب إضافة نوع رسالة جديد تغييرات في المكتبة الأساسية والتوثيق. how to add new message type to ShareGo protocol what is add-message-type skill add-message-type alternative add-message-type vs WebSocket protocol add-message-type setup guide add-message-type installation ShareGo protocol extension typed JSON messages over WebSocket end-to-end encrypted file sharing 添加消息类型 ShareGo协议 WebSocket typed JSON 服务器端到端加密 文件分享 AIエージェント 服务器less Adds new message types to the ShareGo protocol using WebSocket Modifies the core library by updating the MessageType enum in types.ts Defines new message interfaces, such as PingMessage, extending BaseMessage Supports end-to-end encrypted file and secret sharing between devices on a local network Uses typed JSON messages for secure and reliable communication Requires updates to the core library and documentation add-message-type is a skill that allows developers to extend the ShareGo protocol by adding new message types using typed JSON messages over WebSocket.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('silentip404/wangshuhao/create-commit-message', 'community', 'silentip404', 'wangshuhao', 'silentip404/wangshuhao', 'create-commit-message', 0, 0, 30, '2026-03-08T01:57:15.495Z', '2026-03-08T02:10:12.772Z', 'c2f2438164cfd786feb2172e1ef0680a6371a269e84546e9940bd4666093a82e', '{"id":"silentip404/wangshuhao/create-commit-message","name":"create-commit-message","description":{"en":"The create-commit-message skill generates standardized commit messages based on project commitlint configurations, benefiting developers by streamlining their Git workflow.","zh":"Create Commit Message 根据项目 commitlint 配置生成规范的提交消息，智能检测变更范围，提高代码提交效率","ja":"Create Commit Message は、プロジェクトの commitlint 構成に基づいて規範のコミットメッセージを生成し、変更範囲を智能的に検出してコードの提出効率を向上させる","ko":"Create Commit Message는 프로젝트의 commitlint 설정에 따라 표준화된 커밋 메시지를 생성하며, 변경 범위를智能적으로检测하여 코드 제출 효율을 높입니다","es":"create-commit-message es una herramienta que genera mensajes de commit personalizados según la configuración de commitlint. Ayuda a los desarrolladores a mantener un historial de commits claro y coherente.","fr":"create-commit-message est un outil qui génère des messages de commit personnalisés en fonction de la configuration de commitlint. Il aide les développeurs à maintenir un historique de commits clair et cohérent.","de":"create-commit-message ist ein Tool, das benutzerdefinierte Commit-Mitteilungen basierend auf der commitlint-Konfiguration generiert. Es hilft Entwicklern, ein klares und kohärentes Commit-Verlauf zu erhalten.","pt":"O Create Commit Message é uma ferramenta que gera mensagens de commit personalizadas com base no commitlint. Ele detecta automaticamente o escopo das alterações e gera mensagens de commit de acordo.","ru":"Инструмент создания коммитов генерирует индивидуальные сообщения о коммитах на основе commitlint. Он автоматически обнаруживает объем изменений и генерирует сообщения о коммитах соответственно.","ar":"أداة إنشاء رسائل الإلتزام تُنشئ رسائل إلتزام مخصصة على أساس commitlint. فهي تكتشف تلقائيًا نطاق التغييرات وتُنشئ رسائل إلتزام وفقًا لذلك."},"seo":{"title":{"en":"create-commit-message: Automated Commit Message Generatio...","zh":"Create Commit Message Setup Guide - 生成规范提交消息","ja":"Create Commit Message の設定方法 - コミットメッセージ自動生成","ko":"Create Commit Message 설정 가이드 - 커밋 메시지 자동 생성","es":"Guía de Configuración de create-commit-message para Desar...","fr":"Configurer create-commit-message: Meilleures Pratiques po...","de":"Einrichten von create-commit-message: Leitfaden für Entwi...","pt":"Guia de Configuração do Create Commit Message","ru":"Настройка Инструмента Создания Коммитов","ar":"دليل إعداد أداة إنشاء رسائل الإلتزام"},"description":{"en":"Automate your Git workflow with create-commit-message. Learn how to generate standardized commit messages with ease. Get started now!","zh":"使用 Create Commit Message 生成规范的提交消息，自动检测变更范围，提高代码提交效率","ja":"Create Commit Message を使用して、規範のコミットメッセージを自動生成し、コードの提出効率を向上させる","ko":"Create Commit Message를 사용하여 표준화된 커밋 메시지를 자동 생성하고 코드 제출 효율을 높여보세요","es":"Aprende a configurar create-commit-message para generar mensajes de commit personalizados y mejorar tu flujo de trabajo de desarrollo con Git","fr":"Découvrez comment configurer create-commit-message pour générer des messages de commit personnalisés et améliorer votre flux de travail de développement avec...","de":"Erfahren Sie, wie Sie create-commit-message konfigurieren, um benutzerdefinierte Commit-Mitteilungen zu generieren und Ihren Entwicklungsworkflow mit Git zu ...","pt":"Aprenda a configurar o Create Commit Message para gerar mensagens de commit personalizadas com base no commitlint","ru":"Узнайте, как настроить инструмент создания коммитов для генерации индивидуальных сообщений о коммитах на основе commitlint","ar":"تعلم كيفية تكوين أداة إنشاء رسائل الإلتزام لإنشاء رسائل إلتزام مخصصة على أساس commitlint"},"definition":{"en":"create-commit-message is a skill that automatically generates commit messages according to project commitlint configurations, using Git commands like git diff --cached and git diff.","zh":"Create Commit Message 是一个根据项目 commitlint 配置生成规范提交消息的工具","ja":"Create Commit Message は、プロジェクトの commitlint 構成に基づいて規範のコミットメッセージを生成するツールです","ko":"Create Commit Message는 프로젝트의 commitlint 설정에 따라 표준화된 커밋 메시지를 생성하는 툴입니다","es":"create-commit-message es una herramienta de línea de comandos que genera mensajes de commit personalizados para proyectos Git","fr":"create-commit-message est un outil en ligne de commande qui génère des messages de commit personnalisés pour les projets Git","de":"create-commit-message ist ein Command-Line-Tool, das benutzerdefinierte Commit-Mitteilungen für Git-Projekte generiert","pt":"O Create Commit Message é uma ferramenta que gera mensagens de commit personalizadas com base no commitlint","ru":"Инструмент создания коммитов - это инструмент, генерирующий индивидуальные сообщения о коммитах на основе commitlint","ar":"أداة إنشاء رسائل الإلتزام هي أداة تُنشئ رسائل إلتزام مخصصة على أساس commitlint"},"features":{"en":["Detects changes in the Git repository using git diff --cached and git diff","Generates commit messages based on commitlint configurations","Supports analysis of staged and unstaged changes","Provides options for users to specify change ranges, including staged, unstaged, or all changes","Uses Git commands to retrieve change contents, such as git diff --cached for staged changes"],"zh":["智能检测变更范围","自动分析暂存区和工作区变更","支持 commitlint 配置","生成规范提交消息","提高代码提交效率"],"ja":["変更範囲の智能検出","ステージングエリアとワークエリアの自動分析","commitlint 構成のサポート","規範のコミットメッセージの生成","コードの提出効率の向上"],"ko":["변경 범위의智能検출","스테이징 영역과 작업 영역의 자동 분석","commitlint 설정 지원","표준화된 커밋 메시지 생성","코드 제출 효율성 향상"],"es":["Generación de mensajes de commit personalizados según la configuración de commitlint","Detección automática del alcance de los cambios","Soporte para análisis de cambios en el área de espera y en el directorio de trabajo","Compatibilidad con Git y commitlint","Informes personalizados antes de generar el mensaje de commit"],"fr":["Génération de messages de commit personnalisés en fonction de la configuration de commitlint","Détection automatique de la portée des modifications","Prise en charge de l''analyse des modifications dans la zone de mise en attente et dans le répertoire de travail","Compatibilité avec Git et commitlint","Rapports personnalisés avant la génération du message de commit"],"de":["Generierung benutzerdefinierter Commit-Mitteilungen basierend auf der commitlint-Konfiguration","Automatische Erkennung des Änderungsbereichs","Unterstützung für die Analyse von Änderungen im Staging-Bereich und im Arbeitsverzeichnis","Kompatibilität mit Git und commitlint","Benutzerdefinierte Berichte vor der Generierung der Commit-Mitteilung"],"pt":["Detecção automática do escopo das alterações","Geração de mensagens de commit personalizadas com base no commitlint","Suporte a análise de alterações em staging e não staging","Integração com Git para obter alterações","Geração de mensagens de commit para alterações em staging, não staging ou todas as alterações"],"ru":["Автоматическое обнаружение объема изменений","Генерация индивидуальных сообщений о коммитах на основе commitlint","Поддержка анализа изменений в staging и не staging","Интеграция с Git для получения изменений","Генерация сообщений о коммитах для изменений в staging, не staging или всех изменений"],"ar":["اكتشاف تلقائي لنطاق التغييرات","إنشاء رسائل إلتزام مخصصة على أساس commitlint","دعم تحليل التغييرات في مرحلة الإعداد ومرحلة ما قبل الإعداد","التكامل مع Git للحصول على التغييرات","إنشاء رسائل إلتزام للتغييرات في مرحلة الإعداد، مرحلة ما قبل الإعداد أو جميع التغييرات"]},"keywords":{"en":["how to use create-commit-message","create-commit-message setup guide","automated commit message generation","git commit message best practices","create-commit-message vs git commit","create-commit-message install","what is create-commit-message","create-commit-message alternative","git workflow automation"],"zh":["Create Commit Message","commitlint","智能检测变更范围","自动提交消息","代码提交效率","AIエージェント","代码管理工具"],"ja":["Create Commit Message","commitlint","変更範囲の智能検出","自動コミットメッセージ","コードの提出効率","AIエージェント","コード管理ツール"],"ko":["Create Commit Message","commitlint","변경 범위의智能검출","자동 커밋 메시지","코드 제출 효율성","AI 에이전트","코드 관리 툴"],"es":["create-commit-message","commitlint","mensajes de commit personalizados","Git","desarrollo de software","herramientas de desarrollo","línea de comandos","configuración de commit"],"fr":["create-commit-message","commitlint","messages de commit personnalisés","Git","développement de logiciels","outils de développement","ligne de commande","configuration de commit"],"de":["create-commit-message","commitlint","benutzerdefinierte Commit-Mitteilungen","Git","Software-Entwicklung","Entwicklungstools","Command-Line","Commit-Konfiguration"],"pt":["create commit message","commitlint","git","mensagem de commit","ferramenta de commit","detecção de alterações","análise de alterações","integração com git"],"ru":["создание коммитов","commitlint","git","сообщение о коммите","инструмент создания коммитов","обнаружение изменений","анализ изменений","интеграция с git","ИИ Агенты"],"ar":["إنشاء رسائل الإلتزام","commitlint","git","رسالة إلتزام","أداة إنشاء رسائل الإلتزام","اكتشاف التغييرات","تحليل التغييرات","التكامل مع git","أدوات الذكاء الاصطناعي"]}},"owner":"silentip404","repo":"wangshuhao","repoPath":"silentip404/wangshuhao","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.495Z","topics":[],"category":"community","skillMd":{"name":"create-commit-message","description":"生成符合项目 commitlint 规范的提交消息。当用户请求生成 commit message、提交消息或询问如何编写提交信息时使用此 skill。","bodyPreview":"# Create Commit Message\n\n根据项目 commitlint 配置生成规范的提交消息。\n\n## 工作流程\n\n### 明确变更范围\n\n**智能检测变更范围**：\n\n当用户未明确指定分析哪些变更时，执行以下逻辑：\n\n**检查变更状态**：使用 `git diff --cached` 和 `git diff` 检查暂存区和工作区。\n\n**根据检测结果决定**：\n\n- **仅存在暂存变更** → 自动分析暂存变更，**生成前先告知**：\"检测到暂存区有变更，正在为暂存区生成提交消息...\"\n- **仅存在未暂存变更** → 自动分析未暂存变更，**生成前先告知**：\"检测到工作区有变更，正在为未暂存变更生成提交消息...\"\n- **两者都存在** → 必须询问用户指定范围：\n  - 暂存区变更（staged changes）？\n  - 未暂存变更（unstaged changes）？\n  - 全部变更（all changes）？\n\n**获取对应的变更内容**：\n\n- 暂存区变更：使用 `git diff --cached`\n- 未暂存变更：使用 `git diff`\n- 全","body":"# Create Commit Message\n\n根据项目 commitlint 配置生成规范的提交消息。\n\n## 工作流程\n\n### 明确变更范围\n\n**智能检测变更范围**：\n\n当用户未明确指定分析哪些变更时，执行以下逻辑：\n\n**检查变更状态**：使用 `git diff --cached` 和 `git diff` 检查暂存区和工作区。\n\n**根据检测结果决定**：\n\n- **仅存在暂存变更** → 自动分析暂存变更，**生成前先告知**：\"检测到暂存区有变更，正在为暂存区生成提交消息...\"\n- **仅存在未暂存变更** → 自动分析未暂存变更，**生成前先告知**：\"检测到工作区有变更，正在为未暂存变更生成提交消息...\"\n- **两者都存在** → 必须询问用户指定范围：\n  - 暂存区变更（staged changes）？\n  - 未暂存变更（unstaged changes）？\n  - 全部变更（all changes）？\n\n**获取对应的变更内容**：\n\n- 暂存区变更：使用 `git diff --cached`\n- 未暂存变更：使用 `git diff`\n- 全部变更：使用 `git diff HEAD`\n\n### 读取项目配置\n\n动态读取最新的 commitlint 配置：\n\n- 读取[commitlint.config.ts](../../../commitlint.config.ts)\n- 执行 `pnpm exec commitlint --print-config` 获取完整配置\n\n### 分析变更\n\n分析变更时必须：\n\n**区分主要变更和次要变更**：\n\n- 主要：核心功能改动、新增特性、bug 修复\n- 次要：因主要变更引起的连锁改动（如重命名导致的 import 更新）\n\n**评估变更一致性**：\n\n- 所有变更是否服务于单一目的？\n- 如果包含多个不相关的改动，建议用户拆分提交\n\n**识别不确定的意图**：\n\n- 无法准确判断变更目的时，必须向用户请求澄清\n- 不要猜测或假设\n\n### 生成提交消息\n\n根据 commitlint 配置生成消息，遵循：\n\n**仅使用项目配置的规则**：\n\n- 不引用 Angular 约定、常规提交指南或仓库历史\n- 严格遵循读取的配置\n\n**使用正确的语言**：\n\n- 若用户未明确说明，使用用户的目标语言\n\n**聚焦主要变更**：\n\n- 提交消息描述主要变更目的\n- 次要变更可在详细描述中简要提及\n\n**保持简洁准确**：\n\n- 清晰描述\"做了什么\"和\"为什么\"\n- 避免冗余信息\n\n## 输出格式\n\n仅提供提交消息内容，不执行提交操作：\n\n```\ntype(scope): subject\n\nbody\n\nfooter\n```\n\n使用代码块展示，方便用户复制。\n\n## 约束检查清单\n\n在生成前确认：\n\n- [ ] 已明确变更范围\n- [ ] 已读取最新 commitlint 配置\n- [ ] 已区分主要和次要变更\n- [ ] 变更符合单一目的原则（或已建议拆分）\n- [ ] 不确定的地方已向用户澄清\n- [ ] 使用正确的语言\n- [ ] 仅提供消息，不执行提交\n\n## 交互原则\n\n- **保持简洁**：避免过多解释，直接提供结果\n- **明确范围**：智能检测时，生成前必须告知用户是根据哪个范围生成的\n- **主动询问**：范围不明或意图不清时立即询问\n- **建设性建议**：发现问题时提供改进建议\n- **尊重配置**：严格遵循项目规则，不添加个人偏好\n\n## 示例交互流程\n\n### 仅有暂存变更（自动检测）\n\n**用户**: 帮我生成提交消息\n\n**助手**: 检测到暂存区有变更，正在为暂存区生成提交消息...\n\n[读取配置和变更，分析后提供消息]\n\n```\nfeat(auth): 添加用户登录功能\n\n实现 JWT 认证和会话管理\n```\n\n### 同时存在暂存和未暂存变更（需询问）\n\n**用户**: 帮我生成提交消息\n\n**助手**: 检测到暂存区和工作区都有变更，需要为哪些变更生成提交消息？\n\n- 暂存区变更\n- 未暂存变更\n- 全部变更\n\n**用户**: 暂存区\n\n**助手**:\n[分析暂存区变更后提供消息]\n\n```\nfix(auth): 修复登录状态持久化问题\n```\n\n## 常见场景处理\n\n### 自动检测变更范围\n\n**智能检测后必须先告知用户**：\n\n当检测到单一类型的变更时，在生成前说明：\n\n- \"检测到暂存区有变更，正在为暂存区生成提交消息...\"\n- \"检测到工作区有变更，正在为未暂存变更生成提交消息...\"\n\n当检测到多种类型的变更时，明确询问：\n\n\"检测到暂存区和工作区都有变更，需要为哪些变更生成提交消息？\n\n- 暂存区变更\n- 未暂存变更\n- 全部变更\"\n\n### 多个不相关的变更\n\n检测到多个不相关改动时：\n\n\"检测到多个独立的变更：\n\n- 用户认证功能\n- 首页样式调整\n\n建议拆分为两个独立的提交。是否需要指导如何拆分？\"\n\n### 变更意图不明确\n\n无法确定变更目的时：\n\n\"这些更改的主要目的是什么？\n\n- 修复某个问题？\n- 添加新功能？\n- 重构代码？\"\n\n### 仅有次要变更\n\n所有变更都是次要的（如格式化、导入排序）：\n\n按实际情况生成对应的 type（如 `style`, `chore`），不要忽略这些变更。\n"},"lastSynced":"2026-03-08T02:10:12.772Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing streamlined Git workflows with standardized commit messages.","zh":"非常适合需要简化 Git 工作流并标准化提交消息的开发代理。","ja":"開発エージェントがストリームライン化された Git ワークフローと標準化されたコミット メッセージを必要とする場合に最適です。","ko":"개발 에이전트가 간소화된 Git 워크플로우와 표준화된 커밋 메시지를 필요로 할 때 완벽합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan flujos de trabajo de Git optimizados con mensajes de confirmación estandarizados.","fr":"Parfait pour les agents de développement nécessitant des flux de travail Git optimisés avec des messages de validation standardisés.","de":"Perfekt für Entwicklungssagenten, die optimierte Git-Arbeitsabläufe mit standardisierten Commit-Nachrichten benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de fluxos de trabalho Git otimizados com mensagens de commit padronizadas.","ru":"Идеально подходит для агентов разработки, которым требуются оптимизированные рабочие процессы Git с стандартизированными сообщениями о фиксации.","ar":"مثالي للوكلاء النموزجيين الذين يحتاجون إلى تدفقات عمل Git مبسطة مع رسائل الالتزام المعيارية."},"recommendation":{"en":"Empowers agents to generate commit messages based on project commitlint configurations, utilizing Git commands like `git diff --cached` and `git diff` to analyze staged and unstaged changes, thereby streamlining their Git workflow.","zh":"赋予代理生成基于项目 commitlint 配置的提交消息的能力，利用 Git 命令如 `git diff --cached` 和 `git diff` 来分析暂存和未暂存的更改，从而简化他们的 Git 工作流程。","ja":"エージェントがプロジェクトの commitlint 構成に基づいてコミット メッセージを生成する能力を付与します。`git diff --cached` および `git diff` などの Git コマンドを使用してステージングされた変更とステージングされていない変更を分析して、Git ワークフローを合理化します。","ko":"에이전트가 프로젝트의 commitlint 구성에 따라 커밋 메시지를 생성할 수 있는 능력을 부여합니다. `git diff --cached` 및 `git diff`와 같은 Git 명령을 사용하여 스테이징된 변경 사항과 스테이징되지 않은 변경 사항을 분석하여 Git 워크플로우를 간소화합니다.","es":"Permite a los agentes generar mensajes de confirmación basados en configuraciones de commitlint del proyecto, utilizando comandos de Git como `git diff --cached` y `git diff` para analizar cambios en espera y no en espera, lo que optimiza su flujo de trabajo de Git.","fr":"Permet aux agents de générer des messages de validation basés sur les configurations commitlint du projet, en utilisant des commandes Git comme `git diff --cached` et `git diff` pour analyser les modifications en attente et non en attente, ce qui optimise leur flux de travail Git.","de":"Ermöglich es den Agenten, Commit-Nachrichten basierend auf commitlint-Konfigurationen des Projekts zu generieren, indem Git-Befehle wie `git diff --cached` und `git diff` verwendet werden, um gestufte und nicht gestufte Änderungen zu analysieren, wodurch ihr Git-Arbeitsablauf optimiert wird.","pt":"Habilita os agentes a gerar mensagens de commit com base nas configurações do commitlint do projeto, utilizando comandos Git como `git diff --cached` e `git diff` para analisar alterações em estágio e não em estágio, otimizando assim o fluxo de trabalho Git.","ru":"Наделяет агентов возможностью генерировать сообщения о фиксации на основе конфигураций commitlint проекта, используя команды Git как `git diff --cached` и `git diff` для анализа изменений в стадии и не в стадии, тем самым оптимизируя рабочий процесс Git.","ar":"تمكّن الوكلاء من توليد رسائل الالتزام على أساس تكوينات commitlint للمشروع، باستخدام أوامر Git مثل `git diff --cached` و `git diff` لتحليل التغييرات المحددة والمحددة غير المحددة، وبالتالي تحسين تدفق العمل Git."},"useCases":{"en":["Automating commit message generation for staged changes","Generating commit messages for unstaged changes with clear descriptions","Debugging commit message configurations to ensure adherence to project standards"],"zh":["自动为暂存的更改生成提交消息","为未暂存的更改生成带有清晰描述的提交消息","调试提交消息配置以确保符合项目标准"],"ja":["ステージングされた変更のコミット メッセージを自動生成する","ステージングされていない変更のコミット メッセージを明確な説明で生成する","コミット メッセージ構成をデバッグしてプロジェクトの標準に従っていることを確認する"],"ko":["스테이징된 변경 사항에 대한 커밋 메시지를 자동으로 생성한다","스테이징되지 않은 변경 사항에 대한 커밋 메시지를 명확한 설명과 함께 생성한다","커밋 메시지 구성의 디버깅을 통해 프로젝트 표준을 준수하는지 확인한다"],"es":["Automatizar la generación de mensajes de confirmación para cambios en espera","Generar mensajes de confirmación para cambios no en espera con descripciones claras","Depurar configuraciones de mensajes de confirmación para garantizar el cumplimiento de los estándares del proyecto"],"fr":["Automatiser la génération de messages de validation pour les modifications en attente","Générer des messages de validation pour les modifications non en attente avec des descriptions claires","Déboguer les configurations de messages de validation pour assurer le respect des normes du projet"],"de":["Automatisieren der Generierung von Commit-Nachrichten für gestufte Änderungen","Generieren von Commit-Nachrichten für nicht gestufte Änderungen mit klaren Beschreibungen","Debuggen von Commit-Nachrichten-Konfigurationen, um die Einhaltung der Projektnormen sicherzustellen"],"pt":["Automatizar a geração de mensagens de commit para alterações em estágio","Gerar mensagens de commit para alterações não em estágio com descrições claras","Depurar configurações de mensagens de commit para garantir a adesão aos padrões do projeto"],"ru":["Автоматизировать генерацию сообщений о фиксации для изменений в стадии","Генерировать сообщения о фиксации для изменений не в стадии с четкими описаниями","Отладить конфигурации сообщений о фиксации, чтобы обеспечить соблюдение стандартов проекта"],"ar":["تحويل رسائل الالتزام إلى تلقائية للتحديثات المحددة","توليد رسائل الالتزام للتحديثات غير المحددة مع وصف واضح","تصحيح تكوينات رسائل الالتزام لضمان الامتثال لمعايير المشروع"]},"limitations":{"en":["Requires Git installation and configuration","Needs commitlint configuration files for project-specific settings","Limited to generating commit messages based on detected changes in the Git repository"],"zh":["需要 Git 安装和配置","需要 commitlint 配置文件以获取项目特定的设置","仅限根据 Git 存储库中检测到的更改生成提交消息"],"ja":["Git のインストールと構成が必要","プロジェクト固有の設定を取得するために commitlint 構成ファイルが必要","Git リポジトリで検出された変更に基づいてコミット メッセージを生成することのみ"],"ko":["Git 설치 및 구성이 필요하다","프로젝트별 설정을 얻기 위해 commitlint 구성 파일이 필요하다","Git 리포지토리에서 감지된 변경 사항을 기반으로 커밋 메시지를 생성하는 것만 제한된다"],"es":["Requiere la instalación y configuración de Git","Necesita archivos de configuración commitlint para la configuración específica del proyecto","Limitado a la generación de mensajes de confirmación basados en los cambios detectados en el repositorio de Git"],"fr":["Nécessite l''installation et la configuration de Git","A besoin de fichiers de configuration commitlint pour les paramètres spécifiques du projet","Limité à la génération de messages de validation basés sur les modifications détectées dans le référentiel Git"],"de":["Benötigt die Installation und Konfiguration von Git","Benötigt commitlint-Konfigurationsdateien für projektspezifische Einstellungen","Begrenzt auf die Generierung von Commit-Nachrichten basierend auf den erkannten Änderungen im Git-Repository"],"pt":["Requer instalação e configuração do Git","Necessita de arquivos de configuração do commitlint para configurações específicas do projeto","Limitado a gerar mensagens de commit com base em alterações detectadas no repositório Git"],"ru":["Требует установки и конфигурации Git","Требует файлов конфигурации commitlint для проектных настроек","Ограничен генерацией сообщений о фиксации на основе обнаруженных изменений в репозитории Git"],"ar":["يتطلب تركيب وتكوين Git","يحتاج إلى ملفات تكوين commitlint لأعدادات مشروع معين","محدود بتوليد رسائل الالتزام على أساس التغييرات المكتشفة في مستودع Git"]},"version":4},"contentHash":"c2f2438164cfd786feb2172e1ef0680a6371a269e84546e9940bd4666093a82e","qualityScore":30}');
