INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('silentip404/wangshuhao/create-commit-message', 'create-commit-message', 'silentip404', 'wangshuhao', 'community', 'create-commit-message silentip404 wangshuhao community The create-commit-message skill generates standardized commit messages based on project commitlint configurations, benefiting developers by streamlining their Git workflow. Create Commit Message 根据项目 commitlint 配置生成规范的提交消息，智能检测变更范围，提高代码提交效率 Create Commit Message は、プロジェクトの commitlint 構成に基づいて規範のコミットメッセージを生成し、変更範囲を智能的に検出してコードの提出効率を向上させる Create Commit Message는 프로젝트의 commitlint 설정에 따라 표준화된 커밋 메시지를 생성하며, 변경 범위를智能적으로检测하여 코드 제출 효율을 높입니다 create-commit-message es una herramienta que genera mensajes de commit personalizados según la configuración de commitlint. Ayuda a los desarrolladores a mantener un historial de commits claro y coherente. create-commit-message est un outil qui génère des messages de commit personnalisés en fonction de la configuration de commitlint. Il aide les développeurs à maintenir un historique de commits clair et cohérent. create-commit-message ist ein Tool, das benutzerdefinierte Commit-Mitteilungen basierend auf der commitlint-Konfiguration generiert. Es hilft Entwicklern, ein klares und kohärentes Commit-Verlauf zu erhalten. O Create Commit Message é uma ferramenta que gera mensagens de commit personalizadas com base no commitlint. Ele detecta automaticamente o escopo das alterações e gera mensagens de commit de acordo. Инструмент создания коммитов генерирует индивидуальные сообщения о коммитах на основе commitlint. Он автоматически обнаруживает объем изменений и генерирует сообщения о коммитах соответственно. أداة إنشاء رسائل الإلتزام تُنشئ رسائل إلتزام مخصصة على أساس commitlint. فهي تكتشف تلقائيًا نطاق التغييرات وتُنشئ رسائل إلتزام وفقًا لذلك. how to use create-commit-message create-commit-message setup guide automated commit message generation git commit message best practices create-commit-message vs git commit create-commit-message install what is create-commit-message create-commit-message alternative git workflow automation Create Commit Message commitlint 智能检测变更范围 自动提交消息 代码提交效率 AIエージェント 代码管理工具 Detects changes in the Git repository using git diff --cached and git diff Generates commit messages based on commitlint configurations Supports analysis of staged and unstaged changes Provides options for users to specify change ranges, including staged, unstaged, or all changes Uses Git commands to retrieve change contents, such as git diff --cached for staged changes create-commit-message is a skill that automatically generates commit messages according to project commitlint configurations, using Git commands like git diff --cached and git diff.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Xbotics-Embodied-AI-club/Xbotics-Embodied-Guide/news-pdf-integration', 'community', 'Xbotics-Embodied-AI-club', 'Xbotics-Embodied-Guide', 'Xbotics-Embodied-AI-club/Xbotics-Embodied-Guide', 'news-pdf-integration', 0, 0, 30, '2026-03-08T01:57:15.507Z', '2026-03-08T02:10:22.480Z', 'b76cb2f76e6f946f75f25122fe64f4534ac568c1b0de7a8ac2faf48976d096de', '{"id":"Xbotics-Embodied-AI-club/Xbotics-Embodied-Guide/news-pdf-integration","name":"news-pdf-integration","description":{"en":"The news-pdf-integration skill generates MD files from source articles, helping developers and content creators organize and process large volumes of text data efficiently.","zh":"新闻PDF集成是一种高效的新闻文章聚合和MD文件生成技术，通过优先读取news/source-daily.md或news/source.md，实现每篇文章的重新整理和核心内容保留","ja":"ニュースPDF統合は、効率的なニュース記事の集約とMDファイルの生成を実現する技術で、news/source-daily.mdまたはnews/source.mdを優先的に読み込み、各記事の再構成と核心内容の保留を実現","ko":"뉴스 PDF 통합은 효율적인 뉴스 기사 수집과 MD 파일 생성을 실현하는 기술로서 news/source-daily.md 또는 news/source.md를 우선적으로 읽어들여 각 기사의 재구성과 핵심 내용 보존을 구현합니다","es":"El agente de noticias en PDF utiliza Markdown para reorganizar artículos de noticias y evitar la infracción de derechos de autor.","fr":"L''outil de nouvelles en PDF utilise Markdown pour réorganiser les articles de nouvelles et éviter les violations de droits d''auteur.","de":"Das KI-Tool für Nachrichten in PDF verwendet Markdown, um Nachrichtenartikel neu zu organisieren und Urheberrechtsverletzungen zu vermeiden.","pt":"A ferramenta de integração de notícias em PDF processa múltiplas fontes de notícias e gera arquivos MD personalizados. Ela prioriza a leitura de notícias diárias e reorganiza o conteúdo para evitar violações de direitos autorais.","ru":"Инструмент интеграции новостей в PDF обрабатывает несколько источников новостей и генерирует индивидуальные файлы MD. Он отдает приоритет чтению ежедневных новостей и реорганизует контент, чтобы избежать нарушений авторских прав.","ar":"أداة دمج الأخبار في تنسيق PDF تعمل على معالجة العديد من مصادر الأخبار وتوليد ملفات MD مخصصة. إنها تعطي الأولوية لقراءة الأخبار اليومية وإعادة تنظيم المحتوى لتجنب انتهاكات حقوق النشر."},"seo":{"title":{"en":"news-pdf-integration: MD File Generation Setup Guide | AI...","zh":"新闻PDF集成设置指南","ja":"ニュースPDF統合セットアップガイド","ko":"뉴스 PDF 통합 설정 가이드","es":"Guía de Integración de Noticias en PDF con AI Agent","fr":"Guide d''Intégration de Nouvelles en PDF avec Outil IA","de":"Anleitung zur Integration von Nachrichten in PDF mit KI-Tool","pt":"Guia de Integração de Notícias em PDF para Desenvolvedores","ru":"ИИ Агенты: Руководство по Интеграции Новостей в PDF","ar":"دليل دمج الأخبار في تنسيق PDF للמطورين"},"description":{"en":"Unlock efficient article processing with news-pdf-integration. Learn how to generate MD files from source articles and discover the power of automated conten...","zh":"了解新闻PDF集成的技术细节和最佳实践，实现高效的新闻文章聚合和MD文件生成","ja":"ニュースPDF統合のテクニカル詳細とベストプラクティスを学び、効率的なニュース記事の集約とMDファイルの生成を実現","ko":"뉴스 PDF 통합의 기술적인 세부사항과 모범 사례를 알아보고 효율적인 뉴스 기사 수집 및 MD 파일 생성을 실현하세요","es":"Aprende a integrar noticias en PDF con nuestro agente de inteligencia artificial. Descubre cómo funciona y cómo puedes aprovecharlo.","fr":"Découvrez comment intégrer des nouvelles en PDF avec notre outil d''intelligence artificielle. Comprenez son fonctionnement et ses avantages.","de":"Erfahren Sie, wie Sie Nachrichten in PDF mit unserem KI-Tool integrieren können. Entdecken Sie seine Funktionen und Vorteile.","pt":"Aprenda a integrar notícias em PDF com nossa ferramenta de IA. Descubra como processar múltiplas fontes de notícias e gerar arquivos MD personalizados.","ru":"Узнайте, как интегрировать новости в PDF с помощью нашего ИИ инструмента. Откройте для себя, как обрабатывать несколько источников новостей и генерировать ин...","ar":"تعرف على كيفية دمج الأخبار في تنسيق PDF باستخدام أداة الذكاء الاصطناعي. اكتشف كيفية معالجة العديد من مصادر الأخبار وتوليد ملفات MD مخصصة."},"definition":{"en":"news-pdf-integration is a skill that automates the process of generating MD files from source articles, allowing for efficient content organization and processing.","zh":"新闻PDF集成是一种通过优先读取特定MD文件，实现新闻文章聚合和MD文件生成的技术","ja":"ニュースPDF統合は、特定のMDファイルを優先的に読み込み、ニュース記事の集約とMDファイルの生成を実現する技術","ko":"뉴스 PDF 통합은 특정 MD 파일을 우선적으로 읽어들여 뉴스 기사 수집과 MD 파일 생성을 실현하는 기술입니다","es":"La integración de noticias en PDF es una función de agente de inteligencia artificial que reorganiza artículos de noticias en formato Markdown.","fr":"L''intégration de nouvelles en PDF est une fonction d''outil d''intelligence artificielle qui réorganise les articles de nouvelles au format Markdown.","de":"Die Integration von Nachrichten in PDF ist eine Funktion eines KI-Tools, das Nachrichtenartikel im Markdown-Format neu organisiert.","pt":"A integração de notícias em PDF é uma ferramenta de IA que processa e reorganiza notícias de múltiplas fontes em arquivos MD personalizados.","ru":"Интеграция новостей в PDF - это инструмент ИИ, который обрабатывает и реорганизует новости из нескольких источников в индивидуальные файлы MD.","ar":"دمج الأخبار في تنسيق PDF هو أداة ذكاء اصطناعي تقوم بمعالجة وإعادة تنظيم الأخبار من العديد من المصادر في ملفات MD مخصصة."},"features":{"en":["Reads multiple articles from news/source-daily.md or news/source.md","Generates a separate MD file for each article in files/source/","Preserves core content while avoiding copyright infringement","Supports reorganization of articles into thematic categories","Outputs MD files with concise summaries of original content"],"zh":["优先读取news/source-daily.md或news/source.md","实现每篇文章的重新整理和核心内容保留","生成原创MD文件写入files/source/","避免侵权，仅保留核心内容","支持多篇文章聚合和单篇文章处理"],"ja":["news/source-daily.mdまたはnews/source.mdを優先的に読み込み","各記事の再構成と核心内容の保留を実現","原創のMDファイルをfiles/source/に書き込み","著作権侵害を避け、核心内容のみを保留","多篇記事の集約と単篇記事の処理をサポート"],"ko":["news/source-daily.md 또는 news/source.md를 우선적으로 읽어들여","각 기사의 재구성과 핵심 내용 보존을 구현","원본 MD 파일을 files/source/에 작성","저작권 침해를 피하고 핵심 내용만 보존","다수의 기사 수집과 단일 기사 처리를 지원"],"es":["Reorganización de artículos de noticias en formato Markdown","Evitación de la infracción de derechos de autor mediante la reescritura de contenido","Uso de la convención de nombres de archivos `files/source/<tema>.md`","Compatibilidad con múltiples fuentes de noticias","Generación de archivos PDF a partir de artículos de noticias","Integración con herramientas de inteligencia artificial para el análisis de noticias"],"fr":["Réorganisation d''articles de nouvelles au format Markdown","Évitement des violations de droits d''auteur grâce à la réécriture de contenu","Utilisation de la convention de nommage de fichiers `files/source/<thème>.md`","Compatibilité avec plusieurs sources de nouvelles","Génération de fichiers PDF à partir d''articles de nouvelles","Intégration avec des outils d''intelligence artificielle pour l''analyse de nouvelles"],"de":["Neuorganisation von Nachrichtenartikeln im Markdown-Format","Vermeidung von Urheberrechtsverletzungen durch die Neufassung von Inhalten","Verwendung der Dateinamenskonvention `files/source/<Thema>.md`","Kompatibilität mit mehreren Nachrichtenquellen","Erstellung von PDF-Dateien aus Nachrichtenartikeln","Integration mit KI-Tools für die Analyse von Nachrichten"],"pt":["Processamento de múltiplas fontes de notícias","Geração de arquivos MD personalizados","Priorização da leitura de notícias diárias","Reorganização do conteúdo para evitar violações de direitos autorais","Suporte a arquivos MD com temas personalizados"],"ru":["Обработка нескольких источников новостей","Генерация индивидуальных файлов MD","Приоритет чтения ежедневных новостей","Реорганизация контента, чтобы избежать нарушений авторских прав","Поддержка файлов MD с индивидуальными темами"],"ar":["معالجة العديد من مصادر الأخبار","توليد ملفات MD مخصصة","إعطاء الأولوية لقراءة الأخبار اليومية","إعادة تنظيم المحتوى لتجنب انتهاكات حقوق النشر","دعم ملفات MD ذات مواضيع مخصصة"]},"keywords":{"en":["how to use news-pdf-integration","news-pdf-integration setup guide","MD file generation from source articles","automated content organization tools","news-pdf-integration vs manual content processing","installing news-pdf-integration for AI agents"],"zh":["新闻PDF集成","MD文件生成","新闻文章聚合","核心内容保留","避免侵权","news/source-daily.md","news/source.md","files/source/","AIエージェント","AI工具"],"ja":["ニュースPDF統合","MDファイルの生成","ニュース記事の集約","核心内容の保留","著作権侵害の回避","news/source-daily.md","news/source.md","files/source/","AIエージェント","AIツール"],"ko":["뉴스 PDF 통합","MD 파일 생성","뉴스 기사 수집","핵심 내용 보존","저작권 침해 피하기","news/source-daily.md","news/source.md","files/source/","AI 에이전트","AI 툴"],"es":["integración de noticias en PDF","agente de inteligencia artificial","Markdown","evitación de la infracción de derechos de autor","reorganización de artículos de noticias","herramientas de inteligencia artificial","análisis de noticias","generación de archivos PDF","compatibilidad con múltiples fuentes de noticias"],"fr":["intégration de nouvelles en PDF","outil d''intelligence artificielle","Markdown","évitement des violations de droits d''auteur","réorganisation d''articles de nouvelles","outils d''intelligence artificielle","analyse de nouvelles","génération de fichiers PDF","compatibilité avec plusieurs sources de nouvelles"],"de":["Integration von Nachrichten in PDF","KI-Tool","Markdown","Vermeidung von Urheberrechtsverletzungen","Neuorganisation von Nachrichtenartikeln","KI-Tools","Analyse von Nachrichten","Erstellung von PDF-Dateien","Kompatibilität mit mehreren Nachrichtenquellen"],"pt":["integração de notícias em PDF","ferramenta de IA para notícias","processamento de notícias","geração de arquivos MD","direitos autorais","notícias diárias","temas personalizados"],"ru":["ИИ Агенты","интеграция новостей в PDF","обработка новостей","генерация файлов MD","авторские права","ежедневные новости","индивидуальные темы"],"ar":["أداة دمج الأخبار في تنسيق PDF","ذكاء اصطناعي للأخبار","معالجة الأخبار","توليد ملفات MD","حقوق النشر","الأخبار اليومية","مواضيع مخصصة"]}},"owner":"Xbotics-Embodied-AI-club","repo":"Xbotics-Embodied-Guide","repoPath":"Xbotics-Embodied-AI-club/Xbotics-Embodied-Guide","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.507Z","topics":[],"category":"community","skillMd":{"name":"news-pdf-integration","description":"优先从 news/source-daily.md（若存在）或 news/source.md 读取多篇文章，逐篇原创整理为 MD 输出到 files/source/，保留核心内容、规避侵权。当用户更新 source-daily.md/source.md、需要批量处理多篇来源文章、或将外部文章整理进项目时使用。","bodyPreview":"# 从 source(-daily).md 多篇文章到 files/source 整理流程\n\n优先从 **`news/source-daily.md`**（若存在）读取**多篇**聚合文章；若仅有 `news/source.md`，则从 `source.md` 读取。在 **Plan 阶段** 明确识别每篇边界与数量，对**每一篇**进行**重新整理**，生成原创 MD 写入 **`files/source/`**，**只保留核心内容**，避免侵权。不直接复制原文。\n\n---\n\n## 一、数据源与输出约定\n\n| 项目 | 约定 |\n|------|------|\n| **输入** | **优先**：`news/source-daily.md`；若不存在则使用 `news/source.md`（单文件内多篇文章聚合，可能来自公众号、转载等） |\n| **输出** | 每篇文章对应一个 MD：`files/source/<主题简写>.md` |\n| **原则** | 每篇**重新整理**、用自己的话归纳，**保留核心内容**即可，不逐段抄录 |\n\n**侵权规避**：source.md 中内","body":"# 从 source(-daily).md 多篇文章到 files/source 整理流程\n\n优先从 **`news/source-daily.md`**（若存在）读取**多篇**聚合文章；若仅有 `news/source.md`，则从 `source.md` 读取。在 **Plan 阶段** 明确识别每篇边界与数量，对**每一篇**进行**重新整理**，生成原创 MD 写入 **`files/source/`**，**只保留核心内容**，避免侵权。不直接复制原文。\n\n---\n\n## 一、数据源与输出约定\n\n| 项目 | 约定 |\n|------|------|\n| **输入** | **优先**：`news/source-daily.md`；若不存在则使用 `news/source.md`（单文件内多篇文章聚合，可能来自公众号、转载等） |\n| **输出** | 每篇文章对应一个 MD：`files/source/<主题简写>.md` |\n| **原则** | 每篇**重新整理**、用自己的话归纳，**保留核心内容**即可，不逐段抄录 |\n\n**侵权规避**：source.md 中内容可能涉及版权，因此**必须**对每一篇做原创化整理（提炼观点、术语、结论，改写表述），仅保留核心信息，不原文照搬。\n\n---\n\n## 二、Plan 阶段（必做）\n\n在处理前必须先完成**规划**，避免漏篇或重复：\n\n1. **读取** `news/source-daily.md`（若存在）或 `news/source.md` 全文。\n2. **识别多篇文章边界**：\n   - 文章通常以**主标题**或**明显分隔**（如空行+新标题、`END`、下一篇文章标题）为界。\n   - 常见模式：首行或前几行为第一篇标题；后续出现与上文无关的新标题、或「END」+ 大量空行/列表/“留言”等，多为下一篇开始。\n3. **列出每篇文章**：\n   - 序号、**标题/主题**、**建议文件名**（英文或拼音，如 `pku-wanghe-2025-embodied-roundup.md`、`leju-showroom-strategy-2026.md`）。\n4. **确认**：共 N 篇，输出到 `files/source/` 的 N 个 MD 与之一一对应。\n\n只有在 Plan 中明确「篇数 + 每篇标题 + 输出文件名」后，再逐篇执行整理。\n\n---\n\n## 三、文章边界识别参考\n\n- **第一篇**：多为文件开头到第一个「结尾标志」或下一篇文章标题之前。\n- **下一篇**：新出现的独立标题（与上文无连贯关系）、或「END」/「写在最后」+ 空行/列表/“留言”之后的**新标题**。\n- **噪音**：企业名单、公众号引导、留言、精选推荐等可视为分隔或文末噪音，不纳入正文；若某段明显是下一篇开头，则从该处切开。\n\n不确定时，宁可先按「标题 + 语义连贯性」切出候选篇，在整理时再微调边界。\n\n---\n\n## 四、单篇整理与输出规范\n\n对 **每一篇** 独立执行：\n\n1. **从 source.md 中截取**该篇的完整正文（按 Plan 中划定的边界）。\n2. **原创整理**：\n   - 提炼：核心观点、关键术语、重要结论、数据/结果（若有）。\n   - 用自己的话重写，分节归纳（可加小标题），**不逐段抄录**。\n3. **写出 MD** 到 `files/source/<主题简写>.md`：\n   - 必须包含：**标题**、**整理说明**（如「基于 [原文主题] 的整理，仅保留核心内容」）、**正文**（分节、列表均可）。\n   - 可选：文末注明「—— 整理自 Xbotics 具身智能学习指南 | 供学习参考」。\n\n### 单篇 MD 模板\n\n```markdown\n# [文章主题标题]\n\n*基于原文的整理，仅保留核心内容，供学习参考。*\n\n---\n\n## 1. [小节名]\n[原创归纳内容……]\n\n## 2. [小节名]\n[原创归纳内容……]\n\n---\n\n*—— 整理自 Xbotics 具身智能学习指南 | 供学习参考*\n```\n\n**文件名**：`files/source/` 下使用英文或拼音，如 `pku-wanghe-2025-roundup.md`、`leju-showroom-2026.md`、`xiaomi-vla-open-source.md`，避免中文与特殊字符。\n\n### 图标与表情（必做）\n\n- **`news/source-daily.md`（或 `news/source.md`）**：在编辑或生成日报/源文件时，在**主标题、本期重点、各篇标题、小节标题**（如「一句话记住」「为什么重要」「核心亮点」「配图建议」「资源」）及**要点列表**前使用适量图标与表情，使内容更生动、易扫读。可参考：📰 🎯 🤖 🧭 📐 🔄 💡 ❓ ✨ 🖼️ 🔗 📌 🏷️ 等，按主题选用。\n- **`files/source/*.md` 整理稿**：写入每篇整理稿时，在**文章标题、小节标题**（如「背景与目标」「核心亮点」「实验结果与意义」）及**要点条目前**同样使用适量图标与表情，与 source-daily 风格一致，便于阅读。\n\n---\n\n## 五、检查（必做）\n\n每篇整理并写出 MD 后，**必须**做以下两项检查；不合格则修正再继续。\n\n### 5.1 内容一致性检查（总结与原文是否一致）\n\n- **对照原文**：用 source.md 中该篇的原文段落，逐条核对整理稿是否覆盖了**核心信息**（主要观点、关键术语、重要结论、数据/结果）。\n- **通过标准**：无**实质性遗漏**（如漏掉原文明确的核心论点、关键数字、方法名/论文名）；无**实质性偏差**（如把“A 优于 B”写成“B 优于 A”）；允许概括与改写，但语义不得与原文矛盾。\n- **若不一致**：在整理稿中补全遗漏、修正偏差，必要时调整小节结构，使总结与原文核心一致。\n\n### 5.2 放置位置检查（放的位置是否合适）\n\n- **主输出位置**：所有整理稿的**主产出**一律放在 `files/source/<主题简写>.md`，无需再检查“是否该放 source”。\n- **可选集成时的位置**：若做了「在 files/papers/、files/interviews/、files/foundations/ 写摘要或索引，并在 docs 中加链接」，则需检查：\n  - **类型是否匹配**：论文/技术 → `files/papers/` 及 docs/5-sota、4-classical、1.3 等；访谈/产业 → `files/interviews/` 及 docs/8-people、9-landscape、1.3 产业视角；基础/教程 → `files/foundations/` 及 docs/3-foundations、2-roadmaps。\n  - **链接是否到位**：摘要/索引中指向 `../source/xxx.md` 的链接正确；docs 内链接到的是最相关的小节，而非随便挂到某章末尾。\n- **通过标准**：主产出均在 `files/source/`；若做了可选集成，则类型与目录对应正确、链接有效且挂到合适小节。\n- **若不合适**：移动或重命名摘要/索引文件到正确目录，或调整 docs 中的链接目标到更贴切的小节。\n\n**检查清单（可逐篇勾选）**：\n\n- [ ] 内容一致性：核心信息无遗漏、无语义偏差\n- [ ] 放置位置：主产出在 `files/source/`；若做了集成，类型与链接位置合适\n\n---\n\n## 六、实施步骤总览\n\n| 步骤 | 说明 |\n|------|------|\n| **Step 0 Plan** | 优先读 `news/source-daily.md`（若存在，否则读 `news/source.md`）→ 识别多篇文章边界 → 列出每篇标题与 `files/source/<名>.md` |\n| **Step 1 逐篇整理** | 对每篇：截取正文 → 原创归纳（保留核心）→ 写入 `files/source/<主题简写>.md` |\n| **Step 2 检查** | 每篇：内容与原文一致性检查 + 放置位置检查；不合格则修正 |\n| **Step 3 可选** | 若需接入项目文档：在 `files/papers/`、`files/interviews/`、`files/foundations/` 做摘要或索引，并在 docs 相应小节增加链接（见下节） |\n\n---\n\n## 七、可选：与 docs 的集成\n\n整理结果以 **`files/source/*.md`** 为主产出。若需在项目知识库中引用：\n\n- **论文/技术类**：可在 `files/papers/` 增加简短笔记或索引，链到 `../source/xxx.md`；在 docs/1-embodied-overview、5-sota、4-classical、2-roadmaps 相关小节末加「延伸」链接。\n- **访谈/产业类**：可在 `files/interviews/` 做摘要，链到 `../source/xxx.md`；在 docs/8-people、9-landscape、1.3 产业视角加链接。\n- **基础/教程类**：可在 `files/foundations/` 做索引，链到 `../source/xxx.md`；在 docs/3-foundations、2-roadmaps 加链接。\n\n链接格式示例：`[主题](../source/主题简写.md)`（从 `files/papers/`、`files/interviews/`、`files/foundations/` 出发）。\n\n---\n\n## 八、集成位置速查\n\n```\ndocs/\n├── 1-embodied-overview/   # 术语、世界模型、产业视角\n├── 2-roadmaps/            # 学习路线与延伸\n├── 3-foundations/         # 基础与教程\n├── 4-classical/  5-sota/  # 经典与 SOTA\n├── 8-people/  9-landscape/ # 人物与公司\n└── …\nfiles/\n├── source/                # 本流程主输出：每篇整理 MD\n├── papers/  interviews/  foundations/  # 可选摘要与链接\n└── …\n```\n\n---\n\n## 九、若仍有 PDF 需求（可选保留）\n\n若项目中**同时**存在需要从 **PDF** 提取并整理的内容（例如 `news/` 下个别 PDF）：\n\n- 可继续使用现有 `news/extract_pdf.py`、`news/ocr_pdf.py` 提取文字；\n- 提取后的文本建议**先汇总或粘贴到 `news/source.md` 的独立“文章块”中**，再按本流程统一「Plan → 逐篇整理 → 输出到 `files/source/`」；\n- 或对单份 PDF 单独执行：提取/OCR → 原创整理 → 输出 `files/source/<主题>.md`。\n\n本 skill 的**主流程**以 **`news/source.md` 多篇文章 → `files/source/*.md`** 为准；PDF 仅作为可选输入来源之一。\n"},"lastSynced":"2026-03-08T02:10:22.480Z","agentAnalysis":{"suitability":{"en":"Perfect for Text Analysis Agents needing efficient news article processing and MD file generation.","zh":"适合需要高效新闻文章处理和MD文件生成的文本分析代理。","ja":"テキスト分析エージェントが効率的なニュース記事処理とMDファイル生成を必要とする場合に最適です。","ko":"효율적인 뉴스 기사 처리 및 MD 파일 생성이 필요한 텍스트 분석 에이전트에게 적합합니다.","es":"Perfecto para agentes de Análisis de Texto que necesitan un procesamiento eficiente de artículos de noticias y generación de archivos MD.","fr":"Parfait pour les agents d''Analyse de Texte nécessitant un traitement efficace des articles de nouvelles et la génération de fichiers MD.","de":"Perfekt für Textanalyse-Agents, die ein effizientes Verarbeiten von Nachrichtenartikeln und die Generierung von MD-Dateien benötigen.","pt":"Perfeito para Agentes de Análise de Texto que necessitam de processamento eficiente de artigos de notícias e geração de arquivos MD.","ru":"Идеально подходит для агентов анализа текста, которым требуется эффективная обработка новостных статей и генерация файлов MD.","ar":"مثالي لعمليات تحليل النص التي تحتاج إلى معالجة كفؤة لمقالات الأخبار وتوليد ملفات MD."},"recommendation":{"en":"Empowers agents to generate organized MD files from large volumes of text data, utilizing source articles from files like `news/source-daily.md` and `news/source.md`, while preserving core content and avoiding copyright infringement through reorganization and summarization.","zh":"赋予代理从大量文本数据生成有组织的MD文件的能力，利用来自文件的源文章，如`news/source-daily.md`和`news/source.md`，同时在重新组织和总结的同时保留核心内容并避免侵犯版权。","ja":"エージェントが多量のテキストデータから組織化されたMDファイルを生成できるようにし、`news/source-daily.md`や`news/source.md`などのファイルからソース記事を利用しながら、コアコンテンツを保ち、リオーガニゼーションや要約を通じて著作権侵害を回避します。","ko":"대량의 텍스트 데이터에서 조직화된 MD 파일을 생성할 수 있는 에이전트의 능력을 강화하여, `news/source-daily.md` 및 `news/source.md`와 같은 파일의 소스 기사를 활용하면서 핵심 내용을 보존하고 재구성 및 요약을 통해 저작권 침해를 피합니다.","es":"Habilita a los agentes a generar archivos MD organizados a partir de grandes volúmenes de datos de texto, utilizando artículos de fuentes como `news/source-daily.md` y `news/source.md`, preservando el contenido principal y evitando la infracción de derechos de autor a través de la reorganización y la resumen.","fr":"Permet aux agents de générer des fichiers MD organisés à partir de grands volumes de données textuelles, en utilisant des articles de sources comme `news/source-daily.md` et `news/source.md`, tout en préservant le contenu principal et en évitant les violations de droits d''auteur grâce à la réorganisation et à la synthèse.","de":"Ermöglicht es Agents, organisierte MD-Dateien aus großen Mengen an Textdaten zu generieren, indem sie Quellenartikel wie `news/source-daily.md` und `news/source.md` verwenden, während sie den Kerninhalt bewahren und Urheberrechtsverletzungen durch Reorganisation und Zusammenfassung vermeiden.","pt":"Habilita os agentes a gerar arquivos MD organizados a partir de grandes volumes de dados de texto, utilizando artigos de fontes de arquivos como `news/source-daily.md` e `news/source.md`, preservando o conteúdo principal e evitando violações de direitos autorais por meio de reorganização e resumo.","ru":"Позволяет агентам генерировать организованные файлы MD из больших объемов текстовых данных, используя статьи из источников, таких как `news/source-daily.md` и `news/source.md`, сохраняя основной контент и избегая нарушений авторских прав за счет реорганизации и суммирования.","ar":"يمكن العميل من توليد ملفات MD منظمة من أحجام كبيرة من بيانات النص، باستخدام مقالات من مصادر الملفات مثل `news/source-daily.md` و `news/source.md` ، مع الحفاظ على المحتوى الأساسي وتجنب انتهاكات حقوق النشر من خلال إعادة التنظيم والتلخيص."},"useCases":{"en":["Automating news article aggregation from multiple sources","Generating MD files for efficient content organization","Processing large volumes of text data from source articles"],"zh":["从多个来源自动聚合新闻文章","生成MD文件以实现高效的内容组织","处理来自源文章的大量文本数据"],"ja":["複数のソースからのニュース記事の自動集約","効率的なコンテンツ組織のためのMDファイルの生成","ソース記事からの大量のテキストデータの処理"],"ko":["여러 소스에서 뉴스 기사를 자동으로 집계하는 것","효율적인 콘텐츠 조직을 위한 MD 파일 생성","소스 기사에서 대량의 텍스트 데이터를 처리하는 것"],"es":["Automatizar la agregación de artículos de noticias de múltiples fuentes","Generar archivos MD para una organización de contenido eficiente","Procesar grandes volúmenes de datos de texto de artículos de fuente"],"fr":["Automatiser l''agrégation d''articles de nouvelles de multiples sources","Générer des fichiers MD pour une organisation de contenu efficace","Traiter de grands volumes de données textuelles d''articles de source"],"de":["Automatisieren der Aggregation von Nachrichtenartikeln aus mehreren Quellen","Generieren von MD-Dateien für eine effiziente Inhaltsorganisation","Verarbeiten großer Mengen an Textdaten von Quellenartikeln"],"pt":["Automatizar a agregação de artigos de notícias de várias fontes","Gerar arquivos MD para organização eficiente de conteúdo","Processar grandes volumes de dados de texto de artigos de fontes"],"ru":["Автоматизировать сбор новостных статей из нескольких источников","Генерировать файлы MD для эффективной организации контента","Обрабатывать большие объемы текстовых данных из статей источников"],"ar":["أتمتة جمع مقالات الأخبار من عدة مصادر","توليد ملفات MD لتنظيم المحتوى بكفاءة","معالجة أحجام كبيرة من بيانات النص من مقالات المصادر"]},"limitations":{"en":["Requires input files in MD format (e.g., `news/source-daily.md`, `news/source.md`)","Limited to text data processing, no support for PDF files directly"],"zh":["需要输入文件以MD格式（例如，`news/source-daily.md`，`news/source.md`）","仅限于文本数据处理，不支持直接处理PDF文件"],"ja":["入力ファイルはMD形式（例：`news/source-daily.md`、`news/source.md`）である必要がある","テキストデータ処理のみに限定され、PDFファイルの直接サポートはありません"],"ko":["입력 파일은 MD 형식이어야 함（예: `news/source-daily.md`, `news/source.md`）","텍스트 데이터 처리에만 제한되며, PDF 파일에 대한 직접 지원은 없습니다"],"es":["Requiere archivos de entrada en formato MD (por ejemplo, `news/source-daily.md`, `news/source.md`)","Limitado al procesamiento de datos de texto, sin soporte para archivos PDF directamente"],"fr":["Nécessite des fichiers d''entrée au format MD (par exemple, `news/source-daily.md`, `news/source.md`)","Limité au traitement de données textuelles, sans prise en charge directe des fichiers PDF"],"de":["Erfordert Eingabedateien im MD-Format (z.B. `news/source-daily.md`, `news/source.md`)","Begrenzt auf die Verarbeitung von Textdaten, ohne direkte Unterstützung für PDF-Dateien"],"pt":["Requer arquivos de entrada no formato MD (por exemplo, `news/source-daily.md`, `news/source.md`)","Limitado ao processamento de dados de texto, sem suporte a arquivos PDF diretamente"],"ru":["Требует входных файлов в формате MD (например, `news/source-daily.md`, `news/source.md`)","Ограничен обработкой текстовых данных, без поддержки файлов PDF напрямую"],"ar":["يتطلب ملفات إدخال بالتنسيق MD (على سبيل المثال `news/source-daily.md` و `news/source.md`)","محدود بمعالجة بيانات النص، بدون دعم مباشر لملفات PDF"]},"version":4},"contentHash":"b76cb2f76e6f946f75f25122fe64f4534ac568c1b0de7a8ac2faf48976d096de","qualityScore":30}');
DELETE FROM skills_fts WHERE id = 'Xbotics-Embodied-AI-club/Xbotics-Embodied-Guide/news-pdf-integration';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Xbotics-Embodied-AI-club/Xbotics-Embodied-Guide/news-pdf-integration', 'news-pdf-integration', 'Xbotics-Embodied-AI-club', 'Xbotics-Embodied-Guide', 'community', 'news-pdf-integration Xbotics-Embodied-AI-club Xbotics-Embodied-Guide community The news-pdf-integration skill generates MD files from source articles, helping developers and content creators organize and process large volumes of text data efficiently. 新闻PDF集成是一种高效的新闻文章聚合和MD文件生成技术，通过优先读取news/source-daily.md或news/source.md，实现每篇文章的重新整理和核心内容保留 ニュースPDF統合は、効率的なニュース記事の集約とMDファイルの生成を実現する技術で、news/source-daily.mdまたはnews/source.mdを優先的に読み込み、各記事の再構成と核心内容の保留を実現 뉴스 PDF 통합은 효율적인 뉴스 기사 수집과 MD 파일 생성을 실현하는 기술로서 news/source-daily.md 또는 news/source.md를 우선적으로 읽어들여 각 기사의 재구성과 핵심 내용 보존을 구현합니다 El agente de noticias en PDF utiliza Markdown para reorganizar artículos de noticias y evitar la infracción de derechos de autor. L''outil de nouvelles en PDF utilise Markdown pour réorganiser les articles de nouvelles et éviter les violations de droits d''auteur. Das KI-Tool für Nachrichten in PDF verwendet Markdown, um Nachrichtenartikel neu zu organisieren und Urheberrechtsverletzungen zu vermeiden. A ferramenta de integração de notícias em PDF processa múltiplas fontes de notícias e gera arquivos MD personalizados. Ela prioriza a leitura de notícias diárias e reorganiza o conteúdo para evitar violações de direitos autorais. Инструмент интеграции новостей в PDF обрабатывает несколько источников новостей и генерирует индивидуальные файлы MD. Он отдает приоритет чтению ежедневных новостей и реорганизует контент, чтобы избежать нарушений авторских прав. أداة دمج الأخبار في تنسيق PDF تعمل على معالجة العديد من مصادر الأخبار وتوليد ملفات MD مخصصة. إنها تعطي الأولوية لقراءة الأخبار اليومية وإعادة تنظيم المحتوى لتجنب انتهاكات حقوق النشر. how to use news-pdf-integration news-pdf-integration setup guide MD file generation from source articles automated content organization tools news-pdf-integration vs manual content processing installing news-pdf-integration for AI agents 新闻PDF集成 MD文件生成 新闻文章聚合 核心内容保留 避免侵权 news/source-daily.md news/source.md files/source/ AIエージェント AI工具 Reads multiple articles from news/source-daily.md or news/source.md Generates a separate MD file for each article in files/source/ Preserves core content while avoiding copyright infringement Supports reorganization of articles into thematic categories Outputs MD files with concise summaries of original content news-pdf-integration is a skill that automates the process of generating MD files from source articles, allowing for efficient content organization and processing.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('liushoukun/pdta/generate-prd', 'community', 'liushoukun', 'pdta', 'liushoukun/pdta', 'generate-prd', 0, 0, 30, '2026-03-08T01:57:15.510Z', '2026-03-08T02:10:27.443Z', '07c3bb4611a36919cbc98c7884d232d01340502ca2a5a511afb3ec28075aaff1', '{"id":"liushoukun/pdta/generate-prd","name":"generate-prd","description":{"en":"The generate-prd skill utilizes AI to generate PRD drafts, assisting product managers in quickly creating standardized demand documents. It benefits product teams by automating the initial drafting process.","zh":"AI辅助生成PRD文档，帮助产品经理快速完成标准化的需求文档编写，支持核心功能、需求背景、目标用户等信息的输入","ja":"AIエージェントによるPRD文書生成は、プロダクトマネージャーが迅速に標準化された要件文書を完成させるのに役立ち、コア機能、要件背景、対象ユーザーなどの情報を入力することができる","ko":"AI 도구를 이용한 PRD 문서 생성은 프로덕트 매니저가 빠르게 표준화된 요구사항 문서를 완성하도록 도와주며, 핵심 기능, 요구사항 배경, 목표 사용자 등의 정보를 입력할 수 있다","es":"La habilidad generate-prd utiliza AI para generar borradores de documentos de requisitos de producto. Ayuda a los gerentes de productos a crear documentos estandarizados rápidamente","fr":"La compétence generate-prd utilise l''IA pour générer des brouillons de documents de spécifications de produit. Elle aide les gestionnaires de produits à créer des documents standardisés rapidement","de":"Die Fähigkeit generate-prd verwendet KI, um Entwürfe von Produktanforderungsdokumenten zu erstellen. Sie hilft Produktmanagern, standardisierte Dokumente schnell zu erstellen","pt":"O generate-prd é uma ferramenta de IA que ajuda a criar PRDs padrão. Aprenda a configurá-la para agilizar seu trabalho.","ru":"Generate-prd - это инструмент ИИ, который помогает создавать стандартизированные шаблоны PRD. Узнайте, как его настроить для ускорения своей работы.","ar":"generate-prd هو أداة ذكاء اصطناعي تساعد في إنشاء نماذج PRD معايير. تعلم كيفية إعدادها لتحسين عملك."},"seo":{"title":{"en":"generate-prd: AI-Driven PRD Generation Setup Guide | AI A...","zh":"AI辅助生成PRD文档Setup Guide","ja":"AIエージェントによるPRD文書生成Best Practices","ko":"AI 도구를 이용한 PRD 문서 생성 가이드","es":"Guía de configuración para generar PRD con herramientas d...","fr":"Guide de mise en place pour générer des PRD avec des outi...","de":"Einrichtungsleitfaden für die Generierung von PRD mit KI-...","pt":"Guia de Configuração do generate-prd: Crie PRDs com Ferra...","ru":"Настройка generate-prd: Создание Шаблонов PRD с Помощью И...","ar":"دليل إعداد generate-prd: إنشاء نماذج PRD باستخدام أدوات ا..."},"description":{"en":"Discover how to streamline your product development with generate-prd, an AI-powered tool for creating standardized PRD documents - get started now!","zh":"使用AI辅助生成PRD文档，帮助产品经理快速完成标准化的需求文档编写，提高工作效率","ja":"AIエージェントを利用してPRD文書を生成し、プロダクトマネージャーの作業効率を向上させる","ko":"AI 도구를 이용하여 PRD 문서를 생성하고 프로덕트 매니저의 작업 효율을 향상시키는 방법","es":"Aprende a generar documentos de requisitos de producto con habilidades de AI. Descubre cómo crear PRD rápidamente con nuestra guía paso a paso","fr":"Découvrez comment générer des documents de spécifications de produit avec des compétences en IA. Suivez notre guide étape par étape pour créer des PRD rapide...","de":"Erfahren Sie, wie Sie Produktanforderungsdokumente mit KI-Fähigkeiten erstellen. Folgen Sie unserer Schritt-für-Schritt-Anleitung, um PRD schnell zu erstellen","pt":"Aprenda a configurar o generate-prd para criar PRDs padrão com auxílio de IA. Guia passo a passo para desenvolvedores.","ru":"Узнайте, как настроить generate-prd для создания стандартизированных шаблонов PRD с помощью ИИ Агентов. Руководство для разработчиков.","ar":"تعلم كيفية إعداد generate-prd لإنشاء نماذج PRD معايير باستخدام أدوات الذكاء الاصطناعي. دليل خطوة بخطوة للمطورين."},"definition":{"en":"generate-prd is an AI agent skill that automates the generation of Product Requirements Document (PRD) drafts, leveraging user-provided information to create standardized documents.","zh":"AI辅助生成PRD文档是一种利用人工智能技术来辅助生成产品需求文档的方法","ja":"AIエージェントによるPRD文書生成とは、人工知能技術を利用してプロダクト要件文書を生成する方法である","ko":"AI 도구를 이용한 PRD 문서 생성은 인공지능 기술을 활용하여 프로덕트 요구사항 문서를 생성하는 방법이다","es":"Un generate-prd es una habilidad de AI que ayuda a crear documentos de requisitos de producto estandarizados","fr":"Un generate-prd est une compétence en IA qui aide à créer des documents de spécifications de produit standardisés","de":"Ein generate-prd ist eine KI-Fähigkeit, die dabei hilft, standardisierte Produktanforderungsdokumente zu erstellen","pt":"O generate-prd é uma ferramenta de IA que gera PRDs padrão com base em informações fornecidas.","ru":"Generate-prd - это инструмент ИИ, который генерирует стандартизированные шаблоны PRD на основе предоставленной информации.","ar":"generate-prd هو أداة ذكاء اصطناعي ت生成 نماذج PRD معايير بناءً على المعلومات المقدمة."},"features":{"en":["Generates PRD drafts based on user-inputted demand background, core functionality, and target user information","Supports optional information inputs, including business objectives, quantitative metrics, and technical constraints","Provides a structured approach to PRD creation, ensuring consistency and completeness in demand documentation","Facilitates rapid creation of PRD documents for product managers with initial demand ideas","Enables the generation of PRD drafts based on existing information, streamlining the document creation process"],"zh":["支持核心功能、需求背景、目标用户等信息的输入","能够生成标准化的PRD文档","提高产品经理的工作效率","支持业务目标和量化指标的输入","支持竞品参考或类似功能的输入"],"ja":["コア機能、要件背景、対象ユーザーなどの情報を入力することができる","標準化されたPRD文書を生成することができる","プロダクトマネージャーの作業効率を向上させる","ビジネス目標と量化指標を入力することができる","競合他社の参考や類似機能を入力することができる"],"ko":["핵심 기능, 요구사항 배경, 목표 사용자 등의 정보를 입력할 수 있다","표준화된 PRD 문서를 생성할 수 있다","프로덕트 매니저의 작업 효율을 향상시킨다","사업 목표와 정량적 지표를 입력할 수 있다","경쟁사 참조 또는 유사 기능을 입력할 수 있다"],"es":["Generación de borradores de PRD con información de contexto","Soporte para la creación de documentos estandarizados","Capacidad para recopilar información de requisitos a través de preguntas de AI","Integración con tecnologías de lenguaje natural para mejorar la precisión","Opción para proporcionar información adicional, como objetivos comerciales y restricciones técnicas"],"fr":["Génération de brouillons de PRD avec des informations de contexte","Prise en charge de la création de documents standardisés","Capacité à recueillir des informations de spécifications à travers des questions d''IA","Intégration avec des technologies de langage naturel pour améliorer la précision","Option pour fournir des informations supplémentaires, telles que des objectifs commerciaux et des contraintes techniques"],"de":["Erstellung von Entwürfen für PRD mit Kontextinformationen","Unterstützung für die Erstellung standardisierter Dokumente","Fähigkeit, Anforderungsinformationen durch KI-Fragen zu sammeln","Integration mit Technologien der natürlichen Sprache zur Verbesserung der Genauigkeit","Option, zusätzliche Informationen wie Geschäftsziele und technische Einschränkungen bereitzustellen"],"pt":["Geração de PRDs padrão com auxílio de IA","Suporte à coleta de informações de demanda","Criação de estruturas de documento padronizadas","Integração com informações de negócios e objetivos","Suporte à definição de funcionalidades e requisitos"],"ru":["Генерация стандартизированных шаблонов PRD с помощью ИИ","Поддержка сбора информации о требованиях","Создание стандартизированных структур документов","Интеграция с бизнес-информацией и целями","Поддержка определения функциональности и требований"],"ar":["إنشاء نماذج PRD معايير باستخدام أدوات الذكاء الاصطناعي","دعم جمع معلومات الطلب","إنشاء هياكل وثائق معايير","التكامل مع معلومات العمل وأهدافها","دعم تعريف الوظائف والمتطلبات"]},"keywords":{"en":["how to use generate-prd","generate-prd setup guide","what is generate-prd","generate-prd alternative","generate-prd vs manual PRD creation","PRD document generation","AI-driven PRD tools","product requirements document template","generate-prd install","generate-prd tutorial"],"zh":["AI辅助生成PRD文档","产品需求文档","标准化文档","产品经理工具","AI工具","PRD文档生成","需求文档编写","工作效率提高"],"ja":["AIエージェントによるPRD文書生成","プロダクト要件文書","標準化文書","プロダクトマネージャーツール","AIツール","PRD文書生成","要件文書作成","作業効率向上"],"ko":["AI 도구를 이용한 PRD 문서 생성","프로덕트 요구사항 문서","표준화 문서","프로덕트 매니저 도구","AI 도구","PRD 문서 생성","요구사항 문서 작성","작업 효율 향상"],"es":["generar PRD","herramientas de AI para PRD","creación de documentos de requisitos de producto","gestión de productos con AI","documentos estandarizados de PRD","preguntas de AI para recopilar información","tecnologías de lenguaje natural para PRD"],"fr":["générer des PRD","outils d''IA pour PRD","création de documents de spécifications de produit","gestion de produits avec IA","documents standardisés de PRD","questions d''IA pour recueillir des informations","technologies de langage naturel pour PRD"],"de":["PRD erstellen","KI-Tools für PRD","Erstellung von Produktanforderungsdokumenten","Produktmanagement mit KI","standardisierte PRD-Dokumente","KI-Fragen zur Sammlung von Informationen","Technologien der natürlichen Sprache für PRD"],"pt":["generate-prd","ferramentas de ia para desenvolvedores","criação de prds","padronização de documentos","desenvolvimento de software","ia para desenvolvedores","ferramentas de desenvolvimento","prds padrão"],"ru":["generate-prd","инструменты ИИ для разработчиков","создание шаблонов PRD","стандартизация документов","разработка ПО","ИИ для разработчиков","инструменты разработки","стандартизированные шаблоны PRD"],"ar":["generate-prd","أدوات الذكاء الاصطناعي للمطورين","إنشاء نماذج PRD","معايير الوثائق","تطوير البرمجيات","الذكاء الاصطناعي للمطورين","أدوات التطوير","نماذج PRD معايير"]}},"owner":"liushoukun","repo":"pdta","repoPath":"liushoukun/pdta","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.510Z","topics":[],"category":"community","skillMd":{"name":"generate-prd","description":"辅助生成PRD产品需求文档草稿。当用户需要创建PRD、生成产品需求文档，或提到生成PRD、创建需求文档、写PRD时使用此技能。","bodyPreview":"# 生成PRD技能\n\n## 技能概述\n\nAI辅助生成PRD（产品需求文档）草稿，帮助产品经理快速完成标准化的需求文档编写。\n\n---\n\n## 使用场景\n\n### 何时使用\n- ✅ 需要快速创建PRD文档\n- ✅ 有初步需求想法，需要AI辅助完善\n- ✅ 需要规范化的文档结构\n- ✅ 需要基于现有信息生成PRD草稿\n\n### 何时不使用\n- ❌ 完全从零开始的复杂需求（建议先人工梳理）\n- ❌ PRD已存在只需局部修改\n- ❌ 需求尚未明确，缺少基本信息\n\n---\n\n## 前置条件\n\n### 必需信息\n至少提供以下信息之一：\n1. **需求背景**：为什么要做这个需求\n2. **核心功能**：主要实现什么功能\n3. **目标用户**：给谁用，解决什么问题\n\n### 可选信息\n- 业务目标和量化指标\n- 竞品参考或类似功能\n- 技术约束或限制\n- 时间节点要求\n\n---\n\n## 使用步骤\n\n### 步骤1：收集需求信息\n\n**AI提问收集**：\n\n**问题1**：需求基本信息\n```\n请提供以下信息：\n1. 需求名称：[简短描述，如\"移动端首页改版\"]\n2. 需求背景：[为什么要做这个需求","body":"# 生成PRD技能\n\n## 技能概述\n\nAI辅助生成PRD（产品需求文档）草稿，帮助产品经理快速完成标准化的需求文档编写。\n\n---\n\n## 使用场景\n\n### 何时使用\n- ✅ 需要快速创建PRD文档\n- ✅ 有初步需求想法，需要AI辅助完善\n- ✅ 需要规范化的文档结构\n- ✅ 需要基于现有信息生成PRD草稿\n\n### 何时不使用\n- ❌ 完全从零开始的复杂需求（建议先人工梳理）\n- ❌ PRD已存在只需局部修改\n- ❌ 需求尚未明确，缺少基本信息\n\n---\n\n## 前置条件\n\n### 必需信息\n至少提供以下信息之一：\n1. **需求背景**：为什么要做这个需求\n2. **核心功能**：主要实现什么功能\n3. **目标用户**：给谁用，解决什么问题\n\n### 可选信息\n- 业务目标和量化指标\n- 竞品参考或类似功能\n- 技术约束或限制\n- 时间节点要求\n\n---\n\n## 使用步骤\n\n### 步骤1：收集需求信息\n\n**AI提问收集**：\n\n**问题1**：需求基本信息\n```\n请提供以下信息：\n1. 需求名称：[简短描述，如\"移动端首页改版\"]\n2. 需求背景：[为什么要做这个需求？当前有什么问题？]\n3. 目标用户：[谁会使用这个功能？]\n4. 核心功能：[主要实现哪些功能？]\n```\n\n**问题2**：需求目标\n```\n请明确需求目标：\n1. 业务目标：[期望达成什么业务效果？]\n2. 量化指标：[如何衡量成功？如用户增长X%，转化率提升Y%]\n3. 成功标准：[什么情况下认为需求成功？]\n```\n\n**问题3**：需求范围\n```\n请明确需求范围：\n1. 本期包含：[哪些功能在本期实现？]\n2. 本期不包含：[哪些功能暂不实现？为什么？]\n3. 边界限制：[有哪些约束条件？]\n```\n\n---\n\n### 步骤2：确认文档信息\n\n**AI确认**：\n```\n确认文档基本信息：\n- 需求名称：[从步骤1获取]\n- 创建年月：[默认当月，格式：YYYYMM]\n- 产品负责人：[询问用户]\n- 开发负责人：[询问用户或待定]\n- 测试负责人：[询问用户或待定]\n```\n\n---\n\n### 步骤3：生成文档结构\n\n**AI执行**：\n\n1. **创建文件夹**（如不存在）\n```bash\ndocs/需求文档/{年月}-{需求名称}/product/\n```\n\n2. **生成PRD.md文件**\n基于 [PRD_template.md](./templates/PRD_template.md) 模板和收集的信息生成。\n\n**模板使用说明**：\n- 模板位置：`.cursor/skills/generate-prd/templates/PRD_template.md`\n- 模板变量替换：\n  - `{{需求名称}}` → 实际需求名称\n  - `{{创建日期}}` → 当前日期（YYYY-MM-DD）\n- AI应基于模板结构生成内容，替换占位符并填充实际内容\n\n---\n\n### 步骤4：生成PRD内容\n\n**AI自动生成以下章节**：\n\n#### 一、需求概述\n**1.1 需求背景**\n- 基于用户提供的背景信息生成\n- 补充业务价值分析\n- 添加合理的假设和推断\n\n**1.2 需求目标**\n- 转换业务目标为SMART格式\n- 确保至少1个量化指标\n- 区分短期和长期目标\n\n**1.3 需求范围**\n- 使用✅和❌标识包含和不包含的功能\n- 说明边界和限制\n- 明确优先级\n\n**1.4 目标用户**\n- 基于用户信息创建用户画像\n- 描述典型使用场景\n- 分析用户痛点\n\n---\n\n#### 二、功能需求\n\n**2.1 功能架构**\n- 基于核心功能生成Mermaid功能树\n- 至少2层结构（主功能-子功能）\n\n```mermaid\ngraph TD\n    A[需求名称] --> B[主功能1]\n    A --> C[主功能2]\n    B --> B1[子功能1.1]\n    B --> B2[子功能1.2]\n```\n\n**2.2 核心功能详述**\n为每个核心功能生成：\n- **功能描述**：清晰说明功能价值\n- **用户故事**：作为[角色]，我想要[功能]，以便[目标]\n- **功能要点**：3-5个关键点\n- **业务规则**：数据验证、权限约束\n- **交互流程**：生成Mermaid时序图\n\n---\n\n#### 三、非功能需求\n\n**3.1 性能要求**\n生成性能指标表格：\n- 页面加载时间：基于页面复杂度推断\n- 接口响应时间：< 1秒（标准值）\n- 并发用户数：基于目标用户规模估算\n\n**3.2 安全要求**\n- 数据安全：加密、备份标准方案\n- 访问控制：基于用户角色设计权限\n- 合规要求：隐私保护基本要求\n\n**3.3 兼容性要求**\n- 浏览器：主流浏览器最近2个版本\n- 设备：PC/移动/平板\n- 分辨率：常见分辨率范围\n\n**3.4 可用性要求**\n- 易用性目标\n- 可维护性要求\n- 可扩展性考虑\n\n---\n\n#### 四、交互设计\n\n**4.1 页面结构**\n- 描述整体布局\n- 使用ASCII图示意\n\n**4.2 页面清单**\n生成页面列表表格：\n\n| 页面名称 | 页面路径 | 说明 | 优先级 |\n|---------|---------|------|--------|\n| [生成] | [推断] | [描述] | P0/P1/P2 |\n\n**4.3 交互细节**\n- 关键交互行为\n- 状态变化和反馈\n- 异常处理方式\n\n**4.4 异常处理**\n生成异常处理表格，包含常见场景。\n\n---\n\n#### 五、数据需求\n\n**5.1 数据字典**\n基于功能需求推断核心数据实体：\n\n| 字段名称 | 字段类型 | 必填 | 说明 | 示例值 |\n|---------|---------|------|------|--------|\n| id | 整数 | 是 | 唯一标识 | 1001 |\n\n**5.2 数据来源**\n- 说明数据来源\n- 是否需要对接外部系统\n- 数据质量要求\n\n**5.3 数据流转**\n生成Mermaid数据流图。\n\n---\n\n#### 六、验收标准\n\n生成任务列表格式的验收标准：\n\n**6.1 功能验收**\n- [ ] 核心功能完整实现\n- [ ] 业务规则正确执行\n\n**6.2 性能验收**\n- [ ] 性能指标达标\n- [ ] 无内存泄漏\n\n**6.3 兼容性验收**\n- [ ] 主流浏览器测试通过\n- [ ] 移动端适配正常\n\n**6.4 安全验收**\n- [ ] 无高危漏洞\n- [ ] 权限控制正常\n\n**6.5 体验验收**\n- [ ] 界面美观符合规范\n- [ ] 操作流畅无卡顿\n\n---\n\n#### 七、项目计划\n\n**7.1 里程碑**\n生成标准项目阶段表格：\n\n| 阶段 | 开始日期 | 结束日期 | 交付物 |\n|------|---------|---------|--------|\n| 需求评审 | [推算] | [推算] | PRD |\n| 技术设计 | [推算] | [推算] | TDD |\n| 开发测试 | [推算] | [推算] | 功能代码 |\n| 上线发布 | [推算] | [推算] | 线上功能 |\n\n**7.2 风险管理**\n生成常见风险表格。\n\n---\n\n#### 八、附录\n\n**8.1 参考资料**\n- 预留位置，提示人工补充\n\n**8.2 专业术语**\n- 提取关键术语，生成术语表\n\n**8.3 原型图/设计稿**\n- 预留位置，提示添加图片或链接\n\n---\n\n#### 九、版本历史\n\n初始化版本记录：\n\n| 版本号 | 修改日期 | 修改人 | 修改内容 |\n|--------|----------|--------|----------|\n| v1.0 | [今天日期] | [产品负责人] | 初始版本 |\n\n---\n\n#### 十、评审记录\n\n创建空表格待填：\n\n| 评审日期 | 参与人 | 评审意见 | 处理状态 |\n|---------|--------|---------|---------|\n| - | - | - | - |\n\n---\n\n### 步骤5：质量检查\n\n**AI自动检查**：\n\n**结构完整性**\n- [ ] 包含所有必需章节（一至十）\n- [ ] 章节顺序正确\n- [ ] 标题层级符合规范\n\n**内容质量**\n- [ ] 需求背景有理有据\n- [ ] 需求目标可量化（至少1个指标）\n- [ ] 功能描述清晰完整\n- [ ] 至少1个Mermaid图\n- [ ] 验收标准使用任务列表\n- [ ] 用户故事格式正确\n\n**格式规范**\n- [ ] 表格格式正确\n- [ ] Mermaid图表正确\n- [ ] 无占位符（\"待补充\"等）\n- [ ] 文档元信息完整\n\n**输出检查报告**。\n\n---\n\n### 步骤6：人工审核和完善\n\n**AI提示**：\n```\n✅ PRD草稿已生成：docs/需求文档/{年月}-{需求名称}/product/PRD.md\n\n📋 请人工审核和完善以下内容：\n1. 需求背景是否准确反映实际情况\n2. 功能描述是否完整，有无遗漏\n3. 验收标准是否明确可检查\n4. 交互设计是否需要添加原型图\n5. 项目计划是否符合实际排期\n\n⚠️ 注意事项：\n- AI生成的是草稿，核心内容需人工确认\n- 数据推断可能不准确，需要实际数据支撑\n- 交互细节需要结合UI设计完善\n- 性能指标需要根据实际情况调整\n\n✏️ 完善后请更新：\n- 文档状态：🔵 草稿 → 🟡 评审中\n- 补充原型图或设计稿\n- 确认负责人信息\n- 添加参考资料链接\n```\n\n---\n\n## 生成规则\n\n### 内容推断规则\n\n#### 性能指标推断\n```\n页面类型 → 加载时间要求\n- 简单页面（列表、详情）：< 1秒\n- 复杂页面（图表、大表格）：< 2秒\n- 首页/入口页面：< 1.5秒\n\n用户规模 → 并发要求\n- 小型应用（< 1000用户）：100并发\n- 中型应用（1000-10000用户）：500并发\n- 大型应用（> 10000用户）：1000+并发\n```\n\n#### 功能优先级推断\n```\nP0（必须）：\n- 核心业务流程功能\n- 无此功能无法使用\n\nP1（重要）：\n- 提升体验的功能\n- 大多数用户需要\n\nP2（可选）：\n- 辅助功能\n- 少数用户使用\n```\n\n#### 页面路由推断\n```\n功能名称 → 路由规则\n- 列表页：/resource-name\n- 详情页：/resource-name/:id\n- 新增页：/resource-name/new\n- 编辑页：/resource-name/:id/edit\n```\n\n---\n\n### 质量保证规则\n\n#### 必需元素\n- ✅ 文档元信息表格完整\n- ✅ 至少1个Mermaid功能架构图\n- ✅ 至少1个Mermaid流程图或数据流图\n- ✅ 用户故事格式正确\n- ✅ 验收标准使用任务列表\n- ✅ 版本历史已初始化\n\n#### 禁止元素\n- ❌ 空白章节或\"待补充\"占位符\n- ❌ 技术实现细节（如\"使用Vue3\"）\n- ❌ 模糊表述（\"尽量\"、\"大概\"）\n- ❌ 无法检查的验收标准\n\n#### 推荐实践\n- ✅ 提供具体数据和示例\n- ✅ 使用表格提升可读性\n- ✅ 用图表辅助说明\n- ✅ 标注需要人工补充的内容\n\n---\n\n## 交互模式\n\n### 模式1：问答式生成（推荐）\n\n**适用**：信息不足，需要逐步收集\n\n**流程**：\n1. AI提问收集基本信息\n2. AI确认并补充遗漏信息\n3. AI生成PRD草稿\n4. AI执行质量检查\n5. AI提示人工审核要点\n\n---\n\n### 模式2：基于现有信息生成\n\n**适用**：用户已提供详细需求描述\n\n**流程**：\n1. AI分析用户提供的信息\n2. AI提取关键要素\n3. AI直接生成PRD草稿\n4. AI执行质量检查\n5. AI提示需要人工确认的部分\n\n---\n\n### 模式3：基于竞品参考生成\n\n**适用**：有明确的竞品或参考案例\n\n**流程**：\n1. 用户提供竞品信息或链接\n2. AI分析竞品功能\n3. AI基于竞品生成功能需求\n4. AI补充本产品特色\n5. AI生成完整PRD草稿\n\n---\n\n## 命令示例\n\n### 示例1：基本创建\n\n**用户**：\n```\n帮我生成一个\"用户权限管理\"的PRD\n```\n\n**AI**：\n```\n好的，我来帮你生成\"用户权限管理\"的PRD。\n\n请先回答几个问题：\n\n1. 需求背景：为什么需要用户权限管理功能？\n2. 目标用户：谁会使用这个功能（管理员、普通用户）？\n3. 核心功能：需要实现哪些权限管理能力？\n```\n\n---\n\n### 示例2：详细信息生成\n\n**用户**：\n```\n生成PRD：移动端首页改版\n\n背景：当前首页信息展示不够清晰，用户反馈找不到常用功能\n目标：提升首页易用性，核心功能点击率提升30%\n用户：移动端APP用户，日活5000+\n功能：\n- 个性化推荐模块\n- 快捷入口定制\n- 数据可视化展示\n```\n\n**AI**：\n```\n收到，基于你提供的信息生成PRD...\n\n[AI自动分析信息]\n[AI生成完整PRD]\n[AI执行质量检查]\n\n✅ PRD已生成：docs/需求文档/202602-移动端首页改版/product/PRD.md\n```\n\n---\n\n### 示例3：参考竞品生成\n\n**用户**：\n```\n参考微信的小程序收藏功能，生成我们的\"内容收藏\"PRD\n```\n\n**AI**：\n```\n好的，我会参考微信小程序收藏功能的设计。\n\n请确认以下信息：\n1. 收藏的内容类型：[文章/视频/商品/...]？\n2. 收藏场景：用户在哪里可以收藏？\n3. 特殊需求：相比微信，我们有什么特色功能？\n\n[等待用户回答后继续生成]\n```\n\n---\n\n## 高级功能\n\n### 功能1：批量生成多个功能模块\n\n当需求包含多个独立模块时，可以：\n1. 先生成主PRD\n2. 为每个模块生成详细的功能描述\n3. 确保模块间的数据关联正确\n\n---\n\n### 功能2：基于现有PRD增量生成\n\n当需要在现有PRD基础上添加功能：\n1. 读取现有PRD\n2. 分析现有功能架构\n3. 生成新功能章节\n4. 更新功能架构图\n5. 更新版本历史\n\n---\n\n### 功能3：生成配套的用户故事地图\n\n除了标准PRD，还可以生成：\n- 用户旅程地图\n- 功能优先级矩阵\n- 需求分析报告\n\n---\n\n## 常见问题\n\n### Q1: PRD生成需要多长时间？\n**A**: 通常2-5分钟，取决于需求复杂度和信息完整性。\n\n### Q2: 生成的PRD可以直接用于开发吗？\n**A**: 不能。PRD草稿需要产品经理审核、完善，补充原型图等，评审通过后才能进入开发。\n\n### Q3: 如何确保生成的PRD质量？\n**A**: AI会执行自动质量检查，但核心内容准确性需要人工确认。\n\n### Q4: 可以修改生成的内容吗？\n**A**: 可以。PRD草稿完全可编辑，建议人工审核后根据实际情况修改。\n\n### Q5: 如何处理复杂的业务逻辑？\n**A**: 复杂业务逻辑建议先人工梳理清楚，再让AI辅助生成文档结构。\n\n### Q6: 生成的Mermaid图不合理怎么办？\n**A**: 可以在生成后手动调整Mermaid代码，或提供更详细的功能结构信息重新生成。\n\n---\n\n## 检查清单\n\n生成PRD后，使用此清单验证：\n\n**结构检查**\n- [ ] 包含所有必需章节（一至十）\n- [ ] 章节顺序正确\n- [ ] 文档元信息完整\n\n**内容检查**\n- [ ] 需求背景清晰有据\n- [ ] 需求目标可量化\n- [ ] 功能描述完整\n- [ ] 至少1个功能架构图\n- [ ] 至少1个流程图或数据流图\n- [ ] 用户故事格式正确\n- [ ] 验收标准明确可检查\n\n**格式检查**\n- [ ] 表格格式正确\n- [ ] Mermaid图可正常渲染\n- [ ] 无占位符和\"待补充\"\n- [ ] 任务列表语法正确\n\n**质量检查**\n- [ ] 术语使用一致\n- [ ] 无技术实现细节\n- [ ] 避免模糊表述\n- [ ] 示例数据合理\n\n---\n\n## 相关资源\n\n### 规则\n- [PRD编写标准](../../rules/doc-writing/prd-standard.md)\n- [文档结构规范](../../rules/doc-structure/RULE.md)\n- [文档质量检查规范](../../rules/doc-quality/RULE.md)\n\n### 技能\n- [生成TDD](../generate-tdd/SKILL.md)\n- [生成测试用例](../generate-test/SKILL.md)\n- [分析文档覆盖率](../analyze-coverage/SKILL.md)\n\n### 模板\n- [PRD模板](./templates/PRD_template.md)\n\n---\n\n## 最佳实践\n\n### 1. 充分准备再生成\n在生成前尽量收集完整信息，减少后期修改。\n\n### 2. 分阶段生成\n对于复杂需求，可以先生成基础框架，再逐步完善细节。\n\n### 3. 保持迭代思维\nPRD不是一次性完成的，可以通过多轮生成和修改逐步完善。\n\n### 4. 结合原型图\nAI生成文字描述后，建议补充原型图使交互设计更清晰。\n\n### 5. 重视验收标准\n验收标准决定了需求的成功标准，要特别注意其明确性和可检查性。\n\n---\n\n## 示例场景\n\n### 场景：电商平台优惠券功能\n\n**用户输入**：\n```\n生成\"优惠券功能\"PRD\n\n背景：\n- 当前没有优惠券功能，促销手段单一\n- 竞品都有优惠券，我们需要跟进\n- 运营反馈需要更多营销工具\n\n目标：\n- 上线优惠券功能，提升转化率15%\n- 支持多种优惠券类型\n- 用户领券-用券流程流畅\n\n功能：\n- 用户领券、查看、使用\n- 商家创建、发放、管理优惠券\n- 多种优惠券类型（满减、折扣、兑换）\n```\n\n**AI生成过程**：\n1. 分析需求信息，提取关键要素\n2. 确认文档信息（年月、负责人）\n3. 生成PRD结构：\n   - 需求概述：背景、目标、范围、用户\n   - 功能需求：用户端+商家端功能架构\n   - 非功能需求：性能、安全、兼容性\n   - 交互设计：页面清单、流程图\n   - 数据需求：优惠券表、用户优惠券表\n   - 验收标准：功能、性能、体验\n   - 项目计划：里程碑、风险\n4. 生成功能架构Mermaid图\n5. 生成用户领券流程时序图\n6. 生成数据流转图\n7. 执行质量检查\n8. 输出完善建议\n\n**生成结果**：\n```\n✅ PRD已生成：docs/需求文档/202602-优惠券功能/product/PRD.md\n\n📊 质量检查结果：\n- 完整性: 100/100 ✅\n- 清晰性: 92/100 ✅\n- 一致性: 95/100 ✅\n- 可执行性: 90/100 ✅\n总分: 94/100 (优秀)\n\n💡 完善建议：\n1. 补充优惠券使用规则的详细说明\n2. 添加优惠券叠加使用的策略\n3. 补充优惠券过期提醒的交互细节\n4. 建议添加原型图辅助说明\n\n📋 下一步：\n1. 产品经理审核并完善细节\n2. 添加原型图或设计稿\n3. 确认开发和测试负责人\n4. 提交产品评审\n```\n\n---\n\n**技能维护者**: [填写]  \n**最后更新**: 2026-02-09  \n**版本**: v1.0\n"},"lastSynced":"2026-03-08T02:10:27.443Z","agentAnalysis":{"suitability":{"en":"Perfect for Product Management Agents needing automated PRD drafting capabilities.","zh":"非常适合需要自动化PRD编写能力的产品管理代理","ja":"自動化されたPRD作成機能を必要とする製品管理エージェントに最適","ko":"자동화된 PRD 작성 기능이 필요한 제품 관리 에이전트에 적합","es":"Perfecto para Agentes de Gestión de Productos que necesitan capacidades de creación de borradores de PRD automatizadas.","fr":"Parfait pour les agents de gestion de produits ayant besoin de capacités de rédaction automatisée de PRD.","de":"Perfekt für Produktmanagement-Agenten, die automatisierte PRD-Entwurfsfunktionen benötigen.","pt":"Perfeito para Agentes de Gerenciamento de Produtos que precisam de capacidades de criação automática de PRD.","ru":"Идеально для агентов по управлению продукцией, которым необходимы автоматические возможности создания PRD.","ar":"مثالي لعمليات إدارة المنتج التي تحتاج إلى إمكانات صياغة PRD автоматически."},"recommendation":{"en":"Empowers agents to generate standardized PRD drafts using AI, streamlining the initial drafting process with core functionality, demand background, and target user information, while supporting optional details like business objectives, competitor references, and technical constraints.","zh":"赋予代理生成标准化的PRD草稿的能力，使用AI进行初步草稿流程，包括核心功能、需求背景和目标用户信息，同时支持可选的详细信息，如商业目标、竞争对手引用和技术约束","ja":"エージェントが標準化されたPRD草案を生成できるようにし、AIを使用して初期の草案作成プロセスを合理化し、コア機能、需要背景、ターゲットユーザー情報を含み、ビジネス目標、競合他社の引用、技術的制約などのオプションの詳細もサポート","ko":"에이전트가 표준화된 PRD 초안을 생성할 수 있도록하여 AI를 사용하여 초기 초안 작성 프로세스를 최적화하며 핵심 기능, 수요 배경, 대상 사용자 정보를 포함하고 비즈니스 목표, 경쟁사 참조, 기술적 제약 등의 선택적 세부 정보도 지원","es":"Habilita a los agentes a generar borradores de PRD estandarizados utilizando IA, simplificando el proceso de creación inicial con funcionalidad principal, antecedentes de demanda y información del usuario objetivo, y admitiendo detalles opcionales como objetivos comerciales, referencias de competidores y restricciones técnicas.","fr":"Permet aux agents de générer des brouillons de PRD standardisés à l''aide de l''IA, en simplifiant le processus de création initial avec les fonctionnalités principales, les antécédents de la demande et les informations de l''utilisateur cible, tout en prenant en charge des détails facultatifs comme les objectifs commerciaux, les références des concurrents et les contraintes techniques.","de":"Ermächtigt Agenten, standardisierte PRD-Entwürfe mithilfe von KI zu erstellen, indem sie den initialen Erstellungsprozess mit Kernfunktionen, Hintergrundinformationen zur Nachfrage und Zielbenutzerinformationen straffen und optional Details wie Geschäftsziele, Wettbewerbsverweise und technische Einschränkungen unterstützen.","pt":"Habilita os agentes a gerar projetos de PRD padronizados usando IA, agilizando o processo de criação inicial com funcionalidade principal, demanda de fundo e informações do usuário-alvo, além de suportar detalhes opcionais como objetivos comerciais, referências de concorrentes e restrições técnicas.","ru":"Наделяет агентов возможностью создавать стандартизированные черновики PRD с помощью ИИ, оптимизируя начальную стадию создания документов с основной функциональностью, фоном спроса и информацией о целевом пользователе, а также поддерживая необязательные детали, такие как бизнес-цели, ссылки на конкурентов и технические ограничения.","ar":"تمكين الوكلاء من إنشاء مشاريع(PRD) معيارية باستخدام الذكاء الاصطناعي، وتيسير عملية الصياغة الأولى مع الوظائف الأساسية، و背景 الطلب، ومعلومات المستخدم المستهدف، ودعم تفاصيل إضافية مثل الأهداف التجارية، وإشارات المنافسين، والقيود الفنية."},"useCases":{"en":["Automating PRD document creation for new product features","Generating PRD drafts based on initial demand ideas and basic information","Standardizing PRD document structures for product teams"],"zh":["自动化创建新产品特性的PRD文档","根据初始需求想法和基本信息生成PRD草稿","为产品团队标准化PRD文档结构"],"ja":["新しい製品機能のPRD文書の自動化作成","初期の需要アイデアと基本情報に基づいてPRD草案を生成","製品チームのPRD文書構造を標準化"],"ko":["새로운 제품 기능의 PRD 문서 자동화 생성","초기 수요 아이디어와 기본 정보를 기반으로 PRD 초안 생성","제품 팀의 PRD 문서 구조 표준화"],"es":["Automatizar la creación de documentos de PRD para nuevas características de producto","Generar borradores de PRD en función de ideas de demanda iniciales y información básica","Establecer estructuras de documentos de PRD estandarizadas para equipos de producto"],"fr":["Automatiser la création de documents de PRD pour les nouvelles fonctionnalités de produit","Générer des brouillons de PRD en fonction des idées de demande initiales et des informations de base","Standardiser les structures de documents de PRD pour les équipes de produit"],"de":["Automatisieren der Erstellung von PRD-Dokumenten für neue Produktfunktionen","Erstellen von PRD-Entwürfen auf Grundlage von initialen Nachfrageideen und Basisinformationen","Standardisieren von PRD-Dokumentstrukturen für Produktteams"],"pt":["Automatizar a criação de documentos PRD para novos recursos de produto","Gerar projetos de PRD com base em ideias iniciais de demanda e informações básicas","Padronizar estruturas de documentos PRD para equipes de produto"],"ru":["Автоматизировать создание документов PRD для новых функций продукта","Генерировать черновики PRD на основе первоначальных идей спроса и основных сведений","Стандартизировать структуры документов PRD для команд продукта"],"ar":["توفير آلي لإنشاء وثائق(PRD) لسمات المنتج الجديدة","إنشاء مشاريع(PRD) استناداً إلى أفكار الطلب الأولية والمعلومات الأساسية","تقييس هياكل وثائق(PRD) لفريق المنتج"]},"limitations":{"en":["Requires at least one of: demand background, core functionality, or target user information","Not suitable for completely new, complex demands without initial human analysis","Limited to generating drafts, not final PRD documents"],"zh":["需要至少一个：需求背景、核心功能或目标用户信息","不适合完全新的、复杂的需求而没有初始的人工分析","仅限于生成草稿，不是最终的PRD文档"],"ja":["需要背景、コア機能、またはターゲットユーザー情報の少なくとも1つ","完全に新しい、複雑な需要には初期の人間の分析なしに適さない","草案の生成のみ、最終的なPRD文書ではない"],"ko":["需求 배경, 핵심 기능 또는 대상 사용자 정보 중 최소 한 개가 필요","초기 인적 분석 없이 완전히 새로운 복잡한 수요에는 적합하지 않음","초안 생성만 가능, 최종 PRD 문서 아님"],"es":["Requiere al menos uno de: antecedentes de demanda, funcionalidad principal o información del usuario objetivo","No es adecuado para demandas completamente nuevas y complejas sin análisis humano inicial","Limitado a la generación de borradores, no documentos de PRD finales"],"fr":["Nécessite au moins l''un des éléments suivants : antécédents de la demande, fonctionnalité principale ou informations de l''utilisateur cible","N''est pas adapté aux demandes entièrement nouvelles et complexes sans analyse humaine initiale","Limité à la génération de brouillons, et non de documents de PRD finals"],"de":["Erfordert mindestens eines von: Hintergrundinformationen zur Nachfrage, Kernfunktionen oder Zielbenutzerinformationen","Nicht geeignet für völlig neue und komplexe Anforderungen ohne vorherige menschliche Analyse","Begrenzt auf die Erstellung von Entwürfen, nicht auf finale PRD-Dokumente"],"pt":["Exige pelo menos um dos seguintes: demanda de fundo, funcionalidade principal ou informações do usuário-alvo","Não é adequado para demandas completamente novas e complexas sem análise humana inicial","Limitado a gerar projetos, não documentos PRD finais"],"ru":["Требует как минимум одного из следующих: фон спроса, основная функциональность или информация о целевом пользователе","Не подходит для совершенно новых, сложных спросов без первоначального человеческого анализа","Ограничен генерацией черновиков, а не окончательных документов PRD"],"ar":["يتطلب على الأقل واحد من التالي: خلفية الطلب، أو الوظائف الأساسية، أو معلومات المستخدم المستهدف","لا يصلح للطلبات الجديدة والمعقدة تماما بدون تحليل بشري أولي","محدود بالمشاريع، وليس وثائق(PRD) النهائية"]},"version":4},"contentHash":"07c3bb4611a36919cbc98c7884d232d01340502ca2a5a511afb3ec28075aaff1","qualityScore":30}');
