INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('liushoukun/pdta/generate-prd', 'generate-prd', 'liushoukun', 'pdta', 'community', 'generate-prd liushoukun pdta community The generate-prd skill utilizes AI to generate PRD drafts, assisting product managers in quickly creating standardized demand documents. It benefits product teams by automating the initial drafting process. AI辅助生成PRD文档，帮助产品经理快速完成标准化的需求文档编写，支持核心功能、需求背景、目标用户等信息的输入 AIエージェントによるPRD文書生成は、プロダクトマネージャーが迅速に標準化された要件文書を完成させるのに役立ち、コア機能、要件背景、対象ユーザーなどの情報を入力することができる AI 도구를 이용한 PRD 문서 생성은 프로덕트 매니저가 빠르게 표준화된 요구사항 문서를 완성하도록 도와주며, 핵심 기능, 요구사항 배경, 목표 사용자 등의 정보를 입력할 수 있다 La habilidad generate-prd utiliza AI para generar borradores de documentos de requisitos de producto. Ayuda a los gerentes de productos a crear documentos estandarizados rápidamente La compétence generate-prd utilise l''IA pour générer des brouillons de documents de spécifications de produit. Elle aide les gestionnaires de produits à créer des documents standardisés rapidement Die Fähigkeit generate-prd verwendet KI, um Entwürfe von Produktanforderungsdokumenten zu erstellen. Sie hilft Produktmanagern, standardisierte Dokumente schnell zu erstellen O generate-prd é uma ferramenta de IA que ajuda a criar PRDs padrão. Aprenda a configurá-la para agilizar seu trabalho. Generate-prd - это инструмент ИИ, который помогает создавать стандартизированные шаблоны PRD. Узнайте, как его настроить для ускорения своей работы. generate-prd هو أداة ذكاء اصطناعي تساعد في إنشاء نماذج PRD معايير. تعلم كيفية إعدادها لتحسين عملك. how to use generate-prd generate-prd setup guide what is generate-prd generate-prd alternative generate-prd vs manual PRD creation PRD document generation AI-driven PRD tools product requirements document template generate-prd install generate-prd tutorial AI辅助生成PRD文档 产品需求文档 标准化文档 产品经理工具 AI工具 PRD文档生成 需求文档编写 工作效率提高 Generates PRD drafts based on user-inputted demand background, core functionality, and target user information Supports optional information inputs, including business objectives, quantitative metrics, and technical constraints Provides a structured approach to PRD creation, ensuring consistency and completeness in demand documentation Facilitates rapid creation of PRD documents for product managers with initial demand ideas Enables the generation of PRD drafts based on existing information, streamlining the document creation process generate-prd is an AI agent skill that automates the generation of Product Requirements Document (PRD) drafts, leveraging user-provided information to create standardized documents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('armanisadeghi/matrx-platform/mobile-native-standards', 'community', 'armanisadeghi', 'matrx-platform', 'armanisadeghi/matrx-platform', 'mobile-native-standards', 0, 0, 30, '2026-03-08T01:57:15.512Z', '2026-03-08T02:10:27.968Z', 'dcfabb1cb94a9b924b35374b4211ec385e4640796233a806acc2ba855749d35b', '{"id":"armanisadeghi/matrx-platform/mobile-native-standards","name":"mobile-native-standards","description":{"en":"The mobile-native-standards skill ensures code adherence to mobile native template principles, benefiting developers creating UI components and screens. It proactively applies validation checks.","zh":"移动原生标准Enforcer是一种确保代码质量的工具，通过遵循核心原则，如无硬编码颜色、使用主题系统和安全区域处理","ja":"モバイルネイティブ標準Enforcerは、コード品質を確保するためのツールです。コア原則を遵守します。ハードコーディングされた色のない、テーマシステムの使用、および安全エリアの処理が含まれます","ko":"모바일 네이티브 표준 Enforcer는 코드 품질을 보장하는 도구입니다. 핵심 원칙을 준수합니다. 하드코딩된 색상이 없는 테마 시스템 사용 및 안전 영역 처리가 포함됩니다","es":"El estándar nativo móvil garantiza que el código se ajuste a los principios básicos de la plantilla móvil nativa, utilizando hooks como useTheme() y useSafeAreaInsets()","fr":"La norme native mobile garantit que le code respecte les principes de base du modèle mobile natif, en utilisant des hooks tels que useTheme() et useSafeAreaInsets()","de":"Der mobile Native-Standard stellt sicher, dass der Code den Grundprinzipien der mobilen Native-Vorlage entspricht, indem Hooks wie useTheme() und useSafeAreaInsets() verwendet werden","pt":"O Mobile Native Standards é uma habilidade que garante que todos os códigos adiram aos princípios básicos do template nativo móvel","ru":"ИИ Агенты для Mobile Native Standards - это навык, который обеспечивает соблюдение всех кодов основополагающих принципов родного мобильного шаблона","ar":"المعايير الأصلية للأجهزة المحمولة هي مهارة تضمن أن جميع الشفرات تتماشى مع المبادئ الأساسية للقالب الأصلي للأجهزة المحمولة"},"seo":{"title":{"en":"Mobile-Native-Standards: Enforcement Setup Guide | AI Age...","zh":"移动原生标准设置指南","ja":"モバイルネイティブ標準のベストプラクティス","ko":"모바일 네이티브 표준 구현 가이드","es":"Guía de configuración de estándares nativos móviles con A...","fr":"Configurer les normes natives mobiles avec l''outil AI","de":"Einrichtungsleitfaden für mobile Native-Standards mit KI-...","pt":"Guia de Configuração para Mobile Native Standards","ru":"Настройка ИИ Агентов для Mobile Native Standards","ar":"دليل إعداد معايير الأصل الأصلي للموبايل"},"description":{"en":"Discover how to enforce mobile-native standards in your UI code with this AI agent skill. Learn to validate your code with useTheme() and useSafeAreaInsets()...","zh":"使用移动原生标准Enforcer确保代码质量，遵循核心原则，包括无硬编码颜色、使用主题系统和安全区域处理","ja":"モバイルネイティブ標準Enforcerを使用してコード品質を確保し、コア原則を遵守します。ハードコーディングされた色のない、テーマシステムの使用、および安全エリアの処理が含まれます","ko":"모바일 네이티브 표준 Enforcer를 사용하여 코드 품질을 보장하고 핵심 원칙을 준수합니다. 하드코딩된 색상이 없는 테마 시스템 사용 및 안전 영역 처리가 포함됩니다","es":"Aprende a aplicar estándares nativos móviles en tu código con nuestra guía de validación y mejores prácticas para desarrolladores","fr":"Découvrez comment appliquer les normes natives mobiles dans votre code avec notre guide de validation et les meilleures pratiques pour les développeurs","de":"Erfahren Sie, wie Sie mobile Native-Standards in Ihrem Code anwenden können, mit unserer Validierungs- und Best-Practices-Anleitung für Entwickler","pt":"Aprenda a aplicar os padrões nativos móveis com validação de cores, tema e áreas seguras para um desenvolvimento de UI eficaz","ru":"Узнайте, как применять родные мобильные стандарты с проверкой цветов, тем и безопасных зон для эффективного развития UI","ar":"تعرف على كيفية تطبيق المعايير الأصلية للأجهزة المحمولة مع التحقق من الألوان والنظام والمناطق الآمنة من أجل تطوير واجهة المستخدم الفعال"},"definition":{"en":"mobile-native-standards is a set of guidelines ensuring all code follows core principles of mobile native templates, using hooks like useTheme() and useSafeAreaInsets() for consistency.","zh":"移动原生标准Enforcer是一种工具，确保代码遵循移动原生模板的核心原则","ja":"モバイルネイティブ標準Enforcerは、コードがモバイルネイティブテンプレートのコア原則に準拠することを保証するツールです","ko":"모바일 네이티브 표준 Enforcer는 코드가 모바일 네이티브 템플릿의 핵심 원칙을 준수하도록 보장하는 도구입니다","es":"Un estándar nativo móvil es un conjunto de reglas que garantizan la coherencia y la calidad del código en aplicaciones móviles","fr":"Une norme native mobile est un ensemble de règles qui garantissent la cohérence et la qualité du code dans les applications mobiles","de":"Ein mobile Native-Standard ist eine Reihe von Regeln, die die Konsistenz und Qualität des Codes in mobilen Anwendungen gewährleisten","pt":"O que é Mobile Native Standards? É uma habilidade que valida códigos para garantir a conformidade com os padrões nativos móveis","ru":"Что такое Mobile Native Standards? Это навык, который проверяет коды для обеспечения соответствия родным мобильным стандартам","ar":"ما هي معايير الأصل الأصلي للموبايل؟ هي مهارة تحقق من الشفرات لتضمن مطابقتها لمعايير الأجهزة المحمولة الأصلية"},"features":{"en":["Validates code against hardcoded colors and hex codes","Enforces use of theme system via useTheme() hook","Handles safe areas with useSafeAreaInsets() or layout components","Applies standards validation checklist for proactive code review","Supports explicit or mental validation checklist for developers"],"zh":["无硬编码颜色（hex代码或Tailwind颜色类）","使用主题系统via useTheme() hook","安全区域处理via useSafeAreaInsets()或layout组件"],"ja":["ハードコーディングされた色（hexコードまたはTailwind色クラス）なし","テーマシステムの使用via useTheme() hook","安全エリアの処理via useSafeAreaInsets()またはレイアウトコンポーネント"],"ko":["하드코딩된 색상이 없는（hex 코드 또는 Tailwind 색상 클래스）","테마 시스템 사용 via useTheme() hook","안전 영역 처리 via useSafeAreaInsets() 또는 레이아웃 컴포넌트"],"es":["Validación de colores sin codificar","Uso del sistema de temas con useTheme()","Gestión de áreas seguras con useSafeAreaInsets()","Compatibilidad con Tailwind CSS","Integración con componentes y pantallas personalizadas"],"fr":["Validation des couleurs non codées","Utilisation du système de thèmes avec useTheme()","Gestion des zones sûres avec useSafeAreaInsets()","Compatibilité avec Tailwind CSS","Intégration avec des composants et écrans personnalisés"],"de":["Validierung von nicht hartcodierten Farben","Verwendung des Themasystems mit useTheme()","Verwaltung von sicheren Bereichen mit useSafeAreaInsets()","Kompatibilität mit Tailwind CSS","Integration mit benutzerdefinierten Komponenten und Bildschirmen"],"pt":["Validação de cores para evitar códigos hexadecimais","Uso do sistema de tema via hook useTheme()","Manipulação de áreas seguras com useSafeAreaInsets() ou componente de layout"],"ru":["Проверка цветов для избежания кодов в шестнадцатеричном формате","Использование системы тем через хук useTheme()","Обработка безопасных зон с помощью useSafeAreaInsets() или компонента макета"],"ar":["التحقق من الألوان لتجنب Codes Hex","استخدام نظام المواضيع عبر hook useTheme()","تعامل مع المناطق الآمنة باستخدام useSafeAreaInsets() أو مكون التخطيط"]},"keywords":{"en":["how to use mobile-native-standards","what is mobile-native-standards","mobile-native-standards setup guide","mobile-native-standards enforcement","useTheme() hook implementation","useSafeAreaInsets() best practices","mobile native template principles"],"zh":["移动原生标准","AIエージェント","代码质量","核心原则","无硬编码颜色","主题系统","安全区域处理"],"ja":["モバイルネイティブ標準","AIエージェント","コード品質","コア原則","ハードコーディングされた色なし","テーマシステム","安全エリア処理"],"ko":["모바일 네이티브 표준","AI 에이전트","코드 품질","핵심 원칙","하드코딩된 색상 없음","테마 시스템","안전 영역 처리"],"es":["estándares nativos móviles","desarrollo de aplicaciones móviles","validación de código","useTheme()","useSafeAreaInsets()","Tailwind CSS","componentes personalizados","pantallas personalizadas"],"fr":["normes natives mobiles","développement d''applications mobiles","validation de code","useTheme()","useSafeAreaInsets()","Tailwind CSS","composants personnalisés","écrans personnalisés"],"de":["mobile Native-Standards","Entwicklung von mobilen Anwendungen","Code-Validierung","useTheme()","useSafeAreaInsets()","Tailwind CSS","benutzerdefinierte Komponenten","benutzerdefinierte Bildschirme"],"pt":["desenvolvimento de UI","padrões nativos móveis","validação de códigos","React"," Tailwind","useTheme()","useSafeAreaInsets()"],"ru":["разработка UI","родные мобильные стандарты","проверка кодов","React","Tailwind","useTheme()","useSafeAreaInsets()"],"ar":["تطوير واجهة المستخدم","معايير الأجهزة المحمولة الأصلية","التحقق من الشفرات","React","Tailwind","useTheme()","useSafeAreaInsets()"]}},"owner":"armanisadeghi","repo":"matrx-platform","repoPath":"armanisadeghi/matrx-platform","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.512Z","topics":[],"category":"community","skillMd":{"name":"mobile-native-standards","description":"Enforces mobile native template principles including no hardcoded colors, proper safe area handling, platform-specific implementations, centralized theming, and TypeScript strict mode. Use when creating components, reviewing code, editing files, or when violations of template standards might occur.","bodyPreview":"# Mobile Native Standards Enforcer\n\nThis skill ensures all code adheres to the mobile native template''s core principles. Apply these checks proactively when creating or modifying components, screens, or any UI code.\n\n## Before Making Changes\n\nRun this validation checklist mentally or explicitly:\n\n```\nStandards Validation:\n- [ ] No hardcoded colors (hex codes or Tailwind color classes)\n- [ ] Using theme system via useTheme() hook\n- [ ] Safe areas handled with useSafeAreaInsets() or layout compone","body":"# Mobile Native Standards Enforcer\n\nThis skill ensures all code adheres to the mobile native template''s core principles. Apply these checks proactively when creating or modifying components, screens, or any UI code.\n\n## Before Making Changes\n\nRun this validation checklist mentally or explicitly:\n\n```\nStandards Validation:\n- [ ] No hardcoded colors (hex codes or Tailwind color classes)\n- [ ] Using theme system via useTheme() hook\n- [ ] Safe areas handled with useSafeAreaInsets() or layout components\n- [ ] Platform-specific code uses correct patterns\n- [ ] TypeScript strict mode compliant (no ''any'' types)\n- [ ] Animations use Reanimated 4\n- [ ] Component is production-grade (if creating new component)\n```\n\n## Core Principle Enforcement\n\n### 1. Zero Hardcoded Colors\n\n**Rule**: Every color must come from the theme system.\n\n**Check for violations**:\n- Hex codes: `#000000`, `#FFFFFF`, `#FF5733`, etc.\n- RGB/RGBA values: `rgb(0,0,0)`, `rgba(255,255,255,0.5)`\n- Tailwind color classes: `bg-black`, `text-blue-500`, `border-red-600`\n- Named colors: `backgroundColor: ''red''`, `color: ''white''`\n\n**Correct pattern**:\n```typescript\nimport { useTheme } from ''@/hooks'';\n\nconst { colors } = useTheme();\n\n// For View/TouchableOpacity/Pressable\n<View style={{ backgroundColor: colors.background.primary }} />\n\n// For Text\n<Text style={{ color: colors.text.primary }} />\n\n// For borders\n<View style={{ borderColor: colors.border.default }} />\n```\n\n**Available theme colors** (check `constants/colors.ts` for complete list):\n- `colors.background.*` - primary, secondary, tertiary, elevated\n- `colors.text.*` - primary, secondary, tertiary, inverse\n- `colors.border.*` - default, subtle, emphasis\n- `colors.surface.*` - primary, secondary, overlay\n- `colors.accent.*` - primary, secondary, success, warning, error, info\n\n**If you see a violation**: Stop and refactor to use theme colors before proceeding.\n\n### 2. Safe Area Handling\n\n**Rule**: Never use deprecated `SafeAreaView` from `react-native`.\n\n**Check for violations**:\n```typescript\n// ❌ WRONG - deprecated\nimport { SafeAreaView } from ''react-native'';\n```\n\n**Correct patterns**:\n\n**Option A**: Use the hook (preferred for animations)\n```typescript\nimport { useSafeAreaInsets } from ''react-native-safe-area-context'';\n\nconst insets = useSafeAreaInsets();\n\n<View style={{ paddingTop: insets.top, paddingBottom: insets.bottom }}>\n  {/* content */}\n</View>\n```\n\n**Option B**: Use layout components\n```typescript\nimport { ScreenLayout } from ''@/components/layouts'';\n\n<ScreenLayout>\n  {/* content - safe areas handled automatically */}\n</ScreenLayout>\n```\n\n### 3. Platform-Specific Code\n\n**Rule**: Use correct patterns for platform differences.\n\n**For full component differences**, use file extensions:\n```\nComponent.ios.tsx      // iOS 26 Liquid Glass implementation\nComponent.android.tsx  // Android 16 Material 3 implementation  \nComponent.web.tsx      // Web fallback\nComponent.tsx          // Base/shared logic or type exports\n```\n\n**For minor differences**, use Platform module:\n```typescript\nimport { Platform } from ''react-native'';\n\nconst hitSlop = Platform.select({\n  ios: { top: 10, bottom: 10, left: 10, right: 10 },\n  android: 20,\n  default: 10\n});\n\n// Or conditional logic\nif (Platform.OS === ''ios'') {\n  // iOS-specific code\n} else if (Platform.OS === ''android'') {\n  // Android-specific code\n}\n```\n\n### 4. Animation Standards\n\n**Rule**: All animations must use Reanimated 4.\n\n**Check for violations**:\n- Using `Animated` from `react-native` (deprecated)\n- Using `LayoutAnimation` (unreliable)\n- CSS transitions on web that don''t work on native\n\n**Correct pattern**:\n```typescript\nimport Animated, { \n  FadeIn, \n  FadeOut, \n  SlideInRight,\n  useAnimatedStyle,\n  withTiming \n} from ''react-native-reanimated'';\n\n// Entering/exiting animations\n<Animated.View entering={FadeIn} exiting={FadeOut}>\n  {/* content */}\n</Animated.View>\n\n// Custom animations\nconst animatedStyle = useAnimatedStyle(() => ({\n  opacity: withTiming(isVisible ? 1 : 0)\n}));\n```\n\n### 5. TypeScript Strict Mode\n\n**Rule**: No `any` types. Use proper generics and type inference.\n\n**Check for violations**:\n```typescript\n// ❌ WRONG\nconst data: any = fetchData();\nfunction process(item: any) { }\n```\n\n**Correct patterns**:\n```typescript\n// ✅ Use proper types\ninterface User {\n  id: string;\n  name: string;\n}\n\nconst data: User[] = fetchData();\n\n// ✅ Use generics\nfunction process<T>(item: T): T {\n  return item;\n}\n\n// ✅ Use unknown for truly unknown types, then narrow\nconst data: unknown = fetchData();\nif (typeof data === ''object'' && data !== null) {\n  // Now you can safely access properties\n}\n```\n\n## Production-Grade Component Standards\n\nWhen creating a new component in `components/ui/`, it must meet ALL criteria:\n\n### Component Checklist\n\n```\nProduction Component Requirements:\n- [ ] Fully typed with TypeScript strict mode\n- [ ] Props interface exported and documented with JSDoc\n- [ ] Supports light/dark mode via useTheme()\n- [ ] Has variants (size, color, state) as needed\n- [ ] Works on iOS, Android, and web\n- [ ] Uses Reanimated 4 for animations\n- [ ] Handles accessibility (accessibilityLabel, accessibilityRole)\n- [ ] No hardcoded colors or spacing\n- [ ] Uses centralized spacing from constants/spacing.ts\n- [ ] Exported from components/ui/index.ts\n```\n\n### Component Template\n\nUse this structure for new components:\n\n```typescript\nimport React from ''react'';\nimport { View, Text, Pressable } from ''react-native'';\nimport { useTheme } from ''@/hooks'';\nimport { spacing } from ''@/constants'';\n\n/**\n * [Component description]\n * \n * @example\n * ```tsx\n * <YourComponent variant=\"primary\" size=\"medium\">\n *   Content\n * </YourComponent>\n * ```\n */\n\ninterface YourComponentProps {\n  /** Component children */\n  children?: React.ReactNode;\n  /** Visual variant */\n  variant?: ''primary'' | ''secondary'' | ''tertiary'';\n  /** Size variant */\n  size?: ''small'' | ''medium'' | ''large'';\n  /** Optional callback */\n  onPress?: () => void;\n}\n\nexport function YourComponent({\n  children,\n  variant = ''primary'',\n  size = ''medium'',\n  onPress,\n}: YourComponentProps) {\n  const { colors } = useTheme();\n  \n  // Calculate styles based on props\n  const backgroundColor = variant === ''primary'' \n    ? colors.accent.primary \n    : colors.background.secondary;\n    \n  const paddingSize = size === ''small'' \n    ? spacing.sm \n    : size === ''large'' \n    ? spacing.lg \n    : spacing.md;\n  \n  return (\n    <Pressable\n      onPress={onPress}\n      style={{\n        backgroundColor,\n        padding: paddingSize,\n        borderRadius: spacing.xs,\n      }}\n      accessibilityRole=\"button\"\n    >\n      <Text style={{ color: colors.text.primary }}>\n        {children}\n      </Text>\n    </Pressable>\n  );\n}\n```\n\n## Common Violations and Fixes\n\n### Violation: Hardcoded Black Background\n\n```typescript\n// ❌ WRONG\n<View style={{ backgroundColor: ''#000000'' }} />\n<View className=\"bg-black\" />\n\n// ✅ CORRECT\nconst { colors } = useTheme();\n<View style={{ backgroundColor: colors.background.primary }} />\n```\n\n### Violation: Using SafeAreaView from React Native\n\n```typescript\n// ❌ WRONG\nimport { SafeAreaView } from ''react-native'';\n\n<SafeAreaView>\n  <View>Content</View>\n</SafeAreaView>\n\n// ✅ CORRECT\nimport { useSafeAreaInsets } from ''react-native-safe-area-context'';\n\nconst insets = useSafeAreaInsets();\n\n<View style={{ paddingTop: insets.top }}>\n  <View>Content</View>\n</View>\n```\n\n### Violation: Any Type Usage\n\n```typescript\n// ❌ WRONG\nfunction handleData(data: any) {\n  console.log(data.name);\n}\n\n// ✅ CORRECT\ninterface Data {\n  name: string;\n}\n\nfunction handleData(data: Data) {\n  console.log(data.name);\n}\n```\n\n### Violation: Magic Numbers for Spacing\n\n```typescript\n// ❌ WRONG\n<View style={{ padding: 16, margin: 8 }} />\n\n// ✅ CORRECT\nimport { spacing } from ''@/constants'';\n\n<View style={{ padding: spacing.md, margin: spacing.sm }} />\n```\n\n### Violation: Using Animated from react-native\n\n```typescript\n// ❌ WRONG\nimport { Animated } from ''react-native'';\n\nconst fadeAnim = new Animated.Value(0);\n\n// ✅ CORRECT\nimport Animated, { FadeIn } from ''react-native-reanimated'';\n\n<Animated.View entering={FadeIn}>\n  {/* content */}\n</Animated.View>\n```\n\n## Enforcement Workflow\n\nWhen creating or modifying code:\n\n1. **Before writing**: Review relevant standards above\n2. **While writing**: Use theme system, proper imports, and types\n3. **After writing**: Run the validation checklist\n4. **If violations found**: Fix immediately before proceeding\n\n## Quick Reference\n\n**Colors**: `const { colors } = useTheme();`  \n**Safe Areas**: `const insets = useSafeAreaInsets();`  \n**Spacing**: `import { spacing } from ''@/constants'';`  \n**Platform**: `import { Platform } from ''react-native'';`  \n**Animation**: `import Animated, { FadeIn } from ''react-native-reanimated'';`\n\n## Philosophy Reminder\n\nThis template prioritizes:\n- **Native first**: iOS 26 Liquid Glass + Android 16 Material 3 Expressive\n- **No shortcuts**: Three platform implementations if needed\n- **Design system discipline**: Single source of truth for all styles\n\nEnforce these principles in every change.\n"},"lastSynced":"2026-03-08T02:10:27.968Z","agentAnalysis":{"suitability":{"en":"Perfect for UI-focused Agents needing adherence to mobile native template principles and proactive validation checks.","zh":"非常适合需要遵循移动原生模板原则和主动验证检查的UI专注代理","ja":"UI に焦点を当てたエージェントが、モバイル ネイティブ テンプレートの原則と積極的な検証チェックに従う必要がある場合に最適","ko":"모바일 네이티브 템플릿 원칙과 프로액티브 검증 검사에 대한 순응이 필요한 UI 중심 에이전트에게 적합","es":"Perfecto para Agentes enfocados en la interfaz de usuario que necesitan adherirse a los principios de plantillas nativas móviles y controles de validación proactivos.","fr":"Parfait pour les Agents axés sur l''interface utilisateur nécessitant l''adhésion aux principes de modèles natifs mobiles et des vérifications de validation proactives.","de":"Perfekt für benutzeroberflächenorientierte Agenten, die die Einhaltung der Prinzipien von mobilen Native-Vorlagen und proaktiven Validierungsprüfungen benötigen.","pt":"Perfeito para Agentes focados em UI que necessitam de aderência a princípios de modelo nativo móvel e verificações de validação proativas.","ru":"Идеально подходит для агентов, ориентированных на UI, которым необходимы соблюдение принципов шаблонов мобильных приложений и активные проверки валидации.","ar":"مثالي للوكلاء المعنيين بالواجهة المستخدمة الذين يحتاجون إلى الالتزام بمبادئ القوالب الأصلية للأجهزة المحمولة والتحقق الفعّال من الصحة."},"recommendation":{"en":"Empowers agents to enforce mobile-native-standards using theme systems via useTheme() hook, handling safe areas with useSafeAreaInsets() or layout components, and avoiding hardcoded colors by utilizing Tailwind color classes.","zh":"赋予代理人使用主题系统通过 useTheme() hook、使用 useSafeAreaInsets() 或布局组件处理安全区域以及通过利用 Tailwind 颜色类避免硬编码颜色的能力，以执行移动原生标准","ja":"useTheme() hook を使用したテーマ システム、useSafeAreaInsets() またはレイアウト コンポーネントを使用したセーフ エリアの処理、および Tailwind カラー クラスを使用したハード コーディングされたカラーの回避により、モバイル ネイティブ標準を実施するエージェントをエンパワーする","ko":"테마 시스템을 사용하여 useTheme() hook, useSafeAreaInsets() 또는 레이아웃 구성 요소를 사용하여 안전 영역을 처리하고 Tailwind 색상 클래스를 사용하여 하드 코딩된 색상을 피함으로써 모바일 네이티브 표준을 강제하는 에이전트에 대한 권한을 부여","es":"Habilita a los agentes a hacer cumplir los estándares nativos móviles utilizando sistemas de temas a través del hook useTheme(), manejo de áreas seguras con useSafeAreaInsets() o componentes de diseño, y evitando colores codificados de manera dura mediante las clases de color Tailwind.","fr":"Permet aux agents de faire respecter les normes mobiles natives en utilisant des systèmes de thèmes via l''hook useTheme(), en gérant les zones sécurisées avec useSafeAreaInsets() ou des composants de disposition, et en évitant les couleurs codées de manière rigide en utilisant les classes de couleur Tailwind.","de":"Ermächtigt Agenten, mobile Native-Standards mithilfe von Themasystemen über den Hook useTheme() durchzusetzen, sichere Bereiche mit useSafeAreaInsets() oder Layout-Komponenten zu handhaben und hartcodierte Farben durch Nutzung der Tailwind-Farbklassen zu vermeiden.","pt":"Habilita os agentes a impor padrões móveis nativos usando sistemas de tema via hook useTheme(), manipulando áreas seguras com useSafeAreaInsets() ou componentes de layout e evitando cores codificadas manualmente utilizando classes de cor do Tailwind.","ru":"Позволяет агентам реализовывать мобильные стандарты, используя системы тем через хук useTheme(), обрабатывая безопасные зоны с useSafeAreaInsets() или компонентами макета, и избегая жестко закодированных цветов, используя классы цвета Tailwind.","ar":"تمكّن الوكلاء من فرض معايير الأجهزة المحمولة الأصلية باستخدام أنظمة العناصر المظهرية عبر Hook useTheme()، وتحريك المناطق الآمنة مع useSafeAreaInsets() أو مكونات التصميم، وتجنب الألوان المبرمجة يدويًا من خلال استخدام فئات الألوان Tailwind."},"useCases":{"en":["Validating UI components against mobile native template principles","Automating checks for hardcoded colors and replacing with theme system alternatives","Generating mobile-native-compliant screens with safe area handling"],"zh":["验证 UI 组件是否符合移动原生模板原则","自动检查硬编码颜色并替换为主题系统的替代方案","生成具有安全区域处理的移动原生兼容屏幕"],"ja":["モバイル ネイティブ テンプレートの原則に従った UI コンポーネントの検証","ハード コーディングされたカラーの自動検出とテーマ システムの代替の置き換え","セーフ エリアの処理を備えたモバイル ネイティブ準拠画面の生成"],"ko":["모바일 네이티브 템플릿 원칙에 따라 UI 컴포넌트의 검증","하드 코딩된 색상의 자동 검사 및 테마 시스템의 대체 항목으로의 교체","안전 영역 처리가 포함된 모바일 네이티브 호환성 화면 생성"],"es":["Validar componentes de interfaz de usuario contra los principios de plantillas nativas móviles","Automatizar comprobaciones de colores codificados de manera dura y reemplazarlos con alternativas del sistema de temas","Generar pantallas compatibles con móviles nativos con control de áreas seguras"],"fr":["Valider les composants d''interface utilisateur par rapport aux principes de modèles natifs mobiles","Automatiser les vérifications de couleurs codées de manière rigide et les remplacer par des alternatives de système de thèmes","Générer des écrans compatibles avec les mobiles natifs avec une gestion des zones sécurisées"],"de":["Überprüfen von Benutzeroberflächenkomponenten gegen die Prinzipien von mobilen Native-Vorlagen","Automatisieren von Prüfungen auf hartcodierte Farben und Ersetzen durch Themasystemalternativen","Generieren von mobilen Native-kompatiblen Bildschirmen mit sicherer Bereichshandhabung"],"pt":["Validar componentes de UI contra princípios de modelo nativo móvel","Automatizar verificações de cores codificadas manualmente e substituí-las por alternativas do sistema de tema","Gerar telas compatíveis com padrões móveis nativos com tratamento de área segura"],"ru":["Проверять компоненты UI на соответствие принципам шаблонов мобильных приложений","Автоматизировать проверки жестко закодированных цветов и заменять их альтернативами системы тем","Генерировать экраны, соответствующие мобильным стандартам, с обработкой безопасных зон"],"ar":["التحقق من مكونات الواجهة المستخدمة مقابل مبادئ القوالب الأصلية للأجهزة المحمولة","تحسين التحقق من الألوان المبرمجة يدويًا واستبدالها ببدائل نظام العناصر المظهرية","إنتاج شاشات متوافقة مع المعايير الأصلية للأجهزة المحمولة مع معالجة المناطق الآمنة"]},"limitations":{"en":["Requires understanding of mobile native template principles","Limited to UI development and design","Needs integration with useTheme() hook and useSafeAreaInsets() or layout components"],"zh":["需要了解移动原生模板原则","仅限 UI 开发和设计","需要与 useTheme() hook 和 useSafeAreaInsets() 或布局组件集成"],"ja":["モバイル ネイティブ テンプレートの原則の理解が必要","UI 開発とデザインのみに限定","useTheme() hook および useSafeAreaInsets() またはレイアウト コンポーネントとの統合が必要"],"ko":["모바일 네이티브 템플릿 원칙에 대한 이해가 필요","UI 개발 및 디자인에만 한정","useTheme() hook 및 useSafeAreaInsets() 또는 레이아웃 구성 요소와의 통합이 필요"],"es":["Requiere comprensión de los principios de plantillas nativas móviles","Limitado al desarrollo y diseño de interfaz de usuario","Necesita integración con el hook useTheme() y useSafeAreaInsets() o componentes de diseño"],"fr":["Nécessite une compréhension des principes de modèles natifs mobiles","Limité au développement et à la conception d''interface utilisateur","Nécessite une intégration avec l''hook useTheme() et useSafeAreaInsets() ou des composants de disposition"],"de":["Benötigt Verständnis für die Prinzipien von mobilen Native-Vorlagen","Begrenzt auf die Entwicklung und das Design von Benutzeroberflächen","Benötigt Integration mit dem Hook useTheme() und useSafeAreaInsets() oder Layout-Komponenten"],"pt":["Exige compreensão dos princípios de modelo nativo móvel","Limitado ao desenvolvimento e design de UI","Necessita de integração com hook useTheme() e useSafeAreaInsets() ou componentes de layout"],"ru":["Требует понимания принципов шаблонов мобильных приложений","Ограничен разработкой и проектированием UI","Требует интеграции с хуком useTheme() и useSafeAreaInsets() или компонентами макета"],"ar":["يتطلب فهم مبادئ القوالب الأصلية للأجهزة المحمولة","محدود بالتطوير والتصميم الواجهة المستخدمة","يحتاج إلى التكامل مع Hook useTheme() و useSafeAreaInsets() أو مكونات التصميم"]},"version":4},"contentHash":"dcfabb1cb94a9b924b35374b4211ec385e4640796233a806acc2ba855749d35b","qualityScore":30}');
