INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('armanisadeghi/matrx-platform/mobile-native-standards', 'mobile-native-standards', 'armanisadeghi', 'matrx-platform', 'community', 'mobile-native-standards armanisadeghi matrx-platform community The mobile-native-standards skill ensures code adherence to mobile native template principles, benefiting developers creating UI components and screens. It proactively applies validation checks. 移动原生标准Enforcer是一种确保代码质量的工具，通过遵循核心原则，如无硬编码颜色、使用主题系统和安全区域处理 モバイルネイティブ標準Enforcerは、コード品質を確保するためのツールです。コア原則を遵守します。ハードコーディングされた色のない、テーマシステムの使用、および安全エリアの処理が含まれます 모바일 네이티브 표준 Enforcer는 코드 품질을 보장하는 도구입니다. 핵심 원칙을 준수합니다. 하드코딩된 색상이 없는 테마 시스템 사용 및 안전 영역 처리가 포함됩니다 El estándar nativo móvil garantiza que el código se ajuste a los principios básicos de la plantilla móvil nativa, utilizando hooks como useTheme() y useSafeAreaInsets() La norme native mobile garantit que le code respecte les principes de base du modèle mobile natif, en utilisant des hooks tels que useTheme() et useSafeAreaInsets() Der mobile Native-Standard stellt sicher, dass der Code den Grundprinzipien der mobilen Native-Vorlage entspricht, indem Hooks wie useTheme() und useSafeAreaInsets() verwendet werden O Mobile Native Standards é uma habilidade que garante que todos os códigos adiram aos princípios básicos do template nativo móvel ИИ Агенты для Mobile Native Standards - это навык, который обеспечивает соблюдение всех кодов основополагающих принципов родного мобильного шаблона المعايير الأصلية للأجهزة المحمولة هي مهارة تضمن أن جميع الشفرات تتماشى مع المبادئ الأساسية للقالب الأصلي للأجهزة المحمولة how to use mobile-native-standards what is mobile-native-standards mobile-native-standards setup guide mobile-native-standards enforcement useTheme() hook implementation useSafeAreaInsets() best practices mobile native template principles 移动原生标准 AIエージェント 代码质量 核心原则 无硬编码颜色 主题系统 安全区域处理 Validates code against hardcoded colors and hex codes Enforces use of theme system via useTheme() hook Handles safe areas with useSafeAreaInsets() or layout components Applies standards validation checklist for proactive code review Supports explicit or mental validation checklist for developers mobile-native-standards is a set of guidelines ensuring all code follows core principles of mobile native templates, using hooks like useTheme() and useSafeAreaInsets() for consistency.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ManuelKugelmann/BitBot/claude-get-session-info', 'community', 'ManuelKugelmann', 'BitBot', 'ManuelKugelmann/BitBot', 'claude-get-session-info', 0, 0, 30, '2026-03-08T01:57:15.551Z', '2026-03-08T02:11:28.472Z', '056a5fb7b7a2a1b62a3cb2268fb61c01e330e4780aeea8e100b53faf64bc50b3', '{"id":"ManuelKugelmann/BitBot/claude-get-session-info","name":"claude-get-session-info","description":{"en":"claude-get-session-info is a shared utility for session management, exporting CLAUDE_PID and SESSION_ID environment variables for AI agent development.","zh":"Claude 获取会话信息技能是共享的实用程序，用于会话管理，能够导出 CLAUDE_PID 和 SESSION_ID 环境变量","ja":"Claude セッション情報取得スキルは、セッション管理の共有ユーティリティで、CLAUDE_PID と SESSION_ID 環境変数をエクスポートします","ko":"Claude 세션 정보 가져오기 스킬은 세션 관리를 위한 공유 유틸리티로 CLAUDE_PID와 SESSION_ID 환경 변수를 내보냅니다","es":"claude-get-session-info es una utilidad compartida para la gestión de sesiones que exporta variables de entorno como CLAUDE_PID y SESSION_ID","fr":"claude-get-session-info est une utility partagée pour la gestion de sessions qui exporte des variables d''environnement comme CLAUDE_PID et SESSION_ID","de":"claude-get-session-info ist eine gemeinsam genutzte Utility für die Sitzungsverwaltung, die Umgebungsvariablen wie CLAUDE_PID und SESSION_ID exportiert","pt":"O claude-get-session-info é uma ferramenta de gerenciamento de sessão que exporta variáveis de ambiente CLAUDE_PID e SESSION_ID. Saiba como configurá-lo.","ru":"ИИ Агент claude-get-session-info - утилита для управления сессиями, которая экспортирует переменные среды CLAUDE_PID и SESSION_ID. Узнайте, как его настроить.","ar":"claude-get-session-info هو أداة لإدارة الجلسات التي تصدر متغيرات بيئة CLAUDE_PID و SESSION_ID. تعرف على كيفية إعدادها."},"seo":{"title":{"en":"claude-get-session-info: Session Management Setup Guide |...","zh":"Claude 获取会话信息 Setup Guide","ja":"Claude セッション情報取得 Best Practices","ko":"Claude 세션 정보 가져오기 개발자 가이드","es":"Guía de configuración de claude-get-session-info para age...","fr":"Guide de mise en place de claude-get-session-info pour le...","de":"Einrichtungsleitfaden für claude-get-session-info in der ...","pt":"Guia de Configuração do claude-get-session-info: Gerencia...","ru":"Настройка ИИ Агента claude-get-session-info: Утилита для ...","ar":"دليل إعداد claude-get-session-info: إدارة الجلسات"},"description":{"en":"Unlock efficient session management with claude-get-session-info. Learn how to invoke and utilize its capabilities for seamless AI agent integration.","zh":"了解如何使用 Claude 获取会话信息技能来管理会话并导出环境变量","ja":"Claude セッション情報取得スキルを使用してセッション管理を行い、環境変数をエクスポートしましょう","ko":"Claude 세션 정보 가져오기 스킬을 사용하여 세션 관리를 수행하고 환경 변수를 내보내는 방법을 알아보세요","es":"Aprende a utilizar claude-get-session-info para gestionar sesiones en tus proyectos de IA con este práctico tutorial","fr":"Découvrez comment utiliser claude-get-session-info pour gérer les sessions dans vos projets d''IA avec ce guide pratique","de":"Erfahren Sie, wie Sie claude-get-session-info für die Sitzungsverwaltung in Ihren KI-Projekten einsetzen können","pt":"Aprenda a configurar o claude-get-session-info para gerenciar sessões com eficiência. Veja como exportar variáveis de ambiente CLAUDE_PID e SESSION_ID.","ru":"Узнайте, как настроить ИИ Агент claude-get-session-info для управления сессиями. См. как экспортировать переменные среды CLAUDE_PID и SESSION_ID.","ar":"تعرف على كيفية إعداد claude-get-session-info لإدارة الجلسات بفعالية. انظر كيفية تصدير متغيرات البيئة CLAUDE_PID و SESSION_ID."},"definition":{"en":"claude-get-session-info is a utility skill for managing sessions, providing essential environment variables for AI agent scripts.","zh":"Claude 获取会话信息技能是一种用于管理会话的共享实用程序","ja":"Claude セッション情報取得スキルは、セッション管理のための共有ユーティリティです","ko":"Claude 세션 정보 가져오기 스킬은 세션 관리를 위한 공유 유틸리티입니다","es":"claude-get-session-info es una herramienta de IA para la gestión de sesiones","fr":"claude-ge