INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sf-bcca/ChoreWars/gamification-sim', 'gamification-sim', 'sf-bcca', 'ChoreWars', 'community', 'gamification-sim sf-bcca ChoreWars community The gamification-sim skill helps developers test gamification features by injecting specific data states into the database, ideal for AI agent applications. gamification-sim 是一个用于测试游戏化功能的工具，通过注入特定数据状态到数据库 gamification-sim は、データベースに特定のデータ状態を注入することでゲーム化機能をテストするツールです gamification-sim은 데이터베이스에 특정 데이터 상태를 주입하여 게임화 기능을 테스트하는 도구입니다 gamification-sim es una herramienta para probar características de gamificación con Node.js y scripts CLI. Permite inyectar escenarios personalizados en la base de datos. gamification-sim est un outil pour tester des fonctionnalités de gamification avec Node.js et des scripts CLI. Il permet d''injecter des scénarios personnalisés dans la base de données. gamification-sim ist ein Tool, um Gamification-Funktionen mit Node.js und CLI-Skripten zu testen. Es ermöglicht die Injection von benutzerdefinierten Szenarien in die Datenbank. O Gamification-Sim é uma ferramenta de desenvolvimento que simula funcionalidades de gamificação, permitindo testar cenários específicos ИИ Агент Gamification-Sim - это инструмент разработки, симулирующий функции геймификации, позволяющий тестировать конкретные сценарии Gamification-Sim هو أداة تطوير تمحاكي ميزات لعبة التميز، مما يسمح باختبار السيناريوهات المحددة how to use gamification-sim gamification-sim setup guide gamification-sim alternative what is gamification-sim gamification-sim vs other simulators install gamification-sim gamification-sim node scripts gamification-sim scenarios gamification-sim database injection gamification-sim AI 工具 游戏化功能 CLI 脚本 数据库状态注入 node.js clean-slate 场景 Injects specific scenarios into the database using node scripts Supports scenarios like competitive-family and clean-slate Resets to a clean state using the clean-slate scenario Utilizes bash commands for scenario execution, such as node gamification-sim/scripts/run_scenario.cjs References scenario details from scenarios.md file gamification-sim is a simulator that enables testing of gamification features through data state injection, supporting various scenarios.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MCZME/Genshin-Damage-calculation/skill-genshin-content-adder', 'community', 'MCZME', 'Genshin-Damage-calculation', 'MCZME/Genshin-Damage-calculation', 'skill-genshin-content-adder', 0, 0, 30, '2026-03-08T01:57:15.569Z', '2026-03-08T02:11:43.774Z', '5a6da68f8fc2d8fbcefeac5c481bd953d44a1e61cfcf9b716c75c60b13623c10', '{"id":"MCZME/Genshin-Damage-calculation/skill-genshin-content-adder","name":"skill-genshin-content-adder","description":{"en":"The skill-genshin-content-adder is designed for developers to automate Genshin content creation, ensuring accuracy through user-confirmed validation nodes. It benefits developers working with Genshin content by simplifying the data collection and verification process.","zh":"Genshin 内容添加器是一种通过分段确认制确保仿真精度的工具，开发过程中需严格遵循用户的人工验证节点","ja":"Genshin コンテンツ追加ツールは、分段確認方式によってシミュレーションの精度を確保するツールです。開発プロセスでは、ユーザーの手動検証ノードに従う必要があります","ko":"원신 콘텐츠 추가기는 분 段 확인 방식에 의하여 시뮬레이션의 精度를 보장하는 도구로, 개발 과정에서 사용자의 수동 검증 노드를 엄격히 따르なければ 않습니다","es":"El skill-genshin-content-adder es una herramienta de AI que permite a los desarrolladores agregar contenido de Genshin de manera automática. Utiliza Python y CLI para interactuar con los datos.","fr":"Le skill-genshin-content-adder est un outil d''IA qui permet aux développeurs d''ajouter du contenu Genshin de manière automatique. Il utilise Python et CLI pour interagir avec les données.","de":"Der skill-genshin-content-adder ist ein AI-Tool, das es Entwicklern ermöglicht, Genshin-Inhalt automatisch hinzuzufügen. Es verwendet Python und CLI, um mit den Daten zu interagieren.","pt":"O Skill Genshin Content Adder é uma ferramenta de automação que coleta dados e realiza verificação de base para garantir precisão","ru":"ИИ Агент Genshin Content Adder - это инструмент автоматизации, который собирает данные и выполняет базовую верификацию для обеспечения точности","