INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MCZME/Genshin-Damage-calculation/skill-genshin-content-adder', 'skill-genshin-content-adder', 'MCZME', 'Genshin-Damage-calculation', 'community', 'skill-genshin-content-adder MCZME Genshin-Damage-calculation community The skill-genshin-content-adder is designed for developers to automate Genshin content creation, ensuring accuracy through user-confirmed validation nodes. It benefits developers working with Genshin content by simplifying the data collection and verification process. Genshin 内容添加器是一种通过分段确认制确保仿真精度的工具，开发过程中需严格遵循用户的人工验证节点 Genshin コンテンツ追加ツールは、分段確認方式によってシミュレーションの精度を確保するツールです。開発プロセスでは、ユーザーの手動検証ノードに従う必要があります 원신 콘텐츠 추가기는 분 段 확인 방식에 의하여 시뮬레이션의 精度를 보장하는 도구로, 개발 과정에서 사용자의 수동 검증 노드를 엄격히 따르なければ 않습니다 El skill-genshin-content-adder es una herramienta de AI que permite a los desarrolladores agregar contenido de Genshin de manera automática. Utiliza Python y CLI para interactuar con los datos. Le skill-genshin-content-adder est un outil d''IA qui permet aux développeurs d''ajouter du contenu Genshin de manière automatique. Il utilise Python et CLI pour interagir avec les données. Der skill-genshin-content-adder ist ein AI-Tool, das es Entwicklern ermöglicht, Genshin-Inhalt automatisch hinzuzufügen. Es verwendet Python und CLI, um mit den Daten zu interagieren. O Skill Genshin Content Adder é uma ferramenta de automação que coleta dados e realiza verificação de base para garantir precisão ИИ Агент Genshin Content Adder - это инструмент автоматизации, который собирает данные и выполняет базовую верификацию для обеспечения точности أداة ذكاء اصطناعي Genshin Content Adder هي أداة آليّة لجمع البيانات والتحقق من الأساس لضمان الدقّة how to use skill-genshin-content-adder skill-genshin-content-adder setup guide genshin content automation skill-genshin-content-adder alternative skill-genshin-content-adder vs manual content creation automated data fetching for Genshin content Genshin 内容添加器 AI工具 分段确认制 自动化获取 物理数据交互 数据合并 结构化数据 开发流程优化 Runs fetch_content.py for automated data collection of attributes and multipliers Utilizes data.py for base stats and skill multipliers display and user confirmation Generates temp_frames.csv and temp_physics.csv templates for physics data entry Merges user-filled data into structured formats in data.py Employs a strict development flow with user-confirmed validation nodes skill-genshin-content-adder is a technical skill that automates the process of adding Genshin content through a segmented confirmation mechanism, ensuring high precision in content generation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yinijooy/safa/proofread', 'community', 'yinijooy', 'safa', 'yinijooy/safa', 'proofread', 0, 0, 30, '2026-03-08T01:57:15.589Z', '2026-03-08T02:12:01.025Z', '7c5e72a5c0ddd401b741a2c7fd7cb91108663d7101c3f7292c6102656f2da597', '{"id":"yinijooy/safa/proofread","name":"proofread","description":{"en":"The proofread skill reviews academic documents from a Nature reviewer''s perspective, assessing reproducibility, controls, and statistical appropriateness, benefiting researchers and authors.","zh":"proofread AI工具是一种用于学术文档评估的工具，能够从Nature审稿人的角度出发，评估文档的可复现性、对照组、样本大小/功率、统计适当性和验证等方面","ja":"proofread AIエージェントは、学術文書をNatureレビューアーの観点から評価するツールです。リプロジビリティ、コントロール、サンプルサイズ/パワー、統計的適切性、バリデーションなどの5つの側面で弱点を指摘します","ko":"proofread는 학술 문서를 Nature 리뷰어 관점에서 검토하고 평가하는 도구입니다. GitHub 파일 참조와 Methods/Results 섹션 평가를 통해 문서의 약점을 파악합니다","es":"La habilidad de proofread analiza documentos académicos desde la perspectiva de un revisor de Nature, evaluando la reproducibilidad y la estadística","fr":"La compétence de proofread analyse les documents universitaires du point de vue d''un réviseur de Nature, en évaluant la reproductibilité et les statistiques","de":"Die Fähigkeit zum proofread analysiert akademische Dokumente aus der Sicht eines Nature-Reviewers, indem sie die Reproduzierbarkeit und Statistik bewertet","pt":"O skill de revisão de textos avalia documentos acadêmicos do ponto de vista de um revisor da Nature, verificando a reproducibilidade e a adequação estatística.","ru":"Навык проверки текстов оценивает научные статьи с точки зрения рецензента Nature, проверяя воспроизводимость и статистическую обоснованность.","ar":"مهارة مراجعة النصوص تقييم الوثائق الأكاديمية من وجهة نظر مراجع الطبيعة، وتحقق من إمكانية إعادة الإنتاج والملاءمة الإحصائية."},"seo":{"title":{"en":"Proofread: AI-Powered Academic Review for GitHub Reposito...","zh":"AI工具proofread设置指南","ja":"AIエージェントproofreadベストプラクティス","ko":"proofread Setup Guide for GitHub 파일 검토","es":"Herramientas de revisión de texto: Guía de configuración ...","fr":"Outils d''agents IA pour la révision de texte: Guide de mi...","de":"AI-Tools für Textüberprüfung: Einrichtungsleitfaden für p...","pt":"Guia de Configuração de Ferramentas de Inteligência Artif...","ru":"Настройка ИИ Агентов для Проверки Текстов: Руководство","ar":"دليل إعداد أدوات ذكاء اصطناعي لمراجعة النصوص"},"description":{"en":"Unlock expert-level proofreading for your academic papers with this AI agent skill, evaluating Methods and Results sections for weaknesses and providing acti...","zh":"了解proofread AI工具的功能和特点，包括GitHub文件检索和Methods/Results 섹션评估","ja":"proofread AIエージェントの機能と特徴を紹介します。GitHubファイル参照とMethods/Resultsセクション評価を含みます","ko":"proofread Setup Guide에서 GitHub 파일 참조와 Methods/Results 섹션 평가를 수행하는 방법을 알아보세요","es":"Descubre cómo funciona la habilidad de proofread para revisar documentos académicos como un revisor de Nature, con análisis de reproducibilidad y estadísticas","fr":"Découvrez comment fonctionne la compétence de proofread pour examiner des documents universitaires comme un réviseur de Nature, avec analyse de reproductibil...","de":"Erfahren Sie, wie die Fähigkeit zum proofread funktioniert, um akademische Dokumente wie ein Nature-Reviewer zu überprüfen, mit Analysen zur Reproduzierbarke...","pt":"Aprenda a configurar ferramentas de inteligência artificial para revisão de textos acadêmicos como um revisor da Nature","ru":"Узнайте, как настроить ИИ Агенты для проверки текстов научных статей как рецензент Nature","ar":"تعلم كيفية إعداد أدوات ذكاء اصطناعي لمراجعة النصوص الأكاديمية مثل مراجع الطبيعة"},"definition":{"en":"Proofread is an AI-powered academic review skill that evaluates documents for weaknesses in Methods and Results sections, providing detailed feedback and improvement suggestions.","zh":"proofread AI工具是一种用于评估学术文档的可靠性和有效性的工具","ja":"proofread AIエージェントは、学術文書の信頼性と有効性を評価するツールです","ko":"proofread는 학술 문서의 신뢰성과 유효성을 평가하는 도구입니다","es":"Proofread es una habilidad de revisión de texto que evalúa documentos académicos como un revisor de Nature","fr":"Proofread est une compétence de révision de texte qui examine les documents universitaires comme un réviseur de Nature","de":"Proofread ist eine Fähigkeit zur Textüberprüfung, die akademische Dokumente wie ein Nature-Reviewer bewertet","pt":"Revisão de textos é um processo de avaliação de documentos acadêmicos por um revisor especializado.","ru":"Проверка текстов - это процесс оценки научных статей специализированным рецензентом.","ar":"مراجعة النصوص هي عملية تقييم الوثائق الأكاديمية من قبل مراجع متخصص."},"features":{"en":["Evaluates GitHub files and repositories for academic document review","Assesses Methods sections for weaknesses in 5 key areas: Reproducibility, Controls, Sample size/power, Statistical appropriateness, and Validation","Analyzes Results sections for Claim type, Evidence level, and Overclaiming risk","Provides actionable feedback and improvement suggestions for identified weaknesses","References detailed evaluation guides in reports/proofreading_guide.md"],"zh":["GitHub文件检索和代码/数据文件评估","Methods 섹션评估，包括可复现性、对照组、样本大小/功率、统计适当性和验证","Results 섹션评估，包括Claim type、Evidence level和Overclaiming risk分析","最危险的overclaim 3个指出和修改方法建议"],"ja":["GitHubファイル参照とコード/データファイル評価","Methodsセクション評価，包括リプロジビリティ、コントロール、サンプルサイズ/パワー、統計的適切性とバリデーション","Resultsセクション評価，包括Claim type、Evidence levelとOverclaiming risk分析","最も危険なoverclaim 3つを指摘し、修正方法を提案"],"ko":["GitHub 파일 참조와 코드/데이터 파일 검토","Methods 섹션 평가，包括 Reproducibility, Controls, Sample size/power, Statistical appropriateness, Validation","Results 섹션 평가，包括 Claim type, Evidence level, Overclaiming risk 분석","가장 위험한 overclaim 3개 지적 및 수정 방법 제시"],"es":["Análisis de reproducibilidad en GitHub","Evaluación de la sección Methods en 5 aspectos","Análisis de claims y evidencia en la sección Results","Identificación de overclaiming y sugerencias de mejora"],"fr":["Analyse de reproductibilité sur GitHub","Évaluation de la section Methods en 5 aspects","Analyse des claims et de la preuve dans la section Results","Identification de l''overclaiming et suggestions d''amélioration"],"de":["Analyse der Reproduzierbarkeit in GitHub","Bewertung des Abschnitts Methods in 5 Aspekten","Analyse von Claims und Beweisen im Abschnitt Results","Identifizierung von Overclaiming und Vorschläge zur Verbesserung"],"pt":["Avaliação da seção de métodos em 5 aspectos","Análise da seção de resultados para identificar riscos de overclaiming","Verificação da reproducibilidade e da adequação estatística","Revisão de código e dados em repositórios GitHub","Sugestões de melhoria para os autores"],"ru":["Оценка раздела методов в 5 аспектах","Анализ раздела результатов для выявления рисков overclaiming","Проверка воспроизводимости и статистической обоснованности","Проверка кода и данных в репозиториях GitHub","Предложения по улучшению для авторов"],"ar":["تقييم قسم الطرق في 5 جوانب","تحليل قسم النتائج لتحديد مخاطر المطالبة المفرطة","تحقق من إمكانية إعادة الإنتاج والملاءمة الإحصائية","مراجعة الشفرة والبيانات في مستودعات GitHub","اقتراحات تحسين للكتاب"]},"keywords":{"en":["how to use proofread for academic papers","what is proofread skill","proofread alternative for researchers","proofread vs human reviewers","proofread install guide for GitHub","proofread setup for AI-powered review","academic paper review with AI","Nature-style review for researchers","proofread for reproducibility and validation"],"zh":["AI工具proofread","学术文档评估","GitHub文件检索","Methods 섹션评估","Results 섹션评估","overclaiming risk分析"],"ja":["AIエージェントproofread","学術文書評価","GitHubファイル参照","Methodsセクション評価","Resultsセクション評価","overclaiming risk分析"],"ko":["proofread Setup Guide","학술 문서 검토","GitHub 파일 참조","Methods 섹션 평가","Results 섹션 평가","overclaiming risk 분석"],"es":["herramientas de revisión de texto","proofread","revisión de documentos académicos","análisis de reproducibilidad","evaluación de estadísticas","GitHub","Nature","revisores de texto"],"fr":["outils de révision de texte","proofread","examen de documents universitaires","analyse de reproductibilité","évaluation de statistiques","GitHub","Nature","réviseurs de texte"],"de":["AI-Tools für Textüberprüfung","proofread","Überprüfung akademischer Dokumente","Analyse der Reproduzierbarkeit","Bewertung von Statistiken","GitHub","Nature","Textüberprüfung"],"pt":["revisão de textos","ferramentas de inteligência artificial","revisão de artigos acadêmicos"," Nature","repositorios GitHub","análise de dados","estatística","reproducibilidade"],"ru":["проверка текстов","ИИ Агенты","научные статьи","Nature","репозитории GitHub","анализ данных","статистика","воспроизводимость"],"ar":["مراجعة النصوص","أدوات ذكاء اصطناعي","مراجعة المقالات الأكاديمية","الطبيعة","مستودعات GitHub","تحليل البيانات","إحصاء","إمكانية إعادة الإنتاج"]}},"owner":"yinijooy","repo":"safa","repoPath":"yinijooy/safa","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.589Z","topics":[],"category":"community","skillMd":{"name":"proofread","description":"학술 문서를 검토하고 평가합니다. 프루프리딩, proofread, 논문 검토, Methods 평가, Results 평가, overclaim 분석 요청 시 사용.","bodyPreview":"# Proofreading Skill\n\n학술 문서를 Nature 리뷰어 관점에서 검토하고 평가합니다.\n\n> 모든 상세 내용은 `reports/proofreading_guide.md` 참조\n\n---\n\n## 동작 순서\n\n1. **GitHub 파일 참조** (필요시)\n   - 사용자가 제공한 GitHub 링크에서 원본 문서 확인\n   - 관련 코드/데이터 파일 검토\n\n2. **Methods 섹션 평가**\n   - 5가지 측면에서 약점 지적: Reproducibility, Controls, Sample size/power, Statistical appropriateness, Validation\n   - 각 약점에 대해: 구체적 문제점, 리뷰어 예상 질문, 개선 방안 제시\n\n3. **Results 섹션 평가**\n   - 각 문장별 Claim type, Evidence level, Overclaiming risk 분석\n   - 가장 위험한 overclaim 3개 지적 및 수정 방법 제시\n\n4.","body":"# Proofreading Skill\n\n학술 문서를 Nature 리뷰어 관점에서 검토하고 평가합니다.\n\n> 모든 상세 내용은 `reports/proofreading_guide.md` 참조\n\n---\n\n## 동작 순서\n\n1. **GitHub 파일 참조** (필요시)\n   - 사용자가 제공한 GitHub 링크에서 원본 문서 확인\n   - 관련 코드/데이터 파일 검토\n\n2. **Methods 섹션 평가**\n   - 5가지 측면에서 약점 지적: Reproducibility, Controls, Sample size/power, Statistical appropriateness, Validation\n   - 각 약점에 대해: 구체적 문제점, 리뷰어 예상 질문, 개선 방안 제시\n\n3. **Results 섹션 평가**\n   - 각 문장별 Claim type, Evidence level, Overclaiming risk 분석\n   - 가장 위험한 overclaim 3개 지적 및 수정 방법 제시\n\n4. **종합 프루프리딩**\n   - 평가 결과 통합\n   - 수정 사항 도출\n   - 최종 권고안 작성\n\n---\n\n## Methods 평가 프롬프트\n\n```\n다음 Methods 섹션을 Nature 리뷰어 관점에서 평가해줘:\n\n[Methods text]\n\n다음 5가지 측면에서 약점을 지적:\n1. Reproducibility (재현성)\n2. Controls (통제)\n3. Sample size/power (샘플/검정력)\n4. Statistical appropriateness (통계 적절성)\n5. Validation (타당성)\n\n각 약점에 대해:\n- 구체적 문제점\n- 리뷰어가 제기할 질문\n- 개선 방안\n```\n\n---\n\n## Results 평가 프롬프트\n\n```\n다음 Results 문장들을 분석해줘:\n\n[Results text]\n\n각 문장에 대해:\n1. Claim type (causal/correlational/mechanistic/general)\n2. Evidence level (direct/indirect/suggestive)\n3. Overclaiming risk (1-10)\n4. Conservative alternative phrasing\n\n그리고:\n- 가장 위험한 overclaim 3개 지적\n- 각각을 데이터에 맞게 수정하는 방법\n```\n\n---\n\n## 참고\n\n> 평가 기준, 출력 템플릿, 참고 문서 목록은 모두 `reports/proofreading_guide.md` 참조\n"},"lastSynced":"2026-03-08T02:12:01.025Z","agentAnalysis":{"suitability":{"en":"Perfect for Research Assist Agents needing advanced academic document review capabilities.","zh":"适合需要高级学术文档审查能力的研究助理代理","ja":"高度な学術文書のレビュー機能が必要な研究アシスタントエージェントに適しています","ko":"고급 학술 문서 검토 기능이 필요한 연구 보조 에이전트에 적합합니다","es":"Perfecto para Agentes de Asistencia de Investigación que necesitan capacidades avanzadas de revisión de documentos académicos.","fr":"Parfait pour les Agents d''Assistance de Recherche ayant besoin de capacités avancées de révision de documents académiques.","de":"Perfekt für Forschungs-Assistenten-Agenten, die erweiterte akademische Dokumenten-Überprüfungsfunktionen benötigen.","pt":"Perfeito para Agentes de Assistência à Pesquisa que necessitam de capacidades avançadas de revisão de documentos acadêmicos.","ru":"Идеально подходит для Исследовательских Агентов, которым необходимы продвинутые возможности проверки академических документов.","ar":"مثالي لوكلاء المساعدة البحثية الذين يحتاجون إلى قدرات متقدمة لمراجعة الوثائق الأكاديمية."},"recommendation":{"en":"Empowers agents to assess reproducibility, evaluate statistical appropriateness, and identify overclaiming risks in academic documents using methods like controls and validation, while referencing GitHub files and code.","zh":"赋予代理评估学术文档的可复制性、评估统计学的适当性、并识别过度声明风险，方法如控制和验证，同时引用GitHub文件和代码","ja":"エージェントに学術文書の再現性を評価し、統計学的適切性を評価し、過度の主張のリスクを特定することを可能にし、GitHubのファイルやコードを参照しながら、手法としての制御や検証を行う","ko":"에이전트가 학술 문서의 재현 가능성을 평가하고 통계적 적절성을 평가하며 과대 선언 위험을 식별 할 수 있도록 하며 GitHub 파일 및 코드를 참조 하면서 제어 및 검증과 같은 방법을 사용함으로써 에이전트를 강화합니다","es":"Habilita a los agentes a evaluar la reproducibilidad, evaluar la idoneidad estadística y identificar riesgos de sobredeclaración en documentos académicos utilizando métodos como controles y validación, mientras se hace referencia a archivos y código de GitHub.","fr":"Permet aux agents d''évaluer la reproductibilité, d''évaluer l''adéquation statistique et d''identifier les risques de surdéclaration dans les documents académiques en utilisant des méthodes telles que les contrôles et la validation, tout en référençant des fichiers et du code GitHub.","de":"Ermächtigt Agenten, die Reproduzierbarkeit zu bewerten, die statistische Angemessenheit zu bewerten und Überbeanspruchungsrisiken in akademischen Dokumenten mit Methoden wie Kontrollen und Validierung zu identifizieren, während auf GitHub-Dateien und -Code verwiesen wird.","pt":"Habilita os agentes a avaliar a reprodutibilidade, avaliar a adequação estatística e identificar riscos de superdeclaração em documentos acadêmicos usando métodos como controles e validação, enquanto referencia arquivos e códigos do GitHub.","ru":"Наделяет агентов возможностью оценивать воспроизводимость, оценивать статистическую адекватность и выявлять риски завышенных претензий в академических документах с помощью методов, таких как контроль и проверка, при этом ссылаясь на файлы и код GitHub.","ar":"يمكن الوكلاء من تقييم إمكانية التكرار وتقييم الملاءمة الإحصائية وتحديد مخاطر المطالبات المفرطة في الوثائق الأكاديمية باستخدام طرق مثل التحكم والتحقق، مع الإشارة إلى ملفات GitHub والكود."},"useCases":{"en":["Evaluating Methods sections for reproducibility and statistical appropriateness","Analyzing Results sections for claim types, evidence levels, and overclaiming risks","Generating detailed feedback reports for authors, including specific problems and improvement suggestions"],"zh":["评估方法部分的可复制性和统计学的适当性","分析结果部分的声明类型、证据级别和过度声明风险","为作者生成详细的反馈报告，包括具体问题和改进建议"],"ja":["方法のセクションの再現性と統計学的適切性を評価する","結果のセクションの主張の種類、証拠のレベル、過度の主張のリスクを分析する","著者への詳細なフィードバックレポートを生成する、具体的な問題と改善の提案を含む"],"ko":["방법 섹션의 재현 가능성 및 통계적 적절성을 평가합니다","결과 섹션의 주장 유형, 증거 수준 및 과대 선언 위험을 분석합니다","저자에게 자세한 피드백 보고서를 생성하여 구체적인 문제 및 개선 제안을 포함합니다"],"es":["Evaluar secciones de Métodos para reproducibilidad y idoneidad estadística","Analizar secciones de Resultados para tipos de afirmaciones, niveles de evidencia y riesgos de sobredeclaración","Generar informes de retroalimentación detallados para autores, incluyendo problemas específicos y sugerencias de mejora"],"fr":["Évaluer les sections Méthodes pour la reproductibilité et l''adéquation statistique","Analyser les sections Résultats pour les types d''affirmations, les niveaux de preuve et les risques de surdéclaration","Générer des rapports de rétroaction détaillés pour les auteurs, incluant des problèmes spécifiques et des suggestions d''amélioration"],"de":["Bewerten von Methodenabschnitten für Reproduzierbarkeit und statistische Angemessenheit","Analysieren von Ergebnisabschnitten für Anspruchstypen, Evidenzniveaus und Überbeanspruchungsrisiken","Erstellen detaillierter Feedback-Berichte für Autoren, einschließlich spezifischer Probleme und Verbesserungsvorschläge"],"pt":["Avaliando seções de Métodos para reprodutibilidade e adequação estatística","Analysando seções de Resultados para tipos de afirmações, níveis de evidência e riscos de superdeclaração","Gerando relatórios de feedback detalhados para autores, incluindo problemas específicos e sugestões de melhoria"],"ru":["Оценка разделов Методов для воспроизводимости и статистической адекватности","Анализ разделов Результатов для типов утверждений, уровней доказательств и рисков завышенных претензий","Генерация подробных отчетов обратной связи для авторов, включая конкретные проблемы и предложения по улучшению"],"ar":["تقييم أقسام الطرق من أجل إمكانية التكرار والملاءمة الإحصائية","تحليل أقسام النتائج لأنواع الادعاءات ومستويات الأدلة ومخاطر المطالبات المفرطة","генерация تقارير مفصلة لتغذية الرجعة للمؤلفين، بما في ذلك مشاكل محددة ومقترحات لتحسين"]},"limitations":{"en":["Requires access to academic documents, potentially via GitHub links","Limited to assessing documents from a Nature reviewer''s perspective"],"zh":["需要访问学术文档，可能通过GitHub链接","仅限从Nature审稿人的角度评估文档"],"ja":["学術文書へのアクセスが必要であり、GitHubリンクを介してアクセスする可能性があります","Natureのレビューアーの観点から文書を評価することのみに限定されます"],"ko":["학술 문서에 액세스해야 하며 GitHub 링크를 통해 액세스 할 수 있습니다","네이처 리뷰어의 관점에서 문서를 평가하는 것만으로 제한됩니다"],"es":["Requiere acceso a documentos académicos, potencialmente a través de enlaces de GitHub","Limitado a evaluar documentos desde la perspectiva de un revisor de Nature"],"fr":["Nécessite un accès aux documents académiques, potentiellement via des liens GitHub","Limité à l''évaluation de documents du point de vue d''un réviseur de Nature"],"de":["Benötigt Zugriff auf akademische Dokumente, potenziell über GitHub-Links","Begrenzt auf die Bewertung von Dokumenten aus der Perspektive eines Nature-Reviewers"],"pt":["Requer acesso a documentos acadêmicos, potencialmente via links do GitHub","Limitado a avaliar documentos de uma perspectiva de revisor da Nature"],"ru":["Требует доступа к академическим документам, потенциально через ссылки GitHub","Ограничен оценкой документов с точки зрения рецензента Nature"],"ar":["يتطلب الوصول إلى الوثائق الأكاديمية، ربما عبر روابط GitHub","محدود بالتقدير الوثائق من منظور مراجع في Nature"]},"version":4},"contentHash":"7c5e72a5c0ddd401b741a2c7fd7cb91108663d7101c3f7292c6102656f2da597"