INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yinijooy/safa/proofread', 'proofread', 'yinijooy', 'safa', 'community', 'proofread yinijooy safa community The proofread skill reviews academic documents from a Nature reviewer''s perspective, assessing reproducibility, controls, and statistical appropriateness, benefiting researchers and authors. proofread AI工具是一种用于学术文档评估的工具，能够从Nature审稿人的角度出发，评估文档的可复现性、对照组、样本大小/功率、统计适当性和验证等方面 proofread AIエージェントは、学術文書をNatureレビューアーの観点から評価するツールです。リプロジビリティ、コントロール、サンプルサイズ/パワー、統計的適切性、バリデーションなどの5つの側面で弱点を指摘します proofread는 학술 문서를 Nature 리뷰어 관점에서 검토하고 평가하는 도구입니다. GitHub 파일 참조와 Methods/Results 섹션 평가를 통해 문서의 약점을 파악합니다 La habilidad de proofread analiza documentos académicos desde la perspectiva de un revisor de Nature, evaluando la reproducibilidad y la estadística La compétence de proofread analyse les documents universitaires du point de vue d''un réviseur de Nature, en évaluant la reproductibilité et les statistiques Die Fähigkeit zum proofread analysiert akademische Dokumente aus der Sicht eines Nature-Reviewers, indem sie die Reproduzierbarkeit und Statistik bewertet O skill de revisão de textos avalia documentos acadêmicos do ponto de vista de um revisor da Nature, verificando a reproducibilidade e a adequação estatística. Навык проверки текстов оценивает научные статьи с точки зрения рецензента Nature, проверяя воспроизводимость и статистическую обоснованность. مهارة مراجعة النصوص تقييم الوثائق الأكاديمية من وجهة نظر مراجع الطبيعة، وتحقق من إمكانية إعادة الإنتاج والملاءمة الإحصائية. how to use proofread for academic papers what is proofread skill proofread alternative for researchers proofread vs human reviewers proofread install guide for GitHub proofread setup for AI-powered review academic paper review with AI Nature-style review for researchers proofread for reproducibility and validation AI工具proofread 学术文档评估 GitHub文件检索 Methods 섹션评估 Results 섹션评估 overclaiming risk分析 Evaluates GitHub files and repositories for academic document review Assesses Methods sections for weaknesses in 5 key areas: Reproducibility, Controls, Sample size/power, Statistical appropriateness, and Validation Analyzes Results sections for Claim type, Evidence level, and Overclaiming risk Provides actionable feedback and improvement suggestions for identified weaknesses References detailed evaluation guides in reports/proofreading_guide.md Proofread is an AI-powered academic review skill that evaluates documents for weaknesses in Methods and Results sections, providing detailed feedback and improvement suggestions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('heyhey1007/Article/new-article', 'community', 'heyhey1007', 'Article', 'heyhey1007/Article', 'new-article', 0, 0, 30, '2026-03-08T01:57:15.592Z', '2026-03-08T02:12:03.309Z', 'c66caaa036f08dd3b846fa15ecd3b095259361e2d9b5367022278bc84ccc861f', '{"id":"heyhey1007/Article/new-article","name":"new-article","description":{"en":"The new-article skill creates new article files for Zenn and Qiita platforms based on user requests. It utilizes a bash script to generate articles with specified titles and platforms.","zh":"新規記事作成スキル是一种创建新文章文件的工具，支持Zenn和Qiita平台","ja":"新規記事作成スキルは、ZennとQiita両対応の記事ファイルを作成するためのツールです","ko":"새로운 기사 작성 스킬은 Zenn과 Qiita에 적합한 기사 파일을 생성하는 도구입니다","es":"new-article es una herramienta de AI que crea archivos de artículo para Zenn y Qiita utilizando CLI.","fr":"new-article est un outil d''IA qui crée des fichiers d''article pour Zenn et Qiita à l''aide de CLI.","de":"new-article ist ein KI-Tool, das Artikel-Dateien für Zenn und Qiita mit CLI erstellt.","pt":"O new-article é um skill que cria artigos para Zenn e Qiita. Aprenda a configurá-lo e criar artigos com facilidade","ru":"ИИ Агент new-article - это скилл, который создает статьи для Zenn и Qiita. Узнайте, как его настроить и создать статьи","ar":"جديد-مقال هو مهارة تقوم بإنشاء مقالات لمنصات Zenn و Qiita. تعلم كيفية إعدادها وإنشاء مقالات بسهولة"},"seo":{"title":{"en":"new-article: Automated Article Creation Setup Guide | AI ...","zh":"新規記事作成スキル_setup_guide","ja":"新規記事作成スキル_Setup_Guide","ko":"새로운_기사_작성_스킬_설치_가이드","es":"Guía de Configuración de new-article: Creación de Artícul...","fr":"Guide d''Installation de new-article: Création d''Articles ...","de":"Einrichtungsleitfaden für new-article: Artikel-Erstellung...","pt":"Guia de Configuração do new-article: Crie Artigos com Fer...","ru":"Настройка ИИ Агента new-article: Создание Статей с Помощь...","ar":"دليل إعداد جديد-مقال: إنشاء مقالات باستخدام أدوات الإي ال..."},"description":{"en":"Discover how to automate article creation with new-article skill. Learn to generate articles for Zenn and Qiita platforms using a simple bash script.","zh":"使用新規記事作成スキル创建适合Zenn和Qiita的文章文件，了解如何使用CLI脚本","ja":"新規記事作成スキルを使用してZennとQiita両対応の記事ファイルを作成する方法を学ぶ","ko":"새로운 기사 작성 스킬을 사용하여 Zenn과 Qiita에 적합한 기사 파일을 생성하는 방법을 알아보세요","es":"Aprende a crear artículos con new-article, una herramienta de AI que utiliza CLI para generar archivos de artículo para Zenn y Qiita.","fr":"Découvrez comment créer des articles avec new-article, un outil d''IA qui utilise CLI pour générer des fichiers d''article pour Zenn et Qiita.","de":"Erfahren Sie, wie Sie mit new-article, einem KI-Tool, das CLI verwendet, um Artikel-Dateien für Zenn und Qiita zu erstellen.","pt":"Aprenda a configurar o new-article e criar artigos para Zenn e Qiita com nosso guia passo a passo","ru":"Узнайте, как настроить ИИ Агент new-article и создать статьи для Zenn и Qiita с нашей пошаговой инструкцией","ar":"تعلم كيفية إعداد جديد-مقال وإنشاء مقالات لمنصات Zenn و Qiita باستخدام دليلنا خطوة بخطوة"},"definition":{"en":"new-article is a skill that automates the creation of new article files for Zenn and Qiita platforms using a bash script.","zh":"新規記事作成スキル是一种使用CLI脚本创建新文章文件的工具","ja":"新規記事作成スキルは、CLIスクリプトを使用して新規記事ファイルを作成するツールです","ko":"새로운 기사 작성 스킬은 CLI 스크립트를 사용하여 새로운 기사 파일을 생성하는 도구입니다","es":"new-article es una herramienta de AI que automatiza la creación de artículos para plataformas como Zenn y Qiita.","fr":"new-article est un outil d''IA qui automatise la création d''articles pour des plateformes comme Zenn et Qiita.","de":"new-article ist ein KI-Tool, das die Erstellung von Artikeln für Plattformen wie Zenn und Qiita automatisiert.","pt":"O new-article é um skill de AI que cria artigos para plataformas de compartilhamento de conhecimento","ru":"ИИ Агент new-article - это скилл, который создает статьи для платформ обмена знаниями","ar":"جديد-مقال هو مهارة الإي الأجنت التي تقوم بإنشاء مقالات لمنصات مشاركة المعرفة"},"features":{"en":["Generates article files using a bash script with the ./scripts/new-article.sh command","Supports creation of articles for both Zenn and Qiita platforms","Allows specification of article title using the --title parameter","Supports selection of platform using the --platform parameter with options zenn or qiita","Enables selection of article type using the --type parameter with options tech or idea"],"zh":["支持Zenn和Qiita平台","使用CLI脚本创建新文章文件","可指定文章标题和类型","支持tech和idea两种文章类型"],"ja":["ZennとQiita両対応","CLIスクリプトを使用して新規記事ファイルを作成","記事タイトルとタイプを指定可能","techとideaの2種類の記事タイプをサポート"],"ko":["Zenn과 Qiita 플랫폼 지원","CLI 스크립트를 사용하여 새로운 기사 파일을 생성","기사 제목과 유형을 지정할 수 있음","tech와 idea 두 가지 기사 유형을 지원"],"es":["Creación de archivos de artículo para Zenn y Qiita","Uso de CLI para generar archivos de artículo","Compatibilidad con diferentes plataformas","Opción para seleccionar el tipo de artículo","Soporte para títulos personalizados"],"fr":["Création de fichiers d''article pour Zenn et Qiita","Utilisation de CLI pour générer des fichiers d''article","Compatibilité avec différentes plateformes","Option pour sélectionner le type d''article","Prise en charge de titres personnalisés"],"de":["Erstellung von Artikel-Dateien für Zenn und Qiita","Verwendung von CLI zur Generierung von Artikel-Dateien","Kompatibilität mit verschiedenen Plattformen","Option zur Auswahl des Artikeltyps","Unterstützung für benutzerdefinierte Titel"],"pt":["Cria artigos para Zenn e Qiita","Suporte a diferentes plataformas","Opção de escolher o tipo de artigo (tech ou idea)","Script de criação de artigos em bash","Parâmetros personalizáveis para título e plataforma"],"ru":["Создает статьи для Zenn и Qiita","Поддержка разных платформ","Возможность выбора типа статьи (tech или idea)","Скрипт создания статей на bash","Параметры для настройки названия и платформы"],"ar":["ينشئ مقالات لمنصات Zenn و Qiita","دعم لمنصات مختلفة","خيار اختيار نوع المقال (tech أو idea)","سครبت إنشاء المقالات في bash","معلمات قابلة للتعديل للعنوان والمنصة"]},"keywords":{"en":["how to use new-article","new-article setup guide","new-article alternative","new-article vs article generator","automated article creation","zenn article creation","qiita article creation","new-article install","bash script for article creation"],"zh":["新規記事作成スキル","CLI脚本","Zenn","Qiita","文章文件创建","AIエージェント","技术博客"],"ja":["新規記事作成スキル","CLIスクリプト","Zenn","Qiita","記事ファイル作成","AIエージェント","テクニカルブログ"],"ko":["새로운 기사 작성 스킬","CLI 스크립트","Zenn","Qiita","기사 파일 생성","AI 에이전트","기술 블로그"],"es":["herramientas de AI para escritores","creación de artículos con CLI","Zenn y Qiita","automatización de contenido","new-article","herramientas de productividad para escritores","generación de artículos","CLI para escritores"],"fr":["outils d''IA pour écrivains","création d''articles avec CLI","Zenn et Qiita","automatisation de contenu","new-article","outils de productivité pour écrivains","génération d''articles","CLI pour écrivains"],"de":["KI-Tools für Schriftsteller","Erstellung von Artikeln mit CLI","Zenn und Qiita","Automatisierung von Inhalten","new-article","Produktivitätstools für Schriftsteller","Generierung von Artikeln","CLI für Schriftsteller"],"pt":["new-article","AI Agente","criar artigos","Zenn","Qiita","script bash","parâmetros personalizáveis","tipo de artigo","plataformas de compartilhamento de conhecimento"],"ru":["ИИ Агент new-article","создание статей","Zenn","Qiita","скрипт bash","параметры для настройки","тип статьи","платформы обмена знаниями","ИИ инструменты"],"ar":["جديد-مقال","أدوات الإي الأجنت","إنشاء مقالات","Zenn","Qiita","سكربت bash","معلمات قابلة للتعديل","نوع المقال","منصات مشاركة المعرفة","أدوات الإي"]}},"owner":"heyhey1007","repo":"Article","repoPath":"heyhey1007/Article","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.592Z","topics":[],"category":"community","skillMd":{"name":"new-article","description":"|","bodyPreview":"# 新規記事作成スキル\n\n新規記事ファイルを作成します（Zenn/Qiita両対応）。\n\n## タスク\n\nユーザーのリクエストに基づいて、適切なプラットフォーム用の記事ファイルを作成してください。\n\n## 実行方法\n\n以下のスクリプトを使用して記事を作成します：\n\n```bash\n./scripts/new-article.sh --title \"<タイトル>\" [オプション]\n```\n\n## パラメータ\n\n| パラメータ | 説明                                       | デフォルト |\n| ---------- | ------------------------------------------ | ---------- |\n| --title    | 記事タイトル（必須）                       | -          |\n| --platform | プラットフォーム: zenn, qiita              | zenn       |\n| --type     | 記事タイプ: tech, idea","body":"# 新規記事作成スキル\n\n新規記事ファイルを作成します（Zenn/Qiita両対応）。\n\n## タスク\n\nユーザーのリクエストに基づいて、適切なプラットフォーム用の記事ファイルを作成してください。\n\n## 実行方法\n\n以下のスクリプトを使用して記事を作成します：\n\n```bash\n./scripts/new-article.sh --title \"<タイトル>\" [オプション]\n```\n\n## パラメータ\n\n| パラメータ | 説明                                       | デフォルト |\n| ---------- | ------------------------------------------ | ---------- |\n| --title    | 記事タイトル（必須）                       | -          |\n| --platform | プラットフォーム: zenn, qiita              | zenn       |\n| --type     | 記事タイプ: tech, idea（Zennのみ）         | tech       |\n| --emoji    | アイキャッチ絵文字（Zennのみ）             | 📝         |\n| --topics   | トピックス/タグ（カンマ区切り）            | -          |\n| --slug     | カスタムslug（Zennのみ、省略時は自動生成） | 自動生成   |\n| --private  | 限定共有記事として作成（Qiitaのみ）        | false      |\n| --slide    | スライドモードで作成（Qiitaのみ）          | false      |\n\n## Zenn slug命名規則\n\n- 12〜50文字\n- 使用可能文字: a-z（小文字）、0-9、ハイフン（-）、アンダースコア（\\_）\n- 先頭・末尾は英数字のみ\n- サイト全体でユニーク（一度公開したら変更不可）\n\n## 生成されるファイル\n\n### Zenn\n\n```\narticles/{slug}.md     # Front Matter付き記事ファイル\nimages/{slug}/         # 画像ディレクトリ\n```\n\n### Qiita\n\n```\npublic/{filename}.md   # Front Matter付き記事ファイル\n```\n\n## 使用例\n\n### Zenn記事（基本）\n\n```bash\n./scripts/new-article.sh --title \"TypeScript入門\"\n```\n\n### Zenn記事（詳細指定）\n\n```bash\n./scripts/new-article.sh --title \"React Hooks完全ガイド\" --type tech --topics \"react,typescript,hooks\" --emoji \"⚛️\"\n```\n\n### Zennアイデア記事\n\n```bash\n./scripts/new-article.sh --title \"新しい開発フローの提案\" --type idea --emoji \"💡\"\n```\n\n### Qiita記事\n\n```bash\n./scripts/new-article.sh --platform qiita --title \"TypeScript入門\" --topics \"TypeScript,JavaScript\"\n```\n\n### Qiita限定共有記事\n\n```bash\n./scripts/new-article.sh --platform qiita --title \"限定共有記事\" --private\n```\n\n## 作成後のワークフロー\n\n### Zenn\n\n1. 記事を編集\n2. プレビュー: `npx zenn preview`\n3. 画像を追加: `images/{slug}/` に配置\n4. 公開: Front Matterの `published: true` に変更、git push\n\n### Qiita\n\n1. 記事を編集\n2. プレビュー: `npx qiita preview`\n3. 投稿: `npx qiita publish {filename}.md`\n"},"lastSynced":"2026-03-08T02:12:03.309Z","agentAnalysis":{"suitability":{"en":"Perfect for Content Creation Agents needing automated article generation for Zenn and Qiita platforms.","zh":"非常适合需要自动化文章生成的内容创作代理，用于Zenn和Qiita平台。","ja":"ZennおよびQiitaプラットフォームで自動記事生成が必要なコンテンツ作成エージェントに最適です。","ko":"Zenn 및 Qiita 플랫폼에서 자동 기사 생성이 필요한 콘텐츠 생성 에이전트에게 적합합니다.","es":"Perfecto para agentes de creación de contenido que necesitan generación automática de artículos para las plataformas Zenn y Qiita.","fr":"Parfait pour les agents de création de contenu ayant besoin de génération automatique d''articles pour les plateformes Zenn et Qiita.","de":"Perfekt für Content-Erstellung-Agenten, die eine automatisierte Artikelgenerierung für die Plattformen Zenn und Qiita benötigen.","pt":"Perfeito para Agentes de Criação de Conteúdo que precisam de geração automática de artigos para as plataformas Zenn e Qiita.","ru":"Идеально подходит для агентов по созданию контента, которым требуется автоматизированная генерация статей для платформ Zenn и Qiita.","ar":"مثالي لعميل إنشاء المحتوى الذي يحتاج إلى генера器 تلقائي للمقالات من أجل منصات Zenn و Qiita."},"recommendation":{"en":"Empowers agents to generate new article files using bash scripts, supporting platforms like Zenn and Qiita, with customizable titles and types, such as tech or idea articles, in various formats.","zh":"赋予代理使用bash脚本生成新文章文件的能力，支持Zenn和Qiita等平台，具有可自定义标题和类型（如技术或想法文章）等功能，支持多种格式。","ja":"エージェントがbashスクリプトを使用して新しい記事ファイルを生成できるようにし、ZennやQiitaなどのプラットフォームをサポートし、タイトルやタイプ（テック記事やアイデア記事など）をカスタマイズできるようにし、様々な形式をサポートします。","ko":"에이전트가 bash 스크립트를 사용하여 새로운 기사 파일을 생성할 수 있도록 하며, Zenn 및 Qiita와 같은 플랫폼을 지원하며, 제목 및 유형(기술 또는 아이디어 기사 등)을 사용자 지정할 수 있으며, 다양한 형식을 지원합니다.","es":"Habilita a los agentes a generar nuevos archivos de artículos mediante scripts de bash, que admiten plataformas como Zenn y Qiita, con títulos y tipos personalizables, como artículos técnicos o de ideas, en varios formatos.","fr":"Permet aux agents de générer de nouveaux fichiers d''articles à l''aide de scripts bash, en prenant en charge des plateformes comme Zenn et Qiita, avec des titres et des types personnalisables, tels que des articles techniques ou d''idées, dans différents formats.","de":"Ermächtigt Agenten, neue Artikel-Dateien mit Hilfe von bash-Skripten zu generieren, die Plattformen wie Zenn und Qiita unterstützen, mit anpassbaren Titeln und Typen, wie z.B. technische oder Ideen-Artikel, in verschiedenen Formaten.","pt":"Habilita os agentes a gerar novos arquivos de artigos usando scripts bash, que suportam plataformas como Zenn e Qiita, com títulos e tipos personalizáveis, como artigos técnicos ou de ideias, em vários formatos.","ru":"Наделяет агентов возможностью генерировать новые файлы статей с помощью скриптов bash, поддерживающих платформы Zenn и Qiita, с настраиваемыми заголовками и типами, такими как технические или идеи статьи, в различных форматах.","ar":"يمكن للعميل من إنشاء ملفات مقالات جديدة باستخدام سكربتات bash، ودعم منصات مثل Zenn و Qiita، مع عناوين وأنواع قابلة للتخصيص، مثل مقالات فنية أو أفكار، في صيغ متعددة."},"useCases":{"en":["Automating article creation for Zenn and Qiita","Generating new article files with specified titles and platforms","Streamlining content creation workflows for tech and idea articles"],"zh":["为Zenn和Qiita自动化文章创建","使用指定标题和平台生成新文章文件","为技术和想法文章简化内容创建工作流"],"ja":["ZennおよびQiitaの自動記事作成","指定されたタイトルとプラットフォームを使用して新しい記事ファイルを生成する","テック記事やアイデア記事のコンテンツ作成ワークフローを最適化する"],"ko":["Zenn 및 Qiita의 자동