INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('heyhey1007/Article/new-article', 'new-article', 'heyhey1007', 'Article', 'community', 'new-article heyhey1007 Article community The new-article skill creates new article files for Zenn and Qiita platforms based on user requests. It utilizes a bash script to generate articles with specified titles and platforms. 新規記事作成スキル是一种创建新文章文件的工具，支持Zenn和Qiita平台 新規記事作成スキルは、ZennとQiita両対応の記事ファイルを作成するためのツールです 새로운 기사 작성 스킬은 Zenn과 Qiita에 적합한 기사 파일을 생성하는 도구입니다 new-article es una herramienta de AI que crea archivos de artículo para Zenn y Qiita utilizando CLI. new-article est un outil d''IA qui crée des fichiers d''article pour Zenn et Qiita à l''aide de CLI. new-article ist ein KI-Tool, das Artikel-Dateien für Zenn und Qiita mit CLI erstellt. O new-article é um skill que cria artigos para Zenn e Qiita. Aprenda a configurá-lo e criar artigos com facilidade ИИ Агент new-article - это скилл, который создает статьи для Zenn и Qiita. Узнайте, как его настроить и создать статьи جديد-مقال هو مهارة تقوم بإنشاء مقالات لمنصات Zenn و Qiita. تعلم كيفية إعدادها وإنشاء مقالات بسهولة how to use new-article new-article setup guide new-article alternative new-article vs article generator automated article creation zenn article creation qiita article creation new-article install bash script for article creation 新規記事作成スキル CLI脚本 Zenn Qiita 文章文件创建 AIエージェント 技术博客 Generates article files using a bash script with the ./scripts/new-article.sh command Supports creation of articles for both Zenn and Qiita platforms Allows specification of article title using the --title parameter Supports selection of platform using the --platform parameter with options zenn or qiita Enables selection of article type using the --type parameter with options tech or idea new-article is a skill that automates the creation of new article files for Zenn and Qiita platforms using a bash script.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('josephaw1022/k8s-vpa-benchmarks/debug_vpa', 'community', 'josephaw1022', 'k8s-vpa-benchmarks', 'josephaw1022/k8s-vpa-benchmarks', 'debug_vpa', 0, 0, 30, '2026-03-08T01:57:15.604Z', '2026-03-08T02:13:09.093Z', '645667aef634ee59347a640e5edb6870d5ba543774bb9f0fe90d229c5ee3a6fd', '{"id":"josephaw1022/k8s-vpa-benchmarks/debug_vpa","name":"debug_vpa","description":{"en":"The debug_vpa skill helps developers diagnose issues with Vertical Pod Autoscaler (VPA) not recommending resources or updating pods. It provides step-by-step guidance for troubleshooting VPA problems.","zh":"debug_vpa 是一种用于排除 Vertical Pod Autoscaler 故障的技能，帮助开发者诊断资源推荐和 Pod 更新问题","ja":"debug_vpa は、Vertical Pod Autoscaler のトラブルシューティングに使用されるスキルで、開発者がリソースの推奨とポッドの更新の問題を診断するのに役立ちます","ko":"debug_vpa는 Vertical Pod Autoscaler의 디버깅을 위한 스킬로, 개발자가 리소스 추천 및 Pod 업데이트의 문제를 진단하는 데 도움을 줍니다","es":"El agente de inteligencia artificial debug_vpa ayuda a diagnosticar problemas con Vertical Pod Autoscaler. Sigue los pasos para solucionar problemas de VPA","fr":"L''agent d''intelligence artificielle debug_vpa aide à diagnostiquer les problèmes avec Vertical Pod Autoscaler. Suivez les étapes pour résoudre les problèmes de VPA","de":"Der KI-Agent debug_vpa hilft bei der Fehlersuche bei Vertical Pod Autoscaler. Befolgen Sie die Schritte, um Probleme mit VPA zu lösen","pt":"O debug_vpa é uma ferramenta para diagnosticar problemas com o Vertical Pod Autoscaler, incluindo a verificação do Metrics Server e dos componentes do VPA","ru":"Debug VPA - это инструмент для диагностики проблем с Vertical Pod Autoscaler, включая проверку Metrics Server и компонентов VPA для ИИ Агентов","ar":"debug_vpa هو أداة لتشخيص مشاكل مع Vertical Pod Autoscaler، بما في ذلك التحقق من Metrics Server و مكونات VPA للإيجنتات الذكية"},"seo":{"title":{"en":"debug_vpa: VPA Troubleshooting Setup Guide | AI Agent Skill","zh":"debug_vpa 故障排除指南","ja":"debug_vpa トラブルシューティングガイド","ko":"debug_vpa 디버깅 가이드","es":"Guía de configuración para debug_vpa: Depuración de Verti...","fr":"Guide de dépannage pour debug_vpa: Débogage du Vertical P...","de":"Einrichtungsanleitung für debug_vpa: Fehlersuche bei Vert...","pt":"Guia de Configuração do Debug VPA: Melhores Práticas","ru":"Настройка Debug VPA: Руководство по отладке ИИ Агентов","ar":"دليل إعداد Debug VPA: إرشادات لتحسين أداء الإيجنتات الذكية"},"description":{"en":"Fix VPA issues with our expert debug_vpa guide. Learn how to diagnose problems and get VPA recommending resources again. Start troubleshooting now!","zh":"学习如何排除 Vertical Pod Autoscaler (VPA) 故障，确保资源推荐和 Pod 更新正常","ja":"Vertical Pod Autoscaler (VPA) のトラブルシューティング方法を学び、リソースの推奨とポッドの更新を正常に実行する","ko":"Vertical Pod Autoscaler (VPA) 디버깅 방법을 배우고 리소스 추천 및 Pod 업데이트 오류를 해결하세요","es":"Aprende a depurar Vertical Pod Autoscaler con debug_vpa. Sigue estos pasos para diagnosticar problemas con VPA","fr":"Découvrez comment déboguer Vertical Pod Autoscaler avec debug_vpa. Suivez ces étapes pour diagnostiquer les problèmes de VPA","de":"Erfahren Sie, wie Sie Vertical Pod Autoscaler mit debug_vpa debuggen. Befolgen Sie diese Schritte, um Probleme mit VPA zu diagnostizieren","pt":"Aprenda a depurar o Vertical Pod Autoscaler com nossas dicas e soluções para resolver problemas de recursos e atualizações de pods","ru":"Узнайте, как отладить Vertical Pod Autoscaler и решить проблемы с ресурсами и обновлениями подов с помощью ИИ Агентов","ar":"تعلم كيفية تصحيح أخطاء Vertical Pod Autoscaler و حل مشاكل الموارد و تحديثات الحاويات باستخدام الإيجنتات الذكية"},"definition":{"en":"debug_vpa is a troubleshooting skill for identifying and resolving issues with Vertical Pod Autoscaler (VPA) in Kubernetes environments.","zh":"debug_vpa 是一种用于排除 Vertical Pod Autoscaler 故障的技术，通过检查 Metrics Server 和 VPA 组件来诊断问题","ja":"debug_vpa は、Vertical Pod Autoscaler のトラブルシューティングに使用される技術で、Metrics Server と VPA コンポーネントを確認して問題を診断する","ko":"debug_vpa는 Vertical Pod Autoscaler의 디버깅을 위한 기술로, Metrics Server와 VPA 컴포넌트를 확인하여 문제를 진단합니다","es":"debug_vpa es una herramienta de depuración para Vertical Pod Autoscaler que ayuda a diagnosticar problemas con la recomendación de recursos y la actualización de pods","fr":"debug_vpa est un outil de débogage pour Vertical Pod Autoscaler qui aide à diagnostiquer les problèmes avec la recommandation de ressources et la mise à jour des pods","de":"debug_vpa ist ein Debugging-Tool für Vertical Pod Autoscaler, das hilft, Probleme mit der Empfehlung von Ressourcen und der Aktualisierung von Pods zu diagnostizieren","pt":"O que é debug_vpa? É uma ferramenta de depuração para o Vertical Pod Autoscaler","ru":"Что такое Debug VPA? Это инструмент для отладки Vertical Pod Autoscaler для ИИ Агентов","ar":"ما هو debug_vpa? هو أداة لتصحيح أخطاء Vertical Pod Autoscaler للإيجنتات الذكية"},"features":{"en":["Checks Metrics Server status using kubectl commands","Verifies VPA components for proper functionality","Uses kubectl top commands to identify metrics issues","Provides step-by-step guidance for VPA troubleshooting","Helps resolve issues with VPA not recommending resources or updating pods"],"zh":["检查 Metrics Server 状态","验证 VPA 组件","使用 kubectl 命令诊断问题","排除资源推荐和 Pod 更新故障","支持 Vertical Pod Autoscaler 故障排除"],"ja":["Metrics Server の状態を確認する","VPA コンポーネントを検証する","kubectl コマンドを使用して問題を診断する","リソースの推奨とポッドの更新の故障を排除する","Vertical Pod Autoscaler のトラブルシューティングをサポートする"],"ko":["Metrics Server 상태 확인","VPA 컴포넌트 검증","kubectl 명령어를 사용한 문제 진단","리소스 추천 및 Pod 업데이트 오류 해결","Vertical Pod Autoscaler 디버깅 지원"],"es":["Verificación del servidor de métricas","Verificación de los componentes de VPA","Uso de kubectl para depurar VPA","Diagnóstico de problemas con la recomendación de recursos","Diagnóstico de problemas con la actualización de pods"],"fr":["Vérification du serveur de mesures","Vérification des composants de VPA","Utilisation de kubectl pour déboguer VPA","Diagnostic des problèmes avec la recommandation de ressources","Diagnostic des problèmes avec la mise à jour des pods"],"de":["Überprüfung des Metrics-Servers","Überprüfung der VPA-Komponenten","Verwendung von kubectl zur Fehlersuche bei VPA","Diagnose von Problemen mit der Empfehlung von Ressourcen","Diagnose von Problemen mit der Aktualisierung von Pods"],"pt":["Verificação do Metrics Server","Verificação dos componentes do VPA","Uso do comando kubectl para diagnosticar problemas","Suporte à resolução de problemas de recursos e atualizações de pods","Integração com o Vertical Pod Autoscaler"],"ru":["Проверка Metrics Server","Проверка компонентов VPA","Использование команды kubectl для диагностики проблем","Поддержка решения проблем с ресурсами и обновлениями подов","Интеграция с Vertical Pod Autoscaler для ИИ Агентов"],"ar":["التحقق من Metrics Server","التحقق من مكونات VPA","استخدام الأمر kubectl لتشخيص المشاكل","دعم حل مشاكل الموارد و تحديثات الحاويات","التكامل مع Vertical Pod Autoscaler للإيجنتات الذكية"]},"keywords":{"en":["how to use debug_vpa","debug_vpa troubleshooting guide","VPA not recommending resources","debug_vpa vs kubectl","debug_vpa install","debug_vpa setup guide","what is debug_vpa","debug_vpa alternative","debug_vpa for Kubernetes"],"zh":["debug_vpa","Vertical Pod Autoscaler","Metrics Server","kubectl","故障排除","资源推荐","Pod 更新","AIエージェント","云原生应用"],"ja":["debug_vpa","Vertical Pod Autoscaler","Metrics Server","kubectl","トラブルシューティング","リソースの推奨","ポッドの更新","AIエージェント","クラウドネイティブアプリ"],"ko":["debug_vpa","Vertical Pod Autoscaler","Metrics Server","kubectl","디버깅","리소스 추천","Pod 업데이트","AI 에이전트","클라우드 네이티브 앱"],"es":["debug_vpa","Vertical Pod Autoscaler","depuración de VPA","recomendación de recursos","actualización de pods","kubectl","servidor de métricas","herramientas de inteligencia artificial"],"fr":["debug_vpa","Vertical Pod Autoscaler","débogage de VPA","recommandation de ressources","mise à jour des pods","kubectl","serveur de mesures","outils d''intelligence artificielle"],"de":["debug_vpa","Vertical Pod Autoscaler","Fehlersuche bei VPA","Empfehlung von Ressourcen","Aktualisierung von Pods","kubectl","Metrics-Server","KI-Tools"],"pt":["debug_vpa","Vertical Pod Autoscaler","Metrics Server","kubectl","depuração de pods","otimização de recursos","solução de problemas de VPA","Guia de configuração do VPA","Melhores práticas para VPA"],"ru":["Debug VPA","Vertical Pod Autoscaler","Metrics Server","kubectl","отладка подов","оптимизация ресурсов","решение проблем VPA","Настройка VPA","Лучшие практики для VPA","ИИ Агенты"],"ar":["debug_vpa","Vertical Pod Autoscaler","Metrics Server","kubectl","تصحيح أخطاء الحاويات","تحسين أداء الموارد","حل مشاكل VPA","دليل إعداد VPA","إرشادات لتحسين أداء VPA","الإيجنتات الذكية"]}},"owner":"josephaw1022","repo":"k8s-vpa-benchmarks","repoPath":"josephaw1022/k8s-vpa-benchmarks","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.604Z","topics":[],"category":"community","skillMd":{"name":"debug_vpa","description":"Debug Vertical Pod Autoscaler issues by checking metrics, recommender logs, and eviction events.","bodyPreview":"# Debugging Vertical Pod Autoscaler (VPA)\n\nFollow these steps to diagnose issues with VPA not recommending resources or not updating pods.\n\n## 1. Check Metrics Server\nVPA relies on the Metrics Server to gather historical usage data. If it''s down, VPA won''t work.\n\n```bash\nkubectl get deployment metrics-server -n kube-system\nkubectl top nodes\nkubectl top pods -A\n```\n*If `kubectl top` fails or returns \"Metrics not available\", the Metrics Server is the issue.*\n\n## 2. Check VPA Components\nEnsure the","body":"# Debugging Vertical Pod Autoscaler (VPA)\n\nFollow these steps to diagnose issues with VPA not recommending resources or not updating pods.\n\n## 1. Check Metrics Server\nVPA relies on the Metrics Server to gather historical usage data. If it''s down, VPA won''t work.\n\n```bash\nkubectl get deployment metrics-server -n kube-system\nkubectl top nodes\nkubectl top pods -A\n```\n*If `kubectl top` fails or returns \"Metrics not available\", the Metrics Server is the issue.*\n\n## 2. Check VPA Components\nEnsure the VPA recommender, updater, and admission-controller are running.\n\n```bash\nkubectl get pods -n kube-system -l app.kubernetes.io/name=vpa\n```\n\n## 3. Inspect VPA Object\nCheck the VPA object for `Conditions` and `Recommendations`.\n\n```bash\nkubectl get vpa -A\nkubectl describe vpa <vpa-name> -n <namespace>\n```\n*Look for `Provided` condition being True. If False, check the `message` field.*\n\n## 4. Check Recommender Logs\nIf recommendations are missing, check the recommender logs.\n\n```bash\nkubectl logs -n kube-system -l app=vpa-recommender\n```\n*Look for permission errors or \"no metrics\" warnings.*\n\n## 5. Check Evictions\nIf recommendations exist but pods aren''t updating, check if the VPA Updater is evicting pods.\n\n```bash\nkubectl get events -n <namespace> --sort-by=''.lastTimestamp''\n```\n*Look for `EvictedByVPA` events.*\n"},"lastSynced":"2026-03-08T02:13:09.093Z","agentAnalysis":{"suitability":{"en":"Perfect for Kubernetes Agents needing advanced Vertical Pod Autoscaler (VPA) troubleshooting capabilities.","zh":"非常适合需要高级 Vertical Pod Autoscaler (VPA) 故障排除能力的 Kubernetes Agents。","ja":"Kubernetes Agent が高度な Vertical Pod Autoscaler (VPA) のトラブルシューティング機能を必要とする場合に最適です。","ko":"고급 Vertical Pod Autoscaler (VPA) 문제 해결 기능이 필요한 Kubernetes 에이전트에 적합합니다.","es":"Perfecto para agentes de Kubernetes que necesitan capacidades de depuración avanzadas de Vertical Pod Autoscaler (VPA).","fr":"Parfait pour les agents Kubernetes ayant besoin de capacités de dépannage avancées de Vertical Pod Autoscaler (VPA).","de":"Perfekt für Kubernetes-Agents, die erweiterte Fehlersuche-Funktionen für Vertical Pod Autoscaler (VPA) benötigen.","pt":"Perfeito para agentes Kubernetes que necessitam de capacidades avançadas de depuração do Vertical Pod Autoscaler (VPA).","ru":"Идеально подходит для агентов Kubernetes, которым необходимы расширенные возможности поиска и устранения неисправностей Vertical Pod Autoscaler (VPA).","ar":"مثالي للوكلاء Kubernetes الذين يحتاجون إلى возможات متقدمة لتصحيح Vertical Pod Autoscaler (VPA)."},"recommendation":{"en":"Empowers agents to diagnose VPA issues using Metrics Server and kubectl commands, providing step-by-step guidance for troubleshooting VPA problems with Kubernetes deployments and pods.","zh":"使得代理能够使用 Metrics Server 和 kubectl 命令诊断 VPA 问题，并为 Kubernetes 部署和 pod 的 VPA 问题提供一步步的故障排除指导。","ja":"エージェントが Metrics Server と kubectl コマンドを使用して VPA の問題を診断することを可能にし、Kubernetes デプロイメントとポッドの VPA の問題のトラブルシューティングについてステップバイステップのガイダンスを提供します。","ko":"에이전트가 Metrics Server 및 kubectl 명령을 사용하여 VPA 문제를 진단할 수 있도록 하며 Kubernetes 배포 및 pod의 VPA 문제에 대한 문제 해결을 위해 단계별 지침을 제공합니다.","es":"Habilita a los agentes a diagnosticar problemas de VPA utilizando Metrics Server y comandos kubectl, brindando orientación paso a paso para solucionar problemas de VPA con implementaciones y pods de Kubernetes.","fr":"Permet aux agents de diagnostiquer les problèmes de VPA en utilisant Metrics Server et des commandes kubectl, fournissant une orientation étape par étape pour résoudre les problèmes de VPA avec les déploiements et les pods Kubernetes.","de":"Ermöglicht es Agents, VPA-Probleme mithilfe von Metrics Server und kubectl-Befehlen zu diagnostizieren und bietet Schritt-für-Schritt-Anleitungen zur Lösung von VPA-Problemen mit Kubernetes-Deployments und -Pods.","pt":"Habilita os agentes a diagnosticar problemas do VPA usando o Metrics Server e comandos kubectl, fornecendo orientação passo a passo para solucionar problemas do VPA com implantações e pods do Kubernetes.","ru":"Наделяет агентов возможностью диагностировать проблемы VPA с помощью Metrics Server и команд kubectl, предоставляя пошаговое руководство по устранению неполадок VPA с развертываниями и подами Kubernetes.","ar":"يمنح الوكلاء القدرة على تشخيص مشاكل VPA باستخدام Metrics Server وأوامر kubectl، مع توفير إرشادات خطوة بخطوة لتصحيح مشاكل VPA مع عمليات النشر والبودات في Kubernetes."},"useCases":{"en":["Debugging VPA resource recommendation issues","Troubleshooting pods not updating with VPA","Verifying Metrics Server status for VPA"],"zh":["调试 VPA 资源推荐问题","解决 pod 未使用 VPA 更新的问题","验证 Metrics Server 对于 VPA 的状态"],"ja":["VPA リソース推奨の問題をデバッグする","VPA で更新されないポッドの問題をトラブルシューティングする","VPA に対する Metrics Server のステータスを確認する"],"ko":["VPA 리소스 추천 문제를 디버깅하는 것","VPA로 업데이트되지 않는 pod의 문제를 해결하는 것","VPA에 대한 Metrics Server 상태를 확인하는 것"],"es":["Depuración de problemas de recomendación de recursos de VPA","Solución de problemas de pods que no se actualizan con VPA","Verificación del estado del servidor de métricas para VPA"],"fr":["Débogage des problèmes de recommandation de ressources VPA","Dépannage des pods qui ne sont pas mis à jour avec VPA","Vérification de l''état du serveur de mesures pour VPA"],"de":["Fehlersuche bei VPA-Ressourcenempfehlungsproblemen","Fehlersuche bei Pods, die nicht mit VPA aktualisiert werden","Überprüfung des Status des Metrics-Servers für VPA"],"pt":["Depuração de problemas de recomendação de recursos VPA","Solução de problemas de pods que não estão sendo atualizados com VPA","Verificação do status do Metrics Server para VPA"],"ru":["Отладка проблем с рекомендациями ресурсов VPA","Устранение неполадок подов, которые не обновляются с помощью VPA","Проверка статуса Metrics Server для VPA"],"ar":["تصحيح مشاكل توصية موارد VPA","تصحيح مشاكل البودات التي لا يتم تحديثها مع VPA","التحقق من حالة Metrics Server من أجل VPA"]},"limitations":{"en":["Requires kubectl access","Kubernetes environment only","Metrics Server dependency"],"zh":["需要 kubectl 访问","仅限 Kubernetes 环境","依赖于 Metrics Server"],"ja":["kubectl アクセスが必要","Kubernetes 環境のみ","Metrics Server 依存"],"ko":["kubectl 접근이 필요","쿠버네티스 환경만","Metrics Server 의존"],"es":["Requiere acceso a kubectl","Entorno de Kubernetes solo","Dependencia del servidor de métricas"],"fr":["Nécessite un accès à kubectl","Environnement Kubernetes uniquement","Dépendance du serveur de mesures"],"de":["Benötigt Zugriff auf kubectl","Nur Kubernetes-Umgebung","Abhängigkeit vom Metrics-Server"],"pt":["Requer acesso ao kubectl","Ambiente Kubernetes apenas","Dependência do Metrics Server"],"ru":["Требуется доступ к kubectl","Только среда Kubernetes","Зависимость от Metrics Server"],"ar":["يتطلب الوصول إلى kubectl","بيئة Kubernetes فقط","اعتماد Metrics Server"]},"version":4},"contentHash":"645667aef634ee59347a640e5edb6870d5ba543774bb9f0fe90d229c5ee3a6fd","qualityScore":30}');
