INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('josephaw1022/k8s-vpa-benchmarks/debug_vpa', 'debug_vpa', 'josephaw1022', 'k8s-vpa-benchmarks', 'community', 'debug_vpa josephaw1022 k8s-vpa-benchmarks community The debug_vpa skill helps developers diagnose issues with Vertical Pod Autoscaler (VPA) not recommending resources or updating pods. It provides step-by-step guidance for troubleshooting VPA problems. debug_vpa 是一种用于排除 Vertical Pod Autoscaler 故障的技能，帮助开发者诊断资源推荐和 Pod 更新问题 debug_vpa は、Vertical Pod Autoscaler のトラブルシューティングに使用されるスキルで、開発者がリソースの推奨とポッドの更新の問題を診断するのに役立ちます debug_vpa는 Vertical Pod Autoscaler의 디버깅을 위한 스킬로, 개발자가 리소스 추천 및 Pod 업데이트의 문제를 진단하는 데 도움을 줍니다 El agente de inteligencia artificial debug_vpa ayuda a diagnosticar problemas con Vertical Pod Autoscaler. Sigue los pasos para solucionar problemas de VPA L''agent d''intelligence artificielle debug_vpa aide à diagnostiquer les problèmes avec Vertical Pod Autoscaler. Suivez les étapes pour résoudre les problèmes de VPA Der KI-Agent debug_vpa hilft bei der Fehlersuche bei Vertical Pod Autoscaler. Befolgen Sie die Schritte, um Probleme mit VPA zu lösen O debug_vpa é uma ferramenta para diagnosticar problemas com o Vertical Pod Autoscaler, incluindo a verificação do Metrics Server e dos componentes do VPA Debug VPA - это инструмент для диагностики проблем с Vertical Pod Autoscaler, включая проверку Metrics Server и компонентов VPA для ИИ Агентов debug_vpa هو أداة لتشخيص مشاكل مع Vertical Pod Autoscaler، بما في ذلك التحقق من Metrics Server و مكونات VPA للإيجنتات الذكية how to use debug_vpa debug_vpa troubleshooting guide VPA not recommending resources debug_vpa vs kubectl debug_vpa install debug_vpa setup guide what is debug_vpa debug_vpa alternative debug_vpa for Kubernetes debug_vpa Vertical Pod Autoscaler Metrics Server kubectl 故障排除 资源推荐 Pod 更新 AIエージェント 云原生应用 Checks Metrics Server status using kubectl commands Verifies VPA components for proper functionality Uses kubectl top commands to identify metrics issues Provides step-by-step guidance for VPA troubleshooting Helps resolve issues with VPA not recommending resources or updating pods debug_vpa is a troubleshooting skill for identifying and resolving issues with Vertical Pod Autoscaler (VPA) in Kubernetes environments.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('KrishBakshi/linkedin_research_agent/linkedin-boolean-search', 'community', 'KrishBakshi', 'linkedin_research_agent', 'KrishBakshi/linkedin_research_agent', 'linkedin-boolean-search', 0, 0, 30, '2026-03-08T01:57:15.613Z', '2026-03-08T02:13:16.793Z', '8d781f7d638e4ea4e3bc964d810434b0ef2f38943168e93b246f516dede298d2', '{"id":"KrishBakshi/linkedin_research_agent/linkedin-boolean-search","name":"linkedin-boolean-search","description":{"en":"The linkedin-boolean-search skill enables developers to build precise LinkedIn search queries using Boolean operators and syntax. It benefits developers and recruiters who need to find specific profiles or content on LinkedIn.","zh":"LinkedIn 布尔搜索查询构建器支持三种主要的布尔运算符：AND、OR 和 NOT，帮助您精确搜索","ja":"LinkedIn ブール検索クエリビルダーは、AND、OR、NOT の 3 つの主要なブール演算子をサポートし、精密な検索を実現します","ko":"LinkedIn 불린 검색 쿼리 빌더는 AND, OR, NOT의 3가지 주요 불린 연산자를 지원하여 정확한 검색을 도와줍니다","es":"La búsqueda booleana en LinkedIn utiliza operadores como AND, OR y NOT para refinar resultados. Aprende a usarla.","fr":"La recherche booléenne sur LinkedIn utilise des opérateurs tels que AND, OR et NOT pour affiner les résultats. Apprenez à l''utiliser.","de":"Die boolesche Suche auf LinkedIn verwendet Operatoren wie AND, OR und NOT, um Ergebnisse zu verfeinern. Erfahren Sie, wie Sie sie verwenden.","pt":"A busca booleana no LinkedIn permite utilizar operadores AND, OR e NOT para refinar as pesquisas. Aprenda a utilizar esses operadores para melhorar suas buscas.","ru":"Булевый поиск в LinkedIn позволяет использовать операторы AND, OR и NOT для уточнения результатов. Узнайте, как использовать эти операторы для улучшения поиска.","ar":"البحث المنطقي على لينكد إن يسمح باستخدام عوامل AND و OR و NOT لتحسين نتائج البحث. تعلم كيفية استخدام هذه العوامل لتحسين نتائجك"},"seo":{"title":{"en":"linkedin-boolean-search: Mastering Boolean Query Building...","zh":"LinkedIn 布尔搜索查询构建器 Setup Guide","ja":"LinkedIn ブール検索クエリビルダー ベストプラクティス","ko":"LinkedIn 불린 검색 쿼리 빌더 설정 가이드","es":"Guía de configuración de búsqueda booleana en LinkedIn","fr":"Guide d''installation de la recherche booléenne sur LinkedIn","de":"Einrichtungsanleitung für die boolesche Suche auf LinkedIn","pt":"Guia de Configuração de Busca Booleana no LinkedIn","ru":"Настройка поиска в LinkedIn с помощью булевых операторов ...","ar":"دليل إعداد بحث بعبارات منطقية على لينكد إن"},"description":{"en":"Unlock the full potential of LinkedIn search with our expert guide to boolean query building. Learn how to use AND, OR, NOT, and more to find exactly what yo...","zh":"了解 LinkedIn 布尔搜索的核心运算符和语法规则，优化您的搜索结果，AIエージェント","ja":"LinkedIn ブール検索の核心演算子と基本構文をマスターして、検索結果を最適化する、AIエージェント","ko":"LinkedIn 불린 검색의 핵심 연산자와 기본 구문을 이해하여 검색 결과를 최적화 하세요, AI 도구","es":"Aprende a utilizar los operadores booleanos en LinkedIn para mejorar tus búsquedas. Descubre cómo usar AND, OR, NOT y más.","fr":"Découvrez comment utiliser les opérateurs booléens sur LinkedIn pour améliorer vos recherches. Apprenez à utiliser AND, OR, NOT et plus.","de":"Erfahren Sie, wie Sie boolesche Operatoren auf LinkedIn verwenden, um Ihre Suchanfragen zu verbessern. Entdecken Sie, wie Sie AND, OR, NOT und mehr verwenden.","pt":"Aprenda a utilizar operadores booleanos no LinkedIn para melhorar suas pesquisas e encontrar os resultados certos com nossa ferramenta de busca booleana","ru":"Узнайте, как использовать булевые операторы в LinkedIn, чтобы улучшить поиск и найти нужные результаты с помощью ИИ Агенты","ar":"تعرف على كيفية استخدام العوامل المنطقية في لينكد إن لتحسين نتائج البحث و العثور على النتائج الصحيحة باستخدام أداة البحث المنطقية"},"definition":{"en":"linkedin-boolean-search is a query building technique that utilizes Boolean operators like AND, OR, and NOT to refine LinkedIn search results.","zh":"LinkedIn 布尔搜索是一个使用布尔运算符和语法规则来筛选搜索结果的技术","ja":"LinkedIn ブール検索は、ブール演算子と基本構文を使用して検索結果をフィルタリングする技術です","ko":"LinkedIn 불린 검색은 불린 연산자와 기본 구문을 사용하여 검색 결과를 필터링하는 기술입니다","es":"La búsqueda booleana en LinkedIn es una función que utiliza operadores lógicos para filtrar resultados de búsqueda.","fr":"La recherche booléenne sur LinkedIn est une fonction qui utilise des opérateurs logiques pour filtrer les résultats de recherche.","de":"Die boolesche Suche auf LinkedIn ist eine Funktion, die logische Operatoren verwendet, um Suchergebnisse zu filtern.","pt":"Busca booleana no LinkedIn é uma técnica de pesquisa que utiliza operadores lógicos para refinar resultados","ru":"Булевый поиск в LinkedIn - это метод поиска, который использует логические операторы для уточнения результатов","ar":"البحث المنطقي على لينكد إن هو تقنية بحث تستخدم عوامل منطقية لتحسين نتائج البحث"},"features":{"en":["Supports core Boolean operators: AND, OR, and NOT","Utilizes quotation marks for exact phrase matching","Employs parentheses to control logic order","Follows case-insensitive syntax rules","Allows explicit and implicit AND operator usage"],"zh":["支持 AND、OR 和 NOT 布尔运算符","使用引号实现exact匹配","使用括号控制逻辑顺序","支持大小写不敏感的搜索","推荐使用大写运算符"],"ja":["AND、OR、NOT ブール演算子をサポート","クォーテーションマークを使用して exact マッチングを実現","カッコを使用して論理順序を制御","大文字と小文字を区別しない検索をサポート","大文字の演算子を推奨"],"ko":["AND, OR, NOT 불린 연산자 지원","따옴표를 사용하여 exact 일치 구현","괄호를 사용하여 논리 순서 제어","대소문자 구분 없는 검색 지원","대문자 연산자 사용 권장"],"es":["Uso de operadores booleanos como AND, OR y NOT","Búsqueda de frases exactas con comillas","Uso de paréntesis para controlar el orden lógico","Búsqueda insensible a mayúsculas y minúsculas","Uso de operadores para excluir términos de los resultados"],"fr":["Utilisation d''opérateurs booléens tels que AND, OR et NOT","Recherche de phrases exactes avec des guillemets","Utilisation de parenthèses pour contrôler l''ordre logique","Recherche insensible à la casse","Utilisation d''opérateurs pour exclure des termes des résultats"],"de":["Verwendung von booleschen Operatoren wie AND, OR und NOT","Suche nach exakten Phrasen mit Anführungszeichen","Verwendung von Klammern zur Kontrolle der logischen Reihenfolge","Suche unempfindlich gegenüber Groß- und Kleinschreibung","Verwendung von Operatoren zum Ausschließen von Termen aus den Ergebnissen"],"pt":["Utilização de operadores AND, OR e NOT","Suporte a frases exatas com aspas","Agrupamento de termos com parênteses","Pesquisa insensível a maiúsculas e minúsculas","Recomendação de utilização de letras maiúsculas para operadores"],"ru":["Использование операторов AND, OR и NOT","Поддержка точных фраз с кавычками","Группировка термов с помощью скобок","Поиск не зависит от регистра","Рекомендация использования заглавных букв для операторов"],"ar":["استخدام العوامل AND و OR و NOT","دعم الجمل الصحيحة مع علامات التنصيص","تجميع المصطلحات مع أقواس","البحث غير حساس لحالة الأحرف","توصية باستخدام الأحرف الكبيرة للعوامل"]},"keywords":{"en":["how to use linkedin-boolean-search","linkedin-boolean-search tutorial","linkedin-boolean-search alternative","linkedin-boolean-search vs google search","linkedin-boolean-search setup guide","linkedin-boolean-search best practices"],"zh":["LinkedIn 布尔搜索","布尔运算符","exact 匹配","逻辑顺序","大小写不敏感","AIエージェント","搜索优化","LinkedIn 技术"],"ja":["LinkedIn ブール検索","ブール演算子","exact マッチング","論理順序","大文字と小文字を区別しない","AIエージェント","検索最適化","LinkedIn 技術"],"ko":["LinkedIn 불린 검색","불린 연산자","exact 일치","논리 순서","대소문자 구분 없는","AI 도구","검색 최적화","LinkedIn 기술"],"es":["búsqueda booleana en LinkedIn","operadores booleanos","AND OR NOT","búsqueda de frases exactas","paréntesis en búsqueda","búsqueda insensible a mayúsculas y minúsculas","herramientas de búsqueda en LinkedIn","mejora de la búsqueda en LinkedIn"],"fr":["recherche booléenne sur LinkedIn","opérateurs booléens","AND OR NOT","recherche de phrases exactes","parenthèses dans la recherche","recherche insensible à la casse","outils de recherche sur LinkedIn","amélioration de la recherche sur LinkedIn"],"de":["boolesche Suche auf LinkedIn","boolesche Operatoren","AND OR NOT","Suche nach exakten Phrasen","Klammern in der Suche","Suche unempfindlich gegenüber Groß- und Kleinschreibung","Suchtools auf LinkedIn","Verbesserung der Suche auf LinkedIn"],"pt":["busca booleana linkedin","operadores booleanos","pesquisa avançada linkedin","ferramenta de busca booleana","guias de configuração de busca","melhorar resultados de busca","técnicas de busca eficazes","linkedin boolean search"],"ru":["булевый поиск linkedin","булевые операторы","расширенный поиск linkedin","инструмент булевого поиска","руководство по настройке поиска","улучшение результатов поиска","эффективные методы поиска","ИИ Агенты для поиска"],"ar":["بحث بعبارات منطقية لينكد إن","عوامل منطقية","بحث متقدم لينكد إن","أداة بحث بعبارات منطقية","دليل إعداد البحث","تحسين نتائج البحث","تقنيات بحث فعالة","أدوات ذكاء اصطناعي للبحث"]}},"owner":"KrishBakshi","repo":"linkedin_research_agent","repoPath":"KrishBakshi/linkedin_research_agent","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.613Z","topics":[],"category":"community","skillMd":{"name":"linkedin-boolean-search","description":"Constructs advanced LinkedIn Boolean search queries using AND, OR, NOT operators, quotation marks, parentheses, and LinkedIn-specific filters. Use when the user wants to search LinkedIn, find candidates, create recruiter searches, build talent sourcing queries, or needs help with LinkedIn search operators.","bodyPreview":"# LinkedIn Boolean Search Query Builder\n\n## Core Boolean Operators\n\nLinkedIn supports three primary Boolean operators:\n\n- **AND**: All terms must be present (implied by default, can be explicit)\n- **OR**: At least one term must be present\n- **NOT**: Excludes terms from results\n- **Quotation marks `\"\"`**: Exact phrase matching\n- **Parentheses `()`**: Groups terms to control logic order\n\n## Basic Syntax Rules\n\n1. **Case insensitive**: Operators work in any case, but UPPERCASE is recommended for cl","body":"# LinkedIn Boolean Search Query Builder\n\n## Core Boolean Operators\n\nLinkedIn supports three primary Boolean operators:\n\n- **AND**: All terms must be present (implied by default, can be explicit)\n- **OR**: At least one term must be present\n- **NOT**: Excludes terms from results\n- **Quotation marks `\"\"`**: Exact phrase matching\n- **Parentheses `()`**: Groups terms to control logic order\n\n## Basic Syntax Rules\n\n1. **Case insensitive**: Operators work in any case, but UPPERCASE is recommended for clarity\n2. **Implicit AND**: Space between terms defaults to AND\n3. **Grouping**: Use parentheses to control operator precedence\n4. **Quotes**: Use for exact job titles, company names, or multi-word phrases and location\n\n## Filter rules\n1. Apply filters for locations, company, and connection type only\n2. Use filters when finding specific locations, etc. is explicitly mentioned\n3. Navigate using ''linkedin_search_page_navigation'' skill\n\n## Search Pattern Examples\n\n```\n(developer OR engineer) AND (python OR java)\n```\nMultiple role variations with required skills.\n\n```\n\"product manager\" AND \"london\"\n```\nExact phrase with location keyword within quotes.\n\n```\n(react OR angular) AND typescript NOT junior\n```\nSkills combination excluding unwanted terms.\n\n## LinkedIn-Specific Search Filters\n\nWhile Boolean operators work in the main search, combine them with LinkedIn''s built-in filters for precision:\n\n### Available Filters (apply after search if specified, refer ''linkedin_search_page_naviagtion'' skill for navigation)\n- **1st, 2nd, 3rd+ connections**: Filter by network proximity\n- **Location**: Specific cities, regions, or countries\n- **Current companies**: Filter by current employer\n- **Past companies**: Find people who worked at specific companies\n- **Industries**: Target specific industry sectors\n- **Profile language**: Search profiles in specific languages\n- **Schools**: Find alumni from specific universities\n- **Service categories**: For service providers\n\n### Location Filter Usage Rules\n- **\"Based in [Location]\"**: Apply the specific Location filter for that region/country.\n  - *Example*: \"Find AI engineers based in Japan\" -> Apply `Location: Japan` filter.\n- **\"Associated with [Location]\"**: Do NOT apply the Location filter. Instead, include the location name as a keyword in the Boolean string.\n  - *Example*: \"Find people associated with Japan\" -> Add `AND \"Japan\"` to the query string, but do not restrict the Location filter (to catch expats, people with past education/work there, etc.).\n\n## Advanced Query Examples\n\n```\n(\"software engineer\" OR \"senior developer\") AND (aws OR azure) AND python NOT manager\n```\nComplex criteria: senior ICs with cloud and Python skills.\n\n```\n(\"ai engineer\" OR \"ml engineer\") AND pytorch NOT founder NOT ceo\n```\nIC roles only: excludes executives who have AI skills but aren''t hands-on engineers.\n\n## Critical Rules\n\n1. **Max 2-4 OR terms per group** - LinkedIn has complexity limits\n   - Bad: `(\"ai\" OR \"ml\" OR \"data science\" OR \"analytics\")` \n   - Good: `(\"ai\" OR \"data science\")`\n\n2. **Never use short AND long forms of same term**\n   - Bad: `(\"ml\" OR \"machine learning\")` or `(\"ai\" OR \"artificial intelligence\")`\n   - Good: `(\"ai\" OR \"ml\")` - different concepts, both short\n   - Always use short forms: \"ai\", \"ml\" not \"artificial intelligence\", \"machine learning\"\n\n3. **Use parentheses for grouping**\n   - Bad: `developer OR engineer AND python OR java`\n   - Good: `(developer OR engineer) AND (python OR java)`\n\n4. **Use quotes for multi-word phrases**\n   - Bad: `product manager`\n   - Good: `\"product manager\"`\n\n5. **NOT requires AND before it**\n   - Bad: `developer NOT junior`\n   - Good: `developer AND NOT junior`\n\n6. **Exclude incompatible roles for IC searches**\n   - Bad: `\"ai engineer\"` (includes founders/CTOs)\n   - Good: `\"ai engineer\" NOT founder NOT ceo`\n\n## Query Examples by Role\n\n**Engineers:**\n```\n(\"senior software engineer\" OR \"staff engineer\") AND (\"distributed systems\" OR microservices)\n```\n\n**Data Professionals:**\n```\n(\"data analyst\" OR \"data scientist\") AND sql AND python\n```\n\n**AI/ML Engineers (ICs only):**\n```\n(\"ai engineer\" OR \"ml engineer\") AND (pytorch OR tensorflow) NOT founder\n```\n\n**AI/ML Founders:**\n```\n(\"founder\" OR \"co-founder\") AND (\"ai\" OR \"data science\") AND japan\n```\n\n## Best Practices\n\n1. **Use short forms**: \"ai\", \"ml\" not \"artificial intelligence\", \"machine learning\"\n2. **Keep compact**: 2-4 OR terms per group maximum\n3. **Start simple**: Core role + 1-2 skills, then add complexity\n4. **Use quotes**: For exact phrases like `\"product manager\"`\n5. **Group with parentheses**: Any query with multiple operators\n6. **Operator precedence**: Parentheses > NOT > AND > OR\n\n## Operator Usage\n\n- **AND**: Required terms (skills, experience)\n- **OR**: Alternatives (role variations, equivalent skills)\n- **NOT**: Exclude unwanted (junior, intern, founder for IC searches)\n- **Quotes**: Exact phrases (job titles, certifications)\n- **Parentheses**: Group related terms\n"},"lastSynced":"2026-03-08T02:13:16.793Z","agentAnalysis":{"suitability":{"en":"Perfect for Recruiter Agents needing precise LinkedIn profile filtering using Boolean operators.","zh":"非常适合需要使用布尔运算符进行精确 LinkedIn 个人资料筛选的招聘代理","ja":"Boolean 演算子を使用した LinkedIn プロフィールの精密フィルタリングが必要なRecruiter エージェントに最適","ko":"부울 연산자를 사용하여 LinkedIn 프로필을 精密하게 필터링해야 하는 Recruiter 에이전트에게 적합","es":"Perfecto para Agentes de Contratación que necesitan un filtrado preciso de perfiles de LinkedIn utilizando operadores Booleanos.","fr":"Parfait pour les agents de recrutement ayant besoin d''un filtrage précis de profils LinkedIn à l''aide d''opérateurs booléens.","de":"Perfekt für Recruiter-Agenten, die ein präzises Filtern von LinkedIn-Profilen mit Booleschen Operatoren benötigen.","pt":"Perfeito para Recruiters Agents que precisam de filtragem precisa de perfis do LinkedIn usando operadores Booleanos.","ru":"Идеально подходит для агентов по набору персонала, которым требуется точная фильтрация профилей LinkedIn с помощью булевых операторов.","ar":"مثالي لعمال التوظيف الذين يحتاجون إلى تصفية دقيقة لملفات LinkedIn باستخدام مشغلات Boolean."},"recommendation":{"en":"Empowers agents to construct complex search queries using AND, OR, NOT operators, exact phrase matching with quotation marks, and logical grouping with parentheses, enabling efficient profile discovery and talent acquisition.","zh":"赋予代理构造复杂搜索查询的能力，使用 AND、OR、NOT 运算符、带引号的确切短语匹配和使用括号的逻辑分组，从而实现高效的个人资料发现和人才招聘","ja":"AND、OR、NOT 演算子、引用符による正確なフレーズマッチング、括弧による論理グループ化を使用して複雑な検索クエリを構築する機能をエージェントに与え、効率的なプロフィールの発見とタレントの獲得を可能に","ko":"AND, OR, NOT 연산자, 따옴표를 사용한 정확한 구문 일치 및 괄호를 사용한 논리적 그룹화를 사용하여 복잡한 검색 쿼리를 구성할 수 있는 기능을 에이전트에게 제공하여 효율적인 프로필 발견 및 인재 채용을 가능하게 함","es":"Permite a los agentes construir consultas de búsqueda complejas utilizando operadores AND, OR, NOT, coincidencia de frases exactas con comillas y agrupación lógica con paréntesis, lo que permite un descubrimiento eficiente de perfiles y adquisición de talentos.","fr":"Permet aux agents de construire des requêtes de recherche complexes en utilisant les opérateurs AND, OR, NOT, la correspondance de phrase exacte avec des guillemets et le regroupement logique avec des parenthèses, ce qui permet une découverte de profils efficace et une acquisition de talents.","de":"Ermächtigt die Agenten, komplexe Suchabfragen mit den Operatoren AND, OR, NOT, exakter Phrasenübereinstimmung mit Anführungszeichen und logischer Gruppierung mit Klammern zu erstellen, was eine effiziente Profilerkennung und Talentakquise ermöglicht.","pt":"Permite que os agentes construam consultas de pesquisa complexas usando operadores AND, OR, NOT, correspondência de frase exata com aspas e agrupamento lógico com parênteses, permitindo a descoberta eficiente de perfis e aquisição de talentos.","ru":"Наделяет агентов возможностью создавать сложные поисковые запросы с помощью операторов AND, OR, NOT, точного соответствия фразы в кавычках и логической группировки с помощью скобок, обеспечивая эффективное обнаружение профилей и набор персонала.","ar":"يسمح للعمال بالبناء استفسارات بحث معقدة باستخدام مشغلات AND و OR و NOT، والتعرف على العبارات الدقيقة مع علامات الاقتباس، والتركيب المنطقي مع القوس، مما يتيح اكتشاف ملفات الشخصية بكفاءة واكتساب المواهب."},"useCases":{"en":["Automating candidate searches with specific skill sets","Generating targeted lead lists using company name and job title filters","Debugging search queries to improve result accuracy"],"zh":["使用特定技能集自动执行候选人搜索","使用公司名称和工作标题过滤器生成有针对性的潜在客户名单","调试搜索查询以提高结果准确性"],"ja":["特定スキルセットを使用した候補者検索の自動化","会社名と仕事のタイトルフィルターを使用したターゲットリードリストの生成","結果の精度を高めるために検索クエリのデバッグ"],"ko":["특정 기술 세트를 사용한 후보자 검색 자동화","회사 이름 및 직함 필터를 사용한 타겟 리드 목록 생성","결과 정확도를 높이기 위한 검색 쿼리 디버깅"],"es":["Automatización de búsquedas de candidatos con conjuntos de habilidades específicos","Generación de listas de leads dirigidos utilizando filtros de nombre de empresa y título de trabajo","Depuración de consultas de búsqueda para mejorar la precisión de los resultados"],"fr":["Automatisation des recherches de candidats avec des ensembles de compétences spécifiques","Génération de listes de prospects ciblés en utilisant des filtres de nom d''entreprise et de titre de travail","Débogage des requêtes de recherche pour améliorer la précision des résultats"],"de":["Automatisierung von Kandidatensuchen mit spezifischen Fähigkeitssets","Erstellung von gezielten Lead-Listen unter Verwendung von Unternehmensname- und Jobtitelfiltern","Fehlerbehebung von Suchabfragen zur Verbesserung der Ergebnisgenauigkeit"],"pt":["Automatizar pesquisas de candidatos com conjuntos de habilidades específicas","Gerar listas de leads direcionadas usando filtros de nome da empresa e título do trabalho","Depurar consultas de pesquisa para melhorar a precisão dos resultados"],"ru":["Автоматизация поиска кандидатов с конкретными наборами навыков","Генерация целевых списков лидов с помощью фильтров названия компании и должности","Отладка поисковых запросов для повышения точности результатов"],"ar":["أتمتة عمليات البحث عن المرشحين الذين لديهم مجموعات مهارات محددة","генерация قوائم مرشحين محددين باستخدام مرشحات أسماء الشركات وألقاب الوظائف","تصحيح استفسارات البحث لتحسين دقة النتائج"]},"limitations":{"en":["Requires understanding of Boolean syntax and operators","Dependent on LinkedIn''s search query limitations and restrictions"],"zh":["需要了解布尔语法和运算符","依赖于 LinkedIn 的搜索查询限制和限制"],"ja":["Boolean 文法と演算子の理解が必要","LinkedIn の検索クエリの制限と制約に依存"],"ko":["부울 문법 및 연산자의 이해가 필요","LinkedIn의 검색 쿼리 제한 및 제약에 의존"],"es":["Requiere una comprensión de la sintaxis Booleana y los operadores","Depende de las limitaciones y restricciones de las consultas de búsqueda de LinkedIn"],"fr":["Nécessite une compréhension de la syntaxe booléenne et des opérateurs","Dépend des limitations et des restrictions des requêtes de recherche de LinkedIn"],"de":["Erfordert ein Verständnis der Booleschen Syntax und der Operatoren","Hängt von den Einschränkungen und Beschränkungen der Suchabfragen von LinkedIn ab"],"pt":["Exige compreensão da sintaxe Booleana e operadores","Dependente das limitações e restrições de consulta de pesquisa do LinkedIn"],"ru":["Требует понимания булевой синтаксиса и операторов","Зависит от ограничений и ограничений запроса поиска LinkedIn"],"ar":["يتطلب فهم 문법 Boolean والمشغلين","يعتمد على حدود وقيود استفسار البحث في LinkedIn"]},"version":4},"contentHash":"8d781f7d638e4ea4e3bc964d810434b0ef2f38943168e93b246f516dede298d2","qualityScore":30}');
