INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('KrishBakshi/linkedin_research_agent/linkedin-boolean-search', 'linkedin-boolean-search', 'KrishBakshi', 'linkedin_research_agent', 'community', 'linkedin-boolean-search KrishBakshi linkedin_research_agent community The linkedin-boolean-search skill enables developers to build precise LinkedIn search queries using Boolean operators and syntax. It benefits developers and recruiters who need to find specific profiles or content on LinkedIn. LinkedIn 布尔搜索查询构建器支持三种主要的布尔运算符：AND、OR 和 NOT，帮助您精确搜索 LinkedIn ブール検索クエリビルダーは、AND、OR、NOT の 3 つの主要なブール演算子をサポートし、精密な検索を実現します LinkedIn 불린 검색 쿼리 빌더는 AND, OR, NOT의 3가지 주요 불린 연산자를 지원하여 정확한 검색을 도와줍니다 La búsqueda booleana en LinkedIn utiliza operadores como AND, OR y NOT para refinar resultados. Aprende a usarla. La recherche booléenne sur LinkedIn utilise des opérateurs tels que AND, OR et NOT pour affiner les résultats. Apprenez à l''utiliser. Die boolesche Suche auf LinkedIn verwendet Operatoren wie AND, OR und NOT, um Ergebnisse zu verfeinern. Erfahren Sie, wie Sie sie verwenden. A busca booleana no LinkedIn permite utilizar operadores AND, OR e NOT para refinar as pesquisas. Aprenda a utilizar esses operadores para melhorar suas buscas. Булевый поиск в LinkedIn позволяет использовать операторы AND, OR и NOT для уточнения результатов. Узнайте, как использовать эти операторы для улучшения поиска. البحث المنطقي على لينكد إن يسمح باستخدام عوامل AND و OR و NOT لتحسين نتائج البحث. تعلم كيفية استخدام هذه العوامل لتحسين نتائجك how to use linkedin-boolean-search linkedin-boolean-search tutorial linkedin-boolean-search alternative linkedin-boolean-search vs google search linkedin-boolean-search setup guide linkedin-boolean-search best practices LinkedIn 布尔搜索 布尔运算符 exact 匹配 逻辑顺序 大小写不敏感 AIエージェント 搜索优化 LinkedIn 技术 Supports core Boolean operators: AND, OR, and NOT Utilizes quotation marks for exact phrase matching Employs parentheses to control logic order Follows case-insensitive syntax rules Allows explicit and implicit AND operator usage linkedin-boolean-search is a query building technique that utilizes Boolean operators like AND, OR, and NOT to refine LinkedIn search results.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Junghyun99/StockAsset/code-analysis', 'community', 'Junghyun99', 'StockAsset', 'Junghyun99/StockAsset', 'code-analysis', 0, 0, 30, '2026-03-08T01:57:15.620Z', '2026-03-08T02:13:27.848Z', '9139c25a1bd33c4972ac1304ca539f1eba580fd97e6d1579026119de6f41f52f', '{"id":"Junghyun99/StockAsset/code-analysis","name":"code-analysis","description":{"en":"The code-analysis skill analyzes designated directories or files to identify issues, ambiguities, and areas for improvement, registering them as GitHub issues. It benefits developers by streamlining code review.","zh":"代码分析工具可以帮助开发者识别代码中的问题点和改进区域，包括边界条件、类型不匹配和异常处理等","ja":"コード分析ツールは、開発者がコード内の問題点や改善区域を特定するのに役立ちます。境界条件、タイプ不一致、例外処理などを含みます","ko":"코드 분석은 지정된 디렉토리 또는 파일을 분석하여 문제점, 모호한 점, 개선이 필요한 사항을 식별하고 각각을 GitHub 이슈로 등록합니다","es":"El análisis de código con StockAsset identifica problemas y mejora la calidad del código. Analiza directorios y archivos para detectar errores y sugerir mejoras","fr":"L''analyse de code avec StockAsset identifie les problèmes et améliore la qualité du code. Analyse des répertoires et des fichiers pour détecter les erreurs et suggérer des améliorations","de":"Die Code-Analyse mit StockAsset identifiziert Probleme und verbessert die Qualität des Codes. Analysiert Verzeichnisse und Dateien, um Fehler zu erkennen und Verbesserungsvorschläge zu machen","pt":"A análise de código é uma ferramenta poderosa que ajuda a identificar problemas e melhorar a qualidade do código, utilizando técnicas de IA para analisar o código e detectar erros","ru":"Анализ кода - это мощный инструмент, который помогает выявить проблемы и улучшить качество кода, используя методы ИИ для анализа кода и обнаружения ошибок","ar":"تحليل الشفرة هو أداة قوية تساعد في تحديد المشاكل وتحسين جودة الشفرة، باستخدام تقنيات الذكاء الاصطناعي لتحليل الشفرة واكتشاف الأخطاء"},"seo":{"title":{"en":"Code-Analysis: Automated Code Review Setup Guide | AI Age...","zh":"代码分析工具：识别问题和改进代码质量","ja":"コード分析ツール：問題点の特定とコード品質の改善","ko":"코드 분석 설정 가이드: 버그 및 로직 오류 식별","es":"Guía de configuración de análisis de código con StockAsset","fr":"Configurer l''analyse de code avec StockAsset - Meilleures...","de":"Code-Analyse-Setup mit StockAsset - Eine Anleitung","pt":"Guia de Configuração de Análise de Código com Ferramentas...","ru":"Настройка анализа кода с помощью ИИ Агентов","ar":"إعداد تحليل الشفرة مع أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how code-analysis AI agent skill identifies bugs, logic errors, and design flaws in your codebase. Get started with automated code review today!","zh":"利用代码分析工具自动识别代码中的问题点和改进区域，包括边界条件、类型不匹配和异常处理等","ja":"コード分析ツールを使用して、コード内の問題点や改善区域を自動的に特定します。境界条件、タイプ不一致、例外処理などを含みます","ko":"코드 분석을 통해 버그 및 로직 오류, 설계 및 아키텍처 문제를 식별하고 GitHub 이슈로 등록하여 코드 품질을 개선합니다","es":"Aprende a configurar el análisis de código con StockAsset y mejora la calidad de tu código con herramientas de AI","fr":"Découvrez comment configurer l''analyse de code avec StockAsset et améliorer la qualité de votre code avec les outils d''IA","de":"Erfahren Sie, wie Sie die Code-Analyse mit StockAsset konfigurieren und die Qualität Ihres Codes mit AI-Tools verbessern","pt":"Aprenda a configurar a análise de código com ferramentas de IA para identificar problemas e melhorar a qualidade do seu código","ru":"Узнайте, как настроить анализ кода с помощью ИИ Агентов для выявления проблем и улучшения качества кода","ar":"تعلم كيفية إعداد تحليل الشفرة مع أدوات الذكاء الاصطناعي لتحديد المشاكل وتحسين جودة الشفرة"},"definition":{"en":"Code-analysis is a skill that automates code review by scanning files for bugs, logic errors, and design flaws, providing actionable insights for improvement.","zh":"代码分析是指使用AIエージェント或工具自动检查代码中的问题点和改进区域的过程","ja":"コード分析は、AIエージェントまたはツールを使用してコード内の問題点や改善区域を自動的にチェックするプロセスです","ko":"코드 분석은 코드를 분석하여 문제점, 모호한 점, 개선이 필요한 사항을 식별하는 기술입니다","es":"Análisis de código es una técnica que utiliza herramientas de AI para identificar problemas y mejorar la calidad del código","fr":"L''analyse de code est une technique qui utilise des outils d''IA pour identifier les problèmes et améliorer la qualité du code","de":"Code-Analyse ist eine Technik, die AI-Tools verwendet, um Probleme zu identifizieren und die Qualität des Codes zu verbessern","pt":"Análise de código é o processo de examinar o código-fonte para identificar problemas, erros e melhorias","ru":"Анализ кода - это процесс изучения исходного кода для выявления проблем, ошибок и улучшений","ar":"تحليل الشفرة هو عملية فحص الشفرة المصدرية لتحديد المشاكل والأخطاء وتحسينها"},"features":{"en":["Identifies boundary condition errors, such as empty lists or division by zero","Detects type mismatches and incorrect type assumptions","Analyzes exception handling for completeness and correctness","Checks for off-by-one errors and incorrect conditional statements","Evaluates code against Clean Architecture principles"],"zh":["自动识别边界条件问题","检测类型不匹配和异常处理问题","支持GitHub이슈注册","代码设计和架构分析","识别off-by-one错误和Clean Architecture违规"],"ja":["境界条件の問題を自動的に特定","タイプ不一致と例外処理の問題を検出","GitHubイシューの登録をサポート","コード設計とアーキテクチャの分析","off-by-oneエラーとClean Architecture違反を特定"],"ko":["버그 및 로직 오류 식별","경계 조건 누락 및 타입 불일치 검출","예외 처리 누락 및 잘못된 예외 처리 검출","GitHub 이슈 등록 지원","코드 설계 및 아키텍처 분석"],"es":["Detección de errores de lógica y bugs","Análisis de diseño y arquitectura","Identificación de problemas de tipos y excepciones","Sugerencias de mejora para el código","Integración con GitHub para registrar issues","Soporte para análisis de directorios y archivos"],"fr":["Détection d''erreurs de logique et de bugs","Analyse de conception et d''architecture","Identification de problèmes de types et d''exceptions","Suggestions d''amélioration pour le code","Intégration avec GitHub pour enregistrer des issues","Prise en charge de l''analyse de répertoires et de fichiers"],"de":["Fehler- und Bug-Erkennung","Design- und Architekturanalyse","Identifizierung von Typ- und Ausnahmeproblemen","Vorschläge zur Verbesserung des Codes","Integration mit GitHub für die Erstellung von Issues","Unterstützung für die Analyse von Verzeichnissen und Dateien"],"pt":["Análise de código para identificar problemas e erros","Detecção de bugs e erros lógicos","Análise de design e arquitetura","Verificação de dependências e interfaces","Integração com GitHub para registro de issues"],"ru":["Анализ кода для выявления проблем и ошибок","Обнаружение багов и логических ошибок","Анализ дизайна и архитектуры","Проверка зависимостей и интерфейсов","Интеграция с GitHub для регистрации проблем"],"ar":["تحليل الشفرة لتحديد المشاكل والأخطاء","اكتشاف الأخطاء اللوجيستية","تحليل التصميم والهيكل","فحص الإعتماديات والواجهات","التكامل مع GitHub لتسجيل المشاكل"]},"keywords":{"en":["how to use code-analysis","code-analysis vs sonarqube","code-analysis setup guide","automated code review tools","code-analysis alternative to linters","what is code-analysis","code-analysis install","code-analysis for GitHub"],"zh":["代码分析工具","AIエージェント","代码质量改善","边界条件问题","类型不匹配","异常处理","GitHubイシュー","代码设计","アーキテクチャ分析"],"ja":["コード分析ツール","AIエージェント","コード品質改善","境界条件の問題","タイプ不一致","例外処理","GitHubイシュー","コード設計","アーキテクチャ分析"],"ko":["코드 분석","AI Tools","코드 품질 개선","버그 및 로직 오류","경계 조건 누락","타입 불일치","예외 처리","GitHub 이슈","코드 설계","아키텍처 분석"],"es":["análisis de código","herramientas de AI","mejora de la calidad del código","detección de errores","análisis de diseño","GitHub integration","desarrollo de software","ingeniería de software","herramientas de desarrollo"],"fr":["analyse de code","outils d''IA","amélioration de la qualité du code","détection d''erreurs","analyse de conception","intégration GitHub","développement de logiciels","ingénierie de logiciels","outils de développement"],"de":["Code-Analyse","AI-Tools","Qualitätsverbesserung des Codes","Fehlererkennung","Designanalyse","GitHub-Integration","Softwareentwicklung","Softwareingenieurwesen","Entwicklungstools"],"pt":["análise de código","ferramentas de IA","desenvolvimento de software","qualidade de código","GitHub","integração contínua","análise de design","arquitetura de software"],"ru":["анализ кода","ИИ Агенты","разработка программного обеспечения","качество кода","GitHub","продолженная интеграция","анализ дизайна","архитектура программного обеспечения"],"ar":["تحليل الشفرة","أدوات الذكاء الاصطناعي","تطوير البرمجيات","جودة الشفرة","GitHub","التكامل المستمر","تحليل التصميم","هيكل البرمجيات"]}},"owner":"Junghyun99","repo":"StockAsset","repoPath":"Junghyun99/StockAsset","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.620Z","topics":[],"category":"community","skillMd":{"name":"code-analysis","description":"지정된 디렉토리/파일의 문제점을 분석하고 각 문제를 개별 GitHub 이슈로 등록합니다.","bodyPreview":"# 코드 분석 및 GitHub 이슈 등록\n\n지정된 디렉토리 또는 파일을 분석하여 문제점, 모호한 점, 개선이 필요한 사항을 식별하고 각각을 GitHub 이슈로 등록합니다.\n\n## 실행 절차\n\n### 1단계: 분석 대상 확인\n\n- 인자가 없으면 사용자에게 분석 대상 경로를 질문\n- 지정된 경로의 파일 목록 수집 (Glob 사용)\n- 각 파일의 전체 내용 읽기 (Read 사용)\n\n### 2단계: 코드 분석\n\n아래 관점에서 문제점을 식별합니다. 억지로 문제를 찾지말고 문제가 없다면 없다고 출력하고 진행을 종료합니다.:\n\n#### 2-1. 버그 및 로직 오류\n- 경계 조건 누락 (빈 리스트, None, 0 나누기 등)\n- 타입 불일치 또는 잘못된 타입 가정\n- 예외 처리 누락 또는 잘못된 예외 처리\n- 잘못된 조건문, off-by-one 에러\n\n#### 2-2. 설계 및 아키텍처\n- Clean Architecture 위반 (core → infra 의존)\n- 인터페이스 미구현 또는 불완전한","body":"# 코드 분석 및 GitHub 이슈 등록\n\n지정된 디렉토리 또는 파일을 분석하여 문제점, 모호한 점, 개선이 필요한 사항을 식별하고 각각을 GitHub 이슈로 등록합니다.\n\n## 실행 절차\n\n### 1단계: 분석 대상 확인\n\n- 인자가 없으면 사용자에게 분석 대상 경로를 질문\n- 지정된 경로의 파일 목록 수집 (Glob 사용)\n- 각 파일의 전체 내용 읽기 (Read 사용)\n\n### 2단계: 코드 분석\n\n아래 관점에서 문제점을 식별합니다. 억지로 문제를 찾지말고 문제가 없다면 없다고 출력하고 진행을 종료합니다.:\n\n#### 2-1. 버그 및 로직 오류\n- 경계 조건 누락 (빈 리스트, None, 0 나누기 등)\n- 타입 불일치 또는 잘못된 타입 가정\n- 예외 처리 누락 또는 잘못된 예외 처리\n- 잘못된 조건문, off-by-one 에러\n\n#### 2-2. 설계 및 아키텍처\n- Clean Architecture 위반 (core → infra 의존)\n- 인터페이스 미구현 또는 불완전한 구현\n- 과도한 결합 (tight coupling)\n- 단일 책임 원칙(SRP) 위반\n\n#### 2-3. 모호한 코드\n- 의도가 불분명한 매직 넘버 또는 하드코딩 값\n- 이름만으로 역할을 파악하기 어려운 변수/함수\n- 주석과 실제 동작이 불일치하는 코드\n- 복잡한 조건문이나 중첩 로직\n\n#### 2-4. 누락된 기능 및 미완성 코드\n- TODO, FIXME, HACK, XXX 주석\n- 빈 구현체 (pass, NotImplementedError)\n- 테스트가 없는 핵심 로직\n\n#### 2-5. 유지보수성\n- 중복 코드\n- 과도하게 긴 함수 (50줄 이상)\n- 깊은 중첩 (3단계 이상의 if/for)\n- 사용되지 않는 import, 변수, 함수\n\n### 3단계: 분석 결과 정리\n\n발견된 각 문제를 다음 형식으로 정리합니다:\n\n```\n- 제목: 간결한 한줄 요약\n- 파일: 해당 파일 경로\n- 위치: 라인 번호 또는 함수명\n- 심각도: Critical / Warning / Suggestion\n- 카테고리: Bug / Design / Ambiguous / Missing / Maintenance\n- 설명: 문제의 상세 내용과 왜 문제인지 설명\n- 제안: 개선 방향 또는 수정 방안\n```\n\n### 4단계: 사용자 확인\n\n- 발견된 전체 문제 목록을 요약 테이블로 출력\n- 사용자에게 이슈로 등록할 항목을 확인 요청\n- 사용자가 선택한 항목만 이슈로 등록 (전체 등록도 가능)\n\n### 5단계: GitHub 이슈 등록\n\ngh cli를 사용하기 위해 curl로 gh cli 설치 버전을 확인하고 미설치시 아래에서 다운로드한다.\n\ncurl -fsSL https://github.com/cli/cli/releases/download/version\n\n\n각 문제를 개별 GitHub 이슈로 생성합니다:\n\n```bash\ngh issue create \\\n  --title \"[카테고리] 제목\" \\\n  --body \"본문\" \\\n  --label \"라벨\"\n```\n\n#### 이슈 본문 형식\n\n```markdown\n## 문제 설명\n{설명}\n\n## 위치\n- **파일**: `{파일 경로}`\n- **위치**: {라인 번호 또는 함수명}\n\n## 심각도\n{Critical / Warning / Suggestion}\n\n## 제안\n{개선 방향 또는 수정 방안}\n\n---\n_이 이슈는 코드 분석 스킬에 의해 자동 생성되었습니다._\n```\n\n#### 라벨 매핑\n\n| 카테고리 | 라벨 |\n|---------|------|\n| Bug | `bug` |\n| Design | `design` |\n| Ambiguous | `clarification` |\n| Missing | `enhancement` |\n| Maintenance | `maintenance` |\n\n- 라벨이 존재하지 않으면 라벨 없이 생성합니다 (--label 옵션 생략)\n- 심각도가 Critical이면 추가로 `priority: high` 라벨을 시도합니다\n\n### 6단계: 결과 보고\n\n## 출력 형식\n\n```\n## 코드 분석 결과\n\n### 분석 대상\n- 경로: {분석 대상 경로}\n- 파일 수: {N}개\n\n### 발견된 문제\n\n| # | 심각도 | 카테고리 | 파일 | 제목 |\n|---|--------|---------|------|------|\n| 1 | Critical | Bug | src/core/analyzer.py | ... |\n| 2 | Warning | Design | src/infra/broker.py | ... |\n\n### 등록된 이슈\n\n| # | 이슈 번호 | 제목 | URL |\n|---|----------|------|-----|\n| 1 | #12 | [Bug] ... | https://github.com/.../issues/12 |\n| 2 | #13 | [Design] ... | https://github.com/.../issues/13 |\n\n### 요약\n- 총 {N}개 문제 발견 (Critical: {n}, Warning: {n}, Suggestion: {n})\n- {M}개 이슈 등록 완료\n```\n\n## 주의사항\n\n- 분석은 읽기 전용으로 수행하며, 코드를 수정하지 않습니다\n- .env 파일은 분석 대상에서 제외합니다\n- 이슈 등록 전 반드시 사용자 확인을 받습니다\n- 동일한 문제가 이미 이슈로 등록되어 있는지 `gh issue list`로 확인 후 중복 방지\n- 한 번에 너무 많은 이슈를 등록하지 않도록 10개 초과 시 사용자에게 분할 등록 제안\n"},"lastSynced":"2026-03-08T02:13:27.848Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing advanced static analysis capabilities for GitHub integration.","zh":"非常适合需要高级静态分析能力以集成 GitHub 的代码审查代理。","ja":"GitHub 統合に高度な静的分析機能を必要とするコードレビューエージェントに最適です。","ko":"GitHub 통합을 위한 고급 정적 분석 기능이 필요한 코드 리뷰 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Revisión de Código que necesitan capacidades de análisis estático avanzadas para integración con GitHub.","fr":"Parfait pour les Agents de Revue de Code nécessitant des capacités d''analyse statique avancées pour l''intégration GitHub.","de":"Perfekt für Code-Review-Agents, die erweiterte statische Analysefunktionen für die GitHub-Integration benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de capacidades avançadas de análise estática para integração com o GitHub.","ru":"Идеально подходит для агентов код-ревью, которым необходимы продвинутые возможности статического анализа для интеграции с GitHub.","ar":"مثالي للوكلاء المراجعة الكود التي تحتاج إلىقدرات متقدمة من التحليل الثابت لمزامنة مع GitHub."},"recommendation":{"en":"Empowers agents to identify code issues, ambiguities, and areas for improvement using GitHub issues, covering aspects like bug detection, logic errors, and design flaws, including boundary condition checks, type mismatches, and exception handling analysis.","zh":"赋予代理识别代码问题、歧义和改进区域的能力，使用 GitHub 问题，涵盖错误检测、逻辑错误和设计缺陷等方面，包括边界条件检查、类型不匹配和异常处理分析。","ja":"GitHub の問題を使用して、エージェントがコードの問題、曖昧さ、改善すべき点を特定する能力を提供します。バグ検出、論理エラー、設計上の欠陥など、境界条件のチェック、タイプの不一致、例外ハンドリングの分析などを網羅します。","ko":"에이전트가 코드 문제, 모호성 및 개선 영역을 식별할 수 있는 능력을 제공하며 GitHub 문제를 사용하여 버그 검색, 논리 오류 및 설계 결함 등을 포함하여 경계 조건 체크, 유형 불일치 및 예외 처리 분석 등을 다룹니다.","es":"Habilita a los agentes a identificar problemas de código, ambigüedades y áreas de mejora utilizando problemas de GitHub, cubriendo aspectos como la detección de errores, errores lógicos y fallos de diseño, incluyendo comprobaciones de condiciones de límite, incompatibilidades de tipo y análisis de manejo de excepciones.","fr":"Permet aux agents d''identifier les problèmes de code, les ambiguïtés et les domaines d''amélioration en utilisant les problèmes GitHub, couvrant des aspects tels que la détection des bogues, les erreurs logiques et les défauts de conception, y compris les vérifications des conditions limites, les incompatibilités de type et l''analyse du traitement des exceptions.","de":"Ermächtigt Agenten, Codeprobleme, Mehrdeutigkeiten und Verbesserungsbereiche unter Verwendung von GitHub-Problemen zu identifizieren, wobei Aspekte wie Fehlernachweis, Logikfehler und Designfehler abgedeckt werden, einschließlich Prüfungen von Grenzbedingungen, Typeninkompatibilitäten und Ausnahmehandling-Analyse.","pt":"Habilita os agentes a identificar problemas de código, ambiguidades e áreas para melhoria usando problemas do GitHub, cobrindo aspectos como detecção de bugs, erros lógicos e falhas de design, incluindo verificações de condições de limite, incompatibilidades de tipo e análise de tratamento de exceções.","ru":"Позволяет агентам выявлять проблемы с кодом, неоднозначности и области для улучшения, используя проблемы GitHub, охватывая такие аспекты, как обнаружение ошибок, логические ошибки и ошибки проектирования, включая проверки граничных условий, несоответствия типов и анализ обработки исключений.","ar":"تمكين الوكلاء من تحديد مشاكل الشفرة والغموض ومناطق التحسين باستخدام مشاكل GitHub، وتغطية جوانب مثل كشف الأخطاء والأخطاء المنطقية واخطاء التصميم، بما في ذلك فحص شروط الحدود وعدم تطابق النوع وتحليل معالجة الاستثناءات."},"useCases":{"en":["Automating code reviews for Python projects","Identifying potential bugs and logic errors in codebases","Generating GitHub issues for design and architecture improvements"],"zh":["自动化 Python 项目的代码审查","识别代码库中的潜在 bug 和逻辑错误","为设计和架构改进生成 GitHub 问题"],"ja":["Python プロジェクトのコードレビューを自動化する","コードベースの潜在的なバグと論理エラーを特定する","設計とアーキテクチャの改善のための GitHub の問題を生成する"],"ko":["Python 프로젝트의 코드 리뷰 자동화","코드베이스의 잠재적인 버그 및 논리 오류 식별","디자인 및 아키텍처 개선을 위한 GitHub 문제 생성"],"es":["Automatizar las revisiones de código para proyectos Python","Identificar posibles errores y errores lógicos en las bases de código","Generar problemas de GitHub para mejoras de diseño y arquitectura"],"fr":["Automatiser les revues de code pour les projets Python","Identifier les bogues et les erreurs logiques potentiels dans les bases de code","Générer des problèmes GitHub pour les améliorations de conception et d''architecture"],"de":["Automatisieren von Code-Reviews für Python-Projekte","Identifizieren von potenziellen Fehlern und Logikfehlern in Codebasen","Generieren von GitHub-Problemen für Design- und Architekturverbesserungen"],"pt":["Automatizar revisões de código para projetos Python","Identificar bugs potenciais e erros lógicos em bases de código","Gerar problemas do GitHub para melhorias de design e arquitetura"],"ru":["Автоматизация обзоров кода для проектов Python","Выявление потенциальных ошибок и логических ошибок в кодовых базах","Генерация проблем GitHub для улучшений дизайна и архитектуры"],"ar":["أتمتة استعراض الشفرة لمشاريع Python","تحديد الأخطاء المحتملة والأخطاء المنطقية في قواعد الشفرة","توليد مشاكل GitHub لتحسين التصميم والهيكل"]},"limitations":{"en":["Requires GitHub API access","Limited to analyzing designated directories or files","Currently focused on Python code analysis"],"zh":["需要 GitHub API 访问","仅限分析指定目录或文件","目前仅专注于 Python 代码分析"],"ja":["GitHub API アクセスが必要","指定されたディレクトリまたはファイルのみを分析する","現在は Python コード分析のみに焦点を当てている"],"ko":["GitHub API 접근이 필요하다","지정된 디렉토리 또는 파일만 분석한다","현재는 Python 코드 분석에만 초점을 맞추고 있다"],"es":["Requiere acceso a la API de GitHub","Limitado al análisis de directorios o archivos designados","Actualmente centrado en el análisis de código Python"],"fr":["Nécessite un accès à l''API GitHub","Limité à l''analyse des répertoires ou des fichiers désignés","Actuellement axé sur l''analyse de code Python"],"de":["Benötigt Zugriff auf die GitHub-API","Begrenzt auf die Analyse von bestimmten Verzeichnissen oder Dateien","Derzeit auf die Analyse von Python-Code ausgerichtet"],"pt":["Requer acesso à API do GitHub","Limitado à análise de diretórios ou arquivos designados","Atualmente focado na análise de código Python"],"ru":["Требуется доступ к API GitHub","Ограничен анализ назначенных директорий или файлов","В настоящее время сосредоточен на анализе кода Python"],"ar":["يتطلب الوصول إلى واجهة برمجة التطبيقات GitHub","محدود بتحليل الدلائل أو الملفات المحددة","يُركز حاليًا على تحليل شفرة Python"]},"version":4},"contentHash":"9139c25a1bd33c4972ac1304ca539f1eba580fd97e6d1579026119de6f41f52f","qualityScore":30}');
