INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Junghyun99/StockAsset/code-analysis', 'code-analysis', 'Junghyun99', 'StockAsset', 'community', 'code-analysis Junghyun99 StockAsset community The code-analysis skill analyzes designated directories or files to identify issues, ambiguities, and areas for improvement, registering them as GitHub issues. It benefits developers by streamlining code review. 代码分析工具可以帮助开发者识别代码中的问题点和改进区域，包括边界条件、类型不匹配和异常处理等 コード分析ツールは、開発者がコード内の問題点や改善区域を特定するのに役立ちます。境界条件、タイプ不一致、例外処理などを含みます 코드 분석은 지정된 디렉토리 또는 파일을 분석하여 문제점, 모호한 점, 개선이 필요한 사항을 식별하고 각각을 GitHub 이슈로 등록합니다 El análisis de código con StockAsset identifica problemas y mejora la calidad del código. Analiza directorios y archivos para detectar errores y sugerir mejoras L''analyse de code avec StockAsset identifie les problèmes et améliore la qualité du code. Analyse des répertoires et des fichiers pour détecter les erreurs et suggérer des améliorations Die Code-Analyse mit StockAsset identifiziert Probleme und verbessert die Qualität des Codes. Analysiert Verzeichnisse und Dateien, um Fehler zu erkennen und Verbesserungsvorschläge zu machen A análise de código é uma ferramenta poderosa que ajuda a identificar problemas e melhorar a qualidade do código, utilizando técnicas de IA para analisar o código e detectar erros Анализ кода - это мощный инструмент, который помогает выявить проблемы и улучшить качество кода, используя методы ИИ для анализа кода и обнаружения ошибок تحليل الشفرة هو أداة قوية تساعد في تحديد المشاكل وتحسين جودة الشفرة، باستخدام تقنيات الذكاء الاصطناعي لتحليل الشفرة واكتشاف الأخطاء how to use code-analysis code-analysis vs sonarqube code-analysis setup guide automated code review tools code-analysis alternative to linters what is code-analysis code-analysis install code-analysis for GitHub 代码分析工具 AIエージェント 代码质量改善 边界条件问题 类型不匹配 异常处理 GitHubイシュー 代码设计 アーキテクチャ分析 Identifies boundary condition errors, such as empty lists or division by zero Detects type mismatches and incorrect type assumptions Analyzes exception handling for completeness and correctness Checks for off-by-one errors and incorrect conditional statements Evaluates code against Clean Architecture principles Code-analysis is a skill that automates code review by scanning files for bugs, logic errors, and design flaws, providing actionable insights for improvement.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tito-gh/healthcare/clinical-value', 'community', 'tito-gh', 'healthcare', 'tito-gh/healthcare', 'clinical-value', 0, 0, 30, '2026-03-08T01:57:15.620Z', '2026-03-08T02:13:28.708Z', '8893f236225eeef0515b5b3d932d8c51d5699b3448363f4f823fed064ee6972c', '{"id":"tito-gh/healthcare/clinical-value","name":"clinical-value","description":{"en":"The clinical-value skill systematically evaluates the clinical value of research proposals, quantifying contributions to patients, clinicians, and healthcare systems. It benefits researchers, clinicians, and healthcare professionals.","zh":"Clinical Value AI工具用于评估研究案的临床价值，提供定量化的患者、临床医生和医疗系统的贡献度分析","ja":"Clinical Value AIエージェントは、研究案の臨床的価値を体系的に評価し、患者・臨床医・医療システムへの貢献度を定量化する","ko":"클리니컬 밸류 AI 에이전트는 연구 제안의 임상 가치를 체계적으로 평가하고 환자, 임상 의사, 의료 시스템에 대한 기여도를 정량화함","es":"El AI Agent de valor clínico evalúa sistemáticamente el valor clínico de las propuestas de investigación y cuantifica su contribución a los pacientes, médicos y sistemas de salud.","fr":"L''outil d''IA de valeur clinique évalue systématiquement la valeur clinique des propositions de recherche et quantifie sa contribution aux patients, aux médecins et aux systèmes de santé.","de":"Das AI-Tool für den klinischen Wert bewertet systematisch den klinischen Wert von Forschungsvorschlägen und quantifiziert seinen Beitrag zu Patienten, Ärzten und Gesundheitssystemen.","pt":"O Valor Clínico é uma habilidade que avalia a contribuição de propostas de pesquisa para a medicina baseada em evidências","ru":"ИИ Агент для оценки клинической ценности помогает оценить эффективность исследований в области медицины","ar":"قيمة العلاج السريري هي مهارة تقييم مساهمات مقترحات البحث في الطب المبني على الأدلة"},"seo":{"title":{"en":"Clinical-Value: Quantifying Research Impact for AI Agents...","zh":"Clinical Value AI工具设置指南","ja":"Clinical Value AIエージェントのベストプラクティス","ko":"클리니컬 밸류 AI 에이전트 설정 가이드","es":"Guía de configuración de valor clínico para AI Agent","fr":"Guide de mise en place de la valeur clinique pour les out...","de":"Einrichtungsleitfaden für den klinischen Wert von AI-Tools","pt":"Guia de Configuração do Valor Clínico: Avaliação de Propo...","ru":"ИИ Агент для Оценки Клинической Ценности: Руководство по ...","ar":"دليل ضبط قيمة العلاج السريري: تقييم مقترحات البحث"},"description":{"en":"Unlock the clinical value of your research proposals with our AI agent skill. Learn how to quantify patient, clinician, and healthcare system contributions. ...","zh":"了解Clinical Value AI工具的技术细节和设置步骤，评估研究案的临床价值","ja":"Clinical Value AIエージェントの機能と設定方法を学び、研究案の臨床的価値を評価する","ko":"클리니컬 밸류 AI 에이전트의 기술 세부 정보와 설정 단계를 알아보고 연구 제안의 임상 가치를 평가함","es":"Aprende a evaluar el valor clínico de tus investigaciones con nuestro AI Agent de valor clínico. Configuración y mejores prácticas.","fr":"Découvrez comment évaluer la valeur clinique de vos recherches avec notre outil d''IA de valeur clinique. Configuration et bonnes pratiques.","de":"Erfahren Sie, wie Sie den klinischen Wert Ihrer Forschung mit unserem AI-Tool für den klinischen Wert bewerten. Einrichtung und Best Practices.","pt":"Aprenda a configurar o Valor Clínico para avaliar propostas de pesquisa e contribuir para a medicina baseada em evidências","ru":"Узнайте, как настроить ИИ Агент для оценки клинической ценности и внести свой вклад в развитие медицины","ar":"تعلم كيفية ضبط قيمة العلاج السريري لتقييم مقترحات البحث وتحسين الرعاية الصحية"},"definition":{"en":"Clinical-value is a skill that evaluates the clinical value of research proposals, assessing their impact on patients, clinicians, and healthcare systems.","zh":"Clinical Value AI工具是一种评估研究案临床价值的AI技术","ja":"Clinical Value AIエージェントは、研究案の臨床的価値を評価するAI技術の一種","ko":"클리니컬 밸류 AI 에이전트는 연구 제안의 임상 가치를 평가하는 AI 기술의 일종임","es":"El valor clínico se refiere a la evaluación sistemática del impacto de una investigación en la salud de los pacientes y la eficiencia de los sistemas de salud.","fr":"La valeur clinique fait référence à l''évaluation systématique de l''impact d''une recherche sur la santé des patients et l''efficacité des systèmes de santé.","de":"Der klinische Wert bezieht sich auf die systematische Bewertung des Einflusses einer Forschung auf die Gesundheit der Patienten und die Effizienz der Gesundheitssysteme.","pt":"O Valor Clínico é uma ferramenta que avalia a contribuição de propostas de pesquisa para a medicina","ru":"Клиническая ценность - это инструмент для оценки эффективности исследований в области медицины","ar":"قيمة العلاج السريري هي أداة لتقييم مساهمات مقترحات البحث في الطب"},"features":{"en":["Evaluates research proposals based on parameters like RESEARCH_PROPOSAL, DRUG, INDICATION, and TARGET_POPULATION","Quantifies contributions to patients, clinicians, and healthcare systems using a systematic approach","Supports input parameters like CLINICAL_QUESTION and CURRENT_PRACTICE for tailored evaluations","Provides a structured framework for assessing clinical value, including a clinical value assessment formula","Enables researchers to compare treatment regimens, such as DRd vs VRd, and their effects on specific patient populations"],"zh":["支持研究案概要（RESEARCH_PROPOSAL）输入","提供对目标药物（DRUG）和目标疾病（INDICATION）的分析","能够评估目标患者群体（TARGET_POPULATION）","支持临床问题（CLINICAL_QUESTION）输入","提供当前标准治疗（CURRENT_PRACTICE）参考"],"ja":["研究案の概要（RESEARCH_PROPOSAL）入力に対応","対象薬剤（DRUG）と対象疾患（INDICATION）の分析を提供","対象患者集団（TARGET_POPULATION）の評価を可能に","臨床的問い（CLINICAL_QUESTION）入力に対応","現在の標準治療（CURRENT_PRACTICE）参考を提供"],"ko":["연구 제안 개요（RESEARCH_PROPOSAL）입력 지원","대상 약물（DRUG）과 대상 질환（INDICATION）的 분석 제공","대상 환자 집단（TARGET_POPULATION）的 평가 가능","임상 질문（CLINICAL_QUESTION）입력 지원","현재 표준 치료（CURRENT_PRACTICE）참조 제공"],"es":["Evaluación sistemática del valor clínico de las propuestas de investigación","Cuantificación de la contribución a los pacientes, médicos y sistemas de salud","Análisis de la efectividad de los tratamientos y medicamentos","Identificación de la población objetivo y las indicaciones específicas","Integración con la práctica clínica actual y los estándares de tratamiento"],"fr":["Évaluation systématique de la valeur clinique des propositions de recherche","Quantification de la contribution aux patients, aux médecins et aux systèmes de santé","Analyse de l''efficacité des traitements et des médicaments","Identification de la population cible et des indications spécifiques","Intégration avec la pratique clinique actuelle et les normes de traitement"],"de":["Systematische Bewertung des klinischen Werts von Forschungsvorschlägen","Quantifizierung des Beitrags zu Patienten, Ärzten und Gesundheitssystemen","Analyse der Wirksamkeit von Behandlungen und Medikamenten","Identifizierung der Zielgruppe und spezifischer Indikationen","Integration mit der aktuellen klinischen Praxis und den Behandlungsstandards"],"pt":["Avaliação de propostas de pesquisa com base em parâmetros como RESEARCH_PROPOSAL e DRUG","Análise da contribuição para a medicina baseada em evidências","Utilização de tecnologias como CLI para configuração e execução","Integração com dados de pacientes e resultados clínicos","Suporte à tomada de decisões clínicas com base em evidências","Compatibilidade com tecnologias como React e Python"],"ru":["Оценка исследовательских предложений на основе параметров, таких как RESEARCH_PROPOSAL и DRUG","Анализ вклада в медицину, основанную на доказательствах","Использование технологий, таких как CLI, для конфигурации и выполнения","Интеграция с данными пациентов и клиническими результатами","Поддержка принятия клинических решений на основе доказательств","Совместимость с технологиями, такими как React и Python"],"ar":["تقييم مقترحات البحث بناءً على 매개_variables مثل RESEARCH_PROPOSAL و DRUG","تحليل المساهمة في الطب المبني على الأدلة","استخدام تكنولوجيا مثل CLI لضبط وتنفيذ","التكامل مع بيانات المرضى والنتائج السريرية","دعم اتخاذ القرارات السريرية بناءً على الأدلة","التوافق مع تكنولوجيا مثل React و Python"]},"keywords":{"en":["how to use clinical-value","what is clinical-value","clinical-value alternative","clinical-value vs other research evaluation tools","clinical-value install","clinical-value setup guide","quantifying research impact","clinical value assessment","research proposal evaluation"],"zh":["Clinical Value AI工具","AI工具设置","研究案评估","临床价值评估","患者贡献度分析","临床医生贡献度分析","医疗系统贡献度分析"],"ja":["Clinical Value AIエージェント","AIエージェントの設定","研究案の評価","臨床的価値の評価","患者への貢献度分析","臨床医への貢献度分析","医療システムへの貢献度分析"],"ko":["클리니컬 밸류 AI 에이전트","AI 에이전트 설정","연구 제안 평가","임상 가치 평가","환자 기여도 분석","임상 의사 기여도 분석","의료 시스템 기여도 분석"],"es":["valor clínico","AI Agent","investigación clínica","evaluación de tratamientos","práctica clínica","sistemas de salud","medicamentos","indicaciones específicas","población objetivo"],"fr":["valeur clinique","outils d''IA","recherche clinique","évaluation de traitements","pratique clinique","systèmes de santé","médicaments","indications spécifiques","population cible"],"de":["klinischer Wert","AI-Tool","klinische Forschung","Bewertung von Behandlungen","klinische Praxis","Gesundheitssysteme","Medikamente","spezifische Indikationen","Zielgruppe"],"pt":["Valor Clínico","Avaliação de propostas de pesquisa","Medicina baseada em evidências","CLI","React","Python","Análise de dados de pacientes","Tomada de decisões clínicas","Tecnologias de saúde"],"ru":["Клиническая ценность","Оценка исследовательских предложений","Медицина, основанная на доказательствах","CLI","React","Python","Анализ данных пациентов","Принятие клинических решений","Технологии здравоохранения"],"ar":["قيمة العلاج السريري","تقييم مقترحات البحث","الطب المبني على الأدلة","CLI","React","Python","تحليل بيانات المرضى","اتخاذ القرارات السريرية","تكنولوجيا الصحة"]}},"owner":"tito-gh","repo":"healthcare","repoPath":"tito-gh/healthcare","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.620Z","topics":[],"category":"community","skillMd":{"name":"clinical-value","description":"|","bodyPreview":"# Clinical Value Skill\n\n## 目的\n研究案の臨床的価値を体系的に評価し、患者・臨床医・医療システムへの貢献度を定量化する。\n\n## 入力パラメータ\n\n| パラメータ | 必須 | 説明 | 例 |\n|-----------|------|------|-----|\n| RESEARCH_PROPOSAL | Yes | 研究案の概要 | DRd vs VRd比較効果研究 |\n| DRUG | Yes | 対象薬剤 | daratumumab |\n| INDICATION | Yes | 対象疾患 | NDMM |\n| TARGET_POPULATION | Yes | 対象患者集団 | TIE elderly patients |\n| CLINICAL_QUESTION | Yes | 臨床的問い | Which regimen is superior for frail patients? |\n| CURRENT_PRACTICE | No | 現在の標準治療 | VRd or DRd based on availability |\n\n## 臨床的価値評価フレ","body":"# Clinical Value Skill\n\n## 目的\n研究案の臨床的価値を体系的に評価し、患者・臨床医・医療システムへの貢献度を定量化する。\n\n## 入力パラメータ\n\n| パラメータ | 必須 | 説明 | 例 |\n|-----------|------|------|-----|\n| RESEARCH_PROPOSAL | Yes | 研究案の概要 | DRd vs VRd比較効果研究 |\n| DRUG | Yes | 対象薬剤 | daratumumab |\n| INDICATION | Yes | 対象疾患 | NDMM |\n| TARGET_POPULATION | Yes | 対象患者集団 | TIE elderly patients |\n| CLINICAL_QUESTION | Yes | 臨床的問い | Which regimen is superior for frail patients? |\n| CURRENT_PRACTICE | No | 現在の標準治療 | VRd or DRd based on availability |\n\n## 臨床的価値評価フレームワーク\n\n### 1. 患者アウトカムへの影響（Patient Outcomes Impact）\n\n| 評価項目 | 評価基準 | スコア (1-5) |\n|----------|----------|-------------|\n| **生存改善可能性** | 死亡率・OS改善への寄与 | |\n| **QOL改善可能性** | 症状・機能・PRO改善への寄与 | |\n| **有害事象回避** | 毒性・副作用軽減への寄与 | |\n| **治療負担軽減** | 通院・入院・費用負担軽減 | |\n| **個別化治療への貢献** | 患者特性に応じた治療選択支援 | |\n\n### 2. 臨床意思決定への影響（Clinical Decision Impact）\n\n| 評価項目 | 評価基準 | スコア (1-5) |\n|----------|----------|-------------|\n| **エビデンスギャップ充足** | 現在の不確実性解消への貢献 | |\n| **治療選択への影響** | 実臨床での処方行動変化 | |\n| **患者説明への活用** | IC・shared decision making支援 | |\n| **リスク層別化への貢献** | 予後予測・リスク評価改善 | |\n| **適正使用への貢献** | 過少/過剰使用是正 | |\n\n### 3. 医療システムへの影響（Healthcare System Impact）\n\n| 評価項目 | 評価基準 | スコア (1-5) |\n|----------|----------|-------------|\n| **ガイドライン改訂可能性** | 推奨変更への寄与 | |\n| **保険収載・償還への影響** | 薬価・適応拡大への寄与 | |\n| **医療資源適正化** | コスト・資源配分最適化 | |\n| **医療格差是正** | アクセス・公平性改善 | |\n| **医療安全向上** | 安全性監視・リスク管理改善 | |\n\n### 4. エビデンスの質と適用性（Evidence Quality & Applicability）\n\n| 評価項目 | 評価基準 | スコア (1-5) |\n|----------|----------|-------------|\n| **内的妥当性** | バイアス最小化、方法論的質 | |\n| **外的妥当性** | 日本実臨床への適用可能性 | |\n| **効果の大きさ** | 臨床的に意味のある差か | |\n| **精度** | 十分なサンプルサイズ・信頼区間 | |\n| **一貫性** | 先行研究との整合性 | |\n\n## 臨床価値スコアリング\n\n### 総合臨床価値スコア算出\n\n```\nClinical Value Score =\n  (Patient Outcomes × 0.35) +\n  (Clinical Decision × 0.30) +\n  (Healthcare System × 0.20) +\n  (Evidence Quality × 0.15)\n```\n\n### スコア解釈\n\n| スコア範囲 | 臨床価値レベル | 解釈 |\n|-----------|---------------|------|\n| 4.5-5.0 | **Transformative** | 診療を根本的に変える可能性 |\n| 3.5-4.4 | **High** | 重要な臨床的貢献が期待 |\n| 2.5-3.4 | **Moderate** | 一定の臨床的意義あり |\n| 1.5-2.4 | **Limited** | 限定的な臨床的意義 |\n| 1.0-1.4 | **Minimal** | 臨床的意義乏しい |\n\n## 出力フォーマット\n\n```markdown\n# Clinical Value Assessment: {RESEARCH_PROPOSAL}\n\n## 1. 臨床的文脈\n\n### 現在の臨床課題\n- 対象疾患: {INDICATION}\n- 対象薬剤: {DRUG}\n- 対象患者: {TARGET_POPULATION}\n- 臨床的問い: {CLINICAL_QUESTION}\n- 現在の標準治療: {CURRENT_PRACTICE}\n- **未充足臨床ニーズ**: [具体的記述]\n\n### 関連ガイドライン・推奨\n| 発行元 | 現在の推奨 | エビデンスレベル | 参照 |\n|--------|-----------|----------------|------|\n| NCCN | ... | ... | URL |\n| ESMO | ... | ... | URL |\n| 日本血液学会 | ... | ... | URL |\n\n## 2. 臨床価値評価\n\n### 2.1 患者アウトカムへの影響\n| 項目 | スコア | 根拠 |\n|------|--------|------|\n| 生存改善可能性 | X/5 | ... |\n| QOL改善可能性 | X/5 | ... |\n| 有害事象回避 | X/5 | ... |\n| 治療負担軽減 | X/5 | ... |\n| 個別化治療貢献 | X/5 | ... |\n| **小計** | X.X/5.0 | |\n\n### 2.2 臨床意思決定への影響\n| 項目 | スコア | 根拠 |\n|------|--------|------|\n| エビデンスギャップ充足 | X/5 | ... |\n| 治療選択への影響 | X/5 | ... |\n| 患者説明への活用 | X/5 | ... |\n| リスク層別化貢献 | X/5 | ... |\n| 適正使用貢献 | X/5 | ... |\n| **小計** | X.X/5.0 | |\n\n### 2.3 医療システムへの影響\n| 項目 | スコア | 根拠 |\n|------|--------|------|\n| ガイドライン改訂可能性 | X/5 | ... |\n| 保険収載・償還影響 | X/5 | ... |\n| 医療資源適正化 | X/5 | ... |\n| 医療格差是正 | X/5 | ... |\n| 医療安全向上 | X/5 | ... |\n| **小計** | X.X/5.0 | |\n\n### 2.4 エビデンス質と適用性\n| 項目 | スコア | 根拠 |\n|------|--------|------|\n| 内的妥当性 | X/5 | ... |\n| 外的妥当性 | X/5 | ... |\n| 効果の大きさ | X/5 | ... |\n| 精度 | X/5 | ... |\n| 一貫性 | X/5 | ... |\n| **小計** | X.X/5.0 | |\n\n## 3. 総合臨床価値スコア\n\n| カテゴリ | スコア | 重み | 加重スコア |\n|---------|--------|------|-----------|\n| Patient Outcomes | X.X | 0.35 | X.XX |\n| Clinical Decision | X.X | 0.30 | X.XX |\n| Healthcare System | X.X | 0.20 | X.XX |\n| Evidence Quality | X.X | 0.15 | X.XX |\n| **総合** | - | - | **X.XX/5.0** |\n\n### 臨床価値レベル: **[Transformative/High/Moderate/Limited/Minimal]**\n\n## 4. EHR-RWDによる臨床価値向上\n\n### クレームDB研究との差別化による追加価値\n| 観点 | クレームDB | EHR-RWD | 臨床価値への貢献 |\n|------|-----------|---------|-----------------|\n| 詳細臨床情報 | × | ○ | 患者選択精度向上 |\n| 検査値推移 | × | ○ | 効果/安全性評価精度向上 |\n| 経過記録 | × | ○ | アウトカム定義精度向上 |\n\n## 5. 限界と不確実性\n\n1. [限界1]\n2. [限界2]\n3. [不確実性要因]\n\n## 6. 臨床的推奨\n\n### 研究実施推奨度: **[強く推奨 / 推奨 / 条件付推奨 / 非推奨]**\n\n### 理由\n[推奨理由の詳細]\n\n### 想定される臨床インパクト\n[研究結果が陽性だった場合の臨床実践への影響予測]\n```\n\n## 注意事項\n\n1. **患者視点の重視**: 患者アウトカムへの影響を最重要視\n2. **現実的評価**: 理論的価値と実臨床での実装可能性を区別\n3. **エビデンスの質**: 研究デザインの限界が臨床価値を制限する点を考慮\n4. **根拠の明示**: 各評価に文献的根拠またはエキスパートオピニオンを明記\n5. **比較対象の明確化**: 現在の標準治療・既存エビデンスとの比較で価値を評価\n"},"lastSynced":"2026-03-08T02:13:28.708Z","agentAnalysis":{"suitability":{"en":"Ideal for Healthcare Agents requiring systematic evaluation of research proposals and quantification of clinical contributions.","zh":"适合需要系统评估研究提案和量化临床贡献的医疗代理","ja":"医療エージェントが研究提案の体系的な評価と臨床的貢献の量化を必要とする場合に最適","ko":"연구 제안의 체계적인 평가와 임상 기여도를 정량화해야 하는 의료 에이전트에 적합","es":"Ideal para agentes de atención médica que requieren una evaluación sistemática de propuestas de investigación y cuantificación de contribuciones clínicas.","fr":"Idéal pour les agents de soins de santé nécessitant une évaluation systématique des propositions de recherche et une quantification des contributions cliniques.","de":"Ideal für Gesundheitsagenten, die eine systematische Bewertung von Forschungsvorschlägen und eine Quantifizierung von klinischen Beiträgen erfordern.","pt":"Ideal para Agentes de Saúde que exigem avaliação sistemática de propostas de pesquisa e quantificação de contribuições clínicas.","ru":"Идеально для агентов здравоохранения, требующих систематической оценки исследовательских предложений и количественной оценки клинических вкладов.","ar":"مثالي للوكلاء الصحيين الذين يحتاجون إلى تقييم منهجي لل提ارات البحثية وقياس الإسهامات السريرية."},"recommendation":{"en":"Empowers agents to assess the clinical value of research proposals by evaluating patient, clinician, and healthcare system contributions, utilizing parameters such as research proposal overview, target drug, indication, target population, and clinical questions, all while considering current practice standards like VRd or DRd availability.","zh":"使代理能够通过评估患者、临床医生和医疗系统的贡献来评估研究提案的临床价值，利用诸如研究提案概述、目标药物、适应症、目标人群和临床问题等参数，同时考虑当前的实践标准，如VRd或DRd的可用性","ja":"エージェントが研究提案の臨床的価値を評価できるようにし、患者、臨床医、医療システムの貢献を評価し、研究提案の概要、標的薬、適応症、標的集団、臨床的疑問などをパラメータとして使用し、VRdまたはDRdの可用性などの現在の慣行標準も考慮する","ko":"에이전트가 연구 제안의 임상 가치를 평가할 수 있도록 하며, 환자, 임상 의사, 의료 시스템의 기여를 평가하고, 연구 제안 개요, 표적 약물, 적응증, 표적 인구, 임상 질문 등을 매개변수로 사용하며, VRd 또는 DRd의 가용성과 같은 현재의 실무 표준도 고려","es":"Habilita a los agentes a evaluar el valor clínico de las propuestas de investigación evaluando las contribuciones de los pacientes, los clínicos y los sistemas de salud, utilizando parámetros como la descripción general de la propuesta de investigación, el fármaco objetivo, la indicación, la población objetivo y las preguntas clínicas, considerando al mismo tiempo las normas de práctica actual como la disponibilidad de VRd o DRd.","fr":"Permet aux agents d''évaluer la valeur clinique des propositions de recherche en évaluant les contributions des patients, des cliniciens et des systèmes de santé, en utilisant des paramètres tels que la vue d''ensemble de la proposition de recherche, le médicament cible, l''indication, la population cible et les questions cliniques, en tenant compte des normes de pratique actuelles comme la disponibilité de VRd ou DRd.","de":"Ermächtigt die Agenten, den klinischen Wert von Forschungsvorschlägen zu bewerten, indem sie die Beiträge von Patienten, Klinikern und Gesundheitssystemen unter Verwendung von Parametern wie der Übersicht über den Forschungsvorschlag, dem Zielmedikament, der Indikation, der Zielbevölkerung und den klinischen Fragen bewerten, während sie gleichzeitig die aktuellen Praxisstandards wie die Verfügbarkeit von VRd oder DRd berücksichtigen.","pt":"Habilita os agentes a avaliar o valor clínico das propostas de pesquisa avaliando as contribuições do paciente, clínico e sistema de saúde, utilizando parâmetros como visão geral da proposta de pesquisa, droga-alvo, indicação, população-alvo e questões clínicas, considerando os padrões de prática atuais como a disponibilidade de VRd ou DRd.","ru":"Наделяет агентов возможностью оценивать клиническую ценность исследовательских предложений, оценивая вклады пациентов, клиницистов и систем здравоохранения, используя параметры, такие как обзор исследовательского предложения, целевое лекарство, показание, целевая популяция и клинические вопросы, учитывая текущие стандарты практики, такие как доступность VRd или DRd.","ar":"تمكّن الوكلاء من تقييم القيمة السريرية لخطط البحث من خلال تقييم مساهمات المريض والأخصائي والمنظومة الصحية، باستخدام معايير مثل نظرة عامة على خطة البحث، الدواء المستهدف، الإشارة، السكان المستهدفون، والأسئلة السريرية، في ظل مراعاة معايير الممارسة الحالية مثل توافر VRd أو DRd."},"useCases":{"en":["Evaluating the clinical value of new drug regimens like DRd vs VRd for specific patient populations","Quantifying the contributions of research proposals to clinicians and healthcare systems","Assessing the impact of current practice standards on patient outcomes"],"zh":["评估新药治疗方案（如DRd与VRd）对特定患者人群的临床价值","量化研究提案对临床医生和医疗系统的贡献","评估当前实践标准对患者结果的影响"],"ja":["特定の患者集団に対する新薬治療法（DRdとVRdなど）の臨床的価値を評価","臨床医と医療システムに対する研究提案の貢献を量化","現在の実践標準が患者結果に与える影響を評価"],"ko":["특정 환자 집단에 대한 새로운 약물 치료法(예: DRd vs VRd)의 임상 가치를 평가","임상 의사와 의료 시스템에 대한 연구 제안의 기여도를 정량화","현재의 실무 표준이 환자 결과에 미치는 영향을 평가"],"es":["Evaluar el valor clínico de nuevos regímenes de medicamentos como DRd frente a VRd para poblaciones de pacientes específicas","Cuantificar las contribuciones de las propuestas de investigación a los clínicos y los sistemas de salud","Evaluar el impacto de las normas de práctica actual en los resultados de los pacientes"],"fr":["Évaluer la valeur clinique de nouveaux régimes de médicaments comme DRd par rapport à VRd pour des populations de patients spécifiques","Quantifier les contributions des propositions de recherche aux cliniciens et aux systèmes de santé","Évaluer l''impact des normes de pratique actuelles sur les résultats des patients"],"de":["Bewerten des klinischen Wertes neuer Medikamentenschemata wie DRd im Vergleich zu VRd für spezifische Patientenpopulationen","Quantifizieren der Beiträge von Forschungsvorschlägen zu Klinikern und Gesundheitssystemen","Bewerten des Einflusses der aktuellen Praxisstandards auf die Patientenergebnisse"],"pt":["Avaliando o valor clínico de novos regimes de medicamentos como DRd vs VRd para populações de pacientes específicas","Quantificando as contribuições das propostas de pesquisa para clínicos e sistemas de saúde","Avaliando o impacto dos padrões de prática atuais nos resultados dos pacientes"],"ru":["Оценивая клиническую ценность новых режимов лекарств, таких как DRd vs VRd, для конкретных популяций пациентов","Количественно оценивая вклады исследовательских предложений для клиницистов и систем здравоохранения","Оценивая влияние текущих стандартов практики на результаты лечения пациентов"],"ar":["تقييم القيمة السريرية لنظم جديدة من الأدوية مثل DRd مقابل VRd لأفراد السكان المستهدفين","تحديد كمية مساهمات خطط البحث للأخصائيين والمنظومات الصحية","تقييم تأثير معايير الممارسة الحالية على نتائج المرضى"]},"limitations":{"en":["Requires detailed research proposal information","Limited to evaluating clinical value based on predefined parameters","Dependent on accurate and up-to-date clinical data"],"zh":["需要详细的研究提案信息","仅限于根据预定义参数评估临床价值","依赖于准确且最新的临床数据"],"ja":["詳細な研究提案情報が必要","予定義されたパラメータに基づいて臨床的価値を評価することのみ可能","正確で最新の臨床データに依存"],"ko":["詳細한 연구 제안 정보가 필요","预정의된 매개변수를 기준으로 임상 가치를 평가하는 것만 가능","정확하고 최신의 임상 데이터에 의존"],"es":["Requiere información detallada sobre la propuesta de investigación","Limitado a la evaluación del valor clínico en función de parámetros predefinidos","Dependiente de datos clínicos precisos y actualizados"],"fr":["Nécessite des informations détaillées sur la proposition de recherche","Limité à l''évaluation de la valeur clinique sur la base de paramètres prédéfinis","Dépendant de données cliniques précises et à jour"],"de":["Benötigt detaillierte Informationen über den Forschungsvorschlag","Begrenzt auf die Bewertung des klinischen Wertes auf der Grundlage von vordefinierten Parametern","Abhängig von genauen und aktuellen klinischen Daten"],"pt":["Exige informações detalhadas sobre a proposta de pesquisa","Limitado à avaliação do valor clínico com base em parâmetros predefinidos","Dependente de dados clínicos precisos e atualizados"],"ru":["Требует подробной информации о исследовательском предложении","Ограничен оценкой клинической ценности на основе предварительно определенных параметров","Зависит от точных и актуальных клинических данных"],"ar":["يتطلب معلومات مفصلة عن خطة البحث","محدود بتقييم القيمة السريرية بالاعتماد على معايير محددة مسبقا","يعتمد على بيانات سريرية دقيقة ومحدّثة"]},"version":4},"contentHash":"8893f236225eeef0515b5b3d932d8c51d5699b3448363f4f823fed064ee6972c","qualityScore":30}');
