INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tito-gh/healthcare/clinical-value', 'clinical-value', 'tito-gh', 'healthcare', 'community', 'clinical-value tito-gh healthcare community The clinical-value skill systematically evaluates the clinical value of research proposals, quantifying contributions to patients, clinicians, and healthcare systems. It benefits researchers, clinicians, and healthcare professionals. Clinical Value AI工具用于评估研究案的临床价值，提供定量化的患者、临床医生和医疗系统的贡献度分析 Clinical Value AIエージェントは、研究案の臨床的価値を体系的に評価し、患者・臨床医・医療システムへの貢献度を定量化する 클리니컬 밸류 AI 에이전트는 연구 제안의 임상 가치를 체계적으로 평가하고 환자, 임상 의사, 의료 시스템에 대한 기여도를 정량화함 El AI Agent de valor clínico evalúa sistemáticamente el valor clínico de las propuestas de investigación y cuantifica su contribución a los pacientes, médicos y sistemas de salud. L''outil d''IA de valeur clinique évalue systématiquement la valeur clinique des propositions de recherche et quantifie sa contribution aux patients, aux médecins et aux systèmes de santé. Das AI-Tool für den klinischen Wert bewertet systematisch den klinischen Wert von Forschungsvorschlägen und quantifiziert seinen Beitrag zu Patienten, Ärzten und Gesundheitssystemen. O Valor Clínico é uma habilidade que avalia a contribuição de propostas de pesquisa para a medicina baseada em evidências ИИ Агент для оценки клинической ценности помогает оценить эффективность исследований в области медицины قيمة العلاج السريري هي مهارة تقييم مساهمات مقترحات البحث في الطب المبني على الأدلة how to use clinical-value what is clinical-value clinical-value alternative clinical-value vs other research evaluation tools clinical-value install clinical-value setup guide quantifying research impact clinical value assessment research proposal evaluation Clinical Value AI工具 AI工具设置 研究案评估 临床价值评估 患者贡献度分析 临床医生贡献度分析 医疗系统贡献度分析 Evaluates research proposals based on parameters like RESEARCH_PROPOSAL, DRUG, INDICATION, and TARGET_POPULATION Quantifies contributions to patients, clinicians, and healthcare systems using a systematic approach Supports input parameters like CLINICAL_QUESTION and CURRENT_PRACTICE for tailored evaluations Provides a structured framework for assessing clinical value, including a clinical value assessment formula Enables researchers to compare treatment regimens, such as DRd vs VRd, and their effects on specific patient populations Clinical-value is a skill that evaluates the clinical value of research proposals, assessing their impact on patients, clinicians, and healthcare systems.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jehna/vibecad-studio/vibe-model', 'community', 'jehna', 'vibecad-studio', 'jehna/vibecad-studio', 'vibe-model', 0, 0, 30, '2026-03-08T01:57:15.635Z', '2026-03-08T02:13:37.329Z', '959e9639ea965a1afb4beb6bc53f28c37cfb7ea72ee0f5d9a5d82cd950d6a652', '{"id":"jehna/vibecad-studio/vibe-model","name":"vibe-model","description":{"en":"The vibe-model skill allows developers to create or modify parametric 3D models for VibeCad Studio using OpenSCAD. It benefits developers working with browser-based parametric CAD workbenches.","zh":"Vibe-model是一个用于创建和修改parametric 3D模型的工具，使用OpenSCAD和VibeCad Studio","ja":"Vibe-modelは、OpenSCADとVibeCad Studioを使用してパラメトリック3Dモデルを作成と編集するツール","ko":"Vibe-model은 OpenSCAD와 VibeCad Studio를 사용하여 파라메트릭 3D 모델을 생성하고 수정하는 도구","es":"Vibe-Model es una habilidad que permite crear o modificar modelos 3D paramétricos para VibeCad Studio utilizando OpenSCAD. Los modelos se escriben en archivos .scad y se compilan a STL mediante openscad-wasm","fr":"Vibe-Model est une compétence qui permet de créer ou de modifier des modèles 3D paramétriques pour VibeCad Studio en utilisant OpenSCAD. Les modèles sont écrits dans des fichiers .scad et compilés en STL via openscad-wasm","de":"Vibe-Model ist eine Fähigkeit, die die Erstellung oder Modifizierung von parametrischen 3D-Modellen für VibeCad Studio mit OpenSCAD ermöglicht. Die Modelle werden in .scad-Dateien geschrieben und über openscad-wasm in STL kompiliert","pt":"O Vibe-Model é uma ferramenta para criar ou modificar modelos 3D paramétricos para VibeCad Studio usando OpenSCAD. Os modelos são compilados para STL via openscad-wasm.","ru":"Vibe-Model — это инструмент для создания или изменения параметрических 3D-моделей для VibeCad Studio с помощью OpenSCAD. Модели компилируются в STL через openscad-wasm.","ar":"Vibe-Model هو أداة لإنشاء أو تعديل نماذج 3D متعددة المعلمات لاستوديو VibeCad باستخدام OpenSCAD. يتم تجميع النماذج إلى STL عبر openscad-wasm."},"seo":{"title":{"en":"vibe-model: Parametric 3D Modeling Setup Guide | AI Agent...","zh":"Vibe-model-parametric-3D-模型创建指南","ja":"Vibe-model: OpenSCADを使用したパラメトリック3Dモデルの作成","ko":"Vibe-model: OpenSCAD를 이용한 파라메트릭 3D 모델 생성 가이드","es":"Guía de configuración de Vibe-Model: Creación de modelos ...","fr":"Guide de configuration de Vibe-Model: Création de modèles...","de":"Vibe-Model Konfigurationsleitfaden: Erstellung von parame...","pt":"Guia de Configuração do Vibe-Model para Desenvolvedores","ru":"Настройка Vibe-Model: ИИ Агенты для 3D Моделирования","ar":"دليل إعداد Vibe-Model لإنشاء نماذج 3D بالاعتماد على أدوات..."},"description":{"en":"Discover how to create and modify parametric 3D models for VibeCad Studio using OpenSCAD and openscad-wasm. Get started with vibe-model today!","zh":"了解Vibe-model的特点和功能，创建和修改parametric 3D模型，使用OpenSCAD和VibeCad Studio","ja":"Vibe-modelの機能と特徴を学び、OpenSCADとVibeCad Studioを使用してパラメトリック3Dモデルを作成と編集","ko":"Vibe-model의 특징과 기능을 알아보세요. OpenSCAD와 VibeCad Studio를 사용하여 파라메트릭 3D 모델을 생성하고 수정","es":"Aprende a crear o modificar modelos 3D paramétricos para VibeCad Studio utilizando OpenSCAD y descubre cómo funcionan los modelos en este entorno de trabajo ...","fr":"Découvrez comment créer ou modifier des modèles 3D paramétriques pour VibeCad Studio en utilisant OpenSCAD et explorez le fonctionnement des modèles dans cet...","de":"Erfahren Sie, wie Sie parametrische 3D-Modelle für VibeCad Studio mit OpenSCAD erstellen oder modifizieren und entdecken Sie, wie Modelle in dieser browserba...","pt":"Aprenda a criar ou modificar modelos 3D paramétricos para VibeCad Studio usando OpenSCAD e descubra como os modelos são auto-descobertos","ru":"Узнайте, как создавать или изменять параметрические 3D-модели для VibeCad Studio с помощью OpenSCAD и откройте для себя автоматическое обнаружение моделей","ar":"تعلم كيفية إنشاء أو تعديل نماذج 3D متعددة المعلمات لاستوديو VibeCad باستخدام O