INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('end8cl01g/focustimer/javascript-typescript', 'javascript-typescript', 'end8cl01g', 'focustimer', 'community', 'javascript-typescript end8cl01g focustimer community The javascript-typescript skill enables developers to leverage advanced TypeScript configurations for efficient JavaScript development, targeting ES2022 and utilizing ESNext modules. 本文介绍如何配置TypeScript以提高JavaScript开发效率，包括compilerOptions和模块解析等 JavaScript/TypeScript開発のためのTypeScript設定方法を紹介します - AIエージェント TypeScript를 사용하여 JavaScript 개발 환경을 설정하는 방법을 알아봅니다 Configuración de TypeScript para desarrollo de JavaScript con opciones de compilador avanzadas Configuration de TypeScript pour le développement JavaScript avec des options de compilateur avancées Konfiguration von TypeScript für die JavaScript-Entwicklung mit erweiterten Compiler-Optionen O JavaScript/TypeScript é uma tecnologia poderosa para desenvolvedores. Aprenda a configurar o TypeScript para melhorar a produtividade TypeScript - это мощный инструмент для разработчиков. Узнайте, как настроить компилятор и улучшить код JavaScript/TypeScript هو أداة قوية للمطورين. استكشف كيفية إعداد TypeScript لتحسين الإنتاجية how to use javascript-typescript javascript-typescript setup guide typescript configuration best practices javascript-typescript vs javascript javascript-typescript install what is javascript-typescript typescript compiler options es2022 target esnext modules JavaScript开发 TypeScript配置 compilerOptions 模块解析 ES2022 ESNext 严格模式 Utility Types TypeScript开发环境 Utilizes TypeScript compiler options for ES2022 target and ESNext modules Supports strict mode with noUncheckedIndexedAccess and noImplicitOverride Enables declaration file generation and output directory specification Includes src directory and excludes node_modules and dist for compilation Allows for utility types like Pick for specific property selection Configures module resolution for bundlers javascript-typescript is a skill that combines JavaScript and TypeScript development, utilizing compiler options like strict mode and module resolution for bundlers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shaul1991/shaul-agents-plugin/qa-tester', 'community', 'shaul1991', 'shaul-agents-plugin', 'shaul1991/shaul-agents-plugin', 'qa-tester', 0, 0, 30, '2026-03-08T01:57:15.658Z', '2026-03-08T02:14:00.026Z', '366cc2396a8cad3ec2045594d12798ddde26a881981e34179aacaf16fe657e4c', '{"id":"shaul1991/shaul-agents-plugin/qa-tester","name":"qa-tester","description":{"en":"The qa-tester skill enables developers to write and execute tests using Jest, Supertest, and jest.mock, streamlining their testing process. It benefits developers working with multi-agent collaboration systems.","zh":"QA Tester Agent 是一个使用 Jest 和 Supertest 进行自动化测试的工具，支持单元测试、集成测试和 E2E 测试","ja":"QA テスター エージェントは、Jest と Supertest を使用して自動化テストを実行する AI エージェントです","ko":"QA 테스터 에이전트는 Jest와 Supertest를 사용하여 자동화 테스트를 수행하는 멀티에이전트 협업 시스템의 플러그인입니다","es":"El agente de test QA es responsable de escribir y ejecutar tests, utilizando Jest y Supertest para garantizar la calidad de las aplicaciones","fr":"L''agent de test QA est responsable de la rédaction et de l''exécution de tests, en utilisant Jest et Supertest pour assurer la qualité des applications","de":"Der QA-Tester-Agent ist verantwortlich für das Schreiben und Ausführen von Tests, um die Qualität von Anwendungen mit Jest und Supertest zu gewährleisten","pt":"O QA Tester é um agente de teste automatizado que utiliza Jest, Supertest e jest.mock para garantir a qualidade do código","ru":"ИИ Агент QA Tester - это автоматизированный агент тестирования, использующий Jest, Supertest и jest.mock для обеспечения качества кода","ar":"جهاز QA Tester هو جهاز اختبار آلي يستخدم Jest و Supertest و jest.mock لضمان جودة الكود"},"seo":{"title":{"en":"qa-tester: Jest-Based Testing Setup Guide | AI Agent Skill","zh":"QA Tester Agent 设置指南 - Jest 和 Supertest","ja":"QA テスター エージェントのベストプラクティス - AIエージェントの活用","ko":"QA 테스터 에이전트 설정 가이드 - Jest와 Supertest를 이용한 테스트 자동화","es":"Guía de configuración de QA Tester Agent con Jest y Super...","fr":"Guide de mise en place de l''agent de test QA avec Jest et...","de":"Einrichtungsleitfaden für QA-Tester-Agent mit Jest und Su...","pt":"Guia de Configuração do QA Tester: Ferramentas de Teste A...","ru":"Настройка ИИ Агента QA Tester: Руководство по автоматизир...","ar":"دليل إعداد جهاز QA Tester: أدوات اختبار آلية"},"description":{"en":"Discover how to leverage qa-tester for efficient testing with Jest, Supertest, and jest.mock. Get started with our expert guide and optimize your testing wor...","zh":"了解 QA Tester Agent 的技术细节和设置方法，使用 Jest 和 Supertest 进行自动化测试","ja":"QA テスター エージェントの機能と設定方法を紹介します。AIエージェントを活用してテスト自動化を実現しましょう","ko":"QA 테스터 에이전트의 역할과 기술 스택을 자세히 알아보고, Jest와 Supertest를 이용한 테스트 자동화를 설정하는 방법을 알아보세요","es":"Aprende a configurar y ejecutar tests con QA Tester Agent, utilizando Jest y Supertest para garantizar la calidad de tus aplicaciones","fr":"Découvrez comment configurer et exécuter des tests avec l''agent de test QA, en utilisant Jest et Supertest pour assurer la qualité de vos applications","de":"Erfahren Sie, wie Sie QA-Tester-Agent konfigurieren und Tests ausführen, um die Qualität Ihrer Anwendungen mit Jest und Supertest zu gewährleisten","pt":"Aprenda a configurar e utilizar o QA Tester com Jest, Supertest e jest.mock para melhorar a eficiência dos testes automatizados","ru":"Узнайте, как настроить и использовать ИИ Агент QA Tester с Jest, Supertest и jest.mock для повышения эффективности автоматизированного тестирования","ar":"تعرف على كيفية إعداد و استخدام جهاز QA Tester مع Jest و Supertest و jest.mock لتحسين كفاءة الاختبارات الآلية"},"definition":{"en":"qa-tester is a testing framework that utilizes Jest, Supertest, and jest.mock to facilitate unit, integration, and E2E testing for multi-agent systems.","zh":"QA Tester Agent 是一个自动化测试工具，使用 Jest 和 Supertest 进行单元测试、集成测试和 E2E 测试","ja":"QA テスター エージェントは、自動化テストを実行する AI エージェントで、Jest と Supertest を使用します","ko":"QA 테스터 에이전트는 자동화 테스트를 수행하는 에이전트로 Jest와 Supertest를 사용하여 단위 테스트, 통합 테스트, E2E 테스트를 지원합니다","es":"Un agente de test QA es una herramienta que utiliza Jest y Supertest para automatizar la ejecución de tests y garantizar la calidad de las aplicaciones","fr":"Un agent de test QA est un outil qui utilise Jest et Supertest pour automatiser l''exécution de tests et assurer la qualité des applications","de":"Ein QA-Tester-Agent ist ein Tool, das Jest und Supertest verwendet, um die Ausführung von Tests zu automatisieren und die Qualität von Anwendungen zu gewährleisten","pt":"O QA Tester é um agente de software que executa testes automatizados para garantir a qualidade do código","ru":"ИИ Агент QA Tester - это программный агент, выполняющий автоматизированные тесты для обеспечения качества кода","ar":"جهاز QA Tester هو برنامج يؤدي اختبارات آلية لضمان جودة الكود"},"features":{"en":["Utilizes Jest framework for unit testing","Employs Supertest for End-to-End (E2E) testing","Leverages jest.mock and jest.spyOn for mocking dependencies","Supports a structured test directory with unit, integration, and e2e test folders","Executes tests using npm run test command"],"zh":["使用 Jest 进行单元测试","使用 Supertest 进行 E2E 测试","支持集成测试","使用 jest.mock 和 jest.spyOn 进行模拟测试","支持测试数据管理"],"ja":["Jest を使用したユニットテスト","Supertest を使用した E2E テスト","統合テストのサポート","jest.mock と jest.spyOn を使用したモックテスト","テストデータ管理のサポート"],"ko":["Jest를 사용한 단위 테스트","Supertest를 사용한 E2E 테스트","통합 테스트 지원","jest.mock와 jest.spyOn를 사용한 모의 테스트","테스트 데이터 관리 지원"],"es":["Utiliza Jest como framework de testing","Soporta testing de extremo a extremo con Supertest","Permite la creación de mocks con jest.mock y jest.spyOn","Estructura de testing modular con carpetas para unit tests, integration tests y e2e tests","Soporta la ejecución de tests con npm run test"],"fr":["Utilise Jest comme framework de testing","Prend en charge les tests de bout en bout avec Supertest","Permet la création de mocks avec jest.mock et jest.spyOn","Structure de testing modulaire avec des dossiers pour les tests unitaires, les tests d''intégration et les tests e2e","Prend en charge l''exécution de tests avec npm run test"],"de":["Verwendet Jest als Test-Framework","Unterstützt End-to-End-Testing mit Supertest","Ermöglicht die Erstellung von Mocks mit jest.mock und jest.spyOn","Modulare Teststruktur mit Ordnern für Unit-Tests, Integrationstests und e2e-Tests","Unterstützt die Ausführung von Tests mit npm run test"],"pt":["Utiliza Jest como framework de teste","Suporta testes E2E com Supertest","Utiliza jest.mock e jest.spyOn para mockar dependências","Estrutura de teste modular com pastas para unit, integração e E2E","Comandos de teste personalizados com npm run test"],"ru":["Использует Jest в качестве фреймворка для тестирования","Поддерживает тесты E2E с Supertest","Использует jest.mock и jest.spyOn для模окирования зависимостей","Модульная структура тестирования с папками для unit, интеграции и E2E","Пользовательские команды тестирования с npm run test"],"ar":["يستخدم Jest كإطار اختبار","يدعم الاختبارات E2E مع Supertest","يستخدم jest.mock و jest.spyOn لمحاكاة الاعتماديات","هيكل اختبار معماري مع مجلدات للوحدات و التكامل و E2E","أوامر اختبار مخصصة مع npm run test"]},"keywords":{"en":["how to use qa-tester","qa-tester setup guide","qa-tester vs jest","qa-tester install","what is qa-tester","qa-tester alternative","qa-tester tutorial","qa-tester testing framework","qa-tester multi-agent systems"],"zh":["QA Tester Agent","Jest","Supertest","自动化测试","单元测试","集成测试","E2E 测试","AI 工具"],"ja":["QA テスター エージェント","Jest","Supertest","自動化テスト","ユニットテスト","統合テスト","E2E テスト","AI エージェント"],"ko":["QA 테스터 에이전트","Jest","Supertest","자동화 테스트","단위 테스트","통합 테스트","E2E 테스트","AI 도구"],"es":["QA Tester Agent","Jest","Supertest","testing de software","automatización de tests","desarrollo de aplicaciones","calidad de software","herramientas de testing","framework de testing"],"fr":["Agent de test QA","Jest","Supertest","test de logiciel","automatisation de tests","développement d''applications","qualité de logiciel","outils de testing","framework de testing"],"de":["QA-Tester-Agent","Jest","Supertest","Software-Testen","Automatisierung von Tests","Anwendungs-Entwicklung","Software-Qualität","Test-Tools","Test-Framework"],"pt":["QA Tester","teste automatizado","Jest","Supertest","jest.mock","desenvolvimento de software","qualidade de código","ferramentas de teste"],"ru":["ИИ Агент QA Tester","автоматизированное тестирование","Jest","Supertest","jest.mock","разработка программного обеспечения","качество кода","инструменты тестирования"],"ar":["جهاز QA Tester","اختبار آلي","Jest","Supertest","jest.mock","تطوير البرمجيات","جودة الكود","أدوات الاختبار"]}},"owner":"shaul1991","repo":"shaul-agents-plugin","repoPath":"shaul1991/shaul-agents-plugin","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.658Z","topics":[],"category":"community","skillMd":{"name":"qa-tester","description":"QA Tester Agent. 테스트 작성, 실행, 검증을 담당합니다. 테스트, 검증, 단위테스트, 통합테스트, E2E 관련 요청 시 사용됩니다.","bodyPreview":"# QA Tester Agent\n\n## 역할\n테스트 작성 및 실행을 담당합니다.\n\n## 테스트 스택\n- **Framework**: Jest\n- **E2E**: Supertest\n- **Mocking**: jest.mock, jest.spyOn\n\n## 테스트 구조\n\n```\ntest/\n├── unit/                   # 단위 테스트\n│   ├── services/\n│   └── controllers/\n├── integration/            # 통합 테스트\n│   └── modules/\n├── e2e/                    # E2E 테스트\n│   ├── app.e2e-spec.ts\n│   └── [feature].e2e-spec.ts\n└── fixtures/               # 테스트 데이터\n    └── [entity].fixture.ts\n```\n\n## 테스트 명령어\n\n```bash\n# 전체 테스트\nnpm run test\n\n# 특정 파","body":"# QA Tester Agent\n\n## 역할\n테스트 작성 및 실행을 담당합니다.\n\n## 테스트 스택\n- **Framework**: Jest\n- **E2E**: Supertest\n- **Mocking**: jest.mock, jest.spyOn\n\n## 테스트 구조\n\n```\ntest/\n├── unit/                   # 단위 테스트\n│   ├── services/\n│   └── controllers/\n├── integration/            # 통합 테스트\n│   └── modules/\n├── e2e/                    # E2E 테스트\n│   ├── app.e2e-spec.ts\n│   └── [feature].e2e-spec.ts\n└── fixtures/               # 테스트 데이터\n    └── [entity].fixture.ts\n```\n\n## 테스트 명령어\n\n```bash\n# 전체 테스트\nnpm run test\n\n# 특정 파일 테스트\nnpm run test -- [file-pattern]\n\n# 커버리지\nnpm run test:cov\n\n# E2E 테스트\nnpm run test:e2e\n\n# Watch 모드\nnpm run test:watch\n```\n\n## 테스트 패턴\n\n### 단위 테스트\n```typescript\ndescribe(''UserService'', () => {\n  let service: UserService;\n  let repository: MockType<Repository<User>>;\n\n  beforeEach(async () => {\n    const module = await Test.createTestingModule({\n      providers: [\n        UserService,\n        { provide: getRepositoryToken(User), useFactory: repositoryMockFactory },\n      ],\n    }).compile();\n\n    service = module.get<UserService>(UserService);\n    repository = module.get(getRepositoryToken(User));\n  });\n\n  describe(''findById'', () => {\n    it(''should return user when found'', async () => {\n      const user = { id: 1, name: ''Test'' };\n      repository.findOne.mockReturnValue(user);\n\n      const result = await service.findById(1);\n\n      expect(result).toEqual(user);\n    });\n\n    it(''should throw when not found'', async () => {\n      repository.findOne.mockReturnValue(null);\n\n      await expect(service.findById(1)).rejects.toThrow(NotFoundException);\n    });\n  });\n});\n```\n\n### E2E 테스트\n```typescript\ndescribe(''AppController (e2e)'', () => {\n  let app: INestApplication;\n\n  beforeEach(async () => {\n    const moduleFixture = await Test.createTestingModule({\n      imports: [AppModule],\n    }).compile();\n\n    app = moduleFixture.createNestApplication();\n    await app.init();\n  });\n\n  afterEach(async () => {\n    await app.close();\n  });\n\n  it(''/health/live (GET)'', () => {\n    return request(app.getHttpServer())\n      .get(''/health/live'')\n      .expect(200)\n      .expect({ status: ''ok'' });\n  });\n});\n```\n\n## 테스트 커버리지 목표\n\n| 유형 | 목표 |\n|------|------|\n| 전체 | > 80% |\n| 서비스 | > 90% |\n| 컨트롤러 | > 70% |\n| 유틸리티 | > 95% |\n\n## 테스트 모범 사례\n\n1. **AAA 패턴**: Arrange → Act → Assert\n2. **단일 책임**: 하나의 테스트는 하나만 검증\n3. **독립성**: 테스트 간 의존성 없음\n4. **명확한 네이밍**: 무엇을 테스트하는지 명시\n"},"lastSynced":"2026-03-08T02:14:00.026Z","agentAnalysis":{"suitability":{"en":"Ideal for Multi-Agent Collaboration Systems seeking to streamline their testing process with Jest, Supertest, and jest.mock","zh":"适用于多Agent协作系统，旨在使用Jest、Supertest和jest.mock来简化测试流程","ja":"Jest、Supertest、jest.mockを使用してテストプロセスを合理化しようとしているマルチエージェントコラボレーションシステムに適しています","ko":"Jest, Supertest, jest.mock를 사용하여 테스트 프로세스를 간소화하려는 다중 에이전트 협업 시스템에 적합합니다","es":"Ideal para Sistemas de Colaboración de Múltiples Agentes que buscan optimizar su proceso de prueba con Jest, Supertest y jest.mock","fr":"Idéal pour les Systèmes de Collaboration d''Agents Multiples cherchant à rationaliser leur processus de test avec Jest, Supertest et jest.mock","de":"Ideal für Multi-Agenten-Kollaborationssysteme, die ihren Testprozess mit Jest, Supertest und jest.mock optimieren möchten","pt":"Ideal para Sistemas de Colaboração de Múltiplos Agentes que buscam otimizar seu processo de teste com Jest, Supertest e jest.mock","ru":"Идеально для систем многогентного сотрудничества, стремящихся оптимизировать процесс тестирования с помощью Jest, Supertest и jest.mock","ar":"مثالي لنظم التعاون بين وكلاء متعددين التي تسعى إلى تسهيل عملية الاختبار باستخدام Jest و Supertest و jest.mock"},"recommendation":{"en":"Empowers agents to write and execute unit tests, integration tests, and end-to-end tests using Jest and Supertest, while utilizing jest.mock and jest.spyOn for mocking dependencies, thus ensuring robust test coverage and validation","zh":"赋予代理能力，使用Jest和Supertest编写和执行单元测试、集成测试和端到端测试，同时利用jest.mock和jest.spyOn模拟依赖项，以确保强大的测试覆盖和验证","ja":"エージェントに単体テスト、統合テスト、およびエンドツーエンドテストをJestとSupertestで書き込み実行する能力を付与し、jest.mockとjest.spyOnを使用して依存関係をモック化することで、堅牢なテストカバーと検証を確保する","ko":"에이전트가 Jest와 Supertest를 사용하여 단위 테스트, 통합 테스트, 엔드 투 엔드 테스트를 작성하고 실행할 수 있는 능력을 부여하고, jest.mock와 jest.spyOn을 사용하여 의존성을 모의함으로써 강력한 테스트 커버리지와 검증을 보장합니다","es":"Habilita a los agentes a escribir y ejecutar pruebas unitarias, pruebas de integración y pruebas de extremo a extremo utilizando Jest y Supertest, mientras utiliza jest.mock y jest.spyOn para simular dependencias, lo que garantiza una cobertura y validación de pruebas robustas","fr":"Permet aux agents d''écrire et d''exécuter des tests unitaires, des tests d''intégration et des tests de bout en bout en utilisant Jest et Supertest, tout en utilisant jest.mock et jest.spyOn pour simuler les dépendances, garantissant ainsi une couverture et une validation de tests robustes","de":"Ermächtigt Agenten, Einheitstests, Integrations-tests und End-to-End-Tests mit Jest und Supertest zu schreiben und auszuführen, während es jest.mock und jest.spyOn zur Mocking von Abhängigkeiten verwendet, um so eine robuste Testabdeckung und -validierung zu gewährleisten","pt":"Habilita agentes a escrever e executar testes unitários, testes de integração e testes de ponta a ponta usando Jest e Supertest, aproveitando jest.mock e jest.spyOn para simular dependências, garantindo assim cobertura de teste robusta e validação","ru":"Наделяет агентов возможностью писать и выполнять модульные тесты, тесты интеграции и тесты от начала до конца, используя Jest и Supertest, а также использовать jest.mock и jest.spyOn для имитации зависимостей, обеспечивая тем самым прочное тестовое покрытие и проверку","ar":"تمكّن الوكلاء من كتابة وتشغيل الاختبارات الوحدوية واختبارات التكامل واختبارات من النهاية إلى النهاية باستخدام Jest و Supertest، مع استخدام jest.mock و jest.spyOn لمحاكاة التبعيات، مما يضمن تغطية اختبار قوية وتصديقًا"},"useCases":{"en":["Automating unit testing for services and controllers","Executing end-to-end tests for feature validation","Mocking dependencies for isolated integration testing"],"zh":["自动化服务和控制器的单元测试","执行端到端测试以验证功能","模拟依赖项以进行隔离集成测试"],"ja":["サービスとコントローラーの単体テストを自動化する","機能の検証のためにエンドツーエンドテストを実行する","依存関係をモック化して隔離された統合テストを実行する"],"ko":["서비스 및 컨트롤러의 단위 테스트 자동화","기능 검증을 위한 엔드 투 엔드 테스트 실행","의존성 모의를 통한 격리된 통합 테스트"],"es":["Automatización de pruebas unitarias para servicios y controladores","Ejecución de pruebas de extremo a extremo para la validación de características","Simulación de dependencias para pruebas de integración aisladas"],"fr":["Automatisation des tests unitaires pour les services et les contrôleurs","Exécution des tests de bout en bout pour la validation des fonctionnalités","Simulation des dépendances pour les tests d''intégration isolés"],"de":["Automatisierung von Einheitstests für Dienste und Controller","Ausführen von End-to-End-Tests zur Validierung von Funktionen","Mocking von Abhängigkeiten für isolierte Integrations-tests"],"pt":["Automatizar testes unitários para serviços e controladores","Executar testes de ponta a ponta para validação de recursos","Simular dependências para testes de integração isolados"],"ru":["Автоматизировать модульное тестирование для сервисов и контроллеров","Выполнять тесты от начала до конца для проверки функций","Имитировать зависимости для изолированного тестирования интеграции"],"ar":["توفير الاختبارات الوحدوية للخدمات والمتحكمات","تشغيل الاختبارات من النهاية إلى النهاية لتحقق الميزات","محاكاة التبعيات لاختبارات التكامل المعزولة"]},"limitations":{"en":["Requires Jest and Supertest setup","Limited to JavaScript-based projects","Needs proper test structure and configuration"],"zh":["需要Jest和Supertest设置","仅限于基于JavaScript的项目","需要适当的测试结构和配置"],"ja":["JestとSupertestの設定が必要","JavaScriptベースのプロジェクトに限定される","適切なテスト構造と構成が必要"],"ko":["Jest 및 Supertest 설정이 필요합니다","JavaScript 기반 프로젝트에만 제한됩니다","적절한 테스트 구조 및 구성이 필요합니다"],"es":["Requiere configuración de Jest y Supertest","Limitado a proyectos basados en JavaScript","Necesita una estructura y configuración de prueba adecuadas"],"fr":["Nécessite une configuration de Jest et Supertest","Limité aux projets basés sur JavaScript","Nécessite une structure et une configuration de test appropriées"],"de":["Benötigt Jest- und Supertest-Setup","Begrenzt auf JavaScript-basierte Projekte","Benötigt eine ordnungsgemäße Teststruktur und -konfiguration"],"pt":["Exige configuração do Jest e Supertest","Limitado a projetos baseados em JavaScript","Necessita de estrutura e configuração de teste adequadas"],"ru":["Требует настройки Jest и Supertest","Ограничен проектами на основе JavaScript","Требует правильной структуры и конфигурации теста"],"ar":["يتطلب إعداد Jest و Supertest","محدود بمشاريع قائم على لغة جافا سكريبت","يحتاج إلى هيكل وتهيئة اختبار مناسبة"]},"version":4},"contentHash":"366cc2396a8cad3ec2045594d12798ddde26a881981e34179aacaf16fe657e4c","qualityScore":30}');
