INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shaul1991/shaul-agents-plugin/qa-tester', 'qa-tester', 'shaul1991', 'shaul-agents-plugin', 'community', 'qa-tester shaul1991 shaul-agents-plugin community The qa-tester skill enables developers to write and execute tests using Jest, Supertest, and jest.mock, streamlining their testing process. It benefits developers working with multi-agent collaboration systems. QA Tester Agent 是一个使用 Jest 和 Supertest 进行自动化测试的工具，支持单元测试、集成测试和 E2E 测试 QA テスター エージェントは、Jest と Supertest を使用して自動化テストを実行する AI エージェントです QA 테스터 에이전트는 Jest와 Supertest를 사용하여 자동화 테스트를 수행하는 멀티에이전트 협업 시스템의 플러그인입니다 El agente de test QA es responsable de escribir y ejecutar tests, utilizando Jest y Supertest para garantizar la calidad de las aplicaciones L''agent de test QA est responsable de la rédaction et de l''exécution de tests, en utilisant Jest et Supertest pour assurer la qualité des applications Der QA-Tester-Agent ist verantwortlich für das Schreiben und Ausführen von Tests, um die Qualität von Anwendungen mit Jest und Supertest zu gewährleisten O QA Tester é um agente de teste automatizado que utiliza Jest, Supertest e jest.mock para garantir a qualidade do código ИИ Агент QA Tester - это автоматизированный агент тестирования, использующий Jest, Supertest и jest.mock для обеспечения качества кода جهاز QA Tester هو جهاز اختبار آلي يستخدم Jest و Supertest و jest.mock لضمان جودة الكود how to use qa-tester qa-tester setup guide qa-tester vs jest qa-tester install what is qa-tester qa-tester alternative qa-tester tutorial qa-tester testing framework qa-tester multi-agent systems QA Tester Agent Jest Supertest 自动化测试 单元测试 集成测试 E2E 测试 AI 工具 Utilizes Jest framework for unit testing Employs Supertest for End-to-End (E2E) testing Leverages jest.mock and jest.spyOn for mocking dependencies Supports a structured test directory with unit, integration, and e2e test folders Executes tests using npm run test command qa-tester is a testing framework that utilizes Jest, Supertest, and jest.mock to facilitate unit, integration, and E2E testing for multi-agent systems.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vivy-yi/xiaohongshu-skills/personal-branding-advanced', 'community', 'vivy-yi', 'xiaohongshu-skills', 'vivy-yi/xiaohongshu-skills', 'personal-branding-advanced', 0, 0, 30, '2026-03-08T01:57:15.660Z', '2026-03-08T02:14:03.200Z', 'c1b8511700b19acc257bb973f5ccb66e8c53a57225baa6ca536d7246417c7cf7', '{"id":"vivy-yi/xiaohongshu-skills/personal-branding-advanced","name":"personal-branding-advanced","description":{"en":"The personal-branding-advanced skill empowers creators to build high-income IPs through unique value propositions, consistent image presentation, and deep audience connections, benefiting influencers and industry leaders","zh":"个人品牌建设高级技能，涵盖内容创作、账号运营、互动运营等9大分类，使用Claude Code技能插件系统打造您的个人品牌","ja":"AIエージェントを使用した個人ブランド構築の高級スキル、内容創作、账号運営、互動運営等の9つのカテゴリを網羅し、Claude Codeスキルプラグインシステムで個人ブランドを構築","ko":"개인 브랜드 구축 고급 스킬, 컨텐츠 생성, 계정 운영, 상호 작용 운영 등 9개의 카테고리를 포함하여 Claude Code 스킬 플러그인 시스템을 사용하여 개인 브랜드를 구축","es":"La marca personal avanzada es un proceso sistemático para convertir tu cuenta en una IP reconocida con influencia y valor comercial","fr":"La marque personnelle avancée est un processus systématique pour transformer votre compte en une IP reconnue avec influence et valeur commerciale","de":"Die fortgeschrittene persönliche Marke ist ein systematischer Prozess, um Ihr Konto in eine anerkannte IP mit Einfluss und kommerziellem Wert zu verwandeln","pt":"O personal-branding-advanced é uma habilidade que ajuda a criar uma marca pessoal forte e aumentar o valor comercial do conteúdo","ru":"Продвинутая личная брендинг - это навык, который помогает создать сильную личную брендинг и увеличить коммерческую стоимость контента","ar":"العلامة التجارية الشخصية المتقدمة هي مهارة تساعد على إنشاء علامة تجارية شخصية قوية وزيادة القيمة التجارية للمحتوى"},"seo":{"title":{"en":"Personal-Branding-Advanced: Expert IP Building Setup Guid...","zh":"个人品牌建设高级指南 - Claude Code 技能插件系统","ja":"AIエージェントを使用した個人ブランド構築のベストプラクティス","ko":"개인 브랜드 구축 고급 가이드 - Claude Code 스킬 플러그인 시스템","es":"Guía de configuración de marca personal avanzada con AI A...","fr":"Guide de mise en place de la marque personnelle avancée a...","de":"Einrichtungsleitfaden für fortgeschrittene persönliche Ma...","pt":"Guia de Configuração de Marca Pessoal Avançada com Claude...","ru":"Руководство по настройке продвинутой личной брендинга с C...","ar":"دليل إعداد العلامة التجارية الشخصية المتقدمة مع Claude Co..."},"description":{"en":"Unlock the secrets of high-income personal branding with our advanced AI agent skill, featuring 9 categories and 139 skills for IP growth","zh":"了解个人品牌建设的高级技巧，包括内容创作、账号运营、互动运营等，使用Claude Code技能插件系统提升您的个人品牌","ja":"AIエージェントを使用して個人ブランドを構築するための高級なテクニックを学び、Claude Codeスキルプラグインシステムで個人ブランドを高める","ko":"개인 브랜드 구축의 고급 기술을 배우고, Claude Code 스킬 플러그인 시스템을 사용하여 개인 브랜드를 강화하세요","es":"Aprende a crear una marca personal avanzada con nuestro AI Agent y aumenta tu influencia en línea","fr":"Découvrez comment créer une marque personnelle avancée avec notre Outil IA et améliorez votre influence en ligne","de":"Erfahren Sie, wie Sie mit unserem KI-Tool eine fortgeschrittene persönliche Marke erstellen und Ihren Online-Einfluss steigern","pt":"Aprenda a criar uma marca pessoal forte com o Claude Code, aumentando a interação e o valor comercial do seu conteúdo","ru":"Узнайте, как создать сильную личную брендинг с помощью Claude Code и ИИ Агентов, увеличивая взаимодействие и коммерческую стоимость вашего контента","ar":"تعلم كيفية إنشاء علامة تجارية شخصية قوية مع Claude Code وأدوات الذكاء الاصطناعي، مما يزيد من التفاعل والقيمة التجارية لمحتواك"},"definition":{"en":"Personal-branding-advanced is a systematic engineering process to elevate accounts into recognizable, influential, and commercially valuable IPs","zh":"个人品牌建设是指将账号提升为具有辨识度、影响力和商业价值的IP的系统性工程","ja":"個人ブランド構築とは、账号を識別可能、影響力を持つ、および商業価値を持つIPに昇格させるための体系的な工程","ko":"개인 브랜드 구축은 계정을 식별 가능하고 영향력과 상업적 가치를 가진 IP로 승격시키는 체계적인 공정","es":"La marca personal avanzada se refiere a la creación de una identidad única y reconocida en línea","fr":"La marque personnelle avancée fait référence à la création d''une identité unique et reconnue en ligne","de":"Die fortgeschrittene persönliche Marke bezieht sich auf die Schaffung einer einzigartigen und anerkannten Online-Identität","pt":"O que é personal-branding-advanced? É uma habilidade que envolve a criação de uma marca pessoal forte e aumentar o valor comercial do conteúdo","ru":"Что такое продвинутая личная брендинг? Это навык, который включает в себя создание сильной личной брендинг и увеличение коммерческой стоимости контента","ar":"ما هي العلامة التجارية الشخصية المتقدمة؟ هي مهارة تشمل إنشاء علامة تجارية شخصية قوية وزيادة القيمة التجارية للمحتوى"},"features":{"en":["Establishes a strong personal brand with a 2-3 times higher average interaction rate","Increases commercial quotes by 3-5 times with a clear personal brand","Improves fan loyalty by 40-60% through brand-oriented accounts","Supports the development of industry opinion leaders with high commercial value","Covers 9 categories including content creation, account operation, and data analysis"],"zh":["内容创作策略","账号运营技巧","互动运营方法","数据分析工具","电商转化策略","平台规则解读"],"ja":["内容創作戦略","账号運営テクニック","互動運営方法","データ分析ツール","電子商取引戦略","プラットフォーム規則解釈"],"ko":["컨텐츠 생성 전략","계정 운영 기술","상호 작용 운영 방법","데이터 분석 도구","전자 상거래 전략","플랫폼 규칙 해석"],"es":["Creación de contenido con valor agregado","Desarrollo de una imagen única y reconocida","Conexión profunda con la audiencia","Análisis de datos para optimizar el contenido","Estrategias de crecimiento para aumentar la influencia en línea","Integración con herramientas de comercio electrónico para aumentar las conversiones"],"fr":["Création de contenu avec valeur ajoutée","Développement d''une image unique et reconnue","Connexion profonde avec le public","Analyse de données pour optimiser le contenu","Stratégies de croissance pour augmenter l''influence en ligne","Intégration avec des outils de commerce électronique pour augmenter les conversions"],"de":["Erstellung von Inhalten mit Mehrwert","Entwicklung eines einzigartigen und anerkannten Bildes","Tiefe Verbindung mit dem Publikum","Datenanalyse zur Optimierung des Inhalts","Wachstumsstrategien zur Steigerung des Online-Einflusses","Integration mit E-Commerce-Tools zur Steigerung der Konversionen"],"pt":["Criação de conteúdo com alto nível de interação","Desenvolvimento de uma marca pessoal forte e única","Análise de dados para otimizar o conteúdo","Integração com o Claude Code para aumento do valor comercial","Aumento da fidelidade dos seguidores em até 40-60%","Aumento do valor comercial do conteúdo em até 3-5 vezes"],"ru":["Создание контента с высоким уровнем взаимодействия","Развитие сильной и уникальной личной брендинг","Анализ данных для оптимизации контента","Интеграция с Claude Code для увеличения коммерческой стоимости","Увеличение лояльности подписчиков на 40-60%","Увеличение коммерческой стоимости контента в 3-5 раз"],"ar":["إنشاء محتوى ذو مستوى تفاعل عالي","تنمية علامة تجارية شخصية قوية وفريدة","تحليل البيانات لتحسين المحتوى","التكامل مع Claude Code لزيادة القيمة التجارية","زيادة ولاء المتابعين بنسبة 40-60%","زيادة القيمة التجارية للمحتوى 3-5 مرات"]},"keywords":{"en":["how to use personal-branding-advanced","personal-branding-advanced setup guide","what is personal-branding-advanced","personal-branding-advanced alternative","personal-branding-advanced vs influencer marketing","personal-branding-advanced install","building a personal brand with AI","high-income personal branding strategies","personal-branding-advanced for industry leaders"],"zh":["个人品牌建设","内容创作","账号运营","互动运营","数据分析","电商转化","平台规则","Claude Code技能插件系统"],"ja":["AIエージェント","個人ブランド構築","内容創作","账号運營","互動運営","データ分析","電子商取引","プラットフォーム規則","Claude Codeスキルプラグインシステム"],"ko":["AI 에이전트","개인 브랜드 구축","컨텐츠 생성","계정 운영","상호 작용 운영","데이터 분석","전자 상거래","플랫폼 규칙","Claude Code 스킬 플러그인 시스템"],"es":["marca personal avanzada","AI Agent","creación de contenido","imagen única","conexión con la audiencia","análisis de datos","estrategias de crecimiento","comercio electrónico","influencia en línea","valor comercial"],"fr":["marque personnelle avancée","Outil IA","création de contenu","image unique","connexion avec le public","analyse de données","stratégies de croissance","commerce électronique","influence en ligne","valeur commerciale"],"de":["fortgeschrittene persönliche Marke","KI-Tool","Erstellung von Inhalten","einzigartiges Bild","Verbindung mit dem Publikum","Datenanalyse","Wachstumsstrategien","E-Commerce","Online-Einfluss","kommerzieller Wert"],"pt":["personal-branding-advanced","marca pessoal forte","valor comercial do conteúdo","interação no conteúdo","análise de dados","Claude Code","criação de conteúdo","desenvolvimento de marca pessoal","aumento da fidelidade dos seguidores"],"ru":["продвинутая личная брендинг","сильная личная брендинг","коммерческая стоимость контента","взаимодействие в контенте","анализ данных","Claude Code","создание контента","развитие личной брендинг","увеличение лояльности подписчиков"],"ar":["العلامة التجارية الشخصية المتقدمة","علامة تجارية شخصية قوية","قيمة المحتوى التجارية","التفاعل في المحتوى","تحليل البيانات","Claude Code","إنشاء المحتوى","تنمية العلامة التجارية الشخصية","زيادة ولاء المتابعين"]}},"owner":"vivy-yi","repo":"xiaohongshu-skills","repoPath":"vivy-yi/xiaohongshu-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.660Z","topics":[],"category":"community","skillMd":{"name":"personal-branding-advanced","description":"高级个人品牌建设 - 从内容创作者到行业意见领袖的系统性品牌架构","bodyPreview":"# 个人品牌建设 (高级)\n\n## 概述\n\n**个人品牌建设**是将账号提升为具有辨识度、影响力和商业价值的IP的系统性工程。它超越了单纯的内容创作，而是通过独特的价值主张、一致的形象呈现和深度的受众连接，建立可持续的品牌资产。\n\n**核心洞察：**\n- 强个人品牌的内容平均互动率比普通账号高**2-3倍**\n- 拥有清晰个人品牌的创作者，商业报价可达到同量级账号的**3-5倍**\n- 品牌化账号的粉丝忠诚度（留存率）比非品牌化账号高**40-60%**\n- 个人品牌最强的前5%创作者，占据行业**70%以上**的商业机会\n\n### 个人品牌的三个层次\n\n| 层次 | 特征 | 内容策略 | 商业价值 | 粉丝关系 |\n|------|------|----------|----------|----------|\n| **内容创作者** | 输出有用信息 | 解决问题 | 低（接广告） | 弱（获取价值） |\n| **垂类专家** | 深耕某一领域 | 专业见解 | 中（咨询/课程） | 中（信任专业） |\n| **行业意见领袖** | 定义行业标准 | 观点引领 | 高（IP授权/","body":"# 个人品牌建设 (高级)\n\n## 概述\n\n**个人品牌建设**是将账号提升为具有辨识度、影响力和商业价值的IP的系统性工程。它超越了单纯的内容创作，而是通过独特的价值主张、一致的形象呈现和深度的受众连接，建立可持续的品牌资产。\n\n**核心洞察：**\n- 强个人品牌的内容平均互动率比普通账号高**2-3倍**\n- 拥有清晰个人品牌的创作者，商业报价可达到同量级账号的**3-5倍**\n- 品牌化账号的粉丝忠诚度（留存率）比非品牌化账号高**40-60%**\n- 个人品牌最强的前5%创作者，占据行业**70%以上**的商业机会\n\n### 个人品牌的三个层次\n\n| 层次 | 特征 | 内容策略 | 商业价值 | 粉丝关系 |\n|------|------|----------|----------|----------|\n| **内容创作者** | 输出有用信息 | 解决问题 | 低（接广告） | 弱（获取价值） |\n| **垂类专家** | 深耕某一领域 | 专业见解 | 中（咨询/课程） | 中（信任专业） |\n| **行业意见领袖** | 定义行业标准 | 观点引领 | 高（IP授权/投资） | 强（认同价值观） |\n\n---\n\n## 适用场景\n\n### 何时使用个人品牌建设策略\n\n✅ **适合以下情况：**\n- 账号已有稳定内容基础（100+篇笔记），希望突破增长瓶颈\n- 粉丝量达到1万以上，但商业转化率不理想\n- 希望从单一平台创作者发展为多平台IP\n- 计划长期深耕内容行业（3年以上）\n- 有强烈的个人特质和价值观可以传递\n\n❌ **不适用场景：**\n- 账号初期（0-50篇笔记）- 应先聚焦内容质量和垂直度\n- 纯流量变现逻辑（如CPA、返佣）- 不需要强个人品牌\n- 匿名/多账号矩阵运营 - 品牌分散，难以聚焦\n- 短期快速获利目标 - 品牌建设需要6-12个月见效\n\n---\n\n## 核心模式\n\n### 品牌化前 vs. 品牌化后\n\n| 维度 | 品牌化前 | 品牌化后 |\n|------|----------|----------|\n| **内容定位** | \"美妆分享\" | \"理性消费倡导者 - 只推真正值得买的好物\" |\n| **视觉识别** | 随意封面，无统一风格 | 标志性橙色封面 + 手写字体 + 统一版式 |\n| **语言风格** | 普通推荐语气 | \"闺蜜式\"真诚表达 + \"测了300款才推荐这5款\" |\n| **记忆点** | 无明显特色 | \"毒舌但真诚的开箱\"、\"平价替代挖掘机\" |\n| **粉丝印象** | \"发美妆的\" | \"说真话的，信她准没错\" |\n| **商业合作** | 接受大部分广告 | 只合作真正认可的品牌，溢价30-50% |\n| **内容复购** | 看完即走 | 主动收藏、分享、等待更新 |\n\n### 个人品牌金字塔\n\n```\n                    ┌─────────────────┐\n                    │   价值观引领     │  ← 粉丝认同你代表什么\n                    │ (Values/Purpose) │\n                    ├─────────────────┤\n                    │   独特观点       │  ← 你的专业见解和判断\n                    │  (Viewpoints)   │\n                    ├─────────────────┤\n                    │   专业能力       │  ← 你能解决什么问题\n                    │ (Expertise)     │\n                    ├─────────────────┤\n                    │   视觉识别       │  ← 被记住的第一印象\n                    │  (Visual ID)    │\n                    └─────────────────┘\n```\n\n---\n\n## 快速参考\n\n### 个人品牌定位矩阵\n\n| 品牌类型 | 核心价值 | 内容特点 | 典型表达 | 适用领域 |\n|---------|---------|----------|----------|----------|\n| **专业权威型** | 深度知识 | 干货密集，数据驱动 | \"根据我10年经验...\" | 职场、金融、教育 |\n| **生活方式型** | 审美向往 | 高质量视觉，情调 | \"我的XX生活准则\" | 美妆、家居、旅行 |\n| **真实陪伴型** | 情感连接 | 日常化，有缺陷感 | \"踩坑了，分享给你们\" | 育儿、情感、健身 |\n| **观点先锋型** | 独特见解 | 观点鲜明，不怕争议 | \"关于XX，说句大实话\" | 科技、社会、商业 |\n| **技能教学型** | 实用价值 | step-by-step教程 | \"3天学会XX\" | 技能、手艺、工具 |\n| **故事讲述型** | 情感共鸣 | 叙事化，有起承转合 | \"从0到1，我用了一年\" | 创业、成长、经历 |\n\n### 视觉识别系统检查清单\n\n| 元素 | 事项 | 示例 |\n|------|------|------|\n| **头像** | ✅ 高辨识度 | 真人照片/标志性造型/统一画风 |\n| **封面配色** | ✅ 2-3主色 | 橙色(#FF6B35)+米白+深灰 |\n| **字体** | ✅ 固定字体组合 | 标题用粗体，正文用宋体 |\n| **版式** | ✅ 统一布局 | 左图右文，标题居中，标签位置固定 |\n| **标志性元素** | ✅ 记忆符号 | 手绘箭头、贴纸、专属边框 |\n| **人设形象** | ✅ 出镜风格 | 统一穿搭、场景、表情风格 |\n\n### 品牌一致性评分表\n\n| 评分维度 | 一致性要求 | 自检问题 |\n|---------|-----------|----------|\n| **内容垂直度** | 80%内容在核心领域 | \"粉丝能在一句话内说清我是做什么的吗？\" |\n| **视觉统一性** | 封面风格识别度>70% | \"遮挡头像，粉丝能认出是我的笔记吗？\" |\n| **语言一致性** | 固定表达方式和口头禅 | \"粉丝能模仿我的说话方式吗？\" |\n| **价值观一致** | 不传递矛盾信息 | \"我推荐的产品都符合我宣称的标准吗？\" |\n| **更新节奏** | 可预期的发布频率 | \"粉丝知道我每周几更吗？\" |\n\n---\n\n## 实施步骤\n\n### Step 1: 品牌定位 - 定义你的\"为什么\"\n\n**目标：** 找到只属于你的独特价值主张\n\n**1.1 自我挖掘三问：**\n\n| 问题 | 引导思考 | 输出 |\n|------|----------|------|\n| **我最擅长的** | 什么事我能做到90分以上，而别人只能做到70分？ | 核心能力 |\n| **我最热爱的** | 什么事我愿意免费做，并且做了10年不厌倦？ | 内在动力 |\n| **市场需要的** | 什么问题我的目标受众最愿意付费解决？ | 商业价值 |\n\n**三个圆圈的交集 = 你的品牌定位**\n\n**1.2 竞品差异化分析：**\n\n研究同量级竞品（5-10个），列出：\n- 他们都在说什么内容？\n- 他们的视觉风格是什么？\n- 他们的粉丝为什么关注他们？\n\n然后问自己：\n- **我能提供什么不同的价值？**\n- **我有什么独特的经历或视角？**\n- **我能用什么方式让内容更有趣/更有用？**\n\n**1.3 品牌定位声明：**\n\n完成这个公式：\n\n> \"我帮助 **[目标受众]** 通过 **[独特方法]** 解决 **[核心问题]**，让他们 **[达成结果]**，不同于 **[竞争对手]**，因为我 **[独特优势]**\"\n\n示例：\n> \"我帮助**25-35岁都市女性**通过**科学成分分析+实测对比**解决**护肤品选择困难**，让他们**不再交智商税**，不同于**单纯推荐好物的博主**，因为我**有化妆品研发背景，坚持自费购买测评**\"\n\n### Step 2: 视觉识别系统 - 建立视觉记忆点\n\n**目标：** 让粉丝在0.5秒内识别出你的内容\n\n**2.1 配色方案：**\n\n选择2-3个主色，确保：\n- **主色**：与内容调性一致（美妆用暖色，科技用冷色）\n- **辅助色**：用于强调和点缀\n- **背景色**：确保文字可读性\n\n**配色原则：**\n- 60% 主色（背景/大面积）\n- 30% 辅助色（次要元素）\n- 10% 强调色（CTA/重点）\n\n**2.2 字体系统：**\n\n| 用途 | 字体选择 | 应用场景 |\n|------|---------|----------|\n| **标题** | 粗体/手写体 | 封面大标题、重点强调 |\n| **正文** | 清晰易读字体 | 笔记正文、说明文字 |\n| **点缀** | 装饰性字体 | 标签、水印、签名 |\n\n**2.3 封面模板化：**\n\n设计3-5个封面模板，固定元素：\n- 布局结构（左图右文/上图下文）\n- 字号大小（标题40-60pt，副标题20-30pt）\n- 元素位置（标签在右上角，签名在右下角）\n\n**2.4 标志性元素：**\n\n创造独属于你的视觉符号：\n- 手绘贴纸（星星、箭头、对话框）\n- 个人表情包/梗图\n- 固定背景元素（书架、工作台、特定场景）\n\n### Step 3: 语言风格系统 - 打造声音识别度\n\n**目标：** 让粉丝不看头像也能认出你的内容\n\n**3.1 确定语言风格：**\n\n从以下维度选择：\n\n| 维度 | 选项 | 选择建议 |\n|------|------|----------|\n| **语调** | 专业/亲切/幽默/犀利 | 与个性一致，不刻意 |\n| **人称** | 第一人称\"我\"/第二人称\"你\" | 用\"你\"增加代入感 |\n| **表达方式** | 数据型/故事型/金句型 | 结合领域特点 |\n| **口头禅** | 固定开场/结尾/过渡 | 增加辨识度 |\n\n**3.2 建立语言库：**\n\n- **开场白**：3-5个固定开场，根据内容类型选择\n  - \"大家好，我是XX，今天要分享...\"\n  - \"姐妹们，又到了我XX的时间\"\n  - \"关于XX，说句大实话...\"\n\n- **过渡句**：固定的段落衔接方式\n  - \"重点来了，拿小本本记好\"\n  - \"说到这个，我必须要强调\"\n  - \"踩过坑才知道...\"\n\n- **结尾句**：固定的互动方式\n  - \"有问题的评论区见\"\n  - \"记得点赞收藏，下次不迷路\"\n  - \"下期想看什么，告诉我\"\n\n**3.3 观点表达框架：**\n\n建立自己的评论框架，让观点有辨识度：\n\n**示例框架（\"理性-感性-行动\"）：**\n1. **理性开场**：抛出数据/现象，建立专业感\n   - \"根据小红书2024年数据...\"\n   - \"我测了50款产品，发现一个规律...\"\n2. **感性连接**：表达个人感受，拉近距离\n   - \"说实话，看到这个结果我挺意外的\"\n   - \"用完这个，我真的有被感动到\"\n3. **行动建议**：给出具体建议，体现价值\n   - \"所以我的建议是...\"\n   - \"如果你也有XX困扰，试试XX\"\n\n### Step 4: 内容品牌化 - 让所有内容强化品牌\n\n**目标：** 每一篇内容都在讲述你的品牌故事\n\n**4.1 内容主题规划：**\n\n围绕品牌定位，规划3-5个内容系列：\n\n| 系列名称 | 内容类型 | 更新频率 | 品牌作用 |\n|---------|---------|----------|----------|\n| **\"XX测评室\"** | 产品测评 | 每周2篇 | 强化专业形象 |\n| **\"XX避坑指南\"** | 避坑经验 | 每周1篇 | 建立信任 |\n| **\"XX日常\"** | 生活vlog | 每周1篇 | 增加亲切感 |\n| **\"XX干货\"** | 知识科普 | 每周1篇 | 提供价值 |\n| **\"XX问答\"** | 粉丝互动 | 不定期 | 增强参与感 |\n\n**4.2 品牌故事线：**\n\n设计贯穿内容的故事线：\n- **起源故事**：为什么开始做这个领域？\n- **成长故事**：遇到什么挑战，如何克服？\n- **价值观故事**：什么是你坚持的原则？\n- **成功故事**：帮助粉丝解决了什么问题？\n\n**示例（美妆博主）：**\n- 起源：\"从烂脸到成分党，我花了3年\"\n- 成长：\"测评1000款产品，我学会了这些\"\n- 价值观：\"我不推荐我自己不会用的东西\"\n- 成功：\"这些产品，救了1000+姐妹的痘痘肌\"\n\n**4.3 统一内容格式：**\n\n每个内容系列有固定格式，增加识别度：\n\n**测评系列格式示例：**\n```\n[封面：产品实拍+测评分数]\nP1：开场白 + 测评背景\nP2：产品基本信息 + 使用场景\nP3-P4：实测过程（对比图/数据）\nP5：优缺点总结\nP6：适合人群 + 购买建议\n最后：互动提问\n```\n\n### Step 5: 品牌触点延伸 - 全渠道一致性\n\n**目标：** 在所有粉丝接触点强化品牌印象\n\n**5.1 账号信息优化：**\n\n| 触点 | 优化内容 | 示例 |\n|------|---------|------|\n| **昵称** | 包含核心关键词 + 个人特色 | \"XX(理性消费倡导者)\" |\n| **简介** | 一句话说明价值主张 | \"帮你避坑的美妆成分党\" |\n| **背景图** | 传达品牌视觉 | 统一配色/品牌口号 |\n| **置顶笔记** | 品牌宣言 + 代表作 | \"我是谁 + 我能帮你什么\" |\n\n**5.2 互动品牌化：**\n\n让每一次互动都强化品牌：\n\n- **回复风格**：保持语言风格一致\n- **评论管理**：固定回复模板（常见问题）\n- **私信回复**：统一开头/结尾\n- **直播风格**：延续内容风格\n\n**5.3 多平台品牌统一：**\n\n如果拓展多平台，确保：\n- **统一昵称**：各平台昵称一致或高度相似\n- **统一视觉**：头像、封面、配色一致\n- **统一简介**：价值主张表达一致\n- **统一内容**：核心内容主题一致，但形式适配平台\n\n### Step 6: 品牌资产积累 - 长期价值建设\n\n**目标：** 将品牌转化为可持续资产\n\n**6.1 品牌清单：**\n\n定期盘点品牌资产：\n\n| 资产类型 | 内容 | 更新频率 |\n|---------|------|----------|\n| **视觉资产** | Logo、模板、配色方案 | 每季度优化 |\n| **内容资产** | 爆款笔记、经典系列 | 每月整理 |\n| **粉丝资产** | 核心粉丝画像、社群 | 每月分析 |\n| **合作资产** | 品牌合作案例 | 每季度更新 |\n| **知识资产** | 方法论、框架、模型 | 持续积累 |\n\n**6.2 品牌保护：**\n\n- **商标注册**：保护品牌名称、Logo\n- **内容存证**：重要原创内容进行版权登记\n- **舆情监控**：定期搜索品牌名，监控口碑\n- **竞品监测**：关注是否有模仿者，及时应对\n\n**6.3 品牌升级：**\n\n当品牌固化后，考虑升级：\n- **视觉升级**：保持核心元素，优化细节\n- **内容升级**：加入新角度，保持新鲜感\n- **价值升级**：拓展品牌边界，但不偏离核心\n\n### Step 7: 品牌变现 - 将影响力转化为价值\n\n**目标：** 商业化但不损害品牌价值\n\n**7.1 变现层次：**\n\n| 层次 | 变现方式 | 品牌要求 | 收益潜力 |\n|------|---------|----------|----------|\n| **基础层** | 广告合作 | 有粉丝基础 | 低 |\n| **进阶层** | 专属产品/课程 | 有信任基础 | 中 |\n| **高层** | IP授权/联名 | 有品牌影响力 | 高 |\n| **顶层** | 投资/孵化 | 有行业地位 | 很高 |\n\n**7.2 商业合作原则：**\n\n- **只接符合定位的合作**：宁可少赚，不破坏信任\n- **真实体验优先**：不推荐自己不认可的产品\n- **明确标注**：广告内容明确告知粉丝\n- **长期主义**：建立长期合作关系，而非一次性合作\n\n**7.3 定价策略：**\n\n品牌化账号的溢价空间：\n- **基础广告**：比同量级非品牌账号高30-50%\n- **深度合作**：定制内容溢价50-100%\n- **长期代言**：年度合作溢价100%以上\n\n**定价公式：**\n```\n基础价格 = 行业CPM × 粉丝数 × 互动率系数\n品牌溢价 = 基础价格 × (品牌强度系数 - 1)\n最终价格 = 基础价格 + 品牌溢价\n```\n\n---\n\n## 常见错误\n\n### ❌ 错误1: 只有视觉没有内核\n\n**表现：**\n- 封面精美但内容空洞\n- 有slogan但没有实际价值主张\n- 视觉风格频繁变化，缺乏一致性\n\n**正确做法：**\n- 品牌定位先行，视觉服务于定位\n- 每3个月自检：粉丝能说出我的3个特点吗？\n\n### ❌ 错误2: 人设与真实自我割裂\n\n**表现：**\n- 塑造\"完美人设\"，不敢展示真实一面\n- 人设崩塌（如人设是\"勤俭\"但被发现奢靡）\n- 长期扮演人设导致疲惫\n\n**正确做法：**\n- **放大真实特质**，而非虚构特质\n- **展示适度缺陷**，增加真实感和亲近感\n- 人设 = 你的优势特质 + 目标受众喜欢的表达方式\n\n### ❌ 错误3: 过度商业化损害品牌\n\n**表现：**\n- 一个月接10+广告\n- 推荐的产品与定位不符\n- 广告内容质量明显低于日常内容\n\n**正确做法：**\n- **广告频率控制**：广告内容不超过20%\n- **选品标准公开化**：让粉丝知道你的合作标准\n- **广告质量不打折**：广告内容也要符合品牌标准\n\n### ❌ 错误4: 品牌定位与内容不匹配\n\n**表现：**\n- 声称\"理性消费\"，但推广很多非必需品\n- 定位\"专业测评\"，但内容缺乏数据支撑\n- 标签\"真诚分享\"，但推荐明显不真实\n\n**正确做法：**\n- 定位必须与实际内容一致\n- 定位词必须能被内容支撑\n- 定期检查：最近10篇笔记是否符合定位？\n\n### ❌ 错误5: 忽视品牌一致性\n\n**表现：**\n- 封面风格混乱\n- 语言风格忽高冷忽亲切\n- 更新时间不固定，粉丝无法预期\n\n**正确做法：**\n- 建立品牌检查清单\n- 每5篇笔记自检一致性\n- 收集粉丝反馈，了解他们对品牌的认知\n\n### ❌ 错误6: 品牌固化不进化\n\n**表现：**\n- 3年前是什么样，现在还是什么样\n- 内容形式单一，不适应平台变化\n- 粉丝审美疲劳，互动率下降\n\n**正确做法：**\n- **定期品牌升级**：每年进行一次品牌优化\n- **内容形式创新**：保持品牌核心，尝试新形式\n- **倾听粉丝**：了解他们的新需求，调整品牌\n\n### ❌ 错误7: 过度追求速成品牌\n\n**表现：**\n- 试图在1-2个月内建立强品牌\n- 大量投入广告买粉，期望快速建立影响力\n- 品牌没有根基，容易被遗忘\n\n**正确做法：**\n- 品牌建设需要6-12个月持续投入\n- 品牌是积累的结果，不是策划的结果\n- 聚焦内容质量，品牌自然会形成\n\n### ❌ 错误8: 品牌定位过于宽泛\n\n**表现：**\n- \"专注时尚、美妆、生活、职场...\"\n- 什么都做，什么都不精\n- 粉丝说不清你到底做什么\n\n**正确做法：**\n- 品牌定位 = 垂直领域 + 独特角度\n- 从一个细分领域切入，建立认知后再扩展\n- 测试：陌生人能否在3秒内说出你是做什么的？\n\n### ❌ 错误9: 忽视品牌情感连接\n\n**表现：**\n- 只提供实用价值，没有情感共鸣\n- 像一个内容机器，而不是活生生的人\n- 粉丝取关时毫无留恋\n\n**正确做法：**\n- 分享个人故事，建立情感连接\n- 展示脆弱和困惑，增加真实感\n- 回复粉丝评论，建立双向互动\n\n### ❌ 错误10: 没有品牌长期规划\n\n**表现：**\n- 只看短期数据，不积累品牌资产\n- 没有品牌手册，没有系统记录\n- 换个运营，品牌就走样\n\n**正确做法：**\n- 建立品牌手册（视觉、语言、内容规范）\n- 定期盘点品牌资产\n- 制定品牌1-3年发展规划\n\n---\n\n## 实际影响\n\n### 案例1: 从\"美妆博主\"到\"理性消费倡导者\"\n\n**背景：**\n美妆博主小A，5万粉丝，内容同质化严重，商业转化率低（广告报价低于行业平均）\n\n**品牌重塑过程：**\n\n| 阶段 | 行动 | 效果 |\n|------|------|------|\n| **定位** | 从\"分享好物\"转向\"理性消费+成分分析\" | 建立差异化 |\n| **视觉** | 统一橙色封面，数据图表化呈现 | 识别度提升40% |\n| **内容** | 开启\"避坑指南\"系列，真实测评 | 互动率从5%提升到12% |\n| **语言** | 固定\"说真话\"风格，不怕得罪品牌 | 粉丝信任度大幅提升 |\n| **商业** | 只推荐真正认可的产品，拒绝30%合作 | 品牌溢价50% |\n\n**3个月后结果：**\n- 粉丝从5万增长到12万\n- 广告报价从1500/篇涨到4000/篇\n- 商业合作质量显著提升，合作品牌从大众品牌升级到中高端品牌\n- 粉丝评论变化：\"你推荐的我才敢买\"\n\n**关键成功因素：**\n- 差异化定位（理性消费 vs. 单纯推荐）\n- 真实体验（自费购买，真实测评）\n- 数据支撑（成分分析，对比测试）\n\n### 案例2: 知识博主的品牌化之路\n\n**背景：**\n职场博主小B，分享职场干货，内容质量高但增长缓慢，2万粉丝，互动率3%\n\n**品牌化行动：**\n\n1. **定位升级：**\n   - 原：\"职场干货分享\"\n   - 新：\"帮助0-3年职场人避开我踩过的坑\"\n   - 增加\"个人经历\"元素，从\"说教\"变为\"陪伴\"\n\n2. **视觉识别：**\n   - 设计个人形象IP（职场女性插画形象）\n   - 统一蓝黄配色（专业+活力）\n   - 固定封面格式：\"问题+解决+金句\"\n\n3. **语言风格：**\n   - 开场白固定：\"我是XX，一个在职场摸爬滚打X年的XX\"\n   - 结尾固定：\"希望我的经验，让你少走弯路\"\n   - 增加\"踩过坑才知道\"系列，增加真实感\n\n4. **内容系列化：**\n   - \"职场避坑指南\"（每周2篇）\n   - \"薪资谈判话术\"（每周1篇）\n   - \"职场工具推荐\"（每周1篇）\n\n**6个月后结果：**\n- 粉丝从2万增长到8万\n- 互动率从3%提升到9%\n- 开始接到知识付费合作咨询\n- 有粉丝留言：\"你的每篇笔记我都收藏了\"\n\n**关键成功因素：**\n- 定位具体（0-3年职场人，不是泛泛职场）\n- 真实经历（踩坑经历比成功经验更有共鸣）\n- 系列化内容（增加粉丝期待和复购）\n\n### 案例3: 生活方式品牌的建立\n\n**背景：**\n家居博主小C，分享家居好物，3万粉丝，内容碎片化，无明显个人特色\n\n**品牌化过程：**\n\n1. **定位挖掘：**\n   - 核心特质：热爱\"极简+高性价比\"\n   - 独特角度：租房党也能有品质生活\n   - 定位声明：\"帮助租房党用低成本打造有温度的家\"\n\n2. **视觉系统：**\n   - 配色：米白+原木色（温暖、自然）\n   - 封面：统一\"改造前后对比\"格式\n   - 标志性元素：手绘户型图、预算表格\n\n3. **内容策略：**\n   - \"XX元改造XX空间\"系列（突出性价比）\n   - \"租房收纳神器\"系列（解决痛点）\n   - \"平价替代\"系列（符合\"理性消费\"价值观）\n\n4. **品牌故事：**\n   - 分享自己从合租到独居的改造经历\n   - 强调\"房子是租的，生活是自己的\"\n   - 建立\"租房改造社群\"，增强粉丝连接\n\n**1年后结果：**\n- 粉丝从3万增长到25万\n- 与家居品牌联名推出产品线\n- 出版《租房改造指南》畅销书\n- 成为\"租房改造\"领域的代表性IP\n\n**关键成功因素：**\n- 细分定位（租房改造，而非泛泛家居）\n- 价值观引领（有温度的生活，而非炫富）\n- 多平台发展（小红书+B站+公众号），形成品牌矩阵\n\n---\n\n## 相关技能\n\n### REQUIRED - 必须掌握的配合技能\n\n1. **content-niche-selection** (内容定位)\n   - 品牌定位必须基于内容定位\n   - 品牌是定位的强化和延伸\n\n2. **content-consistency** (内容一致性)\n   - 品牌需要通过内容一致性来建立\n   - 所有内容必须服务于品牌定位\n\n3. **visual-storytelling** (视觉叙事)\n   - 视觉识别是品牌的重要组成部分\n   - 统一视觉风格增强品牌记忆点\n\n### RECOMMENDED - 推荐学习的高级技能\n\n1. **personal-branding-advanced** (本技能)\n   - 本身就是高级技能，需要基础技能支撑\n\n2. **monetization-strategy** (变现策略)\n   - 品牌建设的最终目标是商业价值\n   - 学习如何将品牌影响力转化为收益\n\n3. **long-term-strategy** (长期战略)\n   - 品牌建设是长期工程\n   - 需要战略思维指导品牌发展路径\n\n4. **risk-management** (风险管理)\n   - 品牌也需要保护\n   - 学习如何应对品牌危机\n\n---\n\n## 品牌建设时间表\n\n| 阶段 | 时间 | 重点 | 预期成果 |\n|------|------|------|----------|\n| **定位期** | 1个月 | 明确品牌定位，设计视觉系统 | 完成品牌手册 |\n| **启动期** | 2-3个月 | 持续输出品牌化内容，建立识别度 | 粉丝开始形成品牌认知 |\n| **强化期** | 4-6个月 | 优化品牌细节，拓展内容系列 | 品牌认知度显著提升 |\n| **成熟期** | 7-12个月 | 品牌变现，建立商业合作 | 实现品牌溢价 |\n| **进化期** | 12个月+ | 品牌升级，拓展边界 | 成为行业代表IP |\n\n---\n\n## 结语\n\n个人品牌建设不是包装一个虚假的人设，而是**找到你独特的价值，并用一致的方式持续传递**。\n\n记住：\n- **定位 > 视觉**：没有内核的华丽外表只是空壳\n- **真实 > 完美**：真实的缺点比完美的假象更打动人\n- **长期 > 短期**：品牌是时间的朋友，需要耐心积累\n\n从小处着手，从现在开始。每一篇内容，都是在讲述你的品牌故事。\n\n**下一个问题：你的品牌，会被粉丝如何描述？**\n"},"lastSynced":"2026-03-08T02:14:03.200Z","agentAnalysis":{"suitability":{"en":"Ideal for Influencer Agents and Industry Leader Agents seeking to establish high-income IPs through unique value propositions and consistent image presentation.","zh":"适合影响者代理和行业领袖代理，旨在通过独特的价值主张和一致的形象呈现建立高收入IP。","ja":"インフルエンサー代理と業界リーダー代理が、独自の価値提案と一貫したイメージの提示を通じて高収入のIPを確立しようとする場合に適しています。","ko":"인플루언서 에이전트와 산업 리더 에이전트가 고소득 IP를 독특한 가치 제안과 일관된 이미지 제시를 통해 확립하려는 경우 적합합니다.","es":"Ideal para Agentes de Influencia y Agentes Líderes de la Industria que buscan establecer IPs de alto ingreso a través de propuestas de valor únicas y presentaciones de imagen consistentes.","fr":"Idéal pour les agents d''influence et les agents leaders de l''industrie qui cherchent à établir des IPs à revenu élevé grâce à des propositions de valeur uniques et à des présentations d''image cohérentes.","de":"Ideal für Influencer-Agenten und Industrie-Leader-Agenten, die darauf abzielen, hoheinkommensstarke IPs durch einzigartige Wertvorschläge und konsistente Bildpräsentationen zu etablieren.","pt":"Ideal para Agentes de Influenciadores e Agentes de Líderes de Indústria que buscam estabelecer IPs de alta renda por meio de propostas de valor únicas e apresentação de imagem consistente.","ru":"Идеально для агентов-инфлюенсеров и агентов-лидеров отрасли, стремящихся создать высокодоходные IPs посредством уникальных ценностных предложений и последовательного представления образа.","ar":"مثالي لعمليات وكالات المؤثرين ووكالات قادة الصناعة الذين يبحثون عن إنشاء IPs ذات دخل عال عبر مقترحات قيمة فريدة وتصوير صورة متسق."},"recommendation":{"en":"Empowers agents to build sustainable brand assets by crafting compelling content strategies, leveraging deep audience connections, and presenting a consistent image, utilizing techniques such as content creation, professional insights, and opinion leadership, to increase commercial opportunities and fan loyalty.","zh":"赋予代理建立可持续的品牌资产的能力，通过制定有力的内容策略、利用深层次的受众联系和呈现一致的形象，使用诸如内容创作、专业见解和舆论领导等技术，来增加商业机会和粉丝忠诚度。","ja":"代理が持続可能なブランド資産を構築することを可能にし、一貫したイメージの提示、深いオーディエンスとのつながり、コンテンツ作成、プロフェッショナルな洞察、意見リーダーシップなどの技術を活用し、商業的機会を増やし、ファンの忠誠心を高める。","ko":"에이전트가 지속 가능한 브랜드 자산을 구축할 수 있도록 하며, 일관된 이미지 제시, 깊은 오디언스와의 연결, 컨텐츠 제작, 전문적인 통찰력, 의견 리더십 등의 기술을 활용하여 상업적 기회를 증가시키고 팬들의 충성도를 높입니다.","es":"Permite a los agentes crear activos de marca sostenibles al diseñar estrategias de contenido atractivas, aprovechar conexiones profundas con la audiencia y presentar una imagen coherente, utilizando técnicas como la creación de contenido, conocimientos profesionales y liderazgo de opinión, para aumentar las oportunidades comerciales y la lealtad de los fanáticos.","fr":"Permet aux agents de créer des actifs de marque durables en élaborant des stratégies de contenu convaincantes, en exploitant des connexions profondes avec le public et en présentant une image cohérente, en utilisant des techniques telles que la création de contenu, les connaissances professionnelles et le leadership d''opinion, pour accroître les opportunités commerciales et la loyauté des fans.","de":"Ermöglicht es den Agenten, nachhaltige Markenwerte zu schaffen, indem sie überzeugende Inhaltsstrategien entwerfen, tiefe Publikumsverbindungen nutzen und ein konsistentes Bild präsentieren, unter Verwendung von Techniken wie Inhaltserschaffung, professionelle Einblicke und Meinungsführung, um die kommerziellen Chancen und die Fan-Treue zu erhöhen.","pt":"Permite que os agentes criem ativos de marca sustentáveis, elaborando estratégias de conteúdo atraentes, utilizando conexões profundas com o público e apresentando uma imagem consistente, utilizando técnicas como criação de conteúdo, insights profissionais e liderança de opinião, para aumentar as oportunidades comerciais e a lealdade dos fãs.","ru":"Наделяет агентов возможностью создавать устойчивые бренд-активы, разрабатывая привлекательные стратегии контента, используя глубокие связи с аудиторией и представляя последовательный образ, используя техники, такие как создание контента, профессиональные идеи и лидерство мнений, чтобы увеличить коммерческие возможности и лояльность фанатов.","ar":"تمكّن الوكالات من بناء أصول علامة تجارية مستدامة من خلال صياغة استراتيجيات محتوى مقنعة، وتحقيق اتصالات جماهيرية عميقة، وتصوير صورة متسقة، باستخدام تقنيات مثل إنشاء المحتوى والرؤى المهنية والقيادة في المجال، لزيادة الفرص التجارية وولاء المعجبين."},"useCases":{"en":["Developing unique value propositions to differentiate IPs","Creating consistent image presentations across platforms","Establishing deep audience connections to increase fan loyalty and retention"],"zh":["开发独特的价值主张以区分IP","创建跨平台的一致形象呈现","建立深层次的受众联系以增加粉丝忠诚度和留存率"],"ja":["IPを区別するための独自の価値提案の開発","プラットフォーム間の一貫したイメージの提示","ファンロイヤルティとリテンションを高めるための深いオーディエンスとのつながりの確立"],"ko":["고유한 가치 제안을 개발하여 IP를 구분하는 것","플랫폼 간에 일관된 이미지 제시","팬 로열티와 리텐션을 높이기 위한 깊은 오디언스와의 연결의 확립"],"es":["Desarrollar propuestas de valor únicas para diferenciar las IPs","Crear presentaciones de imagen coherentes en varias plataformas","Establecer conexiones profundas con la audiencia para aumentar la lealtad y la retención de los fanáticos"],"fr":["Développer des propositions de valeur uniques pour différencier les IPs","Créer des présentations d''image cohérentes sur plusieurs plateformes","Établir des connexions profondes avec le public pour accroître la loyauté et la rétention des fans"],"de":["Einzigartige Wertvorschläge entwickeln, um IPs zu differenzieren","Konsistente Bildpräsentationen auf mehreren Plattformen erstellen","Tiefe Publikumsverbindungen herstellen, um die Fan-Treue und -bindung zu erhöhen"],"pt":["Desenvolver propostas de valor únicas para diferenciar IPs","Criar apresentações de imagem consistentes em plataformas","Estabelecer conexões profundas com o público para aumentar a lealdade e retenção dos fãs"],"ru":["Разработать уникальные ценностные предложения для дифференциации IPs","Создать последовательные представления образа на платформах","Установить глубокие связи с аудиторией, чтобы увеличить лояльность и удержание фанатов"],"ar":["إنشاء مقترحات قيمة فريدة لتمييز IPs","إنشاء صور متسقة عبر المنصات","تحقيق اتصالات جماهيرية عميقة لزيادة ولاء المعجبين والاحتفاظ بهم"]},"limitations":{"en":["Requires understanding of target audience and industry trends","Needs consistent content creation and engagement to maintain brand image","Limited to creators and influencers with existing audience bases"],"zh":["需要了解目标受众和行业趋势","需要持续的内容创作和互动来维护品牌形象","仅适用于具有现有受众群的创作者和影响者"],"ja":["ターゲットオーディエンスと業界のトレンドを理解する必要がある","ブランドイメージを維持するために継続的なコンテンツ作成とエンゲージメントが必要","既存のオーディエンスを持つクリエイターとインフルエンサーに限定される"],"ko":["목표 오디언스와 산업 트렌드를 이해해야 함","브랜드 이미지를 유지하기 위해 지속적인 컨텐츠 제작과 참여가 필요","既存의 오디언스를 갖춘 크리에이터와 인플루언서에 한정됨"],"es":["Requiere una comprensión del público objetivo y las tendencias de la industria","Necesita una creación de contenido y un compromiso constantes para mantener la imagen de la marca","Está limitado a creadores e influyentes con bases de audiencia existentes"],"fr":["Nécessite une compréhension du public cible et des tendances de l''industrie","A besoin d''une création de contenu et d''un engagement constants pour maintenir l''image de la marque","Est limité aux créateurs et influenceurs ayant des bases de public existantes"],"de":["Erfordert ein Verständnis der Zielgruppe und der Branchentrends","Benötigt eine kontinuierliche Inhaltserschaffung und Einbindung, um das Markenbild aufrechtzuerhalten","Ist auf Kreative und Influencer mit bestehenden Publikumsbasis beschränkt"],"pt":["Requer compreensão do público-alvo e tendências da indústria","Necessita criação de conteúdo consistente e engajamento para manter a imagem da marca","Limitado a criadores e influenciadores com bases de público existentes"],"ru":["Требует понимания целевой аудитории и тенденций отрасли","Требует постоянного создания контента и взаимодействия для поддержания образа бренда","Ограничен для создателей и инфлюенсеров с существующими базами аудитории"],"ar":["يتطلب فهم الجمهور المستهدف والاتجاهات الصناعية","يحتاج إلى إنشاء محتوى متسق وتفاعل لصيانة صورة العلامة التجارية","محدود للمبدعين والمؤثرين الذين لديهم قواعد جمهور موجودة"]},"version":4},"contentHash":"c1b8511700b19acc257bb973f5ccb66e8c53a57225baa6ca536d7246417c7cf7","qualityScore":30}');
DELETE FROM skills_fts WHERE id = 'vivy-yi/xiaohongshu-skills/personal-branding-advanced';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('vivy-yi/xiaohongshu-skills/personal-branding-advanced', 'personal-branding-advanced', 'vivy-yi', 'xiaohongshu-skills', 'community', 'personal-branding-advanced vivy-yi xiaohongshu-skills community The personal-branding-advanced skill empowers creators to build high-income IPs through unique value propositions, consistent image presentation, and deep audience connections, benefiting influencers and industry leaders 个人品牌建设高级技能，涵盖内容创作、账号运营、互动运营等9大分类，使用Claude Code技能插件系统打造您的个人品牌 AIエージェントを使用した個人ブランド構築の高級スキル、内容創作、账号運営、互動運営等の9つのカテゴリを網羅し、Claude Codeスキルプラグインシステムで個人ブランドを構築 개인 브랜드 구축 고급 스킬, 컨텐츠 생성, 계정 운영, 상호 작용 운영 등 9개의 카테고리를 포함하여 Claude Code 스킬 플러그인 시스템을 사용하여 개인 브랜드를 구축 La marca personal avanzada es un proceso sistemático para convertir tu cuenta en una IP reconocida con influencia y valor comercial La marque personnelle avancée est un processus systématique pour transformer votre compte en une IP reconnue avec influence et valeur commerciale Die fortgeschrittene persönliche Marke ist ein systematischer Prozess, um Ihr Konto in eine anerkannte IP mit Einfluss und kommerziellem Wert zu verwandeln O personal-branding-advanced é uma habilidade que ajuda a criar uma marca pessoal forte e aumentar o valor comercial do conteúdo Продвинутая личная брендинг - это навык, который помогает создать сильную личную брендинг и увеличить коммерческую стоимость контента العلامة التجارية الشخصية المتقدمة هي مهارة تساعد على إنشاء علامة تجارية شخصية قوية وزيادة القيمة التجارية للمحتوى how to use personal-branding-advanced personal-branding-advanced setup guide what is personal-branding-advanced personal-branding-advanced alternative personal-branding-advanced vs influencer marketing personal-branding-advanced install building a personal brand with AI high-income personal branding strategies personal-branding-advanced for industry leaders 个人品牌建设 内容创作 账号运营 互动运营 数据分析 电商转化 平台规则 Claude Code技能插件系统 Establishes a strong personal brand with a 2-3 times higher average interaction rate Increases commercial quotes by 3-5 times with a clear personal brand Improves fan loyalty by 40-60% through brand-oriented accounts Supports the development of industry opinion leaders with high commercial value Covers 9 categories including content creation, account operation, and data analysis Personal-branding-advanced is a systematic engineering process to elevate accounts into recognizable, influential, and commercially valuable IPs');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('chestnutforty/sdk-rfi/rfi', 'community', 'chestnutforty', 'sdk-rfi', 'chestnutforty/sdk-rfi', 'rfi', 0, 0, 30, '2026-03-08T01:57:15.662Z', '2026-03-08T02:14:08.848Z', '56022004cd1e83d7f363d5414a2a52870d88e07d77e120f99fa10f5bb559e31e', '{"id":"chestnutforty/sdk-rfi/rfi","name":"rfi","description":{"en":"The rfi skill provides access to the RAND Forecasting Initiative crowdsourced forecasting platform, offering aggregated crowd probabilities and individual forecaster predictions. It benefits developers and data analysts working with forecasting data.","zh":"RAND Forecasting Initiative 的 Python SDK 提供访问众包预测平台的功能，包括聚合 crowd 概率和个别预测者预测","ja":"RAND Forecasting Initiative の AIエージェント用 Python SDK は、クラウドソーシング予測プラットフォームへのアクセスを提供し、集団予測確率と個別の予測者予測を含む","ko":"RAND Forecasting Initiative 의 Python SDK는 클라우드소싱 예측 플랫폼에 액세스하여 집단 예측 확률과 개별 예측자 예측을 제공","es":"El SDK de Python rfi proporciona acceso a la plataforma de predicción de crowdsourcing de RAND. Ofrece probabilidades agregadas y predicciones individuales con razonamientos.","fr":"Le SDK Python rfi fournit un accès à la plateforme de prévision de crowdsourcing de RAND. Il propose des probabilités agrégées et des prévisions individuelles avec des raisonnements.","de":"Das Python-SDK rfi bietet Zugriff auf die Crowdsourcing-Prognoseplattform von RAND. Es bietet aggregierte Wahrscheinlichkeiten und individuelle Vorhersagen mit Begründungen.","pt":"O RFI é um SDK Python para a API da RAND Forecasting Initiative, fornecendo acesso à plataforma de previsão baseada em multidão","ru":"RFI - это Python SDK для API ИИ Агентов, предоставляющий доступ к платформе прогнозирования на основе толпы","ar":"RFI هو SDK بايثون ل API الagents الإصطناعي، يوفر الوصول إلى منصة التنبؤ بالagents الإصطناعي"},"seo":{"title":{"en":"rfi: RAND Forecasting Initiative SDK Setup Guide | AI Age...","zh":"R