INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SongYunSeop/oh-my-til/update-plugin', 'update-plugin', 'SongYunSeop', 'oh-my-til', 'community', 'update-plugin SongYunSeop oh-my-til community The update-plugin skill updates the already-installed Oh My TIL plugin to the latest source, benefiting Obsidian users. It utilizes a Claude Code terminal and MCP server for efficient updates. update-plugin 技术用于更新 Obsidian 插件，包括 Claude Code 终端、MCP 服务器和 TIL 学习仪表板 Update Plugin 技術は、Obsidian プラグインを更新し、Claude Code ターミナル、MCP サーバー、TIL 学習ダッシュボードを含みます update-plugin 기술은 Obsidian 플러그인을 업데이트하여 Claude Code 터미널, MCP 서버 및 TIL 학습 대시보드를 포함합니다 Update-plugin es una herramienta para actualizar el plugin Oh My TIL en Obsidian, con funcionalidades de terminal integrada y aprendizaje Update-plugin est un outil pour mettre à jour le plugin Oh My TIL pour Obsidian, avec des fonctionnalités de terminal intégrée et d''apprentissage Update-plugin ist ein Tool zum Aktualisieren des Oh My TIL-Plugins für Obsidian, mit integrierter Terminal- und Lernfunktion O update-plugin é um recurso que atualiza o plugin Oh My TIL para a última versão, incluindo terminal Claude Code e dashboard de aprendizado TIL. Обновление плагина - функция, которая обновляет плагин Oh My TIL до последней версии, включая терминал Claude Code и панель управления TIL. برنامج تحديث البرنامج المساعد هو ميزة لتجديد برنامج Oh My TIL إلى الإصدار الأخير، بما في ذلك محطة Claude Code ولوحة التحكم في التعلم TIL. how to use update-plugin update-plugin setup guide Obsidian plugin update what is update-plugin update-plugin alternative update-plugin vs oh-my-til update-plugin install Claude Code terminal integration TIL learning dashboard 更新插件 Obsidian 插件 CLI 命令 预检验证 AI 工具 AIエージェント update-plugin 技术 Activates via the `/update-plugin <vault-path>` command Supports argument handling for Obsidian vault paths Performs pre-flight validation using `ls` command Updates the Oh My TIL plugin to the latest source Utilizes a Claude Code terminal for embedded code execution Integrates with the TIL learning dashboard for user insights update-plugin is an Obsidian plugin skill that updates the Oh My TIL plugin to the latest source via the `/update-plugin` command and argument handling.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('svetzal/researcher-cli/deploy-skills', 'community', 'svetzal', 'researcher-cli', 'svetzal/researcher-cli', 'deploy-skills', 0, 0, 30, '2026-03-07T18:16:37Z', '2026-03-08T02:14:12.216Z', '7def1c617a1fe8f3adc40d76a3e0072ec48b666f2a25a44a6ddaca1e08743998', '{"id":"svetzal/researcher-cli/deploy-skills","name":"deploy-skills","description":{"en":"The deploy-skills CLI tool indexes and searches document repositories, making it available in all sessions for AI agents like Claude Code and Openclaw. It streamlines skill deployment across different platforms.","zh":"Deploy Skills是一个CLI工具，用于索引和搜索文档仓库。它可以将技能从项目的skills/文件夹复制到全局技能位置","ja":"Deploy Skillsは、文書リポジトリの索引と検索を行うCLIツールです。プロジェクトのskills/フォルダ内のスキルをグローバルスキルロケーションにコピーすることができます","ko":"Deploy Skills는 문서 저장소의 색인 및 검색을 위한 CLI 도구입니다. 프로젝트의 skills/폴더 내의 스킬을 글로벌 스킬 위치로 복사할 수 있습니다","es":"Deploy-skills es una herramienta de línea de comandos para indexar y buscar repositorios de documentos. Permite copiar habilidades del proyecto en ubicaciones de habilidades globales.","fr":"Deploy-skills est un outil en ligne de commande pour indexer et rechercher des référentiels de documents. Il permet de copier des compétences du projet dans des emplacements de compétences globales.","de":"Deploy-skills ist ein CLI-Tool für die Indizierung und Suche von Dokumenten-Repositorys. Es ermöglicht das Kopieren von Fähigkeiten des Projekts in globale Fähigkeitsorte.","pt":"O Deploy-Skills é uma ferramenta CLI para indexar e buscar documentações em repositórios, permitindo a utilização em todas as sessões.","ru":"Deploy-Skills - это инструмент ИИ Агентов для индексации и поиска документов в репозиториях, доступный во всех сессиях.","ar":"Deploy-Skills هو أداة سطر الأوامر للفهرسة والبحث في مستودعات الوثائق، مما يسمح بالاستخدام في جميع الجلسات."},"seo":{"title":{"en":"deploy-skills: CLI Tool Setup Guide for AI Agents","zh":"Deploy Skills Setup Guide: CLI 工具用于索引和搜索文档仓库","ja":"Deploy Skills セットアップガイド: AIエージェントのCLIツールによる文書リポジトリの索引と検索","ko":"Deploy Skills 설정 가이드: CLI 도구를 이용한 문서 저장소 색인 및 검색","es":"Guía de configuración de deploy-skills para herramientas ...","fr":"Guide de mise en place de deploy-skills pour les outils d''IA","de":"Einrichtungsleitfaden für deploy-skills in KI-Tools","pt":"Guia de Configuração do Deploy-Skills: Ferramenta CLI par...","ru":"Руководство по Настройке Deploy-Skills: ИИ Агенты для Инд...","ar":"دليل إعداد Deploy-Skills: أداة سطر الأوامر للفهرسة والبحث..."},"description":{"en":"Discover how to index and search document repositories with deploy-skills. Learn how to copy skills and get started with our easy-to-follow setup guide","zh":"了解Deploy Skills的工作原理，包括CLI工具的使用和文档仓库的索引和搜索功能","ja":"Deploy Skillsの機能とCLIツールの使用方法を紹介。文書リポジトリの索引と検索を効率化する","ko":"Deploy Skills의 작동 원리와 CLI 도구의 사용법을 소개합니다. 문서 저장소의 색인 및 검색 기능을 최적화합니다","es":"Aprende a implementar deploy-skills para indexar y buscar repositorios de documentos con nuestra herramienta de línea de comandos","fr":"Découvrez comment déployer deploy-skills pour indexer et rechercher des référentiels de documents avec notre outil en ligne de commande","de":"Erfahren Sie, wie Sie deploy-skills für die Indizierung und Suche von Dokumenten-Repositorys mit unserem CLI-Tool implementieren","pt":"Aprenda a configurar o Deploy-Skills, uma ferramenta CLI para indexar e buscar documentações em repositórios, para Ferramentas de IA","ru":"Узнайте, как настроить Deploy-Skills, инструмент ИИ Агентов для индексации и поиска документов в репозиториях","ar":"تعرف على كيفية إعداد Deploy-Skills، أداة سطر الأوامر للفهرسة والبحث في مستودعات الوثائق، لأنظمة الإي الأبتكارية"},"definition":{"en":"deploy-skills is a command-line interface tool for indexing and searching document repositories, enabling skill deployment across AI agents","zh":"Deploy Skills是一种CLI工具，用于索引和搜索文档仓库","ja":"Deploy Skillsは、AIエージェントのCLIツールであり、文書リポジトリの索引と検索を行う","ko":"Deploy Skills는 문서 저장소의 색인 및 검색을 위한 CLI 도구입니다","es":"Deploy-skills es una herramienta de AI que indexa y busca repositorios de documentos","fr":"Deploy-skills est un outil d''IA qui indexe et recherche des référentiels de documents","de":"Deploy-skills ist ein KI-Tool, das Dokumenten-Repositorys indiziert und durchsucht","pt":"O que é Deploy-Skills? Uma ferramenta CLI para indexação e busca de documentações em repositórios.","ru":"Что такое Deploy-Skills? Инструмент ИИ Агентов для индексации и поиска документов в репозиториях.","ar":"ما هو Deploy-Skills؟ أداة سطر الأوامر للفهرسة والبحث في مستودعات الوثائق."},"features":{"en":["Lists project skills using the `ls skills/` command","Differs each skill against target locations like `~/.claude/skills/` and `~/.openclaw/workspace/skills/`","Supports deployment of skills to global skill locations for AI agents","Enables searching of document repositories","Compatible with multiple AI agents, including Claude Code and Openclaw","Utilizes a simple workflow for identifying and deploying skills"],"zh":["CLI工具用于索引和搜索文档仓库","支持多个Agent，包括Claude Code和Openclaw","可以将技能从项目的skills/文件夹复制到全局技能位置","提供diff功能，用于比较技能与目标位置的差异","支持多个技能的部署"],"ja":["CLIツールによる文書リポジトリの索引と検索","複数のAgent、包括Claude CodeとOpenclawをサポート","プロジェクトのskills/フォルダ内のスキルをグローバルスキルロケーションにコピーする","diff機能を提供し、スキルとターゲットロケーションの差異を比較する","複数のスキルのデプロイをサポート"],"ko":["CLI 도구를 이용한 문서 저장소의 색인 및 검색","다중 에이전트 지원, Claude Code 및 Openclaw 포함","프로젝트의 skills/폴더 내의 스킬을 글로벌 스킬 위치로 복사","diff 기능 제공, 스킬과 대상 위치의 차이를 비교","다중 스킬의 배포 지원"],"es":["Indexación y búsqueda de repositorios de documentos","Copiar habilidades del proyecto en ubicaciones de habilidades globales","Compatibilidad con Claude Code y Openclaw","Uso de la línea de comandos para implementar habilidades","Detección de diferencias en habilidades entre proyectos y ubicaciones globales"],"fr":["Indexation et recherche de référentiels de documents","Copie de compétences du projet dans des emplacements de compétences globales","Compatibilité avec Claude Code et Openclaw","Utilisation de la ligne de commande pour déployer des compétences","Détection de différences dans les compétences entre les projets et les emplacements globaux"],"de":["Indizierung und Suche von Dokumenten-Repositorys","Kopieren von Fähigkeiten des Projekts in globale Fähigkeitsorte","Kompatibilität mit Claude Code und Openclaw","Verwendung der Kommandozeile zum Implementieren von Fähigkeiten","Erkennung von Unterschieden in Fähigkeiten zwischen Projekten und globalen Orten"],"pt":["Indexação de repositórios de documentações","Busca de documentações em repositórios","Compatibilidade com Claude Code e Openclaw","Utilização da linha de comando (CLI)","Copia de habilidades para locais globais","Suporte a múltiplos agentes"],"ru":["Индексация репозиториев документов","Поиск документов в репозиториях","Совместимость с Claude Code и Openclaw","Использование командной строки (CLI)","Копирование навыков в глобальные места","Поддержка нескольких агентов"],"ar":["فهرسة مستودعات الوثائق","بحث الوثائق في مستودعات","التوافق مع Claude Code و Openclaw","استخدام سطر الأوامر (CLI)","نسخ المهارات إلى مواقع عالمية","دعم عدة وكلاء"]},"keywords":{"en":["how to use deploy-skills","deploy-skills setup guide","deploy-skills alternative","deploy-skills vs other CLI tools","what is deploy-skills","deploy-skills install","deploy-skills for AI agents","document repository indexing","searching document repositories with deploy-skills"],"zh":["Deploy Skills","CLI工具","文档仓库","索引和搜索","AIエージェント","技能部署","全局技能位置","diff功能"],"ja":["Deploy Skills","CLIツール","文書リポジトリ","索引と検索","AIエージェント","スキルデプロイ","グローバルスキルロケーション","diff機能"],"ko":["Deploy Skills","CLI 도구","문서 저장소","색인 및 검색","AI 에이전트","스킬 배포","글로벌 스킬 위치","diff 기능"],"es":["herramientas de AI","indexación de documentos","búsqueda de repositorios","deploy-skills","CLI","Claude Code","Openclaw","implementación de habilidades"],"fr":["outils d''IA","indexation de documents","recherche de référentiels","deploy-skills","CLI","Claude Code","Openclaw","déploiement de compétences"],"de":["KI-Tools","Indizierung von Dokumenten","Suche von Dokumenten-Repositorys","deploy-skills","CLI","Claude Code","Openclaw","Implementierung von Fähigkeiten"],"pt":["Deploy-Skills","Ferramentas de IA","Indexação de documentações","Busca de documentações","CLI","Claude Code","Openclaw","Repositórios de documentações","Habilidades globais"],"ru":["Deploy-Skills","ИИ Агенты","Индексация документов","Поиск документов","CLI","Claude Code","Openclaw","Репозитории документов","Глобальные навыки"],"ar":["Deploy-Skills","أدوات الإي","فهرسة الوثائق","بحث الوثائق","سطر الأوامر","Claude Code","Openclaw","مستودعات الوثائق","مهارات عالمية"]}},"owner":"svetzal","repo":"researcher-cli","repoPath":"svetzal/researcher-cli","stars":0,"forks":0,"updatedAt":"2026-03-07T18:16:37Z","topics":[],"category":"community","skillMd":{"name":"deploy-skills","description":"Deploy this projects skills/ folder to global skill locations; use when the user asks to deploy, publish, sync, or push skills to Claude or Openclaw","bodyPreview":"# Deploy Skills\n\nCopy skills from this project''s `skills/` folder into the global skill locations so they are available in all sessions.\n\n## Target Locations\n\n| Agent | Global Skills Path |\n|-------|-------------------|\n| Claude Code | `~/.claude/skills/` |\n| Openclaw | `~/.openclaw/workspace/skills/` |\n\n## Workflow\n\n### 1. Identify skills to deploy\n\nList the project''s skills:\n\n```bash\nls skills/\n```\n\nEach subdirectory is a skill to deploy.\n\n### 2. Diff each skill against both targets\n\nFor each","body":"# Deploy Skills\n\nCopy skills from this project''s `skills/` folder into the global skill locations so they are available in all sessions.\n\n## Target Locations\n\n| Agent | Global Skills Path |\n|-------|-------------------|\n| Claude Code | `~/.claude/skills/` |\n| Openclaw | `~/.openclaw/workspace/skills/` |\n\n## Workflow\n\n### 1. Identify skills to deploy\n\nList the project''s skills:\n\n```bash\nls skills/\n```\n\nEach subdirectory is a skill to deploy.\n\n### 2. Diff each skill against both targets\n\nFor each skill directory, check whether it differs from the installed versions:\n\n```bash\ndiff -r skills/<name> ~/.claude/skills/<name>\ndiff -r skills/<name> ~/.openclaw/workspace/skills/<name>\n```\n\n### 3. Copy changed skills\n\nFor any skill that differs (or doesn''t exist at the target), copy it:\n\n```bash\ncp -r skills/<name> ~/.claude/skills/\ncp -r skills/<name> ~/.openclaw/workspace/skills/\n```\n\n### 4. Report results\n\nTell the user which skills were updated and which were already up to date.\n\n## Rules\n\n- **Only copy from `skills/` → global locations.** Never copy in the reverse direction.\n- **Never touch skills in the global locations that don''t exist in this project''s `skills/` folder.** Other projects own those.\n- **Do not create skills at the target if the source skill directory is empty or malformed** (missing `SKILL.md`).\n- Copying is non-destructive: `cp -r` overwrites but does not delete unrelated skills at the target.\n"},"lastSynced":"2026-03-08T02:14:12.216Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents like Claude Code and Openclaw needing streamlined skill deployment across multiple platforms.","zh":"Perfect for AI Agents like Claude Code and Openclaw 需要在多个平台上简化技能部署。","ja":"Perfect for AI Agents like Claude Code and Openclaw が、複数のプラットフォームでスキルの導入を簡素化する必要がある場合に適しています。","ko":"Perfect for AI Agents like Claude Code and Openclaw가 여러 플랫폼에서 스킬 배포를 간소화하는 데 필요한 경우에 적합합니다.","es":"Perfecto para agentes de IA como Claude Code y Openclaw que necesitan una implementación de habilidades simplificada en múltiples plataformas.","fr":"Parfait pour les agents d''IA comme Claude Code et Openclaw nécessitant un déploiement de compétences simplifié sur plusieurs plateformes.","de":"Perfekt für KI-Agenten wie Claude Code und Openclaw, die eine vereinfachte Fähigkeitsbereitstellung auf mehreren Plattformen benötigen.","pt":"Perfeito para Agentes de IA como Claude Code e Openclaw que precisam de implantação de habilidades otimizada em várias plataformas.","ru":"Идеально подходит для агентов ИИ, таких как Claude Code и Openclaw, требующих упрощенного развертывания навыков на нескольких платформах.","ar":"مثالي للوكلاء الذكية مثل Claude Code و Openclaw الذين يحتاجون إلى نشر مهارات مدروس عبر منصات متعددة."},"recommendation":{"en":"Empowers agents to seamlessly index and search document repositories, making skills available in all sessions using CLI tools and global skill locations like ~/.claude/skills/ and ~/.openclaw/workspace/skills/.","zh":"Empowers agents 可以无缝地索引和搜索文档存储库，使得所有会话都可以使用 CLI 工具和全局技能位置，如 ~/.claude/skills/ 和 ~/.openclaw/workspace/skills/ 来获取技能。","ja":"Empowers agents が、CLI ツールや ~/.claude/skills/ および ~/.openclaw/workspace/skills/ などのグローバル スキル ロケーションを使用して、文書リポジトリを索引して検索し、すべてのセッションでスキルを利用できるようにします。","ko":"Empowers agents가 CLI 도구와 ~/.claude/skills/ 및 ~/.openclaw/workspace/skills/와 같은 글로벌 스킬 위치를 사용하여 문서 저장소를 인덱싱하고 검색하여 모든 세션에서 스킬을 사용할 수 있도록 합니다.","es":"Permite a los agentes indexar y buscar repositorios de documentos de forma transparente, haciendo que las habilidades estén disponibles en todas las sesiones utilizando herramientas CLI y ubicaciones de habilidades globales como ~/.claude/skills/ y ~/.openclaw/workspace/skills/.","fr":"Permet aux agents d''indexer et de rechercher des référentiels de documents de manière transparente, rendant les compétences disponibles dans toutes les sessions en utilisant des outils CLI et des emplacements de compétences globaux comme ~/.claude/skills/ et ~/.openclaw/workspace/skills/.","de":"Ermöglicht es den Agenten, Dokumenten-Repositorys nahtlos zu indizieren und zu durchsuchen, wodurch Fähigkeiten in allen Sitzungen mithilfe von CLI-Tools und globalen Fähigkeitsstandorten wie ~/.claude/skills/ und ~/.openclaw/workspace/skills/ verfügbar sind.","pt":"Habilita os agentes a indexar e pesquisar repositórios de documentos de forma transparente, tornando as habilidades disponíveis em todas as sessões usando ferramentas CLI e locais de habilidades globais como ~/.claude/skills/ e ~/.openclaw/workspace/skills/.","ru":"Наделяет агентов возможностью бесшовного индексирования и поиска репозиториев документов, что делает навыки доступными во всех сессиях с использованием инструментов CLI и глобальных местоположений навыков, таких как ~/.claude/skills/ и ~/.openclaw/workspace/skills/.","ar":"تمكّن الوكلاء من فهرست و البحث في مستودعات الوثائق بطريقة прозрачة، مما يجعل المهارات متاحة في جميع الجلسات باستخدام أدوات CLI وأماكن المهارات العالمية مثل ~/.claude/skills/ و ~/.openclaw/workspace/skills/."},"useCases":{"en":["Deploying skills across different agent platforms","Indexing and searching document repositories for skill discovery","Streamlining skill management using the deploy-skills CLI tool"],"zh":["在不同代理平台上部署技能","索引和搜索文档存储库以发现技能","使用 deploy-skills CLI 工具简化技能管理"],"ja":["複数のエージェント プラットフォームでスキルを展開する","文書リポジトリを索引して検索してスキルを発見する","deploy-skills CLI ツールを使用してスキル管理を簡素化する"],"ko":["다양한 에이전트 플랫폼에 스킬을 배포하는 것","문서 저장소를 인덱싱하고 검색하여 스킬을 발견하는 것","deploy-skills CLI 도구를 사용하여 스킬 관리를 간소화하는 것"],"es":["Implementar habilidades en diferentes plataformas de agentes","Indexar y buscar repositorios de documentos para el descubrimiento de habilidades","Simplificar la gestión de habilidades utilizando la herramienta CLI deploy-skills"],"fr":["Déployer des compétences sur différentes plateformes d''agents","Indexer et rechercher des référentiels de documents pour la découverte de compétences","Simplifier la gestion des compétences en utilisant l''outil CLI deploy-skills"],"de":["Fähigkeiten auf verschiedenen Agenten-Plattformen bereitstellen","Dokumenten-Repositorys indizieren und durchsuchen, um Fähigkeiten zu entdecken","Fähigkeitsmanagement mithilfe des CLI-Tools deploy-skills vereinfachen"],"pt":["Implantação de habilidades em diferentes plataformas de agentes","Indexação e pesquisa de repositórios de documentos para descoberta de habilidades","Otimização da gestão de habilidades usando a ferramenta CLI deploy-skills"],"ru":["Развертывание навыков на разных платформах агентов","Индексирование и поиск репозиториев документов для открытия навыков","Упрощение управления навыками с помощью инструмента CLI deploy-skills"],"ar":["نشر المهارات عبر منصات وكلاء مختلفة","فهرسة و البحث في مستودعات الوثائق لاكتشاف المهارات","تبسيط إدارة المهارات باستخدام أداة deploy-skills CLI"]},"limitations":{"en":["Requires access to global skill locations","Limited to supported agents like Claude Code and Openclaw"],"zh":["需要访问全局技能位置","仅限支持的代理，如 Claude Code 和 Openclaw"],"ja":["グローバル スキル ロケーションへのアクセスが必要","サポート対象のエージェント (Claude Code および Openclaw など) 限定"],"ko":["글로벌 스킬 위치에 대한 액세스가 필요함","지원되는 에이전트(Claude Code 및 Openclaw 등)만 해당"],"es":["Requiere acceso a ubicaciones de habilidades globales","Limitado a agentes compatibles como Claude Code y Openclaw"],"fr":["Nécessite un accès aux emplacements de compétences globaux","Limité aux agents pris en charge comme Claude Code et Openclaw"],"de":["Erfordert Zugriff auf globale Fähigkeitsstandorte","Begrenzt auf unterstützte Agenten wie Claude Code und Openclaw"],"pt":["Exige acesso a locais de habilidades globais","Limitado a agentes compatíveis como Claude Code e Openclaw"],"ru":["Требует доступа к глобальным местоположениям навыков","Ограничен поддерживаемыми агентами, такими как Claude Code и Openclaw"],"ar":["يتطلب الوصول إلى أماكن المهارات العالمية","محدود بالوكلاء المدعومين مثل Claude Code و Openclaw"]},"version":4},"contentHash":"7def1c617a1fe8f3adc40d76a3e0072ec48b666f2a25a44a6ddaca1e08743998","qualityScore":30}');
