INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('svetzal/researcher-cli/deploy-skills', 'deploy-skills', 'svetzal', 'researcher-cli', 'community', 'deploy-skills svetzal researcher-cli community The deploy-skills CLI tool indexes and searches document repositories, making it available in all sessions for AI agents like Claude Code and Openclaw. It streamlines skill deployment across different platforms. Deploy Skills是一个CLI工具，用于索引和搜索文档仓库。它可以将技能从项目的skills/文件夹复制到全局技能位置 Deploy Skillsは、文書リポジトリの索引と検索を行うCLIツールです。プロジェクトのskills/フォルダ内のスキルをグローバルスキルロケーションにコピーすることができます Deploy Skills는 문서 저장소의 색인 및 검색을 위한 CLI 도구입니다. 프로젝트의 skills/폴더 내의 스킬을 글로벌 스킬 위치로 복사할 수 있습니다 Deploy-skills es una herramienta de línea de comandos para indexar y buscar repositorios de documentos. Permite copiar habilidades del proyecto en ubicaciones de habilidades globales. Deploy-skills est un outil en ligne de commande pour indexer et rechercher des référentiels de documents. Il permet de copier des compétences du projet dans des emplacements de compétences globales. Deploy-skills ist ein CLI-Tool für die Indizierung und Suche von Dokumenten-Repositorys. Es ermöglicht das Kopieren von Fähigkeiten des Projekts in globale Fähigkeitsorte. O Deploy-Skills é uma ferramenta CLI para indexar e buscar documentações em repositórios, permitindo a utilização em todas as sessões. Deploy-Skills - это инструмент ИИ Агентов для индексации и поиска документов в репозиториях, доступный во всех сессиях. Deploy-Skills هو أداة سطر الأوامر للفهرسة والبحث في مستودعات الوثائق، مما يسمح بالاستخدام في جميع الجلسات. how to use deploy-skills deploy-skills setup guide deploy-skills alternative deploy-skills vs other CLI tools what is deploy-skills deploy-skills install deploy-skills for AI agents document repository indexing searching document repositories with deploy-skills Deploy Skills CLI工具 文档仓库 索引和搜索 AIエージェント 技能部署 全局技能位置 diff功能 Lists project skills using the `ls skills/` command Differs each skill against target locations like `~/.claude/skills/` and `~/.openclaw/workspace/skills/` Supports deployment of skills to global skill locations for AI agents Enables searching of document repositories Compatible with multiple AI agents, including Claude Code and Openclaw Utilizes a simple workflow for identifying and deploying skills deploy-skills is a command-line interface tool for indexing and searching document repositories, enabling skill deployment across AI agents');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('daisuke-tanabe/daisuke-tanabe/implement', 'community', 'daisuke-tanabe', 'daisuke-tanabe', 'daisuke-tanabe/daisuke-tanabe', 'implement', 0, 0, 30, '2026-03-07T21:30:10Z', '2026-03-08T02:14:16.842Z', 'c2563fdf6602ebcf8682d9706b1398ccd1d7a4c7e4aab524aaa729e2ce5b4977', '{"id":"daisuke-tanabe/daisuke-tanabe/implement","name":"implement","description":{"en":"The Implement skill automates tasks for portfolio site development, benefiting developers by simplifying UI component additions and style adjustments. It''s ideal for small tasks that don''t require testing.","zh":"实现技能用于处理小规模任务的UI和设置变化，涵盖分析、设计、实现、验证和审查步骤","ja":"実装スキルは、小規模タスクのUIと設定の変更を処理するために使用され、分析、設計、実装、検証、レビューのステップを含みます","ko":"구현 스킬은 소규모 태스크의 UI 및 설정 변경을 처리하는 데 사용되며 분석, 설계, 구현, 검증 및 리뷰 단계를 포함합니다","es":"Implementa AI Agent en tu proyecto con nuestra guía técnica. Aprende a configurar y utilizar las herramientas de implementación","fr":"Implémentez AI Agent dans votre projet avec notre guide technique. Découvrez comment configurer et utiliser les outils d''implémentation","de":"Implementieren Sie AI Agent in Ihrem Projekt mit unserer technischen Anleitung. Erfahren Sie, wie Sie die Implementierungstools konfigurieren und verwenden","pt":"A implementação de um portfólio site com AI Agents envolve análise, design, implementação e testes","ru":"Реализация портфолио-сайта с ИИ Агентами включает анализ, проектирование, реализацию и тестирование","ar":"تنفيذ موقع المحفظة باستخدام وكلاء الذكاء الاصطناعي يتضمن التحليل والتصميم والتنفيذ والاختبار"},"seo":{"title":{"en":"Implement: Portfolio Site Setup Guide | AI Agent Skill","zh":"实现Setup Guide：小规模任务的UI和设置变化","ja":"実装Setup Guide：小規模タスクのUIと設定の変更","ko":"구현 Setup Guide: 소규모 태스크의 UI 및 설정 변경","es":"Guía de Implementación de AI Agent para Desarrolladores","fr":"Guide d''Implémentation d''AI Agent pour les Développeurs","de":"Implementierungsleitfaden für AI Agent-Entwickler","pt":"Guia de Implementação de Portfólio Site com AI Agents","ru":"Руководство по реализации портфолио-сайта с ИИ Агентами","ar":"دليل تنفيذ موقع المحفظة باستخدام وكلاء الذكاء الاصطناعي"},"description":{"en":"Streamline your portfolio site development with Implement, a skill that automates UI component additions and style adjustments. Get started now!","zh":"了解如何使用实现技能来处理小规模任务的UI和设置变化，包括分析、设计、实现、验证和审查步骤","ja":"実装スキルを使用して小規模タスクのUIと設定の変更を処理する方法を学びます。分析、設計、実装、検証、レビューの各ステップを含みます","ko":"구현 스킬을 사용하여 소규모 태스크의 UI 및 설정 변경을 처리하는 방법을 알아보세요. 분석, 설계, 구현, 검증 및 리뷰 단계 포함","es":"Aprende a implementar AI Agent en tu proyecto con nuestra guía paso a paso para desarrolladores","fr":"Découvrez comment implémenter AI Agent dans votre projet avec notre guide étape par étape pour les développeurs","de":"Erfahren Sie, wie Sie AI Agent in Ihrem Projekt implementieren können, mit unserer Schritt-für-Schritt-Anleitung für Entwickler","pt":"Aprenda a implementar um portfólio site com AI Agents, incluindo análise, design e testes","ru":"Узнайте, как реализовать портфолио-сайт с ИИ Агентами, включая анализ, проектирование и тестирование","ar":"تعلم كيفية تنفيذ موقع المحفظة باستخدام وكلاء الذكاء الاصطناعي، بما في ذلك التحليل والتصميم والاختبار"},"definition":{"en":"Implement is a skill that automates tasks for portfolio site development, including UI component additions, style adjustments, and setting changes, without requiring testing.","zh":"实现技能是指使用AIエージェント处理小规模任务的UI和设置变化的技术","ja":"実装スキルとは、小規模タスクのUIと設定の変更を処理するためにAIエージェントを使用する技術です","ko":"구현 스킬은 소규모 태스크의 UI 및 설정 변경을 처리하는 데 AI 에이전트를 사용하는 기술입니다","es":"Implementación de AI Agent es el proceso de configurar y utilizar herramientas de implementación para desarrollar proyectos","fr":"L''implémentation d''AI Agent est le processus de configuration et d''utilisation d''outils d''implémentation pour développer des projets","de":"Die Implementierung von AI Agent ist der Prozess der Konfiguration und Verwendung von Implementierungstools zur Entwicklung von Projekten","pt":"Implementação é o processo de criar um portfólio site com AI Agents","ru":"Реализация - это процесс создания портфолио-сайта с ИИ Агентами","ar":"التنفيذ هو عملية إنشاء موقع المحفظة باستخدام وكلاء الذكاء الاصطناعي"},"features":{"en":["Registers tasks with TaskCreate and updates task status with TaskUpdate","Supports five development stages: analysis, design, implementation, verification, and review","Automates UI component additions and style adjustments","Handles setting changes without requiring testing","Integrates with project conventions via CLA"],"zh":["分析步骤：要求分析","设计步骤：设计变更","实现步骤：代码变更","验证步骤：测试和验证","审查步骤：代码审查"],"ja":["分析ステップ：要件分析","設計ステップ：設計変更","実装ステップ：コード変更","検証ステップ：テストと検証","レビューステップ：コードレビュー"],"ko":["분석 단계: 요구 사항 분석","설계 단계: 설계 변경","구현 단계: 코드 변경","검증 단계: 테스트 및 검증","리뷰 단계: 코드 리뷰"],"es":["Implementación de UI componentes y ajustes de estilo","Configuración de archivos y ajustes de layout","Uso de TaskCreate y TaskUpdate para gestionar el progreso","Análisis y diseño de proyectos con activeForm","Implementación de pequeñas tareas sin necesidad de pruebas"],"fr":["Implémentation de composants UI et ajustements de style","Configuration de fichiers et ajustements de layout","Utilisation de TaskCreate et TaskUpdate pour gérer la progression","Analyse et conception de projets avec activeForm","Implémentation de petites tâches sans nécessité de tests"],"de":["Implementierung von UI-Komponenten und Anpassung von Stilen","Konfiguration von Dateien und Anpassung von Layouts","Verwendung von TaskCreate und TaskUpdate zur Fortschrittsverwaltung","Analyse und Design von Projekten mit activeForm","Implementierung von kleinen Aufgaben ohne Testbedarf"],"pt":["Análise de requisitos","Design de UI","Implementação de código","Testes e validação","Integração com CLA","Gerenciamento de tarefas com TaskCreate e TaskUpdate"],"ru":["Анализ требований","Проектирование UI","Реализация кода","Тестирование и валидация","Интеграция с CLA","Управление задачами с TaskCreate и TaskUpdate"],"ar":["تحليل المتطلبات","تصميم الواجهة","تنفيذ الكود","اختبارات وتصديق","التكامل مع CLA","إدارة المهام مع TaskCreate و TaskUpdate"]},"keywords":{"en":["how to use implement","implement setup guide","portfolio site development","automated UI component additions","implement vs manual development","implement install","what is implement","implement alternative","implement best practices"],"zh":["AIエージェント","实现技能","小规模任务","UI变化","设置变化","分析步骤","设计步骤","实现步骤","验证步骤","审查步骤"],"ja":["AIエージェント","実装スキル","小規模タスク","UI変更","設定変更","分析ステップ","設計ステップ","実装ステップ","検証ステップ","レビューステップ"],"ko":["AI 에이전트","구현 스킬","소규모 태스크","UI 변경","설정 변경","분석 단계","설계 단계","구현 단계","검증 단계","리뷰 단계"],"es":["implementación de AI Agent","desarrollo de proyectos","herramientas de implementación","configuración de UI","gestión de progreso","análisis de proyectos","diseño de proyectos","pequeñas tareas de desarrollo"],"fr":["implémentation d''AI Agent","développement de projets","outils d''implémentation","configuration de UI","gestion de progression","analyse de projets","conception de projets","petites tâches de développement"],"de":["Implementierung von AI Agent","Entwicklung von Projekten","Implementierungstools","Konfiguration von UI","Fortschrittsverwaltung","Analyse von Projekten","Design von Projekten","kleine Entwicklungsarbeiten"],"pt":["implementação de portfólio site","AI Agents","análise de requisitos","design de UI","implementação de código","testes e validação","CLA","TaskCreate","TaskUpdate"],"ru":["реализация портфолио-сайта","ИИ Агенты","анализ требований","проектирование UI","реализация кода","тестирование и валидация","CLA","TaskCreate","TaskUpdate"],"ar":["تنفيذ موقع المحفظة","وكلاء الذكاء الاصطناعي","تحليل المتطلبات","تصميم الواجهة","تنفيذ الكود","اختبارات وتصديق","CLA","TaskCreate","TaskUpdate"]}},"owner":"daisuke-tanabe","repo":"daisuke-tanabe","repoPath":"daisuke-tanabe/daisuke-tanabe","stars":0,"forks":0,"updatedAt":"2026-03-07T21:30:10Z","topics":[],"category":"community","skillMd":{"name":"implement","description":"テスト不要なタスクを実装する。 UI 変更・スタイル調整・設定変更・コンポーネント追加など、ユニットテストが不要な変更に使用する。 テストが必要なロジック実装には /tdd を使うこと。","bodyPreview":"# 実装フロー\n\n## Use when\n\n- UI コンポーネントの追加・変更\n- スタイル・レイアウト調整\n- 設定ファイルの変更\n- テスト不要な軽微な変更\n\n## Don''t use when\n\n- テストが必要なロジック実装（→ /tdd）\n- コードレビューのみ（→ /review）\n\n## 進捗管理\n\nスキル開始時に全ステップを TaskCreate で登録し、各ステップの開始・完了時に TaskUpdate で状態を更新すること。\n\nタスク一覧:\n\n1. Step 1: 分析（activeForm: \"要件を分析中\"）\n2. Step 2: 設計（activeForm: \"設計中\"）\n3. Step 3: 実装（activeForm: \"実装中\"）\n4. Step 4: 検証（activeForm: \"検証中\"）\n5. Step 5: レビュー（activeForm: \"レビュー中\"）\n\n---\n\nテスト不要なタスク（UI 変更、設定変更など）を実装する。\n小規模タスクでは各ステップを簡潔にまとめてよいが、省略はしない。\n\n## 前提\n\n- プロジェクト規約: `CLA","body":"# 実装フロー\n\n## Use when\n\n- UI コンポーネントの追加・変更\n- スタイル・レイアウト調整\n- 設定ファイルの変更\n- テスト不要な軽微な変更\n\n## Don''t use when\n\n- テストが必要なロジック実装（→ /tdd）\n- コードレビューのみ（→ /review）\n\n## 進捗管理\n\nスキル開始時に全ステップを TaskCreate で登録し、各ステップの開始・完了時に TaskUpdate で状態を更新すること。\n\nタスク一覧:\n\n1. Step 1: 分析（activeForm: \"要件を分析中\"）\n2. Step 2: 設計（activeForm: \"設計中\"）\n3. Step 3: 実装（activeForm: \"実装中\"）\n4. Step 4: 検証（activeForm: \"検証中\"）\n5. Step 5: レビュー（activeForm: \"レビュー中\"）\n\n---\n\nテスト不要なタスク（UI 変更、設定変更など）を実装する。\n小規模タスクでは各ステップを簡潔にまとめてよいが、省略はしない。\n\n## 前提\n\n- プロジェクト規約: `CLAUDE.md` に従う\n- Lint: `pnpm --filter web lint`\n- 型チェック: `pnpm --filter web typecheck`\n\n## タスク\n\n$ARGUMENTS\n\n---\n\n## Step 1: 分析\n\nタスクの要件を整理する。\n\n1. 要件・制約・非要件を明確にする\n2. 変更対象のファイルを特定する\n3. 影響範囲を確認する\n\n---\n\n## Step 2: 設計\n\n実装の構造を決定する。\n\n1. 責務の分割とインターフェースを決める\n2. 既存コードとの統合方針を決める\n\n※ 単純な変更ならファイルと変更箇所の列挙だけでよい。\n\n---\n\n## Step 3: 実装\n\n1. 必要な変更を実装する\n2. CLAUDE.md のレイヤー設計・命名規約に従う\n3. 最小限の変更に留める\n\n---\n\n## Step 4: 検証\n\n以下をパスすることを確認する:\n\n- `pnpm --filter web lint`\n- `pnpm --filter web typecheck`\n\n失敗する場合は TaskUpdate で activeForm を更新し（例: \"lint エラーを修正中\"）、修正後に再度検証する。\n\n---\n\n## Step 5: レビュー\n\n### 危険フラグ\n\n以下が含まれていないことを確認する:\n\n- ハードコードされた秘密情報\n- デバッグ用 `console.log`\n- コメントアウトされたコード\n- 放置された TODO / FIXME\n- `any` 型の乱用\n\n### コード品質\n\n- [ ] CLAUDE.md の規約に準拠している\n- [ ] レイヤー設計（依存の方向）を守っている\n- [ ] 不要な変更が含まれていない\n- [ ] 影響範囲に問題がない\n\n### 完了報告\n\n```\n## 実装完了\n- 変更ファイル: {ファイル一覧}\n- lint: PASS\n- typecheck: PASS\n- 危険フラグ: なし / あり（詳細）\n- 総評: {一言コメント}\n```\n"},"lastSynced":"2026-03-08T02:14:16.842Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents needing streamlined UI component implementation and style adjustments.","zh":"适用于需要简化UI组件实现和样式调整的前端代理。","ja":"フロントエンドエージェントがストリームライン化されたUIコンポーネントの実装とスタイルの調整を必要とする場合に最適です。","ko":"프론트엔드 에이전트가 효율적인 UI 컴포넌트 구현 및 스타일 조정을 필요로 하는 경우 적합합니다.","es":"Ideal para agentes frontend que necesitan una implementación de componentes de interfaz de usuario simplificada y ajustes de estilo.","fr":"Idéal pour les agents frontend nécessitant une mise en œuvre de composants d''interface utilisateur simplifiée et des ajustements de style.","de":"Ideal für Frontend-Agents, die eine vereinfachte Implementierung von Benutzeroberflächenkomponenten und Stil-Anpassungen benötigen.","pt":"Ideal para Agentes Frontend que necessitam de implementação de componentes de UI simplificados e ajustes de estilo.","ru":"Идеально для агентов Frontend, которым необходима упрощенная реализация компонентов пользовательского интерфейса и корректировка стилей.","ar":"مثالي لعميل واجهة المستخدم الأمامية الذين يحتاجون إلى تنفيذ مكونات واجهة المستخدم المبسطة وتعديلات الشكل."},"recommendation":{"en":"Empowers agents to automate tasks for portfolio site development, simplifying UI component additions and style adjustments using comprehensive content analysis, and handles setting file changes without requiring testing, leveraging TaskCreate and TaskUpdate for progress management.","zh":"赋予代理人自动执行任务的能力，以简化UI组件的添加和样式调整，使用全面内容分析，并且可以在不需要测试的情况下处理设置文件的更改，利用TaskCreate和TaskUpdate进行进度管理。","ja":"エージェントにタスクの自動化を可能にし、包括的なコンテンツ分析を使用してUIコンポーネントの追加とスタイルの調整を簡素化し、テストを必要とせずに設定ファイルの変更を処理し、進度管理のためにTaskCreateとTaskUpdateを利用します。","ko":"에이전트가 자동화된 작업을 수행할 수 있도록 하여 포트폴리오 사이트 개발을 단순화하고 UI 컴포넌트 추가 및 스타일 조정을 위한 포괄적인 콘텐츠 분석을 사용하며 테스트 없이 설정 파일 변경을 처리하며 TaskCreate 및 TaskUpdate를 사용하여 진행 상황을 관리합니다.","es":"Habilita a los agentes para automatizar tareas para el desarrollo de sitios de portfolio, simplificando la adición de componentes de interfaz de usuario y los ajustes de estilo utilizando un análisis de contenido integral, y maneja los cambios de archivos de configuración sin requerir pruebas, aprovechando TaskCreate y TaskUpdate para la gestión del progreso.","fr":"Permet aux agents d''automatiser les tâches pour le développement de sites de portfolio, en simplifiant l''ajout de composants d''interface utilisateur et les ajustements de style en utilisant une analyse de contenu complète, et gère les modifications de fichiers de configuration sans nécessiter de tests, en exploitant TaskCreate et TaskUpdate pour la gestion de la progression.","de":"Ermächtigt Agenten, Aufgaben für die Entwicklung von Portfolio-Websites zu automatisieren, indem sie die Hinzufügung von Benutzeroberflächenkomponenten und Stil-Anpassungen mithilfe einer umfassenden Inhaltsanalyse vereinfachen und Änderungen an Konfigurationsdateien ohne Testen verwalten, indem sie TaskCreate und TaskUpdate für das Progresmanagement nutzen.","pt":"Habilita os agentes a automatizar tarefas para desenvolvimento de sites de portfólio, simplificando a adição de componentes de UI e ajustes de estilo usando análise de conteúdo abrangente, e lida com alterações de arquivos de configuração sem necessidade de teste, utilizando TaskCreate e TaskUpdate para gerenciamento de progresso.","ru":"Наделяет агентов возможностью автоматизировать задачи для разработки сайтов-портфолио, упрощая добавление компонентов пользовательского интерфейса и корректировку стилей с помощью всестороннего анализа контента, и обрабатывает изменения файлов настроек без необходимости тестирования, используя TaskCreate и TaskUpdate для управления прогрессом.","ar":"يمنح العملاء القدرة على توفير مهام لتطوير مواقع الحافظة، بتسهيل إضافة مكونات واجهة المستخدم وتعديلات الشكل باستخدام تحليل محتوى شامل، وتعامل مع تغييرات файлات الإعداد دون الحاجة إلى اختبار، مستخدمًا TaskCreate و TaskUpdate لإدارة التقدم."},"useCases":{"en":["Automating UI component additions","Adjusting styles and layouts","Updating setting files without testing"],"zh":["自动执行UI组件的添加","调整样式和布局","更新设置文件而无需测试"],"ja":["UIコンポーネントの追加の自動化","スタイルとレイアウトの調整","テストを必要とせずに設定ファイルの更新"],"ko":["UI 컴포넌트 추가 자동화","스타일 및 레이아웃 조정","테스트 없이 설정 파일 업데이트"],"es":["Automatización de la adición de componentes de interfaz de usuario","Ajuste de estilos y diseños","Actualización de archivos de configuración sin pruebas"],"fr":["Automatisation de l''ajout de composants d''interface utilisateur","Ajustement des styles et des dispositions","Mise à jour des fichiers de configuration sans tests"],"de":["Automatisierung der Hinzufügung von Benutzeroberflächenkomponenten","Anpassung von Stilen und Layouts","Aktualisierung von Konfigurationsdateien ohne Testen"],"pt":["Automatizar adições de componentes de UI","Ajustar estilos e layouts","Atualizar arquivos de configuração sem teste"],"ru":["Автоматизировать добавление компонентов пользовательского интерфейса","Корректировать стили и компоновку","Обновлять файлы настроек без тестирования"],"ar":["توفير إضافة مكونات واجهة المستخدم","تعديل الأساليب والتخطيطات","تحديث ملفات الإعداد دون اختبار"]},"limitations":{"en":["Not suitable for logic implementation requiring testing","Limited to small tasks and UI changes","Requires project conventions compliance"],"zh":["不适用于需要测试的逻辑实现","仅限于小任务和UI更改","需要遵守项目约定"],"ja":["テストが必要なロジックの実装には不適切","小規模なタスクとUIの変更のみ","プロジェクトの規約の遵守が必要"],"ko":["테스트가 필요한 로직 구현에는 부적합","소규모 작업 및 UI 변경만 해당","프로젝트 규약 준수 필요"],"es":["No apto para la implementación de lógica que requiere pruebas","Limitado a tareas pequeñas y cambios de interfaz de usuario","Requiere cumplimiento de convenciones de proyecto"],"fr":["Non adapté pour la mise en œuvre de la logique nécessitant des tests","Limité à de petites tâches et aux modifications d''interface utilisateur","Nécessite le respect des conventions de projet"],"de":["Nicht geeignet für die Implementierung von Logik, die Tests erfordert","Begrenzt auf kleine Aufgaben und Benutzeroberflächenänderungen","Benötigt die Einhaltung von Projekt-Konventionen"],"pt":["Não é adequado para implementação de lógica que exija teste","Limitado a tarefas pequenas e alterações de UI","Exige conformidade com convenções de projeto"],"ru":["Не подходит для реализации логики, требующей тестирования","Ограничен pequeñas задачами и изменениями пользовательского интерфейса","Требует соблюдения конвенций проекта"],"ar":["غير مناسب للتنفيذ المنطقي الذي يتطلب الاختبار","محدود بالمهام الصغيرة وتغييرات واجهة المستخدم","يتطلب امتثالًا لاتفاقيات المشروع"]},"version":4},"contentHash":"c2563fdf6602ebcf8682d9706b1398ccd1d7a4c7e4aab524aaa729e2ce5b4977","qualityScore":30}');
